  function setupAuth() {
    const form = $('#auth-form');
    const submitButton = $('#auth-submit');
    const error = $('#auth-error');
    const errorCopy = $('#auth-error-copy');
    const errorAction = $('#auth-error-action');
    const nameField = $('#auth-name-field');
    const nameInput = $('#auth-name');
    const emailInput = $('#auth-email');
    const passwordInput = $('#auth-password');
    const mfaInput = $('#auth-mfa-code');
    const codeInput = $('#auth-code');
    const resendButton = $('#auth-code-resend');
    const methodButton = $('#auth-method');
    let rateLimitTimer = null;
    let rateLimitEndsAt = 0;
    // Code sign-in runs email -> code -> name, and only new players see name.
    let codeStep = 'email';
    let codeChallenge = null;
    let resendTimer = null;
    let resending = false;
    let autoSubmittedCode = '';
    const mfaShown = () => !$('#auth-mfa-field')?.classList.contains('hidden');
    const submitLabel = () => {
      if (mfaShown()) return 'Verify & log in';
      if (usingEmailCode()) {
        return codeStep === 'email' ? 'Email me a code' : codeStep === 'name' ? 'Create account' : 'Continue';
      }
      return authMode === 'login' ? 'Log in' : 'Create account';
    };
    const syncSubmitLabel = () => { submitButton.textContent = submitLabel(); };
    const clearAuthError = () => {
      errorCopy.textContent = '';
      errorAction.textContent = '';
      errorAction.dataset.authDestination = '';
      errorAction.classList.add('hidden');
      error.classList.add('hidden');
      [nameInput, emailInput, passwordInput, mfaInput, codeInput].forEach((input) => {
        input?.removeAttribute('aria-invalid');
        const describedBy = (input?.getAttribute('aria-describedby') || '')
          .split(/\s+/).filter((id) => id && id !== 'auth-error');
        if (!input) return;
        if (describedBy.length) input.setAttribute('aria-describedby', describedBy.join(' '));
        else input.removeAttribute('aria-describedby');
      });
    };
    const showAuthError = (message, target = null, action = null) => {
      clearAuthError();
      errorCopy.textContent = message;
      if (action?.label && action?.destination) {
        errorAction.textContent = action.label;
        errorAction.dataset.authDestination = action.destination;
        errorAction.classList.remove('hidden');
      }
      error.classList.remove('hidden');
      if (target) {
        target.setAttribute('aria-invalid', 'true');
        const describedBy = new Set((target.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean));
        describedBy.add('auth-error');
        target.setAttribute('aria-describedby', [...describedBy].join(' '));
        target.focus({ preventScroll: true });
      } else error.focus({ preventScroll: true });
    };
    const setMfaChallengeVisible = (visible) => {
      const field = $('#auth-mfa-field');
      field?.classList.toggle('hidden', !visible);
      if (mfaInput) {
        mfaInput.required = visible;
        if (!visible) mfaInput.value = '';
      }
      syncSubmitLabel();
    };
    const startRateLimitCountdown = (seconds) => {
      clearInterval(rateLimitTimer);
      rateLimitEndsAt = Date.now() + Math.max(1, Number(seconds) || 1) * 1000;
      const tick = () => {
        const remaining = Math.max(0, Math.ceil((rateLimitEndsAt - Date.now()) / 1000));
        if (!remaining) {
          clearInterval(rateLimitTimer);
          rateLimitTimer = null;
          submitButton.disabled = false;
          submitButton.removeAttribute('aria-busy');
          form.removeAttribute('aria-busy');
          syncSubmitLabel();
          return;
        }
        submitButton.disabled = true;
        submitButton.textContent = `Try again in ${remaining}s`;
      };
      tick();
      rateLimitTimer = setInterval(tick, 1000);
    };
    const withAuthBusy = async (label, task) => {
      submitButton.disabled = true;
      submitButton.setAttribute('aria-busy', 'true');
      form.setAttribute('aria-busy', 'true');
      submitButton.textContent = label;
      try {
        await task();
      } finally {
        submitButton.disabled = !!rateLimitTimer;
        submitButton.removeAttribute('aria-busy');
        form.removeAttribute('aria-busy');
        if (!rateLimitTimer) syncSubmitLabel();
      }
    };
    const syncAuthMode = () => {
      const registering = authMode === 'register';
      const byCode = usingEmailCode();
      const namingNewPlayer = byCode && codeStep === 'name';
      nameField.classList.toggle('hidden', byCode ? !namingNewPlayer : !registering);
      nameInput.required = byCode ? namingNewPlayer : registering;
      passwordInput.autocomplete = registering ? 'new-password' : 'current-password';
      passwordInput.minLength = registering ? 8 : 1;
      $('#auth-password-help').classList.toggle('hidden', !registering);
      $('#auth-forgot-password').classList.toggle('hidden', registering);
      $('#auth-password-field').classList.toggle('hidden', byCode);
      $('#auth-email-field').classList.toggle('hidden', byCode && codeStep !== 'email');
      $('#auth-code-field').classList.toggle('hidden', !byCode || codeStep !== 'code');
      if (byCode) {
        $('#auth-eyebrow').textContent = registering || namingNewPlayer ? 'Join the local game' : 'Welcome back';
        $('#auth-title').textContent = codeStep === 'code' ? 'Check your email'
          : namingNewPlayer ? 'Welcome to Third Shot'
            : registering ? 'Log in or sign up' : 'Log in to Third Shot';
        $('#auth-support').textContent = codeStep === 'code'
          ? `Enter the 6-digit code we sent to ${codeChallenge?.email || 'your email'}.`
          : namingNewPlayer ? 'Last step: add the name other players will see.'
            : pendingInviteName
              ? `${pendingInviteName} invited you. Enter your email to join them on court.`
              : 'Enter your email and we’ll send you a 6-digit code. No password needed.';
      } else {
        $('#auth-eyebrow').textContent = registering ? 'Join the local game' : 'Welcome back';
        $('#auth-title').textContent = registering ? 'Create your account' : 'Log in to Third Shot';
        $('#auth-support').textContent = registering
          ? (pendingInviteName
            ? `${pendingInviteName} invited you. Create an account to join them on court.`
            : 'Save courts and join games.')
          : 'Find courts, meet players, and get on the court.';
      }
      $('#auth-toggle').textContent = registering
        ? 'Already have an account? Log in' : 'New here? Create an account';
      $('#auth-toggle').classList.toggle('hidden', byCode);
      methodButton.classList.toggle('hidden', !emailCodeAvailable || namingNewPlayer);
      methodButton.textContent = byCode ? 'Use a password instead' : 'Email me a code instead';
      form.dataset.mode = byCode ? `code-${codeStep}` : authMode;
      syncSubmitLabel();
    };
    const focusFirstAuthField = () => {
      form.querySelector('.auth-field:not(.hidden) input')?.focus({ preventScroll: true });
    };
    const stopResendCooldown = () => {
      clearInterval(resendTimer);
      resendTimer = null;
      resendButton.disabled = false;
      resendButton.textContent = 'Send a new code';
    };
    const startResendCooldown = (seconds = 30) => {
      clearInterval(resendTimer);
      const endsAt = Date.now() + seconds * 1000;
      const tick = () => {
        const remaining = Math.max(0, Math.ceil((endsAt - Date.now()) / 1000));
        if (!remaining) {
          stopResendCooldown();
          return;
        }
        resendButton.disabled = true;
        resendButton.textContent = `Send a new code in ${remaining}s`;
      };
      tick();
      resendTimer = setInterval(tick, 1000);
    };
    const resetCodeFlow = () => {
      codeStep = 'email';
      codeChallenge = null;
      autoSubmittedCode = '';
      codeInput.value = '';
      stopResendCooldown();
    };
    const requestEmailCode = async (email) => {
      const data = await api('/auth/email-code', { method: 'POST', body: JSON.stringify({ email }) });
      const sameAddress = codeChallenge?.email?.toLowerCase() === email.toLowerCase();
      codeChallenge = {
        email,
        challenge: data.challenge,
        newAccount: sameAddress && !!codeChallenge?.newAccount,
      };
      codeStep = 'code';
      autoSubmittedCode = '';
      codeInput.value = '';
      setMfaChallengeVisible(false);
      syncAuthMode();
      startResendCooldown();
      codeInput.focus({ preventScroll: true });
    };
    const showCodeProblem = (err) => {
      if (['email_code_expired', 'email_code_used', 'email_code_retry'].includes(err.code)) {
        showAuthError(err.message, null, { label: 'Send a new code', destination: 'resend-code' });
      } else if (err.code === 'email_code_unavailable') {
        showAuthError(err.message, null, { label: 'Use a password', destination: 'password' });
      } else if (err.code === 'invalid_email_code') {
        showAuthError(err.message, codeInput);
        codeInput.select();
      } else {
        showAuthError(err.message);
        if (err.code === 'rate_limited') startRateLimitCountdown(err.data?.retry_after);
      }
    };
    const resendCode = async () => {
      const email = codeChallenge?.email || emailInput.value.trim();
      if (!email || resending) return;
      resending = true;
      clearAuthError();
      resendButton.disabled = true;
      try {
        await requestEmailCode(email);
        toast('We sent a new code.');
      } catch (err) {
        stopResendCooldown();
        showCodeProblem(err);
      } finally {
        resending = false;
      }
    };
    const chooseSignInMethod = (password) => {
      passwordChosen = password;
      try { localStorage.setItem(AUTH_METHOD_KEY, password ? 'password' : 'code'); } catch { /* storage unavailable */ }
      resetCodeFlow();
      setMfaChallengeVisible(false);
      clearAuthError();
      syncAuthMode();
      focusFirstAuthField();
    };
    const moveToAuthDestination = (destination) => {
      if (destination === 'forgot-password') {
        openForgotPassword();
        return;
      }
      if (destination === 'resend-code') {
        resendCode();
        return;
      }
      if (destination === 'password') {
        chooseSignInMethod(true);
        return;
      }
      if (!['login', 'register'].includes(destination)) return;
      authMode = destination;
      setMfaChallengeVisible(false);
      clearAuthError();
      syncAuthMode();
      (authMode === 'register' ? nameInput : emailInput).focus({ preventScroll: true });
    };
    syncAuthModeUi = syncAuthMode;
    focusAuthEntryField = focusFirstAuthField;
    [nameInput, emailInput, passwordInput, mfaInput, codeInput].forEach((input) => {
      input?.addEventListener('input', () => {
        if (!error.classList.contains('hidden')) clearAuthError();
      });
    });
    // Autofilled or pasted codes go straight through; nobody hunts for a button.
    codeInput.addEventListener('input', () => {
      const digits = codeInput.value.replace(/\D/g, '').slice(0, 6);
      if (digits !== codeInput.value) codeInput.value = digits;
      if (digits.length === 6 && digits !== autoSubmittedCode && !submitButton.disabled && !mfaShown()) {
        autoSubmittedCode = digits;
        form.requestSubmit();
      }
    });
    resendButton.addEventListener('click', resendCode);
    $('#auth-code-change').addEventListener('click', () => {
      resetCodeFlow();
      setMfaChallengeVisible(false);
      clearAuthError();
      syncAuthMode();
      emailInput.focus({ preventScroll: true });
      emailInput.select();
    });
    methodButton.addEventListener('click', () => chooseSignInMethod(usingEmailCode()));
    $('#auth-password-toggle').addEventListener('click', (event) => {
      const button = event.currentTarget;
      const showing = passwordInput.type === 'text';
      passwordInput.type = showing ? 'password' : 'text';
      button.setAttribute('aria-pressed', String(!showing));
      button.setAttribute('aria-label', showing ? 'Show password' : 'Hide password');
      button.querySelector('span').textContent = showing ? 'Show' : 'Hide';
      passwordInput.focus({ preventScroll: true });
    });
    $('#auth-toggle').addEventListener('click', () => {
      moveToAuthDestination(authMode === 'login' ? 'register' : 'login');
    });
    errorAction.addEventListener('click', () => {
      moveToAuthDestination(errorAction.dataset.authDestination);
    });
    $('#auth-forgot-password').addEventListener('click', openForgotPassword);
    $('#auth-access-toggle')?.addEventListener('click', showAuthEntryForm);
    $('#auth-browse-back')?.addEventListener('click', () => {
      const target = $('#auth-browse-back').dataset.publicRoute || '';
      publicBrowseReturnPending = !target;
      location.hash = target;
    });
    $('#auth-access-back')?.addEventListener('click', () => {
      const access = $('#auth-access');
      access.dataset.userOpened = '';
      access.classList.add('hidden');
      const screen = $('#auth-screen');
      screen?.setAttribute('aria-labelledby', $('#auth-share-context:not(.hidden) [data-share-preview-title]')?.id || 'auth-explore-title');
      if (screen) screen.scrollTop = access._browseScrollTop || 0;
      const trigger = access._browseTrigger;
      (trigger?.isConnected && trigger.checkVisibility() ? trigger
        : $('#auth-share-context:not(.hidden) [data-public-auth], #auth-share-context:not(.hidden) [data-invitation-signin]') || $('#auth-access-toggle'))?.focus({ preventScroll: true });
    });
    $('#auth-court-search-form')?.addEventListener('submit', (event) => {
      event.preventDefault();
      searchPublicCourts();
    });
    setupPublicCourtMap();
    document.querySelectorAll('[data-auth-policy]').forEach((button) => {
      button.addEventListener('click', () => openAccountPolicy(button.dataset.authPolicy));
    });

    // Password and code sign-in finish the same way: open the app, then the
    // invite, shared link, or first-run setup that brought the person here.
    const completeAuthentication = async (data, registering) => {
      persistReplacementToken(data);
      localStorage.setItem('pp_has_account', '1');
      setMfaChallengeVisible(false);
      applyMe(data);
      await showMain();
      const openedLinkedDestination = await resumePlayerInviteIntentAfterAuth()
        || rebuildReloadedMatchRouteIfNeeded()
        || openDeepLink();
      if (registering) {
        if (openedLinkedDestination) pendingNewPlayerOnboardingAccountId = state.me.id;
        else runNewPlayerOnboarding();
      } else if (openedLinkedDestination && state.me?.onboarding_complete === false) {
        pendingNewPlayerOnboardingAccountId = state.me.id;
      } else if (!openedLinkedDestination) {
        if (state.me?.onboarding_complete === false) runNewPlayerOnboarding();
        else maybeOnboardHomeArea();
      }
      syncPushSubscription();
    };

    const submitEmailCode = async () => {
      if (codeStep === 'email' || !codeChallenge) {
        if (!emailInput.value.trim()) {
          showAuthError('Enter your email address.', emailInput);
          return;
        }
        if (emailInput.validity.typeMismatch) {
          showAuthError('Enter a complete email address.', emailInput);
          return;
        }
        await withAuthBusy('Sending code…', async () => {
          try {
            await requestEmailCode(emailInput.value.trim());
          } catch (err) {
            showCodeProblem(err);
          }
        });
        return;
      }
      const code = codeInput.value.replace(/\D/g, '');
      if (code.length !== 6) {
        codeStep = 'code';
        syncAuthMode();
        showAuthError('Enter the 6-digit code from your email.', codeInput);
        return;
      }
      if (codeStep === 'name' && !nameInput.value.trim()) {
        showAuthError('Enter the name players should see.', nameInput);
        return;
      }
      if (mfaShown() && !mfaInput.value.trim()) {
        showAuthError('Enter your authenticator or recovery code.', mfaInput);
        return;
      }
      await withAuthBusy(mfaShown() ? 'Verifying…'
        : codeStep === 'name' ? 'Creating account…' : 'Checking code…', async () => {
        try {
          const body = { email: codeChallenge.email, challenge: codeChallenge.challenge, code };
          const mfaCode = mfaInput?.value.trim();
          if (mfaCode) body.mfa_code = mfaCode;
          if (codeChallenge.newAccount && nameInput.value.trim()) {
            body.display_name = nameInput.value.trim();
            const inviteRef = readPlayerInviteIntent()?.inviter_id;
            if (inviteRef) body.invited_by_user_id = inviteRef;
          }
          const data = await api('/auth/email-code/verify', { method: 'POST', body: JSON.stringify(body) });
          resetCodeFlow();
          authMode = 'login';
          await completeAuthentication(data, data.created === true);
        } catch (err) {
          if (err.code === 'display_name_required') {
            codeChallenge.newAccount = true;
            codeStep = 'name';
            syncAuthMode();
            nameInput.focus({ preventScroll: true });
          } else if (err.code === 'mfa_required') {
            setMfaChallengeVisible(true);
            showAuthError(err.message, mfaInput);
          } else {
            showCodeProblem(err);
          }
        }
      });
    };

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (submitButton.disabled) return; // double-tap = duplicate register attempt
      clearAuthError();
      if (usingEmailCode()) {
        await submitEmailCode();
        return;
      }
      if (authMode === 'register' && !nameInput.value.trim()) {
        showAuthError('Enter the name players should see.', nameInput);
        return;
      }
      if (!emailInput.value.trim()) {
        showAuthError('Enter your email address.', emailInput);
        return;
      }
      if (emailInput.validity.typeMismatch) {
        showAuthError('Enter a complete email address.', emailInput);
        return;
      }
      if (authMode === 'register' ? passwordInput.value.length < 8 : !passwordInput.value) {
        showAuthError(authMode === 'register' ? 'Password must be at least 8 characters.' : 'Enter your password.', passwordInput);
        return;
      }
      const mfaVisible = mfaShown();
      if (mfaVisible && !mfaInput.value.trim()) {
        showAuthError('Enter your authenticator or recovery code.', mfaInput);
        return;
      }
      const registering = authMode === 'register';
      await withAuthBusy(mfaVisible ? 'Verifying…'
        : registering ? 'Creating account…' : 'Logging in…', async () => {
        try {
          const body = {
            email: emailInput.value.trim(),
            password: passwordInput.value,
          };
          const mfaCode = mfaInput?.value.trim();
          if (!registering && mfaCode) body.mfa_code = mfaCode;
          if (registering) {
            body.display_name = nameInput.value.trim();
            const inviteRef = readPlayerInviteIntent()?.inviter_id;
            if (inviteRef) body.invited_by_user_id = inviteRef;
          }
          const data = await api(`/auth/${authMode}`, { method: 'POST', body: JSON.stringify(body) });
          await completeAuthentication(data, registering);
        } catch (err) {
          if (!registering && err.code === 'mfa_required') {
            setMfaChallengeVisible(true);
            showAuthError(err.message, mfaInput);
            return;
          }
          const crossPath = err.code === 'email_taken'
            ? { label: 'Log in instead', destination: 'login' }
            : err.code === 'invalid_credentials'
              ? { label: 'Create an account instead', destination: 'register' }
              : null;
          showAuthError(err.message, null, crossPath);
          if (err.code === 'rate_limited') startRateLimitCountdown(err.data?.retry_after);
        }
      });
    });
    syncAuthMode();

    // Ask the server which methods work today. A cached answer already drew
    // the form, so this only switches it when nobody has started typing.
    if (!state.token) {
      fetch('/api/auth/options', { headers: { Accept: 'application/json' } })
        .then((response) => (response.ok ? response.json() : null))
        .then((options) => {
          if (!options) return;
          const available = options.email_code === true;
          try { localStorage.setItem(AUTH_OPTIONS_KEY, JSON.stringify({ email_code: available })); } catch { /* storage unavailable */ }
          if (available === emailCodeAvailable || passwordInput.value || codeStep !== 'email') return;
          emailCodeAvailable = available;
          setMfaChallengeVisible(false);
          syncAuthMode();
        })
        .catch(() => { /* offline: keep the cached answer */ });
    }
  }

  function purgeAccountChatDrafts(accountId) {
    if (!accountId) return;
    try {
      const marker = `:${accountId}:`;
      const keys = [];
      for (let index = 0; index < sessionStorage.length; index += 1) {
        const key = sessionStorage.key(index);
        if (key?.startsWith('pp_chat_draft_v') && key.includes(marker)) keys.push(key);
      }
      keys.forEach((key) => sessionStorage.removeItem(key));
    } catch { /* storage unavailable */ }
  }

  function resetPrivateUiForLogout(accountId) {
    clearToasts();
    purgeAccountChatDrafts(accountId);
    purgeAccountChatOutbox(accountId);
    clearPlayPulseCreateAttempts(accountId);
    clearPlayPulseAcceptAttempts(accountId);
    clearGameOpenCallAttempts(accountId);
    state.playRenderSeq += 1;
    state.chatRenderSeq += 1;
    profileRenderGeneration += 1;
    profileDashboardCache = { userId: null, promise: null, data: null, readyAt: 0 };
    state.playGamesCache = null;
    state.playPrefsFor = null;
    state.playWhen = 'any';
    state.chatFriendsCache = null;
    state.activeThreadUserId = null;
    state.lastNotifId = null;
    state.unreadMessages = 0;
    state.pendingRequests = 0;
    state.communityRoomUnread = 0;
    state.communityMessageUnread = 0;
    state.communityGroupUnread = 0;
    state.pendingCrewInvites = { count: 0, items: [] };
    state.gamesToConfirm = 0;
    state.activeGame = null;
    state.activeTournament = null;
    state.activeLeague = null;
    state.activeArrival = null;
    state.activePlayPulse = null;
    state.presence = null;
    state.favIds = null;
    state.favoriteCourts = [];
    state.lastAutoCheckAt = 0;
    state.autoCheckCandidateCourtId = null;
    state.autoCheckCandidateSince = 0;
    state.autoCheckoutCourtId = null;
    state.autoCheckoutDepartureFixes = 0;
    state.userLoc = null;
    state.userAccuracyMeters = null;
    state.courtLocationPermission = 'unknown';
    state.courtAutoLocateAttempted = false;
    state.courtLocationRequest = null;
    state.areaLoc = null;
    state.areaLabel = null;
    state.dismissedSearchSuggestionQuery = '';
    state.courtSearchResultsQuery = '';
    state.snapshotAreaProvisional = false;
    state.courtsInView = [];
    clearCourtSelection();
    state.courtMarkers.clear();
    state.courtListSignature = '';
    state.courtListExpandedScrollTop = 0;
    state.courtListLimit = 20;
    state.courtListPlaces = [];
    state.courtListSavedOnly = false;
    state.listSort = 'distance';
    state.courtSortBeforeActive = 'distance';
    Object.keys(state.courtFilters).forEach((key) => { state.courtFilters[key] = false; });
    state.courtFetchSeq += 1;
    state.nearbySkill = '';
    state.nearbyRadius = 25;
    clearLookingBanner();
    state.searchQ = '';
    state.tab = 'courts';
    state.playLane = null;
    state.tabScrollPositions = { play: 0, chat: 0, profile: 0 };
    setPlaySegment('games', { render: false });
    state.chatSeg = 'chats';
    state.chatConversationFilter = 'all';

    if (state.userDot && state.map) state.map.removeLayer(state.userDot);
    state.userDot = null;
    if (state.userAccuracyRing && state.map) state.map.removeLayer(state.userAccuracyRing);
    state.userAccuracyRing = null;
    state.markers?.clearLayers?.();

    clearTimeout(reusableOverlayTimer);
    reusableOverlayTimer = null;
    reusableOverlayEntry = null;
    pendingReusableTraversal = null;
    pendingDeepMatchRebuild = null;
    pendingNewPlayerOnboardingAccountId = null;
    suppressNativeHashRoute = null;
    adoptOverlayEntry = null;
    activeRoutedOverlayLoad = null;
    routedOverlayLoadSeq += 1;
    overlayHistoryRevision += 1;
    dismissAllRequested = false;
    dismissAllCallbacks = [];
    while (overlayStack.length) {
      const entry = overlayStack.pop();
      destroyModal(entry.el, { restoreFocus: false });
    }
    syncModalStack();
    try {
      history.replaceState(overlayHistoryState(null, 0, null), '', baseAppUrl());
    } catch { /* history can be unavailable */ }

    ['#play-content', '#chat-content', '#profile-content'].forEach((selector) => {
      const panel = $(selector);
      if (!panel) return;
      panel.replaceChildren();
      delete panel.dataset.viewKey;
      delete panel.dataset.viewReadyAt;
      panel.setAttribute('aria-busy', 'false');
      panel.classList.remove('view-refreshing');
    });
    $('#court-preview')?.replaceChildren();
    $('#court-preview')?.classList.add('hidden');
    $('#court-list-items')?.replaceChildren();
    const courtSearch = $('#court-search');
    if (courtSearch) courtSearch.value = '';
    hideSearchSuggest();
    syncSearchClear();
    syncCourtFilterControls();
    const banner = $('#active-game-banner');
    if (banner) { banner.replaceChildren(); banner.classList.add('hidden'); }
    document.querySelectorAll('#chat-segments button').forEach((button) => {
      const active = button.dataset.seg === 'chats';
      button.classList.toggle('active', active);
      button.setAttribute('aria-selected', String(active));
    });
  }

  function logout({ reason = '', preserveEmail = false, preserveRoute = false } = {}) {
    const accountId = state.me && state.me.id;
    const rememberedEmail = preserveEmail
      ? String(state.me?.email || $('#auth-email')?.value || '').trim() : '';
    const rememberedRoute = preserveRoute && normalizeOverlayRoute(location.hash)
      ? location.hash : '';
    invalidateMeRequests();
    // Detach this account's request dedupe record. Its fetch may still settle,
    // but captured session ownership prevents it from touching the next login.
    instantRallyInFlight = null;
    rallyArrivalInFlight = null;
    playPulseCreateInFlight = null;
    playPulseAcceptInFlight.clear();
    revokePushSubscription(state.token);
    clearGameDrafts(accountId);
    clearInstantRallyAttempt(accountId);
    clearRallyArrivalAttempt(accountId);
    resetPrivateUiForLogout(accountId);
    stopLocationWatch();
    authSessionEpoch += 1;
    authTokenRevision += 1;
    state.token = null;
    state.me = null;
    localStorage.removeItem('pp_token');
    localStorage.removeItem('pp_me_snapshot_v1');
    clearInterval(state.presenceHeartbeatTimer);
    clearInterval(state.playLiveRefreshTimer);
    stopThreadPolling();
    state.presenceHeartbeatTimer = null;
    state.playLiveRefreshTimer = null;
    state.playLiveRefreshInFlight = false;
    if ('clearAppBadge' in navigator) navigator.clearAppBadge().catch(() => { /* fine */ });
    $('#boot-screen')?.classList.add('hidden');
    $('#main-screen').classList.add('hidden');
    $('#auth-screen').classList.remove('hidden');
    setupPublicCourtMap();
    $('#auth-email').value = rememberedEmail;
    $('#auth-password').value = '';
    $('#auth-name').value = '';
    const authMfaField = $('#auth-mfa-field');
    const authMfaCode = $('#auth-mfa-code');
    authMfaField?.classList.add('hidden');
    if (authMfaCode) { authMfaCode.value = ''; authMfaCode.required = false; }
    authMode = 'login';
    syncAuthModeUi();
    const passwordToggle = $('#auth-password-toggle');
    $('#auth-password').type = 'password';
    passwordToggle?.setAttribute('aria-pressed', 'false');
    passwordToggle?.setAttribute('aria-label', 'Show password');
    const passwordToggleCopy = passwordToggle?.querySelector('span');
    if (passwordToggleCopy) passwordToggleCopy.textContent = 'Show';
    [$('#auth-name'), $('#auth-email'), $('#auth-password'), authMfaCode].forEach((input) => {
      input?.removeAttribute('aria-invalid');
      const describedBy = (input?.getAttribute('aria-describedby') || '')
        .split(/\s+/).filter((id) => id && id !== 'auth-error');
      if (!input) return;
      if (describedBy.length) input.setAttribute('aria-describedby', describedBy.join(' '));
      else input.removeAttribute('aria-describedby');
    });
    const authError = $('#auth-error');
    const authErrorCopy = $('#auth-error-copy');
    const authErrorAction = $('#auth-error-action');
    if (authErrorCopy) authErrorCopy.textContent = reason;
    if (authErrorAction) {
      authErrorAction.textContent = '';
      authErrorAction.dataset.authDestination = '';
      authErrorAction.classList.add('hidden');
    }
    authError.classList.toggle('hidden', !reason);
    if (reason) authError.setAttribute('role', 'alert');
    if (rememberedRoute) {
      try {
        history.replaceState(
          overlayHistoryState(null, 0, null), '', `${baseAppUrl()}${rememberedRoute}`,
        );
      } catch { /* the login screen remains usable without history state */ }
    }
    renderSignedOutShareContext();
  }

  function tokenHint() {
    return state.token ? state.token.slice(-16) : '';
  }

  function saveMeSnapshot(data) {
    if (!state.token || !data || !data.user) return;
    try {
      localStorage.setItem('pp_me_snapshot_v1', JSON.stringify({
        v: 1,
        tokenHint: tokenHint(),
        savedAt: Date.now(),
        data,
      }));
    } catch { /* private mode/storage pressure must never block the app */ }
  }

  function readMeSnapshot() {
    try {
      const snapshot = JSON.parse(localStorage.getItem('pp_me_snapshot_v1') || 'null');
      if (!snapshot || snapshot.v !== 1 || snapshot.tokenHint !== tokenHint()
          || !snapshot.data || !snapshot.data.user
          || Date.now() - Number(snapshot.savedAt || 0) > 30 * 86400000) return null;
      return snapshot;
    } catch { return null; }
  }

  // A cached account payload is useful offline, but its live-game banner is an
  // action surface. Never resurrect an at-court/just-started game after its
  // short live window has passed. Future games and unresolved score reviews
  // remain useful because their server state has no equivalent time expiry.
  function activeGameFromSnapshot(game, savedAt, now = Date.now()) {
    if (!game || typeof game !== 'object') return null;
    const saved = Number(savedAt || 0);
    const snapshotAge = saved > 0 ? Math.max(0, now - saved) : Infinity;
    const scheduledAt = new Date(game.scheduled_at || '').getTime();
    const liveLike = ['live', 'assembling', 'ready'].includes(game.banner_state);
    if (liveLike && (snapshotAge > 10 * 60_000
        || !Number.isFinite(scheduledAt) || now > scheduledAt + 4 * 3_600_000)) return null;
    if (game.status === 'upcoming' && Number.isFinite(scheduledAt)
        && now > scheduledAt + 4 * 3_600_000) return null;
    return game;
  }

  function invalidateMeRequests() {
    meRequestGeneration += 1;
    return meRequestGeneration;
  }

  function notificationTarget(notification) {
    const n = notification || {};
    const actionRoute = safeNotificationOverlayRoute(n.action_url);
    if (actionRoute) return { type: 'route', ...actionRoute };
    const matchId = Number(n.related_match_id || n.match_id || 0) || null;
    if (n.related_crew_id) return { type: 'crew', id: n.related_crew_id };
    if (n.related_league_id) return { type: 'league', id: n.related_league_id, matchId };
    if (n.related_club_id) return { type: 'club', id: n.related_club_id };
    if (n.related_tournament_id) return { type: 'tournament', id: n.related_tournament_id, matchId };
    if (n.related_game_id) return { type: 'game', id: n.related_game_id };
    if (n.related_user_id && ['direct_message', 'friend_request', 'friend_accept', 'friend_checkin', 'player_coming'].includes(n.kind)) {
      return { type: 'user', id: n.related_user_id, directMessage: n.kind === 'direct_message' };
    }
    if (n.kind === 'streak_nag' || n.kind === 'session_rsvp') return { type: 'tab', id: 'play' };
    if (['weekly_recap', 'badge_earned', 'business_claim', 'business_integration'].includes(n.kind)) {
      return { type: 'tab', id: 'profile' };
    }
    return null;
  }

  function openNotificationTarget(notification) {
    const target = notificationTarget(notification);
    if (!target) { openActivity(); return; }
    if (target.type === 'route') { navigateOverlayRoute(target); return; }
    if (target.type === 'tab') { switchTab(target.id); return; }
    if (target.type === 'game') { openGameScreen(Number(target.id)); return; }
    if (target.type === 'tournament') { openTournamentScreen(Number(target.id), target.matchId); return; }
    if (target.type === 'league') { openLeagueScreen(Number(target.id), target.matchId); return; }
    if (target.type === 'crew') { openCrewScreen(Number(target.id)); return; }
    if (target.type === 'club') { openClubScreen(Number(target.id)); return; }
    if (target.type === 'court') { openCourtDetail(Number(target.id)); return; }
    if (target.directMessage) openThread(Number(target.id));
    else openUserProfile(Number(target.id));
  }

  function applyMe(data, {
    persist = true,
    provisional = false,
    reconcileSnapshot = false,
    fromRefresh = false,
  } = {}) {
    // Mutation/login/snapshot responses are authoritative and retire any
    // slower /me request that began against the state they replaced.
    if (!fromRefresh) invalidateMeRequests();
    const hadProvisionalArea = state.snapshotAreaProvisional;
    const previousArea = state.areaLoc ? [...state.areaLoc] : null;
    const previousPresenceView = JSON.stringify([
      !!state.presence?.checked_in,
      state.presence?.court_id || null,
      state.presence?.court_name || '',
    ]);
    const previousPlayPulseView = JSON.stringify([
      state.activePlayPulse?.id || null,
      state.activePlayPulse?.courtId || null,
      state.activePlayPulse?.expiresAt || '',
    ]);
    const previousAccountId = safePositiveId(state.me && state.me.id);
    const nextAccountId = safePositiveId(data.user && data.user.id);
    if (previousAccountId && previousAccountId !== nextAccountId) {
      rallyArrivalInFlight = null;
      playPulseCreateInFlight = null;
      playPulseAcceptInFlight.clear();
      clearRallyArrivalAttempt(previousAccountId);
    }
    state.me = data.user;
    // Catalog of muteable kinds rides alongside the user for the settings UI.
    if (data.muteable_notifications) state.me.muteable_notifications = data.muteable_notifications;
    if (data.mfa && typeof data.mfa === 'object') state.me.mfa = { ...data.mfa };
    if ('operator_role' in data) state.me.operator_role = data.operator_role || '';
    if ('can_review_businesses' in data) state.me.can_review_businesses = data.can_review_businesses === true;
    state.presence = data.presence;
    state.unreadMessages = data.unread_messages || 0;
    if (data.community_room_unread != null) {
      const roomUnread = Number(data.community_room_unread) || 0;
      if (data.community_message_unread != null && data.community_group_unread != null) {
        const messageUnread = Number(data.community_message_unread) || 0;
        const groupUnread = Number(data.community_group_unread) || 0;
        if (messageUnread + groupUnread === roomUnread) {
          state.communityMessageUnread = messageUnread;
          state.communityGroupUnread = groupUnread;
        } else {
          state.communityMessageUnread = 0;
          state.communityGroupUnread = roomUnread;
        }
      } else {
        // Older servers only expose the aggregate. Keep the global badge exact
        // and route the unknown room total to Groups until a lane refresh splits it.
        state.communityMessageUnread = 0;
        state.communityGroupUnread = roomUnread;
      }
      state.communityRoomUnread = roomUnread;
    }
    state.pendingRequests = data.pending_friend_requests || 0;
    if (data.pending_crew_invites && typeof data.pending_crew_invites === 'object') {
      const items = Array.isArray(data.pending_crew_invites.items)
        ? data.pending_crew_invites.items.filter((item) => crewSummaryFrom(item)) : [];
      state.pendingCrewInvites = {
        count: Math.max(items.length, Number(data.pending_crew_invites.count) || 0),
        items,
      };
    }
    state.gamesToConfirm = data.games_to_confirm || 0;

    // Live updates: pop a toast when something new lands while the app is open.
    state.unreadNotifications = data.unread_notifications || 0;
    state.activeGame = data.active_game || null;
    state.activeArrival = normalizeActiveArrival(data.active_arrival);
    if (state.activeArrival && nextAccountId) {
      clearRallyArrivalAttempt(nextAccountId, state.activeArrival.gameId);
    }
    state.activePlayPulse = normalizeActivePlayPulse(data.active_play_pulse);
    if (state.activePlayPulse && nextAccountId) {
      clearPlayPulseCreateAttempt(nextAccountId, state.activePlayPulse.courtId);
    }
    state.activeTournament = data.active_tournament || null;
    state.activeLeague = data.active_league || null;
    state.competitionActionCount = Math.max(
      0, Number(data.competition_actions?.count) || 0,
    );
    const latest = data.latest_notification;
    if (latest) {
      if (state.lastNotifId !== null && latest.id > state.lastNotifId && !latest.read) {
        const coveredByBanner = Boolean(
          latest.related_game_id
            && ((state.activeGame && state.activeGame.id === latest.related_game_id)
              || (state.activeArrival && state.activeArrival.gameId === latest.related_game_id))
          || latest.related_tournament_id
            && state.activeTournament?.id === latest.related_tournament_id
          || latest.related_league_id
            && state.activeLeague?.id === latest.related_league_id,
        );
        if (!coveredByBanner) toast(latest.title, {
          icon: 'bell',
          duration: 6500,
          action: { label: 'Open', onClick: () => openNotificationTarget(latest) },
        });
        if (!state.pushSubscribed && typeof Notification !== 'undefined'
            && Notification.permission === 'granted' && document.hidden) {
          try {
            const notification = new Notification('Third Shot', {
              body: latest.title, icon: '/icon-192.png', tag: `pp-${latest.id}`,
            });
            pageNotifications.add(notification);
            notification.addEventListener('click', () => {
              window.focus();
              openNotificationTarget(latest);
              notification.close();
            }, { once: true });
            notification.addEventListener('close', () => pageNotifications.delete(notification), { once: true });
          } catch { /* not supported */ }
        }
        // Snapshot-first boot already has a fresh initial feed in flight.
        if (state.tab === 'play' && !reconcileSnapshot) renderPlay();
      }
      state.lastNotifId = latest.id;
    } else if (state.lastNotifId === null) {
      state.lastNotifId = 0;
    }

    renderBadges();
    renderPresenceBanner();
    renderActiveGameBanner();
    let areaChanged = false;
    if (provisional && !state.userLoc) {
      state.snapshotAreaProvisional = true;
      state.areaLoc = state.me.home_lat != null
        ? [state.me.home_lat, state.me.home_lng] : null;
    } else if (reconcileSnapshot && hadProvisionalArea && !state.userLoc) {
      const liveArea = state.me.home_lat != null
        ? [state.me.home_lat, state.me.home_lng] : null;
      areaChanged = JSON.stringify(previousArea) !== JSON.stringify(liveArea);
      state.areaLoc = liveArea;
      state.snapshotAreaProvisional = false;
    } else if (state.me.home_lat != null && !state.areaLoc && !state.userLoc) {
      state.areaLoc = [state.me.home_lat, state.me.home_lng];
    }
    updatePlayHeader();
    const nextPresenceView = JSON.stringify([
      !!state.presence?.checked_in,
      state.presence?.court_id || null,
      state.presence?.court_name || '',
    ]);
    const nextPlayPulseView = JSON.stringify([
      state.activePlayPulse?.id || null,
      state.activePlayPulse?.courtId || null,
      state.activePlayPulse?.expiresAt || '',
    ]);
    if (!areaChanged && (previousPresenceView !== nextPresenceView
        || previousPlayPulseView !== nextPlayPulseView)
        && state.tab === 'play' && state.playSeg === 'games'
        && !$('#main-screen').classList.contains('hidden')) {
      // Check-in/out and Free-this-hour state can change in another tab.
      // Reuse cached discovery data while immediately swapping the hero.
      renderPlay({ useCachedData: true });
    }
    if (reconcileSnapshot) {
      if (areaChanged) {
        state.playGamesCache = null;
        state.chatFriendsCache = null;
        clearLookingBanner();
        refreshLookingBanner();
        if (state.map && state.areaLoc) {
          moveCourtMapWithoutRefresh(() => state.map.setView(state.areaLoc, 12, { animate: false }));
        }
        if (state.tab === 'courts' && state.map) {
          beginCourtContextRefresh('Updating courts for your current home area…');
          fetchCourtsInView({ surfaceError: true });
        } else if (state.tab === 'play') renderPlay();
        else if (state.tab === 'chat') renderChat();
      }
      if (state.tab === 'profile') renderProfile({ reuseDashboard: true });
    }
    if (persist) saveMeSnapshot(data);
  }

  function dismissedInvites() {
    try { return JSON.parse(localStorage.getItem('pp_dismissed_invites') || '[]'); }
    catch { return []; }
  }

  function instantRallyAssembly(game) {
    if (!game || !game.is_instant || game.status !== 'upcoming') return null;
    // The server owns whether an instant rally is still recruiting. A rally
    // can remain `upcoming` after play so its participants can enter a score;
    // never turn that durable score-pending row back into a live signal.
    const serverAssemblyState = String(game.assembly_state || '');
    if (game.assembly_active === false || (serverAssemblyState
        && !['finding', 'ready', 'full'].includes(serverAssemblyState))) return null;
    const visibleRosterCount = Array.isArray(game.players) ? game.players.length : 0;
    const aggregateReadyCount = Number(game.ready_count);
    const readyCount = Number.isFinite(aggregateReadyCount)
      ? Math.max(0, aggregateReadyCount) : visibleRosterCount;
    const aggregateRosterCount = Number(game.roster_count);
    const rosterCount = Number.isFinite(aggregateRosterCount)
      ? Math.max(0, aggregateRosterCount) : visibleRosterCount;
    const onWayCount = Math.max(0, Number(game.on_the_way_count) || 0);
    const aggregateCommittedCount = Number(game.committed_count);
    const committedCount = Number.isFinite(aggregateCommittedCount)
      ? Math.max(0, aggregateCommittedCount)
      : Math.max(readyCount, rosterCount) + onWayCount;
    const maxPlayers = Math.max(1, Number(game.max_players) || 4);
    const physicalSpotsLeft = Math.max(0, Number.isFinite(Number(game.physical_spots_left))
      ? Number(game.physical_spots_left) : maxPlayers - readyCount);
    const spotsLeft = Math.max(0, Number.isFinite(Number(game.spots_left))
      ? Number(game.spots_left) : maxPlayers - committedCount);
    const counts = rallyCountsText({
      readyCount, rosterCount, onWayCount, spotsLeft, maxPlayers,
    });
    if (readyCount <= 1) {
      return {
        icon: uiIcon('zap'),
        title: 'Finding players',
        sub: counts,
        banner: `${uiIcon('zap')} Finding players · ${counts}`,
        readyCount, rosterCount, onWayCount, committedCount, maxPlayers,
        physicalSpotsLeft, spotsLeft,
      };
    }
    if (spotsLeft > 0) {
      return {
        icon: uiIcon('pickleball'),
        title: 'Ready to play',
        sub: counts,
        banner: `${uiIcon('pickleball')} Ready to play · ${counts}`,
        readyCount, rosterCount, onWayCount, committedCount, maxPlayers,
        physicalSpotsLeft, spotsLeft,
      };
    }
    if (physicalSpotsLeft > 0 && onWayCount > 0) {
      return {
        icon: uiIcon('map-pin'),
        title: 'Someone’s on the way',
        sub: counts,
        banner: `${uiIcon('map-pin')} Someone’s on the way · ${counts}`,
        readyCount, rosterCount, onWayCount, committedCount, maxPlayers,
        physicalSpotsLeft, spotsLeft,
      };
    }
    return {
      icon: uiIcon('pickleball'),
      title: 'Game full — ready to play',
      sub: counts,
      banner: `${uiIcon('pickleball')} Game full · ${counts}`,
      readyCount, rosterCount, onWayCount, committedCount, maxPlayers,
      physicalSpotsLeft, spotsLeft,
    };
  }

  function instantRallyScorePending(game) {
    return !!(game && game.is_instant && game.status === 'upcoming'
      && game.can_enter_score && Number(game.max_players) <= 4
      && !instantRallyAssembly(game));
  }

  function instantSessionWrapPending(game) {
    return !!(game && game.is_instant && game.status === 'upcoming'
      && game.can_complete_session && Number(game.max_players) > 4
      && !instantRallyAssembly(game));
  }

  function instantRallyClosed(game) {
    if (!game || !game.is_instant || game.status !== 'upcoming'
        || game.can_enter_score || game.can_complete_session) return false;
    const assemblyState = String(game.assembly_state || '');
    return game.assembly_active === false
      || (assemblyState && !['finding', 'ready', 'full'].includes(assemblyState));
  }

  function gameScoreText(game, { includeGames = false } = {}) {
    const rows = Array.isArray(game?.score_games) ? game.score_games : [];
    const score = `${game?.score_team1}–${game?.score_team2}`;
    if (!includeGames || rows.length <= 1) return score;
    return `${score} match · ${rows.map((row) => `${row.score_team1}–${row.score_team2}`).join(', ')}`;
  }

  function renderActiveGameBanner() {
    const el = $('#active-game-banner');
    // Courts is a location-first workspace. Keeping the global game banner
    // docked above its results sheet hides the very court decision a player is
    // trying to make, so active-game context stays on the other primary tabs.
    if (state.tab === 'courts') {
      el.className = 'active-game-banner hidden';
      $('#app').classList.remove('has-banner');
      return;
    }
    const trip = normalizeActiveArrival(state.activeArrival);
    if (state.activeArrival && !trip) state.activeArrival = null;
    if (trip) {
      el.className = 'active-game-banner state-arrival';
      el.innerHTML = `
        <button type="button" class="agb-open" aria-label="${esc(arrivalEtaLabel(trip))} to ${esc(trip.courtName)}. ${esc(rallyCountsText(arrivalRallySummary(trip), { includeOpen: false }))}. ETA shared until ${esc(fmtTimeShort(trip.expiresAt))}; entry is not reserved. View details.">
          <span class="agb-arrival-icon" aria-hidden="true">${uiIcon('map-pin')}</span>
          <span class="agb-main">
            <span class="agb-title">On your way to ${esc(trip.courtName)}</span>
            <span class="agb-sub">${esc(arrivalEtaLabel(trip))} · ${esc(rallyCountsText(arrivalRallySummary(trip), { includeOpen: false }))}</span>
          </span>
        </button>
        <button type="button" class="agb-arrived" id="agb-arrived" aria-label="I’m at ${esc(trip.courtName)}">I’m at the court</button>`;
      el.querySelector('.agb-open').onclick = () => openArrivalDetails(trip);
      el.querySelector('#agb-arrived').onclick = async (event) => {
        event.stopPropagation();
        await confirmArrivalAtCourtAndJoin(trip, {
          button: event.currentTarget,
        });
      };
      el.classList.remove('hidden');
      $('#app').classList.add('has-banner');
      return;
    }
    const game = state.activeGame;
    // A merely-upcoming game yields the slot to a live tournament, or to one
    // starting before it — action states (live/challenge/confirm…) always win.
    const t = state.activeTournament;
    const league = state.activeLeague;
    const leagueActionable = league
      && ['confirm', 'resolve', 'play'].includes(league.banner_state);
    const tournamentWins = t && game && game.banner_state === 'upcoming'
      && (t.banner_state === 'live'
          || new Date(t.starts_at) < new Date(game.scheduled_at));
    const leagueWins = leagueActionable && (!game || game.banner_state === 'upcoming')
      && t?.banner_state !== 'live';
    if (!game || tournamentWins || leagueWins
        || (game.banner_state === 'invited' && dismissedInvites().includes(game.id))) {
      // Live tournaments outrank league work; actionable league work outranks
      // merely upcoming events. A passive league only fills an otherwise empty slot.
      if (t?.banner_state === 'live' && renderTournamentBanner(el)) return;
      if (leagueWins && renderActiveLeagueBanner(el)) return;
      if (renderTournamentBanner(el)) return;
      if (renderActiveLeagueBanner(el)) return;
      el.classList.add('hidden');
      $('#app').classList.remove('has-banner');
      return;
    }
    const court = game.court || {};
    const assembly = instantRallyAssembly(game);
    const stateCfg = assembly && game.banner_state !== 'invited' ? {
      icon: assembly.icon,
      title: `${assembly.title} at ${esc(court.name || 'the court')}`,
      sub: assembly.sub,
    } : {
      challenge: {
        icon: uiIcon('trophy'),
        title: `${esc((game.players[0] || {}).display_name || 'Someone')} challenged you!`,
        sub: `Ranked at ${esc(court.name || 'the court')} · tap to accept or decline`,
      },
      invited: {
        icon: uiIcon('mail'),
        title: `${esc((game.players.find((p) => p.user_id === game.creator_id) || {}).display_name || 'A friend')} invited you to play`,
        sub: game.is_instant
          ? `${esc(court.name || '')} · ${esc(rallyCountsText(rallySummaryFromValue(game)))}`
        : `${gameWhenText(game)} · ${esc(court.name || '')} · ${game.spots_left} spot${game.spots_left === 1 ? '' : 's'} left`,
      },
      live: {
        icon: '<span class="agb-dot"></span>',
        title: `LIVE at ${esc(court.name || 'the court')}`,
        sub: game.players.length >= 2
          ? (Number(game.max_players) > 4
            ? 'Tap to wrap up the session'
            : game.game_type === 'casual'
              ? 'Tap to finish with no score or add one'
              : 'Tap to enter the score')
          : `${game.players.length}/${game.max_players} players — waiting for more`,
      },
      confirm: {
        icon: uiIcon('activity'),
        title: `Confirm the score: ${gameScoreText(game)}`,
        sub: `${esc(game.score_submitted_by_name || 'Opponent')} reported · ${esc(court.name || '')}`,
      },
      waiting: {
        icon: uiIcon('clock'),
        title: `${gameScoreText(game)} sent for confirmation`,
        sub: `Waiting on opponents · ${esc(court.name || '')}`,
      },
      upcoming: {
        icon: uiIcon('calendar'),
        title: `Next play: ${gameWhenText(game)}`,
        sub: `${esc(court.name || '')} · ${game.players.length}/${game.max_players} players`,
      },
    }[game.banner_state] || null;
    if (!stateCfg) {
      el.classList.add('hidden');
      $('#app').classList.remove('has-banner');
      return;
    }

    el.className = `active-game-banner state-${assembly && game.banner_state !== 'invited' ? 'rally' : game.banner_state}`;
    const inviteRally = game.banner_state === 'invited' && game.is_instant
      ? rallySummaryFromValue(game) : null;
    const inviteRallyAction = inviteRally ? rallyActionState(inviteRally) : null;
    const inviteCanAct = !inviteRally || game.is_joined || inviteRallyAction.enabled;
    const inviteActionLabel = inviteRallyAction ? inviteRallyAction.label : 'Join';
    el.innerHTML = `
      <button type="button" class="agb-open">
        ${stateCfg.icon.startsWith('<') ? stateCfg.icon : `<span style="font-size:17px">${stateCfg.icon}</span>`}
        <span class="agb-main">
          <span class="agb-title">${stateCfg.title}</span>
          <span class="agb-sub" aria-live="polite">${stateCfg.sub}</span>
        </span>
        ${game.banner_state === 'invited' ? '' : uiIcon('chevron-right', 'agb-chev')}
      </button>
      ${game.banner_state === 'invited' ? `${inviteCanAct ? `<button type="button" class="agb-join" id="agb-join" aria-label="${esc(inviteActionLabel)} at ${esc(court.name || 'this court')}">${esc(inviteActionLabel)}</button>` : `<span class="agb-unavailable">${esc(inviteActionLabel)}</span>`}<button type="button" class="agb-dismiss" id="agb-dismiss" aria-label="Decline game invite">${uiIcon('x')}</button>` : ''}`;
    const joinBtn = el.querySelector('#agb-join');
    const dismissBtn = el.querySelector('#agb-dismiss');
    if (joinBtn) {
      joinBtn.onclick = async (e) => {
        e.stopPropagation();
        if (game.is_instant) {
          await openReadyRally(inviteRally, joinBtn);
          return;
        }
        const status = el.querySelector('.agb-sub');
        status?.removeAttribute('role');
        const resetAction = beginButtonAction(joinBtn, 'Joining…', [dismissBtn]);
        if (!resetAction) return;
        try {
          const joinedGame = await api(`/games/${game.id}/join`, { method: 'POST' });
          toast("You're in!", { tone: 'success', icon: 'pickleball' });
          state.playGamesCache = null;
          openGameScreen(joinedGame?.id || game.id);
          refreshMe().catch(() => {});
        } catch (err) {
          resetAction();
          if (status) {
            status.textContent = err.message;
            status.setAttribute('role', 'alert');
          }
        }
      };
    }
    if (dismissBtn) {
      dismissBtn.onclick = (e) => {
        e.stopPropagation();
        const ids = dismissedInvites();
        if (!ids.includes(game.id)) ids.push(game.id);
        localStorage.setItem('pp_dismissed_invites', JSON.stringify(ids.slice(-30)));
        renderActiveGameBanner();
        // Tell the host too — best effort; the local dismissal already stuck.
        api(`/games/${game.id}/invites/decline`, { method: 'POST' })
          .then(() => toast("Declined — the host knows you can't make it"))
          .catch(() => toast('Invite dismissed'));
      };
    }
    const openButton = el.querySelector('.agb-open');
    // The banner is navigation, not an implicit mutation workflow. Game
    // detail explains the roster and state first, then exposes score or
    // wrap-up as an explicit action.
    openButton.onclick = () => openGameScreen(game.id);
    $('#app').classList.add('has-banner');
  }

