  // ---------- Live location & auto check-in ----------
  function autoCheckInStorageKey(userId = state.me && state.me.id) {
    return userId ? `pp_auto_checkin:${userId}` : null;
  }

  function autoCheckInEnabled() {
    // The old origin-global preference is intentionally not migrated: on a
    // shared browser, a newly signed-in account must grant its own consent.
    try { localStorage.removeItem('pp_auto_checkin'); } catch { /* unavailable */ }
    const key = autoCheckInStorageKey();
    return !!key && localStorage.getItem(key) === 'on';
  }

  function syncAutoCheckInControls() {
    const enabled = autoCheckInEnabled();
    document.querySelectorAll('#court-auto-checkin, #privacy-auto-checkin').forEach((button) => {
      button.setAttribute(button.getAttribute('role') === 'switch' ? 'aria-checked' : 'aria-pressed', String(enabled));
      button.setAttribute('aria-label', `Auto check-in: ${enabled ? 'On' : 'Off'}`);
      const copy = button.querySelector('[data-switch-copy]');
      if (copy) copy.textContent = enabled ? 'On' : 'Off';
    });
  }

  function setAutoCheckInEnabled(enabled) {
    const key = autoCheckInStorageKey();
    if (!key) return;
    localStorage.setItem(key, enabled ? 'on' : 'off');
    syncAutoCheckInControls();
  }

  function updateUserDot() {
    if (!state.map || !state.userLoc) return;
    const accuracy = Number(state.userAccuracyMeters);
    if (Number.isFinite(accuracy) && accuracy > 0) {
      const radius = Math.max(10, Math.min(accuracy, 5000));
      if (!state.userAccuracyRing) {
        state.userAccuracyRing = L.circle(state.userLoc, {
          radius,
          color: '#1971c2',
          weight: 1,
          opacity: .48,
          fillColor: '#1971c2',
          fillOpacity: .09,
          interactive: false,
        }).addTo(state.map);
      } else {
        state.userAccuracyRing.setLatLng(state.userLoc);
        state.userAccuracyRing.setRadius(radius);
      }
      state.userAccuracyRing.bringToBack?.();
    } else if (state.userAccuracyRing) {
      state.map.removeLayer(state.userAccuracyRing);
      state.userAccuracyRing = null;
    }
    if (!state.userDot) {
      state.userDot = L.circleMarker(state.userLoc, {
        radius: 8, color: '#fff', weight: 3, fillColor: '#1971c2', fillOpacity: 1,
      }).addTo(state.map);
    } else {
      state.userDot.setLatLng(state.userLoc);
    }
  }

  function startLocationWatch() {
    if (!autoCheckInEnabled() || document.hidden || !navigator.geolocation || state.geoWatchId != null) return;
    state.geoWatchId = navigator.geolocation.watchPosition(
      (pos) => {
        state.userLoc = [pos.coords.latitude, pos.coords.longitude];
        state.userAccuracyMeters = Number.isFinite(Number(pos.coords.accuracy))
          ? Math.max(0, Number(pos.coords.accuracy)) : null;
        updateUserDot();
        renderCourtLocationStatus();
        maybeAutoCheckIn();
      },
      (error) => {
        if (Number(error?.code) !== 1) return;
        // A denied permission cannot power the promised feature. Turn the
        // preference back off so foregrounding the app never prompts/nags in
        // a loop; the player can re-enable it after changing browser settings.
        stopLocationWatch();
        setAutoCheckInEnabled(false);
        toast('Auto check-in is off because location access is blocked. Allow location in your browser settings, then turn it on again.', {
          tone: 'warning', duration: 9000,
        });
      },
      // Auto check-in is consequential. Ask for a fresh, higher-quality fix;
      // maybeAutoCheckIn still applies its own conservative accuracy gate.
      { enableHighAccuracy: true, maximumAge: 15000, timeout: 20000 },
    );
  }

  function stopLocationWatch() {
    state.autoCheckCandidateCourtId = null;
    state.autoCheckCandidateSince = 0;
    state.autoCheckoutCourtId = null;
    state.autoCheckoutDepartureFixes = 0;
    if (state.geoWatchId != null && navigator.geolocation) {
      navigator.geolocation.clearWatch(state.geoWatchId);
      state.geoWatchId = null;
    }
  }

  function openAutoCheckInConsent(onChange, { onDismiss } = {}) {
    const modal = openModal(`
      ${modalHead('Auto check-in')}
      <div class="consent-hero" aria-hidden="true">${uiIcon('map-pin')}</div>
      <p style="font-weight:800;margin-bottom:6px">Arrive, play, and let the app handle check-in.</p>
      <p class="row-sub" style="margin-bottom:12px">When Third Shot is open, it can use your location to check you in near a court and check you out after you leave.</p>
      <div class="privacy-note">
        <b>Who can see it?</b>
        <span>${esc(courtPresenceAudience(false))} Your precise live location is never shown.</span>
      </div>
      <button type="button" class="btn btn-primary btn-block" id="auto-checkin-enable" style="margin-top:14px">Allow while the app is open</button>
      <button type="button" class="btn btn-secondary btn-block modal-close" style="margin-top:8px">Not now</button>
    `);
    let resolved = false;
    modal._cleanupFns?.push(() => {
      if (!resolved && onDismiss) queueMicrotask(onDismiss);
    });
    modal.querySelector('#auto-checkin-enable').addEventListener('click', () => {
      if (resolved) return;
      resolved = true;
      setAutoCheckInEnabled(true);
      startLocationWatch();
      toast('Auto check-in is on', { tone: 'success', icon: 'map-pin' });
      dismissModal(modal, onChange);
    });
    if (onDismiss) modal.querySelector('.modal-close').addEventListener('click', (event) => {
      event.stopPropagation();
      if (resolved) return;
      resolved = true;
      dismissModal(modal, onDismiss);
    });
    return modal;
  }

  function maybeOfferAutoCheckInAfterManualCheckIn(court) {
    const userId = safePositiveId(state.me?.id);
    if (!userId || autoCheckInEnabled()) return;
    const key = `pp_auto_checkin_offer:${userId}`;
    if (localStorage.getItem(key) === '1') return;
    localStorage.setItem(key, '1');
    setTimeout(() => {
      if (!state.me || Number(state.me.id) !== userId || autoCheckInEnabled()) return;
      toast(`Want Third Shot to check you in automatically next time you’re at ${court?.name || 'a court'}?`, {
        tone: 'info',
        duration: 10000,
        action: {
          label: 'Set up',
          onClick: () => openAutoCheckInConsent(() => {}),
        },
      });
    }, 650);
  }

  const AUTO_CHECKIN_MILES = 0.09;   // ~150 m: you're at the court
  const AUTO_CHECKOUT_MILES = 0.45;  // you've clearly left
  const AUTO_CHECKIN_MAX_ACCURACY_METERS = 65;
  const AUTO_CHECKOUT_MAX_ACCURACY_METERS = 120;
  const AUTO_CHECKIN_SUSTAIN_MS = 30_000;

  function resetAutoCheckoutDepartureConfirmation() {
    state.autoCheckoutCourtId = null;
    state.autoCheckoutDepartureFixes = 0;
  }

  function milesBetween(a, b) {
    const R = 3958.8;
    const dLat = (b[0] - a[0]) * Math.PI / 180;
    const dLng = (b[1] - a[1]) * Math.PI / 180;
    const s = Math.sin(dLat / 2) ** 2
      + Math.cos(a[0] * Math.PI / 180) * Math.cos(b[0] * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(s));
  }

  function courtPresenceError(code, message) {
    const error = new Error(message);
    error.code = code;
    return error;
  }

  function courtPresenceAudience(looking, visibility = state.me?.nearby_visibility) {
    if (visibility === 'hidden') return 'Your profile stays hidden. Your check-in is included in the court total.';
    if (visibility === 'friends' || !looking) return 'Friends can recognize you. Other people see only the court total.';
    return 'Signed-in players can see your profile while you look for a game. Public visitors see only the total.';
  }

  function courtPresenceSourceText(presence) {
    const source = presence?.location_verified_at ? 'Location confirmed' : 'Self-reported';
    const timestamp = presence?.location_verified_at || presence?.last_confirmed_at;
    const minutes = timestamp ? Math.max(0, Math.floor((Date.now() - new Date(timestamp).getTime()) / 60000)) : null;
    return source + (Number.isFinite(minutes) ? ` · ${minutes < 1 ? 'just now' : `${minutes} min ago`}` : '');
  }

  function courtPresenceSummaryText(summary) {
    if (!summary) return '';
    const parts = [];
    if (summary.location_confirmed) parts.push(`${summary.location_confirmed} location confirmed`);
    if (summary.self_reported) parts.push(`${summary.self_reported} self-reported`);
    const minutes = summary.updated_at ? Math.max(0, Math.floor((Date.now() - new Date(summary.updated_at).getTime()) / 60000)) : null;
    if (parts.length && Number.isFinite(minutes)) parts.push(`updated ${minutes < 1 ? 'just now' : `${minutes} min ago`}`);
    return parts.join(' · ');
  }

  async function freshCourtPresenceLocation(courtValue) {
    const court = playNowCourt(courtValue);
    if (!court) throw courtPresenceError('court_not_found', 'Choose a valid court.');
    if (!navigator.geolocation) {
      throw courtPresenceError(
        'invalid_presence_location',
        'Location is not available on this device. Use Plan for later until you can confirm the court.',
      );
    }
    let target = court;
    if (target.latitude == null || target.longitude == null) {
      const detail = await api(`/courts/${target.id}`);
      target = playNowCourt(detail);
    }
    if (!target || target.latitude == null || target.longitude == null) {
      throw courtPresenceError(
        'court_location_unavailable',
        'This court cannot verify an on-site check-in yet. Use Plan for later or choose another court.',
      );
    }
    const position = await new Promise((resolve, reject) => {
      navigator.geolocation.getCurrentPosition(resolve, (failure) => {
        if (Number(failure?.code) === 1) {
          reject(courtPresenceError(
            'invalid_presence_location',
            'Allow location access to start at this court now. You can still use Plan for later.',
          ));
        } else if (Number(failure?.code) === 3) {
          reject(courtPresenceError(
            'invalid_presence_location',
            'Location took too long. Move into the open and try again, or use Plan for later.',
          ));
        } else {
          reject(courtPresenceError(
            'invalid_presence_location',
            'Couldn’t confirm your location. Try again or use Plan for later.',
          ));
        }
      }, { enableHighAccuracy: true, maximumAge: 0, timeout: 15000 });
    });
    const latitude = Number(position?.coords?.latitude);
    const longitude = Number(position?.coords?.longitude);
    const accuracy = Number(position?.coords?.accuracy);
    if (![latitude, longitude, accuracy].every(Number.isFinite) || accuracy <= 0) {
      throw courtPresenceError(
        'invalid_presence_location',
        'Your device did not return a usable location. Try again with location access on.',
      );
    }
    state.userLoc = [latitude, longitude];
    state.userAccuracyMeters = accuracy;
    updateUserDot();
    renderCourtLocationStatus();
    if (accuracy > AUTO_CHECKIN_MAX_ACCURACY_METERS) {
      throw courtPresenceError(
        'location_accuracy_too_low',
        'Your location is too imprecise to confirm this court. Move into the open, then try again.',
      );
    }
    const conservativeMiles = milesBetween(
      state.userLoc, [target.latitude, target.longitude],
    ) + accuracy / 1609.344;
    if (conservativeMiles > AUTO_CHECKIN_MILES) {
      throw courtPresenceError(
        'court_proximity_mismatch',
        `You’re not close enough to ${target.name} to start now. Use Plan for later until you arrive.`,
      );
    }
    return {
      latitude,
      longitude,
      accuracy_meters: accuracy,
    };
  }

  async function maybeAutoCheckIn() {
    if (!state.me || !state.userLoc) return;
    if (!autoCheckInEnabled()) return;
    const accuracyMeters = Number(state.userAccuracyMeters);
    if (!Number.isFinite(accuracyMeters) || accuracyMeters <= 0) {
      state.autoCheckCandidateCourtId = null;
      state.autoCheckCandidateSince = 0;
      resetAutoCheckoutDepartureConfirmation();
      return;
    }
    const callerSession = instantRallySession();
    if (!callerSession) return;
    const callerLocation = [Number(state.userLoc[0]), Number(state.userLoc[1])];
    const requestIsCurrent = () => instantRallySessionMatches(callerSession)
      && Array.isArray(state.userLoc)
      && Number(state.userLoc[0]) === callerLocation[0]
      && Number(state.userLoc[1]) === callerLocation[1];
    const now = Date.now();

    const presence = state.presence;
    if (presence && presence.checked_in) {
      state.autoCheckCandidateCourtId = null;
      state.autoCheckCandidateSince = 0;
      // Check out only after two consecutive, accurate fixes put even the
      // nearest possible edge of the uncertainty circle beyond the boundary.
      if (accuracyMeters <= AUTO_CHECKOUT_MAX_ACCURACY_METERS
          && presence.court_latitude != null) {
        const distance = milesBetween(
          state.userLoc, [presence.court_latitude, presence.court_longitude],
        );
        const nearestPossibleDistance = distance - accuracyMeters / 1609.344;
        if (nearestPossibleDistance > AUTO_CHECKOUT_MILES) {
          const courtId = Number(presence.court_id);
          if (state.autoCheckoutCourtId !== courtId) {
            state.autoCheckoutCourtId = courtId;
            state.autoCheckoutDepartureFixes = 0;
          }
          state.autoCheckoutDepartureFixes += 1;
          if (state.autoCheckoutDepartureFixes < 2) return;
          resetAutoCheckoutDepartureConfirmation();
          try {
            await api('/checkout', { method: 'POST' });
            if (!requestIsCurrent()) return;
            toast(`Auto checked out of ${presence.court_name}`, { icon: 'map-pin' });
            await refreshMe();
            if (!requestIsCurrent()) return;
            fetchCourtsInView();
          } catch { /* ignore */ }
        } else {
          resetAutoCheckoutDepartureConfirmation();
        }
      } else {
        resetAutoCheckoutDepartureConfirmation();
      }
      return;
    }
    resetAutoCheckoutDepartureConfirmation();
    if (now - (state.lastAutoCheckAt || 0) < 45000) return;
    state.lastAutoCheckAt = now;

    // A coarse network-derived location can easily place someone at a nearby
    // park. Never turn that into a public presence signal.
    if (accuracyMeters > AUTO_CHECKIN_MAX_ACCURACY_METERS) {
      state.autoCheckCandidateCourtId = null;
      state.autoCheckCandidateSince = 0;
      return;
    }

    try {
      const data = await api(`/courts?lat=${callerLocation[0]}&lng=${callerLocation[1]}&radius=1&limit=3`);
      if (!requestIsCurrent()) return;
      const nearest = data.items[0];
      // Include the uncertainty radius: the entire reported accuracy circle
      // must fit inside the arrival threshold, not merely its center point.
      const conservativeDistance = nearest && nearest.distance_miles != null
        ? Number(nearest.distance_miles) + accuracyMeters / 1609.344 : Infinity;
      if (nearest && conservativeDistance <= AUTO_CHECKIN_MILES) {
        if (state.autoCheckCandidateCourtId !== Number(nearest.id)) {
          state.autoCheckCandidateCourtId = Number(nearest.id);
          state.autoCheckCandidateSince = now;
          return;
        }
        if (now - state.autoCheckCandidateSince < AUTO_CHECKIN_SUSTAIN_MS) return;
        await api(`/courts/${nearest.id}/checkin`, {
          method: 'POST',
          body: JSON.stringify({
            looking_for_game: false,
            presence_intent: 'auto_checkin',
            presence_location: {
              latitude: callerLocation[0],
              longitude: callerLocation[1],
              accuracy_meters: accuracyMeters,
            },
          }),
        });
        if (!requestIsCurrent()) return;
        state.autoCheckCandidateCourtId = null;
        state.autoCheckCandidateSince = 0;
        toast(`Auto checked in at ${nearest.name}`, { tone: 'success', icon: 'map-pin' });
        await refreshMe();
        if (!requestIsCurrent()) return;
        fetchCourtsInView();
      } else {
        state.autoCheckCandidateCourtId = null;
        state.autoCheckCandidateSince = 0;
      }
    } catch { /* offline */ }
  }

  function compactCourtFact(value, maximum = 34) {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (!text || text.length <= maximum) return text;
    return `${text.slice(0, Math.max(1, maximum - 1)).trimEnd()}…`;
  }

  const COURT_WEEKDAY_LABELS = {
    mon: 'Mon', tue: 'Tue', wed: 'Wed', thu: 'Thu', fri: 'Fri', sat: 'Sat', sun: 'Sun',
  };

  function courtOpenPlayRows(court) {
    if (!Array.isArray(court?.open_play_schedule_rows)) return [];
    return court.open_play_schedule_rows.filter((row) => (
      row && COURT_WEEKDAY_LABELS[row.weekday]
      && /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(row.start || '')
      && /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(row.end || '')
    ));
  }

  function courtClockLabel(value) {
    const [hourText, minute = '00'] = String(value || '').split(':');
    const hour = Number(hourText);
    if (!Number.isInteger(hour) || hour < 0 || hour > 23) return '';
    const suffix = hour >= 12 ? 'PM' : 'AM';
    const face = hour % 12 || 12;
    return { face: `${face}${minute === '00' ? '' : `:${minute}`}`, suffix };
  }

  function courtTimeRangeLabel(start, end) {
    const from = courtClockLabel(start);
    const to = courtClockLabel(end);
    if (!from || !to) return '';
    return from.suffix === to.suffix
      ? `${from.face}–${to.face} ${to.suffix}`
      : `${from.face} ${from.suffix}–${to.face} ${to.suffix}`;
  }

  function courtOpenPlayRowLabel(row, { includeDay = true, includeNotes = true } = {}) {
    const parts = [];
    if (includeDay) parts.push(COURT_WEEKDAY_LABELS[row.weekday]);
    parts.push(courtTimeRangeLabel(row.start, row.end));
    if (row.level) parts.push(row.level);
    if (row.cost) parts.push(row.cost);
    if (includeNotes && row.notes) parts.push(row.notes);
    return parts.filter(Boolean).join(' · ');
  }

  function nextCourtOpenPlayStart(row, now = new Date(), timeZone = null) {
    const weekdayIndex = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
    const targetDay = weekdayIndex[row?.weekday];
    const match = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(row?.start || ''));
    if (targetDay == null || !match || !Number.isFinite(now.getTime())) return null;
    if (timeZone) {
      try {
        const formatter = new Intl.DateTimeFormat('en-US', {
          timeZone, calendar: 'gregory', numberingSystem: 'latn', hourCycle: 'h23',
          year: 'numeric', month: '2-digit', day: '2-digit',
          hour: '2-digit', minute: '2-digit', second: '2-digit',
        });
        const parts = (date) => Object.fromEntries(formatter.formatToParts(date)
          .filter((part) => part.type !== 'literal').map((part) => [part.type, Number(part.value)]));
        const stamp = (value) => Date.UTC(value.year, value.month - 1, value.day, value.hour, value.minute, value.second);
        const today = parts(now);
        const localDate = new Date(Date.UTC(today.year, today.month - 1, today.day));
        localDate.setUTCDate(localDate.getUTCDate() + ((targetDay - localDate.getUTCDay() + 7) % 7));
        for (let week = 0; week < 3; week++) {
          const desired = Date.UTC(localDate.getUTCFullYear(), localDate.getUTCMonth(), localDate.getUTCDate(), Number(match[1]), Number(match[2]));
          // Offsets on either side of the target cover clock changes, including
          // half-hour changes. Verify the wall clock instead of shifting a gap.
          const offsets = new Set([-48, -24, 0, 24, 48].map((hours) => {
            const sample = desired + hours * 3600000;
            return stamp(parts(new Date(sample))) - sample;
          }));
          const candidates = [...offsets].map((offset) => desired - offset)
            .filter((instant) => stamp(parts(new Date(instant))) === desired).sort((a, b) => a - b);
          // Match recurrence generation: first occurrence in a fall-back fold;
          // skip a nonexistent spring-forward time rather than changing it.
          if (candidates.length && candidates[0] > now.getTime()) return new Date(candidates[0]);
          localDate.setUTCDate(localDate.getUTCDate() + 7);
        }
        return null;
      } catch { return null; }
    }
    const start = new Date(now);
    start.setSeconds(0, 0);
    start.setDate(start.getDate() + ((targetDay - start.getDay() + 7) % 7));
    start.setHours(Number(match[1]), Number(match[2]), 0, 0);
    if (start.getTime() <= now.getTime()) start.setDate(start.getDate() + 7);
    return start;
  }

  function courtOpenPlayDuration(row) {
    const minutes = (value) => {
      const match = /^(\d{2}):(\d{2})$/.exec(String(value || ''));
      return match ? Number(match[1]) * 60 + Number(match[2]) : null;
    };
    const start = minutes(row?.start);
    const end = minutes(row?.end);
    if (start == null || end == null) return 90;
    const difference = (end - start + 24 * 60) % (24 * 60);
    return Math.max(30, Math.min(8 * 60, difference || 90));
  }

  function courtTodayKey(court) {
    const timezone = court?.structured_hours?.timezone;
    try {
      return new Intl.DateTimeFormat('en-US', {
        weekday: 'short', ...(timezone ? { timeZone: timezone } : {}),
      }).format(new Date()).slice(0, 3).toLowerCase();
    } catch {
      return ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][new Date().getDay()];
    }
  }

  function courtOpenPlayTodayFact(court, maximum = 54) {
    const rows = courtOpenPlayRows(court);
    if (!rows.length) return null;
    const today = rows.filter((row) => row.weekday === courtTodayKey(court));
    return {
      label: today.length
        ? compactCourtFact(today.length===1 ? courtTimeRangeLabel(today[0].start,today[0].end) : `${today.length} times today`, maximum)
        : 'None scheduled today',
      raw: today.length
        ? today.map((row) => courtOpenPlayRowLabel(row, { includeDay: false })).join('; ')
        : 'No recurring open play is scheduled today.',
      hasToday: today.length > 0,
    };
  }

  function courtOpenPlayScheduleHtml(court) {
    const order = Object.keys(COURT_WEEKDAY_LABELS);
    const rows = courtOpenPlayRows(court).sort((a, b) => (
      order.indexOf(a.weekday) - order.indexOf(b.weekday)
      || String(a.start).localeCompare(String(b.start))
    ));
    if (!rows.length) return '';
    return `
      <div class="cd-open-play-schedule" aria-label="Recurring open-play schedule">
        <div class="row-title section-label-icon">${uiIcon('calendar')} Community-verified open play</div>
        ${rows.map((row, index) => {
          const details = [row.level, row.cost, row.notes].filter(Boolean).join(' · ');
          return `<div class="cd-open-play-row"><span><b>${esc(`${COURT_WEEKDAY_LABELS[row.weekday]} · ${courtTimeRangeLabel(row.start, row.end)}`)}</b>${details ? `<span>${esc(details)}</span>` : ''}</span><button type="button" class="btn btn-secondary btn-sm" data-plan-open-play="${index}" data-open-play-day="${row.weekday}" data-open-play-start="${row.start}">${uiIcon('plus')} Plan to go with others</button></div>`;
        }).join('')}
        ${court.open_play_schedule ? `<p class="cd-open-play-note"><b>General note:</b> ${esc(court.open_play_schedule)}</p>` : ''}
      </div>`;
  }

  function courtFeeFact(value) {
    const fees = String(value || '').trim();
    if (!fees) return '';
    if (/^free\b/i.test(fees)) return 'Free';
    if (/^members? only\b/i.test(fees)) return 'Members only';
    if (/^private\b/i.test(fees)) return 'Private';
    if (/^fee required\b/i.test(fees)) return 'Fee required';
    return compactCourtFact(fees, 28);
  }

  function courtVisitHoursHtml(court) {
    if (court.hours_dawn_to_dusk) return '<p>Dawn to dusk</p>';
    const schedule = court.structured_hours || {};
    const validClock = (value) => /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value || '');
    const rows = Object.entries(COURT_WEEKDAY_LABELS).map(([day, label]) => {
      const raw = schedule[day];
      const windows = (Array.isArray(raw) ? raw : [raw])
        .filter((window) => window && validClock(window.open) && validClock(window.close))
        .map((window) => window.open === window.close ? '24 hours'
          : `${courtTimeRangeLabel(window.open, window.close)}${window.close < window.open ? ' (next day)' : ''}`);
      return { label, windows, closed: Array.isArray(raw) && !raw.length };
    });
    if (!rows.some((row) => row.windows.length || row.closed)) {
      return `<p>${esc(court.hours || 'Hours have not been listed yet.')}</p>`;
    }
    return `<dl class="court-visit-hours">${rows.map((row) => `<div><dt>${esc(row.label)}</dt><dd>${esc(row.windows.join(' · ') || (row.closed ? 'Closed' : 'Not listed'))}</dd></div>`).join('')}</dl>
      ${Object.keys(schedule.exceptions || {}).length ? `<div class="court-hours-exceptions"><b>Special dates</b>${Object.entries(schedule.exceptions).sort(([a],[b])=>a.localeCompare(b)).map(([on,windows])=>`<p>${esc(on)} · ${esc(windows.length ? windows.map(row=>courtTimeRangeLabel(row.open,row.close)).join(' · ') : 'Closed')}</p>`).join('')}</div>` : ''}
      ${schedule.timezone ? `<p class="row-sub">Times at the court · ${esc(String(schedule.timezone).replaceAll('_', ' '))}</p>` : ''}
      ${court.hours ? `<p class="court-visit-note">${esc(court.hours)}</p>` : ''}`;
  }

  function courtTimelineDate(value) {
    return new Date(`${value}T12:00:00`).toLocaleDateString([], {month:'short',day:'numeric'});
  }

  function courtTimelineQuery(from='', to='') {
    const query = new URLSearchParams({viewer_timezone:Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'});
    if (from) query.set('from',from);
    if (to) query.set('to',to);
    return `?${query}`;
  }

  function courtTimelineDay(item, now=new Date()) {
    const zone = item.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
    const on = item.starts_at ? calendarDateInTimeZone(new Date(item.starts_at),zone) : item.event_date;
    if (on === calendarDateInTimeZone(now,zone)) return 'Today';
    const next = new Date(`${calendarDateInTimeZone(now,zone)}T12:00:00Z`);
    next.setUTCDate(next.getUTCDate()+1);
    if (on === next.toISOString().slice(0,10)) return 'Tomorrow';
    return courtTimelineDate(on);
  }

  function courtTimelineZoneLabel(timezone) {
    try {
      return new Intl.DateTimeFormat([], {timeZone:timezone,timeZoneName:'longGeneric'})
        .formatToParts(new Date()).find(part=>part.type==='timeZoneName')?.value || timezone;
    } catch { return String(timezone || 'UTC').replaceAll('_',' '); }
  }

  function courtTimelineTime(item) {
    const row = item.schedule || item.window || {};
    if (item.starts_at) {
      try { return new Date(item.starts_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit',...(item.timezone ? {timeZone:item.timezone,...(item.timezone !== Intl.DateTimeFormat().resolvedOptions().timeZone ? {timeZoneName:'short'} : {})} : {})}); } catch { return fmtTimeShort(item.starts_at); }
    }
    return businessTimeLabel(row.start_time || row.start) || 'Time not listed';
  }

  function courtTimelineItemHtml(item, {compact=false, mapPreview=false} = {}) {
    const game = item.game || {}, row = item.schedule || item.window || {};
    const sourceLabel = item.source_label + (item.source!=='player' && !item.timezone ? ' · Local court time' : '');
    const status = item.status === 'cancelled' ? 'Cancelled' : item.status === 'sold_out' ? 'Full' : '';
    const facts = item.source === 'player'
      ? [game.game_type === 'ranked' ? 'Ranked match' : Number(game.max_players)>4 ? 'Pickup session' : 'Casual match', gameLevelRangeLabel(game), game.is_joined ? 'You’re going' : game.spots_left > 0 ? `${game.spots_left} spot${game.spots_left===1 ? '' : 's'} left` : 'Full', game.cost_cents == null ? null : Number(game.cost_cents) === 0 ? 'Free' : `$${(Number(game.cost_cents)/100).toFixed(2)} per player`]
      : [row.skill_level || row.level, row.price_text || row.cost, row.availability_label || (item.source === 'venue' ? 'Check availability with venue' : '')];
    const booking = item.action === 'external' ? businessActionHref(row.booking_url) : '';
    const action = item.action === 'open_session' ? `<button type="button" class="btn ${!game.is_joined && !(game.spots_left>0) ? 'btn-secondary' : 'btn-primary'} btn-sm" data-court-timeline-game="${game.id}">${esc(item.action_label)}</button>`
      : item.action === 'plan' ? `<button type="button" class="btn btn-secondary btn-sm" data-court-timeline-plan="${esc(item.key)}">Plan to go</button>`
      : booking ? `<a class="btn btn-primary btn-sm" href="${esc(booking)}" target="_blank" rel="noopener"${businessTrackingAttributes('booking',row)}>${esc(item.action_label || 'Register externally')}${uiIcon('link')}<small>${esc(new URL(booking).hostname)}</small></a>`
      : `<span class="court-timeline-status">${esc(status || (item.hours_conflict ? 'Check court hours' : 'Registration details not listed'))}</span>`;
    if (mapPreview) return `<article class="court-map-next"><div class="court-map-next-copy"><small>Next · ${esc(courtTimelineDay(item))} · ${esc(courtTimelineTime(item))}</small><b>${esc(item.title)}</b><span>${esc(sourceLabel)} · ${facts.filter(Boolean).map(esc).join(' · ')}</span></div><div class="court-map-next-action">${action}</div></article>`;
    if (!compact) {
      const availability = item.source === 'player' ? (game.is_joined ? 'Joined' : game.spots_left > 0 ? `${game.spots_left} spot${game.spots_left===1 ? '' : 's'} left` : 'Full') : status;
      const details = item.source === 'player' ? facts.filter((_,index)=>index!==2) : facts;
      const names = (game.players || []).slice(0,3).map(player=>player.display_name).filter(Boolean);
      return `<article class="court-timeline-item court-timeline-card is-${esc(item.source)}${status ? ' is-unavailable' : ''}"><div class="court-timeline-card-top"><time class="court-timeline-time"${item.starts_at ? ` datetime="${esc(item.starts_at)}"` : ''}>${esc(courtTimelineTime(item))}</time>${availability ? `<span class="court-timeline-availability${item.source==='player' && (game.is_joined || game.spots_left>0) ? ' has-space' : ''}${item.source==='player' && game.is_joined ? ' is-joined' : ''}">${esc(availability)}</span>` : ''}</div><div class="court-timeline-content"><h4>${esc(item.title)}</h4><span class="court-timeline-source">${esc(sourceLabel)}</span><p>${details.filter(Boolean).map(esc).join(' · ')}</p>${names.length ? `<p>${esc(names.join(', '))}${game.players.length>names.length ? ` +${game.players.length-names.length}` : ''}</p>` : ''}${item.hours_warning ? `<p class="court-timeline-warning">${uiIcon('alert-triangle')}${esc(item.hours_warning)}</p>` : ''}${item.source==='community' ? '<small>Player plan only. Venue registration is separate.</small>' : ''}${action}</div></article>`;
    }
    return `<article class="court-timeline-item is-${esc(item.source)}${status ? ' is-unavailable' : ''}"><div class="court-timeline-time">${esc(courtTimelineTime(item))}<small>${esc(courtTimelineDay(item))}</small></div><div class="court-timeline-content"><span class="court-timeline-source">${esc(sourceLabel)}</span><h4>${esc(item.title)}</h4><p>${facts.filter(Boolean).map(esc).join(' · ')}</p>${item.hours_warning ? `<p class="court-timeline-warning">${uiIcon('alert-triangle')}${esc(item.hours_warning)}</p>` : ''}${action}</div></article>`;
  }

  const COURT_OPEN_PLAY_PLAN_SOURCE = 'Player plan for community-listed open play.';

  function courtOpenPlayPlanDescription(court, row) {
    const visiting = court.visitor_info || {};
    const entry = [COURT_OPEN_PLAY_PLAN_SOURCE, 'Joining does not register you with the venue or reserve court space.',
      ['reservation','both'].includes(visiting.play_access) ? 'Book or register with the venue separately when required.' : 'Check the court’s current entry rules before going.',
      visiting.access_type === 'members' ? 'Venue membership or guest eligibility may be required.' : visiting.access_type === 'fee' ? 'Venue entry fees may apply.' : '',
      row.cost ? `Community-listed play cost: ${String(row.cost).slice(0,100)}.` : '',
    ].filter(Boolean).join(' ');
    return [entry, String(row.notes || '').trim()].filter(Boolean).join('\n\n').slice(0,1000);
  }

  function courtEntryDescriptionParts(game) {
    const description = String(game.description || '');
    if (!description.startsWith(COURT_OPEN_PLAY_PLAN_SOURCE)) return {entry:'',note:description};
    const [entry,...notes] = description.split(/\n\s*\n/);
    return {entry,note:notes.join('\n\n')};
  }

  function courtEntryNoticeHtml(game) {
    const {entry} = courtEntryDescriptionParts(game);
    return entry ? `<section class="court-entry-notice" aria-label="Venue entry requirements"><b>Plan together · venue entry is separate</b><p>${esc(entry)}</p></section>` : '';
  }

  function openCourtWindowPlan(court, item, parent) {
    const row = item.window || {};
    const venueAccess = court.visitor_info?.play_access;
    const open = opener => parent ? openChildModal(parent, opener) : opener();
    const sheet = open(() => openModal(`${modalHead('Plan to go with others')}<p><b>${esc(court.name)}</b><br />${esc(courtTimelineDate(item.event_date))} · ${esc(businessTimeLabel(row.start))}–${esc(businessTimeLabel(row.end))}</p><p class="simple-note">This creates a player plan. ${venueAccess === 'reservation' || venueAccess === 'both' ? 'Book or register with the venue separately when required.' : 'Venue entry rules and fees still apply.'} ${esc(row.cost || '')}</p>${!item.timezone ? `<label class="form-field">Confirm the court’s time zone<select id="court-plan-timezone">${window.VenueWorkspace.timezoneOptions('')}</select></label>` : ''}<p class="form-error hidden" role="alert"></p><button type="button" class="btn btn-primary btn-block" data-create-court-plan>Continue to player plan</button>`, {label:'Plan a visit with other players'}));
    sheet.querySelector('[data-create-court-plan]').addEventListener('click', async () => {
      const zone = item.timezone || sheet.querySelector('#court-plan-timezone')?.value;
      const anchor = new Date(Date.parse(`${item.event_date}T00:00:00Z`)-36*3600e3);
      const start = zone ? nextCourtOpenPlayStart(row,anchor,zone) : null;
      const error=sheet.querySelector('[role=alert]');
      if (!start || calendarDateInTimeZone(start,zone)!==item.event_date) { error.textContent='Confirm the venue time zone to plan this date correctly.';error.classList.remove('hidden');return; }
      const button = sheet.querySelector('[data-create-court-plan]');
      button.disabled=true;button.textContent='Checking this date…';error.classList.add('hidden');
      try {
        const fresh = await api(`/courts/${court.id}/play${courtTimelineQuery(item.event_date,item.event_date)}`);
        if (!sheet.isConnected) return;
        const listed = (fresh.items || []).find(value => value.source==='community' && value.window?.weekday===row.weekday && value.window?.start===row.start);
        if (!listed || listed.hours_conflict) throw new Error(listed?.hours_warning || 'This time is no longer listed. Check the court schedule before making a plan.');
        openChildModal(sheet, () => openNewGameModal({court,gameType:'casual',lockGameType:true,sessionMode:true,maxPlayers:8,scheduledAt:listed.starts_at || start.toISOString(),durationMinutes:courtOpenPlayDuration(listed.window),title:'Open play together',description:courtOpenPlayPlanDescription(court,listed.window),sourceLabel:'Plan to go · venue entry is separate'}));
      } catch(failure) { if(sheet.isConnected){error.textContent=failure.message;error.classList.remove('hidden');} }
      finally { if(sheet.isConnected){button.disabled=false;button.textContent='Continue to player plan';} }
    });
    return sheet;
  }

  function bindCourtTimelineActions(root, court, items, parent) {
    root.querySelectorAll('[data-court-timeline-game]').forEach(button=>button.addEventListener('click',()=>{
      if (parent) parent._courtTimelineReturnFocus = courtTimelineControlSelector(button);
      const open = () => openGameScreen(Number(button.dataset.courtTimelineGame), { returnFocus:button });
      return parent ? openChildModal(parent,open) : open();
    }));
    root.querySelectorAll('[data-court-timeline-plan]').forEach(button=>button.addEventListener('click',()=>{const item=items.find(row=>row.key===button.dataset.courtTimelinePlan);if(item){if(parent)parent._courtTimelineReturnFocus=courtTimelineControlSelector(button);openCourtWindowPlan(court,item,parent);}}));
    bindBusinessActionTracking(root,null);
  }

  async function loadCourtNextOpportunity(slot, court, {mapPreview=false} = {}) {
    if (!slot || slot.dataset.loading) return;
    slot.dataset.loading = 'true';
    slot.innerHTML = '<p class="row-sub" role="status">Finding the next session…</p>';
    try {
      const data = await api(`/courts/${court.id}/play${courtTimelineQuery()}`);
      if (!slot.isConnected) return;
      const item = (data.items || []).find(row => row.status !== 'cancelled' && row.status !== 'sold_out' && row.action !== 'none');
      slot.innerHTML = item ? (mapPreview ? courtTimelineItemHtml(item,{compact:true,mapPreview:true}) : `<span class="court-next-label">Next up</span>${courtTimelineItemHtml(item,{compact:true})}`)
        : `<p class="row-sub">${data.closed ? 'Court marked closed' : 'No dated play listed in the next 7 days'}</p>`;
      bindCourtTimelineActions(slot,court,item ? [item] : [],null);
      syncCourtDockLayout();
    } catch {
      if (!slot.isConnected) return;
      slot.innerHTML = '<p class="row-sub">Next session unavailable.</p><button type="button" class="btn-link" data-next-retry>Retry schedule</button>';
      slot.querySelector('[data-next-retry]').addEventListener('click',()=>{delete slot.dataset.loading;loadCourtNextOpportunity(slot,court,{mapPreview});});
    }
  }

  function courtTimelineControlSelector(node) {
    for (const name of ['data-court-timeline-game','data-court-timeline-plan','data-timeline-prev','data-timeline-next','data-timeline-today','data-timeline-create','data-timeline-retry']) {
      if (node?.hasAttribute?.(name)) return `[${name}="${CSS.escape(node.getAttribute(name))}"]`;
    }
    return '';
  }

  function loadCourtTimeline(modal,court) {
    const root=modal.querySelector('#cd-play-here');if(!root)return;
    let generation=0, from='', latest=null;
    const load=async(newFrom='', {quiet=false,focus=''}={})=>{
      const seq=++generation;from=newFrom;
      let returnFocus = focus || (root.contains(document.activeElement) ? courtTimelineControlSelector(document.activeElement) : '');
      const captureFocus = () => {
        if (root.contains(document.activeElement)) returnFocus = courtTimelineControlSelector(document.activeElement) || 'h3';
      };
      const restoreFocus = () => requestAnimationFrame(() => {
        if (returnFocus && root.isConnected && seq===generation && !modal.closest('[inert]')
            && (document.activeElement===document.body || document.activeElement===modal.querySelector('.modal'))) {
          (root.querySelector(returnFocus) || root.querySelector('h3'))?.focus({preventScroll:true});
        }
      });
      if (!quiet) root.innerHTML='<h3>Coming up here</h3><p role="status">Loading this court’s schedule…</p>';
      root.setAttribute('aria-busy','true');
      try {
        const data=await api(`/courts/${court.id}/play${courtTimelineQuery(from)}`);
        if(!root.isConnected || seq!==generation)return;
        latest=data;
        const groups=new Map();for(const item of data.items || []){if(!groups.has(item.event_date))groups.set(item.event_date,[]);groups.get(item.event_date).push(item);}
        captureFocus();
        const viewerZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        const zoneLabel = data.timezone && data.timezone !== viewerZone ? `Court time · ${courtTimelineZoneLabel(data.timezone)}` : '';
        root.innerHTML=`<div class="court-timeline-heading"><h3 tabindex="-1">Coming up here</h3><button type="button" class="btn-link" data-timeline-create>${uiIcon('plus')}Create game</button></div>${zoneLabel ? `<p class="court-timeline-zone">${esc(zoneLabel)}</p>` : ''}<div class="court-timeline-range"><button type="button" class="btn btn-secondary btn-sm" data-timeline-prev aria-label="Previous week">${uiIcon('arrow-left')}</button><button type="button" class="court-timeline-dates" data-timeline-today aria-label="${esc(courtTimelineDate(data.from))} to ${esc(courtTimelineDate(data.to))}. Back to today"><b>${esc(courtTimelineDate(data.from))} – ${esc(courtTimelineDate(data.to))}</b><small>${from ? 'Back to today' : 'Next 7 days'}</small></button><button type="button" class="btn btn-secondary btn-sm" data-timeline-next aria-label="Next week">${uiIcon('arrow-right')}</button></div><span class="sr-only" role="status">${esc(courtTimelineDate(data.from))} to ${esc(courtTimelineDate(data.to))}</span>${data.closed ? '<p class="simple-note">New play is paused while this court is marked closed. Existing plans remain in My plans.</p>' : groups.size ? [...groups].map(([on,items])=>{const day=new Date(`${on}T12:00:00`);return `<section class="court-timeline-day${courtTimelineDay(items[0])==='Today' ? ' is-today' : ''}"><h4><span aria-hidden="true">${esc(day.toLocaleDateString([],{weekday:'short'}))}<b>${day.getDate()}</b></span><span class="sr-only">${esc(day.toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'}))}</span></h4><div>${items.map(item=>courtTimelineItemHtml(item)).join('')}</div></section>`;}).join('') : '<p class="court-timeline-empty">Nothing scheduled this week. Tap Play here to start something.</p>'}${data.undated_count ? '<p class="simple-note">More venue programs below · dates not confirmed.</p>' : ''}${data.has_more ? '<p class="simple-note">Showing the first 200 opportunities in this range.</p>' : ''}`;
        const shift=(days,focus)=>{const date=new Date(`${data.from}T12:00:00Z`);date.setUTCDate(date.getUTCDate()+days);load(date.toISOString().slice(0,10),{focus});};
        root.querySelector('[data-timeline-prev]').addEventListener('click',()=>shift(-7,'[data-timeline-prev]'));
        root.querySelector('[data-timeline-next]').addEventListener('click',()=>shift(7,'[data-timeline-next]'));
        root.querySelector('[data-timeline-today]').addEventListener('click',()=>load('',{focus:'[data-timeline-today]'}));
        const create=root.querySelector('[data-timeline-create]');create.disabled=data.closed;create.addEventListener('click',()=>openChildModal(modal,()=>openNewGameModal({court})));
        bindCourtTimelineActions(root,court,data.items,modal);
        restoreFocus();
      } catch(error){if(root.isConnected && seq===generation){captureFocus();root.innerHTML=`<h3 tabindex="-1">Coming up here</h3><p role="alert">${esc(error.message || 'The schedule could not load.')}</p><button type="button" class="btn btn-secondary" data-timeline-retry>Retry schedule</button>`;root.querySelector('[data-timeline-retry]').addEventListener('click',()=>load(from,{focus:'h3'}));restoreFocus();}}
      finally{if(root.isConnected && seq===generation)root.removeAttribute('aria-busy');}
    };
    modal._onResume = () => {
      const focus = modal._courtTimelineReturnFocus || '';
      delete modal._courtTimelineReturnFocus;
      return load(from,{quiet:true,focus});
    };
    load();return()=>latest;
  }

  function courtConditionReportsHtml(court) {
    const reports = court.condition_reports || (court.latest_condition ? [court.latest_condition] : []);
    if (!reports.length) return '';
    const mixed = new Set(reports.map(row => row.condition)).size > 1;
    const line = report => {
      const condition = COURT_CONDITION_LABELS[report.condition] || ['alert-triangle',report.condition];
      return `<li><span>${uiIcon(condition[0])}<b>${esc(condition[1])}</b></span><small>${esc(report.user_name || 'Player')} · ${esc(fmtDateTime(report.reported_at))}</small></li>`;
    };
    return `<section class="court-condition-reports"><h4>${mixed ? 'Recent reports differ' : 'Latest player report'}</h4><ul>${line(reports[0])}</ul>${reports.length > 1 ? `<details><summary>${reports.length - 1} other recent report${reports.length === 2 ? '' : 's'}</summary><ul>${reports.slice(1).map(line).join('')}</ul></details>` : ''}<p>Player reports from the last 3 hours. Conditions may change.</p></section>`;
  }

  // How the courts are right now sits at the top of the court page: the
  // latest report helps people decide whether to head over, and sharing one
  // is a single tap instead of a sheet behind the check-in disclosure.
  const COURT_CONDITION_CHIP_LABELS = {
    good: 'All good', busy: 'Busy', wet: 'Wet', nets_down: 'Nets down', closed: 'Closed',
  };
  function courtConditionSummaryHtml(report) {
    const known = report && COURT_CONDITION_LABELS[report.condition];
    if (!known) return '<span>No reports in the last 3 hours.</span>';
    const age = snapshotAgeLabel(Date.parse(report.reported_at)) || 'recently';
    return `${courtConditionIcon(report.condition)}<span><b>${esc(known[1])}</b> · ${esc(report.user_name || 'Player')}, ${esc(age)}</span>`;
  }
  function courtConditionNowHtml(court) {
    const latest = (court.condition_reports || [])[0] || court.latest_condition || null;
    return `<section class="cd-conditions" aria-labelledby="cd-conditions-heading">
      <h3 id="cd-conditions-heading">Courts right now</h3>
      <p class="cd-conditions-summary" id="cd-conditions-summary">${courtConditionSummaryHtml(latest)}</p>
      ${state.token ? `<div class="cd-condition-chips" role="group" aria-label="Tap to report how the courts are right now">
        ${Object.entries(COURT_CONDITION_CHIP_LABELS).map(([key, label]) => `<button type="button" class="cd-condition-chip" data-cd-cond="${key}" aria-pressed="false">${courtConditionIcon(key)}<span>${label}</span></button>`).join('')}
      </div>
      <p class="cd-conditions-status" role="status" aria-live="polite"></p>` : ''}
    </section>`;
  }

  // Busy hours come from 90 days of check-ins and played games. The court
  // page gets one line only when there is a real pattern; the bars live in
  // Before you go › Hours.
  function courtBusyHintHtml(history) {
    return history?.peak ? `<button type="button" class="cd-busy-hint" data-court-visit="hours">${uiIcon('chart')}<span>Usually busiest ${esc(history.peak)}</span>${uiIcon('chevron-right')}</button>` : '';
  }

  function courtBusyBarsHtml(history) {
    if (history?.hours?.length !== 7) return '';
    const {weekday: today, hour} = history.local_now || {}, days = Object.values(COURT_WEEKDAY_LABELS);
    return `<div class="court-busy"><b>Busy times</b>
      <div class="segmented" role="group" aria-label="Day">${days.map((day, i) => `<button type="button" data-busy-day="${i}" aria-label="${day}" aria-pressed="${i === today}"${i === today ? ' class="active"' : ''}>${day[0]}</button>`).join('')}</div>
      ${history.hours.map((levels, i) => {
        const top = Math.max(...levels), at = courtClockLabel(`${levels.indexOf(top) + 5}:00`);
        return `<div class="court-busy-bars" data-busy-bars="${i}" role="img" aria-label="${days[i]}: ${top ? `busiest around ${at.face} ${at.suffix}` : 'no recent activity'}"${i === today ? '' : ' hidden'}>${levels.map((level, h) => `<i style="--lvl:${Number(level) || 0}"${i === today && h + 5 === hour ? ' class="is-now"' : ''}></i>`).join('')}</div>`;
      }).join('')}
      <p class="court-busy-axis" aria-hidden="true"><span>6 AM</span><span>12 PM</span><span>6 PM</span></p>
      <p class="court-visit-source">From ${Number(history.sample_size) || 0} Third Shot check-ins and games · last 90 days</p>
      ${history.timezone_source === 'approximate' ? '<p class="court-visit-source">Times are approximate; this court has no confirmed time zone.</p>' : ''}
    </div>`;
  }

  function bindCourtBusyDays(root) {
    const buttons = [...root.querySelectorAll('[data-busy-day]')];
    buttons.forEach((button) => button.addEventListener('click', () => {
      buttons.forEach((day) => { day.classList.toggle('active', day === button); day.setAttribute('aria-pressed', String(day === button)); });
      root.querySelectorAll('[data-busy-bars]').forEach((row) => { row.hidden = row.dataset.busyBars !== button.dataset.busyDay; });
    }));
  }

  function courtVisitingInfoHtml(court) {
    const facts = court.visitor_info || {}, sources = court.visitor_info_sources || {};
    const order = ['access_type','play_access','guest_access','entrance','parking','accessibility','rotation','court_labels'];
    const keys = [...new Set([...order,...Object.keys(facts)])].filter(key=>facts[key]);
    if (!keys.length) return '<p class="simple-note">Access and arrival details not listed.</p>';
    return ['venue','community'].map(source=>{
      const rows = keys.filter(key=>(sources[key]==='venue' ? 'venue' : 'community')===source);
      if (!rows.length) return '';
      return `<div class="court-visit-source-group"><p class="court-visit-source">${source==='venue' ? 'From the venue' : 'Community information'}</p><dl class="court-visiting-facts">${rows.map(key=>{
        const summary = window.VenueWorkspace.visitingSummary({[key]:facts[key]}), colon = summary.indexOf(':');
        return `<div><dt>${esc(key==='entrance' ? 'Entrance' : summary.slice(0,colon))}</dt><dd>${esc(summary.slice(colon+1).trim())}</dd></div>`;
      }).join('')}</dl></div>`;
    }).join('');
  }

  function courtVisitManagementHtml(court, section = 'fees') {
    const business = court.business;
    if (!state.me || !business || business.preview_only || !(business.is_owner || business.is_manager)) return '';
    const role = String(business.manager_role || (business.is_owner ? 'owner' : 'viewer'));
    const canEdit = ['owner','admin','editor'].includes(role);
    return `<button type="button" class="btn btn-secondary btn-block court-visit-manage" id="court-visit-manage-${section}" data-visit-manage>${uiIcon(canEdit ? 'settings' : 'eye')} ${canEdit ? 'Manage venue details' : 'View venue workspace'}</button>`;
  }

  function courtVisitPanelsHtml(court) {
    const rows = courtOpenPlayRows(court).sort((a,b)=>Object.keys(COURT_WEEKDAY_LABELS).indexOf(a.weekday)-Object.keys(COURT_WEEKDAY_LABELS).indexOf(b.weekday) || a.start.localeCompare(b.start));
    const facilities = [
      [true,court.indoor ? 'home' : 'sun',court.indoor ? 'Indoor courts' : 'Outdoor courts'],
      [Number(court.num_courts)>0,'grid',`${court.num_courts} court${court.num_courts===1 ? '' : 's'}`],
      [court.nets_provided,'net','Nets provided'],[court.has_restrooms,'restroom','Restrooms'],
      [court.has_water,'water','Water'],[court.lighted,'lightbulb','Lights'],
    ].filter(([listed])=>listed);
    const reservation = businessActionHref(court.reservation_url);
    return {
      hours: `<h4 id="court-visit-hours-title" tabindex="-1">Hours</h4><p class="court-visit-source">${court.hours_source === 'venue' ? 'From the venue' : 'Community information'}</p>${courtVisitHoursHtml(court)}${courtBusyBarsHtml(!court.closed && court.checkin_history)}${courtVisitManagementHtml(court,'hours')}`,
      fees: `<h4 id="court-visit-fees-title" tabindex="-1">Fees &amp; access</h4><p class="court-visit-fee">${esc(court.fees || courtFeeTypeFact(court) || 'Fees not listed.')}</p>${reservation ? `<a class="btn btn-secondary btn-block" href="${esc(reservation)}" target="_blank" rel="noopener">${uiIcon('external')} View reservation details</a>` : ''}${courtVisitingInfoHtml(court)}${courtVisitManagementHtml(court)}${state.me && !court.business?.preview_only ? '<button type="button" class="btn-link court-visit-correction" id="court-visit-correction">Update community details</button>' : ''}`,
      facilities: `<h4 id="court-visit-facilities-title" tabindex="-1">Facilities</h4><ul class="court-visit-facilities">${facilities.map(([,icon,label])=>`<li>${uiIcon(icon)}<span>${esc(label)}</span></li>`).join('')}</ul>${court.surface_type ? `<p>${esc(court.surface_type)} surface</p>` : ''}<p class="court-visit-source">Unlisted facilities are not confirmed.</p>`,
      openplay: `<h4 id="court-visit-openplay-title" tabindex="-1">Open play</h4>${rows.length ? `<div class="court-visit-openplay">${rows.map(row=>`<div><b>${esc(`${COURT_WEEKDAY_LABELS[row.weekday]} · ${courtTimeRangeLabel(row.start,row.end)}`)}</b>${row.level || row.cost ? `<p class="row-sub">${esc([row.level,row.cost].filter(Boolean).join(' · '))}</p>` : ''}${row.notes ? `<p>${esc(row.notes)}</p>` : ''}</div>`).join('')}</div>` : ''}${court.open_play_schedule ? `<p>${esc(court.open_play_schedule)}</p>` : !rows.length ? '<p>No open-play schedule listed.</p>' : ''}${rows.length ? '<p class="court-visit-source">Community-listed times · venue entry is separate.</p>' : ''}`,
    };
  }

  function bindCourtVisitTabs(modal, selected) {
    const tabs = [...modal.querySelectorAll('[data-visit-tab]')];
    const activate = (key,{focus=false}={}) => {
      const chosen=tabs.find(tab=>tab.dataset.visitTab===key) || tabs[0];
      if (!chosen || !modal.isConnected) return;
      tabs.forEach(tab=>{const active=tab===chosen;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active ? 0 : -1;});
      modal.querySelectorAll('[data-visit-panel]').forEach(panel=>{panel.hidden=panel.dataset.visitPanel!==chosen.dataset.visitTab;});
      if (focus) chosen.focus({preventScroll:true});
    };
    tabs.forEach((tab,index)=>{
      tab.addEventListener('click',()=>activate(tab.dataset.visitTab));
      tab.addEventListener('keydown',event=>{
        let next;
        if(event.key==='ArrowRight')next=(index+1)%tabs.length;
        if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;
        if(event.key==='Home')next=0;
        if(event.key==='End')next=tabs.length-1;
        if(next===undefined)return;
        event.preventDefault();activate(tabs[next].dataset.visitTab,{focus:true});
      });
    });
    activate(selected);
    requestAnimationFrame(()=>{if(modal.isConnected && !modal.closest('[inert]'))activate(selected,{focus:true});});
  }

  function openCourtVisitSheet(court, section = 'hours', {onUpdated=null} = {}) {
    const ownerId=state.me?.id;
    let listingChanged=false, refreshSeq=0;
    const panels=courtVisitPanelsHtml(court);
    const selected=Object.hasOwn(panels,section) ? section : 'hours';
    const visitLinks = () => {
      const website=businessActionHref(court.business?.website_url || court.website);
      const number=court.business?.phone || court.phone,phone=safeHref(number && `tel:${number}`,{tel:true});
      return `<a class="btn btn-primary btn-block" href="${esc(courtDirectionsUrl(court))}" target="_blank" rel="noopener">${uiIcon('map-pin')} Directions</a>
        ${website ? `<a class="btn btn-secondary" href="${esc(website)}" target="_blank" rel="noopener">${uiIcon('external')} ${court.business?.website_url ? 'Venue website' : 'Court website'}</a>` : ''}
        ${phone ? `<a class="btn btn-secondary" href="${esc(phone)}">${uiIcon('phone')} ${court.business?.phone ? 'Call venue' : 'Call the court'}</a>` : ''}`;
    };
    const modal=openModal(`
      ${modalHead('Before you go','map-pin')}
      <p class="court-visit-intro"><b>${esc(court.name)}</b></p>
      ${court.closed ? '<p class="court-visit-closed">This court is reported permanently closed.</p>' : ''}
      <div class="court-visit-tabs" role="tablist" aria-label="Visit information">${[['hours','Hours'],['fees','Access'],['facilities','Facilities'],['openplay','Open play']].map(([key,label])=>`<button type="button" role="tab" id="court-visit-tab-${key}" data-visit-tab="${key}" aria-controls="court-visit-panel-${key}" aria-selected="${key===selected}" tabindex="${key===selected ? 0 : -1}">${label}</button>`).join('')}</div>
      ${Object.entries(panels).map(([key,html])=>`<section class="court-visit-section court-visit-panel" id="court-visit-panel-${key}" role="tabpanel" aria-labelledby="court-visit-tab-${key}" data-visit-panel="${key}" tabindex="0" ${key===selected ? '' : 'hidden'}>${html}</section>`).join('')}
      <div id="court-visit-refresh" class="court-visit-refresh hidden" role="status"></div>
      <div class="court-visit-links">${visitLinks()}</div>
    `,{label:`Before you go to ${court.name}`});
    const current=()=>modal.isConnected && !modal._destroyed && state.me?.id===ownerId;
    currentOverlayEntry()?.afterClose.push(()=>{if(listingChanged && state.me?.id===ownerId)onUpdated?.();});
    const refreshVisit = async () => {
      if (!current()) return;
      const seq=++refreshSeq, notice=modal.querySelector('#court-visit-refresh');
      const restoreRetryFocus=notice.contains(document.activeElement);
      notice.classList.remove('hidden');notice.textContent='Refreshing details…';
      try {
        const updated=await api(`/courts/${court.id}`);
        if (!current() || seq!==refreshSeq) return;
        const box=modal.querySelector('.modal'), scroll=box.scrollTop;
        const panelScroll=Object.fromEntries([...modal.querySelectorAll('[data-visit-panel]')].map(panel=>[panel.dataset.visitPanel,panel.scrollTop]));
        const focused=document.activeElement, activeId=modal.contains(focused) ? focused.id : '', wasRetry=restoreRetryFocus && (focused===document.body || notice.contains(focused));
        court=updated;
        Object.entries(courtVisitPanelsHtml(court)).forEach(([key,html])=>{const panel=modal.querySelector(`[data-visit-panel="${key}"]`);panel.innerHTML=html;panel.scrollTop=panelScroll[key] || 0;});
        modal.querySelector('.court-visit-links').innerHTML=visitLinks();
        bindActions();notice.classList.add('hidden');box.scrollTop=scroll;
        if (currentOverlayEntry()?.el===modal) {
          if (wasRetry) modal.querySelector('[data-visit-tab][aria-selected="true"]')?.focus({preventScroll:true});
          else if (activeId && !focused.isConnected) modal.querySelector(`#${activeId}`)?.focus({preventScroll:true});
        }
      } catch {
        if (!current() || seq!==refreshSeq) return;
        notice.innerHTML='<p>Could not refresh. Previous details are shown.</p><button type="button" class="btn btn-secondary btn-sm" data-retry-visit>Try again</button>';
        notice.querySelector('button').addEventListener('click',refreshVisit);
        if (restoreRetryFocus && currentOverlayEntry()?.el===modal) notice.querySelector('button').focus({preventScroll:true});
      }
    };
    const bindActions = () => {
      modal.querySelector('#court-visit-correction')?.addEventListener('click',()=>openChildModal(modal,()=>openSuggestEditSheet(court,()=>{
        listingChanged=true;refreshVisit();
      },{focusVisiting:true})));
      modal.querySelectorAll('[data-visit-manage]').forEach(button=>button.addEventListener('click',()=>{
        openChildModal(modal,()=>openBusinessHub({court,businessId:court.business.id}));
        const workspace=currentOverlayEntry();
        if (workspace?.el!==modal) workspace?.afterClose.push(()=>{if(current()){listingChanged=true;refreshVisit();}});
      }));
      bindCourtBusyDays(modal);
    };
    bindActions();
    modal.querySelector('.modal')?.classList.add('court-visit-dialog');
    bindCourtVisitTabs(modal,selected);
    return modal;
  }

  function courtFeeTypeFact(court) {
    const type = String(court?.fee_type || '').trim().toLowerCase();
    if (['free', 'no_fee'].includes(type)) return 'Free';
    if (['membership', 'members_only'].includes(type)) return 'Members only';
    if (['reservation', 'reservation_required'].includes(type)) return 'Reservation required';
    if (['paid', 'fee', 'drop_in_fee'].includes(type)) return 'Fee required';
    return courtFeeFact(court?.fees);
  }

  function courtOpenStatusFact(court) {
    const status = court?.open_status;
    const label = compactCourtFact(status?.label || court?.hours, 36);
    if (!label) return null;
    return {
      label,
      raw: status?.label || court.hours,
      state: status?.state || 'unavailable',
    };
  }

  function courtTypeFact(value) {
    const type = String(value || '').trim().toLowerCase();
    if (type === 'dedicated') return 'Dedicated';
    if (['shared', 'lined'].includes(type)) return 'Lined / shared';
    return compactCourtFact(value, 24);
  }

  function courtPhotoHtml(court) {
    const fallback = `<span class="court-card-photo-fallback" aria-hidden="true">${uiIcon('pickleball')}</span>`;
    return `<span class="court-card-photo ${court.photo_url ? 'has-photo' : 'is-placeholder'}">${fallback}${court.photo_url
      ? `<img src="${esc(court.photo_url)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" data-remove-on-error>`
      : ''}</span>`;
  }

  function courtRowHtml(c) {
    const cond = c.condition && COURT_CONDITION_LABELS[c.condition];
    const quietNow = !(c.players_here > 0) && !(c.active_games > 0);
    const businessLabel = courtBusinessDiscoveryLabel(c);
    const businessDiscovery = courtBusinessDiscoveryAvailable(c);
    const location = [c.city, c.state].filter(Boolean).join(', ');
    const tags = [];
    if (state.favIds && state.favIds.has(c.id)) tags.push(`${uiIcon('star')} Saved`);
    if (c.business) tags.push(`${uiIcon('check-circle')} Verified venue`);
    tags.push(c.indoor ? `${uiIcon('home')} Indoor` : `${uiIcon('sun')} Outdoor`);
    if (c.lighted) tags.push(`${uiIcon('lightbulb')} Lights`);
    if (c.nets_provided) tags.push(`${uiIcon('net')} Nets`);
    if (c.has_restrooms) tags.push(`${uiIcon('restroom')} Restrooms`);
    if (c.has_water) tags.push(`${uiIcon('water')} Water`);
    const feeFact = courtFeeTypeFact(c);
    const typeFact = courtTypeFact(c.court_type);
    const surfaceFact = compactCourtFact(c.surface_type, 28);
    const hoursFact = courtOpenStatusFact(c);
    const structuredOpenPlay = courtOpenPlayTodayFact(c, 36);
    const openPlayFact = structuredOpenPlay?.label || compactCourtFact(c.open_play_schedule, 36);
    const openPlayRaw = structuredOpenPlay?.raw || c.open_play_schedule;
    const decisionFacts = [
      hoursFact ? ['clock', hoursFact.label, hoursFact.raw, `is-${hoursFact.state}`] : null,
      feeFact ? ['ticket', feeFact, c.fees] : null,
      typeFact ? ['grid', typeFact, c.court_type] : null,
      surfaceFact ? ['pickleball', surfaceFact, c.surface_type] : null,
      openPlayFact ? ['calendar', `Open play: ${openPlayFact}`, openPlayRaw] : null,
    ].filter((fact) => fact && fact[1] !== 'Hours not listed').slice(0, 3);
    const factsHtml = decisionFacts.length ? `<span class="court-card-facts">${decisionFacts.map(([icon, label, raw, className = '']) => (
      `<span class="court-card-fact ${className}" title="${esc(raw)}">${uiIcon(icon)}<span>${esc(label)}</span></span>`
    )).join('')}</span>` : '';
    const liveMetrics = [];
    if (c.players_here > 0) liveMetrics.push(
      `<span class="court-card-metric live"><b>${c.players_here}</b><span>checked in</span></span>`,
    );
    if (c.active_games > 0) liveMetrics.push(
      `<span class="court-card-metric live"><b>${c.active_games}</b><span>open soon</span></span>`,
    );
    if (c.rating_count > 0 && c.rating_avg) liveMetrics.push(
      `<span class="court-card-metric"><b>${uiIcon('star')} ${c.rating_avg}</b><span>${c.rating_count} rating${c.rating_count === 1 ? '' : 's'}</span></span>`,
    );
    const activityHtml = quietNow
      ? `<span class="court-card-quiet">No players checked in${c.upcoming_games > 0 ? ` · ${c.upcoming_games} later session${c.upcoming_games === 1 ? '' : 's'}` : c.rating_count > 0 && c.rating_avg ? ` · ${uiIcon('star')} ${c.rating_avg}` : ''}</span>`
      : `<span class="court-card-metrics">${liveMetrics.join('')}</span>${c.players_here ? `<span class="court-card-reason">${esc(courtPresenceSummaryText(c.presence_summary))}</span>` : ''}`;
    const reasonHtml = location && c.distance_miles != null
      ? `<span class="court-card-reason">${esc(location)}</span>` : '';
    const accessibleActivity = [
      quietNow ? 'No players checked in'
        : c.players_here > 0 ? `${c.players_here} checked in` : '',
      c.active_games > 0
        ? `${c.active_games} pickup game${c.active_games === 1 ? '' : 's'} in the next two hours` : '',
      c.upcoming_games > c.active_games
        ? `${c.upcoming_games - c.active_games} later session${c.upcoming_games - c.active_games === 1 ? '' : 's'}` : '',
    ].filter(Boolean).join(', ');
    const accessibleAmenities = [
      c.indoor ? 'Indoor' : 'Outdoor',
      c.lighted ? 'Lights' : '',
      c.nets_provided ? 'Nets provided' : '',
      c.has_restrooms ? 'Restrooms' : '',
      c.has_water ? 'Water' : '',
    ].filter(Boolean).join(', ');
    const accessibleSummary = [
      `Open ${c.name} court details`,
      c.distance_miles != null ? `${c.distance_miles} miles away` : c.city,
      accessibleActivity,
      cond ? cond[1] : '',
      c.business ? `Official venue profile from ${c.business.name}` : '',
      businessDiscovery ? `${businessLabel} available from the venue` : '',
      `${c.num_courts} court${c.num_courts === 1 ? '' : 's'}`,
      c.rating_count > 0 && c.rating_avg
        ? `${c.rating_avg} stars from ${c.rating_count} rating${c.rating_count === 1 ? '' : 's'}` : '',
      feeFact ? `Fees: ${feeFact}` : '',
      typeFact ? `Court type: ${typeFact}` : '',
      c.surface_type ? `Surface: ${c.surface_type}` : '',
      hoursFact ? hoursFact.raw : '',
      c.reservation_url ? 'Online reservations available' : '',
      openPlayRaw ? `Open play details: ${openPlayRaw}` : '',
      accessibleAmenities,
    ].filter(Boolean).join('. ');
    const selected = state.selectedCourtId === c.id;
    return `
      <article class="court-decision-card ${quietNow ? 'quiet' : ''} ${selected ? 'selected' : ''}" data-court-card="${c.id}">
        <button type="button" class="court-card-main" data-court="${c.id}" aria-label="${esc(accessibleSummary)}">
        <span class="court-card-layout">
          ${courtPhotoHtml(c)}
          <span class="court-card-copy">
            <span class="court-card-head">
              <span class="court-card-name">${esc(c.name)}${c.business ? ` <span class="verified-venue-badge">${uiIcon('check-circle')} Venue</span>` : ''}${cond ? ` <span class="tag ${c.condition === 'good' ? 'live' : 'warn'}" style="margin:0 0 0 5px;font-size:var(--text-xs);padding:2px 7px">${courtConditionIcon(c.condition)} ${esc(cond[1].split(' — ')[0].split(' /')[0])}</span>` : ''}</span>
              <span class="court-card-trailing">
                <span class="court-card-distance">${c.distance_miles != null ? `${c.distance_miles} mi` : esc(c.city || '')}</span>
                <span class="court-card-open-icon" aria-hidden="true">${uiIcon('chevron-right')}</span>
              </span>
            </span>
            ${reasonHtml}
            ${factsHtml}
            ${activityHtml}
            <span class="court-card-tags">
              <span class="tag">${c.num_courts} court${c.num_courts === 1 ? '' : 's'}</span>
              ${tags.slice(0, quietNow ? 2 : 3).map((tag) => `<span class="tag">${tag}</span>`).join('')}
            </span>
          </span>
        </span>
        </button>
        <button type="button" class="court-card-map" data-court-map="${c.id}" aria-pressed="${selected}" aria-label="Show ${esc(c.name)} on map">${uiIcon('map')} Show on map</button>
        ${businessDiscovery ? `<button type="button" class="court-card-programs" data-court-business="${c.id}" aria-label="${esc(`${businessLabel} at ${c.name}`)}"><span>${uiIcon('calendar')} ${esc(businessLabel)}</span><span aria-hidden="true">${uiIcon('chevron-right')}</span></button>` : ''}
      </article>
    `;
  }

  function courtPeekCardHtml(c, index = 0) {
    const selected = Number(state.selectedCourtId) === Number(c.id);
    const live = c.players_here > 0
      ? `${c.players_here} checked in`
      : c.active_games > 0
        ? `${c.active_games} pickup game${c.active_games === 1 ? '' : 's'} soon`
        : 'No players checked in';
    const location = [
      c.distance_miles != null ? `${c.distance_miles} mi` : '',
      c.city || '',
      live,
    ].filter(Boolean).join(' · ');
    return `<article class="court-peek-card" data-court-card="${c.id}">
      <button type="button" class="court-peek-main" data-court="${c.id}" aria-pressed="${selected}" aria-label="Show ${esc(c.name)} on the map">
        ${courtPhotoHtml(c)}
        <span class="court-peek-copy">
          <span class="court-peek-eyebrow">${selected ? 'Selected court' : index === 0 ? 'Nearest result' : 'Nearby result'}</span>
          <span class="court-peek-name">${esc(c.name)}</span>
          <span class="court-peek-meta">${esc(location)}</span>
          ${c.players_here ? `<span class="court-peek-meta">${esc(courtPresenceSummaryText(c.presence_summary))}</span>` : ''}
        </span>
        <span class="court-card-open-icon" aria-hidden="true">${uiIcon('chevron-right')}</span>
      </button>
    </article>`;
  }

  // Client-side mirror of the server's sort param — keeps search results and
  // already-fetched lists consistent with the selected chip.
  function sortCourts(courts) {
    const sorted = [...courts];
    if (state.listSort === 'rating') {
      sorted.sort((a, b) => (b.rating_avg ?? -1) - (a.rating_avg ?? -1)
        || (b.rating_count || 0) - (a.rating_count || 0)
        || (b.num_courts || 0) - (a.num_courts || 0));
    } else if (state.listSort === 'courts') {
      sorted.sort((a, b) => (b.num_courts || 0) - (a.num_courts || 0));
    } else if (state.listSort === 'active') {
      const nowScore = (c) => (c.players_here || 0) * 6
        + (c.active_games || 0) * 3
        + (c.rating_avg || 0) * 0.7
        + Math.min(c.num_courts || 0, 12) * 0.15
        + (c.condition === 'good' ? 1 : ['wet', 'closed', 'nets_down'].includes(c.condition) ? -4 : 0)
        - Math.min(c.distance_miles || 0, 30) * 0.12;
      sorted.sort((a, b) => nowScore(b) - nowScore(a)
        || (a.distance_miles ?? 1e9) - (b.distance_miles ?? 1e9));
    } else if (courts.some((c) => c.distance_miles != null)) {
      sorted.sort((a, b) => (a.distance_miles ?? 1e9) - (b.distance_miles ?? 1e9));
    }
    return sorted;
  }

  function renderCourtList(courts, places = [], { savedOnly = false, preserveLimit = false } = {}) {
    const el = $('#court-list-items');
    if (!el) return;
    el.removeAttribute('aria-busy');
    el.classList.remove('is-refreshing');
    courts = sortCourts(courts);
    state.courtListPlaces = places;
    state.courtListSavedOnly = savedOnly;
    const resultSignature = JSON.stringify({
      query: state.searchQ || '',
      sort: state.listSort,
      savedOnly,
      filters: state.courtFilters,
      courts: courts.map((court) => court.id),
      places: places.map((place) => [place.lat, place.lng]),
    });
    if (!preserveLimit && resultSignature !== state.courtListSignature) {
      state.courtListLimit = 20;
      state.courtListExpandedScrollTop = 0;
    }
    state.courtListSignature = resultSignature;
    let html = '';
    const searching = !!state.searchQ && !savedOnly;
    const hasFilters = activeCourtFilterCount() > 0;
    const hasNarrowingFilters = Object.entries(state.courtFilters)
      .some(([key, active]) => key !== 'saved' && active);
    const emptyResultHtml = () => {
      const icon = savedOnly ? uiIcon('star') : searching ? uiIcon('search')
        : hasFilters ? uiIcon('sliders') : uiIcon('map-pin');
      const title = savedOnly ? 'No saved courts to show'
        : searching ? 'No court matches that search'
          : hasFilters ? 'No courts match these filters' : 'No courts in this map area yet';
      const message = savedOnly
        ? (hasNarrowingFilters ? 'No saved courts match all of these filters.' : 'No saved courts yet. Open a court and choose Save court to keep it handy.')
        : searching && places.length && hasFilters ? 'No courts in this area match all of your filters.'
          : searching ? `Nothing matches “${esc(state.searchQ)}”. Try a court name or city.`
          : hasFilters ? 'No courts match all of these filters in this area.'
            : 'No courts here yet. Move the map, zoom out, or search another area.';
      const recovery = hasFilters
        ? '<button type="button" class="btn btn-primary" id="court-clear-results">Clear filters</button>'
        : `<button type="button" class="btn btn-secondary" id="court-search-again">${uiIcon('search')} ${searching ? 'Edit search' : 'Search another area'}</button>`;
      return `<div class="court-result-empty" role="status">
        <span class="court-result-state-icon" aria-hidden="true">${icon}</span>
        <h4>${title}</h4><p>${message}</p>
        <div class="court-result-empty-actions">${recovery}</div>
      </div>`;
    };
    const recoveryBeforePlaces = !courts.length && places.length && hasFilters;
    syncCourtSheetSummary(courts, { savedOnly, searching });

    const searchMatches = searching
      ? splitExactCourtNameMatches(courts, state.searchQ)
      : { exact: [], other: courts };
    const displayCourts = [...searchMatches.exact, ...searchMatches.other];
    const peekCourt = displayCourts.find((court) => Number(court.id) === Number(state.selectedCourtId))
      || displayCourts[0];
    const peekResultLimit = 3;
    const peekCourts = peekCourt
      ? [peekCourt, ...displayCourts.filter((court) => Number(court.id) !== Number(peekCourt.id))]
        .slice(0, peekResultLimit)
      : [];
    const visibleLimit = state.courtSheetSnap === 'peek' ? peekResultLimit : state.courtListLimit;
    const visibleCourts = state.courtSheetSnap === 'peek'
      ? peekCourts : displayCourts.slice(0, visibleLimit);
    const exactIds = new Set(searchMatches.exact.map((court) => court.id));
    const visibleExact = visibleCourts.filter((court) => exactIds.has(court.id));
    const visibleOther = visibleCourts.filter((court) => !exactIds.has(court.id));
    const placesHtml = places.map((p, i) => `
      <button type="button" class="card row nav-row-button" data-place="${i}" aria-label="View ${esc(p.label)} on the court map">
        <span class="nav-row-leading">${uiIcon('map-pin')}</span>
        <span class="row-main">
          <span class="row-title" style="display:block">${esc(p.label)}</span>
          <span class="row-sub" style="display:block">${esc((p.detail || '').split(',').slice(1, 4).join(',').trim())}</span>
        </span>
        ${uiIcon('chevron-right', 'chev')}
      </button>`).join('');

    // Filter recovery is the primary answer; related place jumps remain just
    // below it instead of pushing the action behind the active-game banner.
    if (state.courtSheetSnap === 'peek' && peekCourts.length) {
      const availableCourtCount = Math.max(
        displayCourts.length, Number(state.courtResultTotal) || 0,
      );
      html += `<div class="court-peek-strip" aria-label="Nearby court previews">${peekCourts
        .map((court, index) => courtPeekCardHtml(court, index)).join('')}</div>
        <button type="button" class="btn-link court-peek-browse" id="court-show-more">See all ${availableCourtCount} court${availableCourtCount === 1 ? '' : 's'} as a list</button>`;
    } else if (recoveryBeforePlaces) html += emptyResultHtml();
    if (state.courtSheetSnap !== 'peek' && visibleExact.length) {
      html += `<div class="section-label" style="margin-top:4px">${uiIcon('pickleball')} Exact court</div>`;
      html += visibleExact.map(courtRowHtml).join('');
    }
    if (state.courtSheetSnap !== 'peek' && places.length) {
      html += `<div class="section-label" style="margin-top:4px">${uiIcon('map-pin')} Jump to area</div>`;
      html += placesHtml;
    }

    if (courts.length && state.courtSheetSnap !== 'peek') {
      if (visibleOther.length) {
        if (places.length || visibleExact.length) {
          html += `<div class="section-label">${visibleExact.length ? 'Other courts' : 'Courts'}</div>`;
        }
        html += visibleOther.map(courtRowHtml).join('');
      }
      if (visibleCourts.length < displayCourts.length) {
        const remaining = displayCourts.length - visibleCourts.length;
        const label = state.courtSheetSnap === 'peek'
          ? `Browse all ${displayCourts.length} courts`
          : `Show ${Math.min(20, remaining)} more · ${remaining} remaining`;
        html += `<button type="button" class="btn btn-primary btn-block" id="court-show-more" style="margin:2px 0 10px">${label}</button>`;
      } else if (!savedOnly && state.courtNextCursor && state.courtPageBaseUrl) {
        const remaining = Math.max(0, Number(state.courtResultTotal) - displayCourts.length);
        html += `<div class="court-results-partial" role="status"><b>${displayCourts.length} of ${Math.max(displayCourts.length, Number(state.courtResultTotal) || 0)} courts loaded</b><span>${searching ? 'Continue this search to see more matches.' : 'Zoom in for a complete local view, or load another page.'}</span></div><button type="button" class="btn btn-primary btn-block" id="court-load-more" style="margin:2px 0 10px">Load ${Math.min(remaining || 50, 250)} more courts</button>`;
      }
    } else if (!courts.length && !recoveryBeforePlaces) html += emptyResultHtml();
    if (state.courtSheetSnap !== 'peek') {
      html += `<button type="button" class="btn btn-secondary btn-block list-add-court" id="list-add-court">${uiIcon('plus')} Missing a court? Add it</button>`;
    }

    el.innerHTML = html;
    el.querySelector('#list-add-court')?.addEventListener('click', openAddCourtSheet);
    el.querySelector('#court-clear-results')?.addEventListener('click', clearCourtFilters);
    el.querySelector('#court-search-again')?.addEventListener('click', () => {
      setCourtSheetSnap('peek');
      const search = $('#court-search');
      search?.focus({ preventScroll: true });
      search?.select();
    });
    el.querySelector('#court-show-more')?.addEventListener('click', () => {
      if (state.courtSheetSnap === 'peek') {
        const firstNewIndex = 0;
        setCourtSheetSnap('full');
        el.querySelectorAll('[data-court]')[firstNewIndex]?.focus({ preventScroll: true });
        return;
      }
      const scrollTop = el.scrollTop;
      const firstNewIndex = state.courtListLimit;
      state.courtListLimit += 20;
      renderCourtList(courts, places, { savedOnly, preserveLimit: true });
      el.scrollTop = scrollTop;
      el.querySelectorAll('[data-court]')[firstNewIndex]?.focus({ preventScroll: true });
    });
    el.querySelector('#court-load-more')?.addEventListener('click', async (event) => {
      const button = event.currentTarget;
      const baseUrl = state.courtPageBaseUrl;
      const cursor = state.courtNextCursor;
      const resetAction = beginButtonAction(button, 'Loading more…');
      if (!resetAction || !baseUrl || !cursor) return;
      try {
        const nextPage = await api(`${baseUrl}&cursor=${encodeURIComponent(cursor)}`);
        if (state.courtPageBaseUrl !== baseUrl || state.courtNextCursor !== cursor) return;
        const knownIds = new Set(courts.map((court) => Number(court.id)));
        const additions = applyCourtFilters(nextPage.items || []).filter((court) => {
          const id = Number(court.id);
          if (knownIds.has(id)) return false;
          knownIds.add(id);
          return true;
        });
        const merged = [...courts, ...additions];
        state.courtResultTotal = Math.max(merged.length, Number(nextPage.total) || 0);
        state.courtNextCursor = nextPage.next_cursor || null;
        state.courtResultsTruncated = nextPage.has_more === true && !!state.courtNextCursor;
        state.courtsInView = merged;
        const firstNewIndex = courts.length;
        state.courtListLimit = Math.max(state.courtListLimit, merged.length);
        drawMarkers(merged);
        renderCourtList(merged, places, { savedOnly, preserveLimit: true });
        requestAnimationFrame(() => {
          const target = $('#court-list-items')?.querySelectorAll('[data-court]')[firstNewIndex]
            || $('#court-load-more');
          target?.focus({ preventScroll: true });
        });
      } catch (error) {
        resetAction();
        showInlineActionError(el, error.message);
      }
    });
    const byId = new Map(courts.map((court) => [court.id, court]));
    el.querySelectorAll('[data-court]').forEach((row) => {
      row.addEventListener('click', () => {
        if (row.classList.contains('court-card-main')) openCourtFromDiscovery(byId.get(Number(row.dataset.court)));
        else activateCourtFromDiscovery(byId.get(Number(row.dataset.court)));
      });
    });
    el.querySelectorAll('[data-court-map]').forEach((row) => {
      row.addEventListener('click', () => activateCourtFromDiscovery(byId.get(Number(row.dataset.courtMap))));
    });
    el.querySelectorAll('[data-court-open]').forEach((row) => {
      row.addEventListener('click', () => openCourtFromDiscovery(
        byId.get(Number(row.dataset.courtOpen)),
      ));
    });
    el.querySelectorAll('[data-court-business]').forEach((button) => {
      button.addEventListener('click', () => {
        openCourtFromDiscovery(byId.get(Number(button.dataset.courtBusiness)), { focusBusiness: true });
      });
    });
    el.querySelectorAll('[data-place]').forEach((row) => {
      const p = places[Number(row.dataset.place)];
      if (p) row.addEventListener('click', () => jumpToPlace(p.lat, p.lng, p.label));
    });
    if (!preserveLimit && state.selectedCourtId && !byId.has(state.selectedCourtId)) {
      clearCourtSelection('The selected court is not in these results.');
    }
  }

  function courtCorrectionChanges(initial,values) {
    const packed = value => JSON.stringify(value, (_key,item) => item && typeof item === 'object' && !Array.isArray(item) ? Object.fromEntries(Object.entries(item).sort(([a],[b])=>a.localeCompare(b))) : item);
    return Object.fromEntries(Object.entries(values).filter(([key,value])=>packed(value)!==packed(initial[key])));
  }

