  // Downscale a picked image file to a JPEG data URL, stepping quality down
  // until it fits the server's 500KB photo limit.
  function imageFileToDataUrl(file, maxDim = 1280, { square = false } = {}) {
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        URL.revokeObjectURL(url);
        try {
          const sourceSize = Math.min(img.width, img.height);
          const targetBasis = square ? sourceSize : Math.max(img.width, img.height);
          const scale = Math.min(1, maxDim / targetBasis);
          const canvas = document.createElement('canvas');
          canvas.width = Math.max(1, Math.round((square ? sourceSize : img.width) * scale));
          canvas.height = Math.max(1, Math.round((square ? sourceSize : img.height) * scale));
          const context = canvas.getContext('2d');
          if (!context) throw new Error('bad_image');
          const sourceX = square ? Math.max(0, (img.width - sourceSize) / 2) : 0;
          const sourceY = square ? Math.max(0, (img.height - sourceSize) / 2) : 0;
          context.drawImage(
            img, sourceX, sourceY,
            square ? sourceSize : img.width,
            square ? sourceSize : img.height,
            0, 0, canvas.width, canvas.height,
          );
          const maxChars = 660000; // ~500KB decoded
          for (const q of [0.82, 0.65, 0.5, 0.35]) {
            const dataUrl = canvas.toDataURL('image/jpeg', q);
            if (dataUrl.length <= maxChars) { resolve(dataUrl); return; }
          }
          reject(new Error('image_too_large'));
        } catch (error) {
          reject(error?.message === 'image_too_large' ? error : new Error('bad_image'));
        }
      };
      img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('bad_image')); };
      img.src = url;
    });
  }

  // Lazy-load photo attachments into any chat thread (payloads only carry
  // has_image; the image endpoint enforces per-thread permissions).
  function hydrateChatImages(msgsEl, chatUX) {
    msgsEl.querySelectorAll('.bubble[data-message-id]').forEach((bubble) => {
      const message = msgsEl._messageReferences?.get(Number(bubble.dataset.messageId));
      if (!message) return;
      bubble.querySelector('.chat-reply-quote')?.remove();
      if (message.reply_to) bubble.insertAdjacentHTML('afterbegin', chatReplyHtml(message.reply_to));
    });
    msgsEl.querySelectorAll('[data-img-id]:not([data-loaded])').forEach(async (slot) => {
      slot.dataset.loaded = 'loading';
      slot.classList.add('chat-image-loading');
      try {
        const { image } = await api(`/messages/${slot.dataset.imgId}/image`);
        const img = new Image();
        img.alt = 'Photo';
        img.style.cssText = 'max-width:100%;border-radius: var(--radius-sm);display:block';
        img.src = image;
        if (typeof img.decode === 'function') await img.decode();
        else if (!img.complete) {
          await new Promise((resolve, reject) => {
            img.addEventListener('load', resolve, { once: true });
            img.addEventListener('error', reject, { once: true });
          });
        }
        if (!slot.isConnected) return;
        const snapshot = chatUX?.captureScroll();
        slot.dataset.loaded = 'ready';
        slot.classList.remove('chat-image-error');
        slot.removeAttribute('role');
        slot.removeAttribute('aria-label');
        slot.removeAttribute('aria-hidden');
        slot.replaceChildren(img);
        if (chatUX) chatUX.restoreScroll(snapshot);
        else msgsEl.scrollTop = msgsEl.scrollHeight;
      } catch {
        if (!slot.isConnected) return;
        const snapshot = chatUX?.captureScroll();
        slot.dataset.loaded = 'error';
        slot.classList.add('chat-image-error');
        slot.removeAttribute('aria-hidden');
        slot.setAttribute('role', 'alert');
        slot.removeAttribute('aria-label');
        slot.innerHTML = `
          <span class="chat-image-error-icon" aria-hidden="true">${uiIcon('camera')}</span>
          <span>Photo couldn’t load.</span>
          <button type="button" class="chat-image-retry">Retry</button>`;
        slot.querySelector('.chat-image-retry').addEventListener('click', () => {
          slot.classList.remove('chat-image-error');
          slot.removeAttribute('role');
          slot.removeAttribute('aria-label');
          slot.setAttribute('aria-hidden', 'true');
          slot.innerHTML = '<span class="spinner"></span>';
          delete slot.dataset.loaded;
          hydrateChatImages(msgsEl, chatUX);
        });
        if (chatUX) chatUX.restoreScroll(snapshot);
      }
    });
  }

  // Add a photo button + hidden file input to a chat composer form.
  function addPhotoToComposer(modal, formSel, textSel, chatUX) {
    const form = modal.querySelector(formSel);
    if (!form) return;
    const file = document.createElement('input');
    file.type = 'file';
    file.accept = 'image/*';
    file.className = 'hidden';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.innerHTML = uiIcon('camera');
    btn.setAttribute('aria-label', 'Send a photo');
    btn.className = 'thread-photo-button';
    form.prepend(file);
    form.prepend(btn);
    btn.addEventListener('click', () => {
      if (file.value) file.value = '';
      file.click();
    });
    file.addEventListener('change', async (e) => {
      const picked = e.target.files[0];
      if (!picked) return;
      try {
        const image = await imageFileToDataUrl(picked, 1024);
        const textEl = modal.querySelector(textSel);
        const body = textEl.value.trim();
        await chatUX.send(body, { image });
        e.target.value = '';
      } catch (err) {
        if (err.message === 'image_too_large' || err.message === 'bad_image') e.target.value = '';
        toast(err.message === 'image_too_large' ? 'That photo is too large — try a smaller one' : err.message);
      }
    });
  }

