  async function openPlaySoonArrivalChoices() {
    const accountId = Number(state.me && state.me.id);
    const modal = openModal(`
      ${modalHead('Nearby play now', 'users')}
      <div class="live-play-location"><span id="live-play-area"></span><button type="button" class="btn btn-secondary btn-sm" id="live-play-refresh">Refresh</button></div>
      <div id="play-soon-rallies" tabindex="-1" aria-live="polite" aria-busy="true"></div>
      <button type="button" class="btn btn-secondary btn-block hidden" id="play-soon-hour-fallback">Share that I’m free this hour</button>
    `, { label: 'Pickup games near you' });
    modal.querySelector('.modal').classList.add('live-play-modal');
    const results = modal.querySelector('#play-soon-rallies');
    const fallback = modal.querySelector('#play-soon-hour-fallback');
    const refresh = modal.querySelector('#live-play-refresh');
    let sequence = 0;
    modal._cleanupFns.push(()=>{sequence += 1;});
    fallback.addEventListener('click', () => transitionModal(modal, openPlayPulseCourtPicker));
    const load = async (focus = false) => {
      const current = ++sequence;
      const active = () => current === sequence && modal.isConnected && Number(state.me && state.me.id) === accountId;
      results.setAttribute('aria-busy','true');
      results.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Finding nearby play…</span></div>';
      fallback.classList.add('hidden'); refresh.disabled = true;
      if (focus) { results.scrollIntoView({block:'start'}); results.focus({preventScroll:true}); }
      const loc = committedAreaLatLng();
      modal.querySelector('#live-play-area').textContent = loc ? `${state.areaLabel || state.me?.home_area || 'Your area'} · 25 mi` : '';
      refresh.classList.toggle('hidden',!loc);
      try {
        if (!loc) {
          results.innerHTML = `<section class="live-play-empty"><span aria-hidden="true">${uiIcon('map-pin')}</span><h4>Set your area</h4><p>Find nearby games and players.</p><button type="button" class="btn btn-primary" data-set-arrival-area>Set area</button></section>`;
          results.querySelector('[data-set-arrival-area]').addEventListener('click',()=>transitionModal(modal,()=>openHomeAreaOnboarding({replay:true,onComplete:openPlaySoonArrivalChoices})));
          return;
        }
        const response = await api(`/players/looking?lat=${loc.lat}&lng=${loc.lng}&radius=25`);
        if (!active()) return;
        const rallies = normalizeLookingRallies(response).filter((rally) => {
          const ownArrival = activeArrivalForGame(rally.gameId, rally.myArrival, rally);
          return !!ownArrival || (rally.arrivalAvailable && rally.spotsLeft > 0);
        });
        const lookingPlayers = normalizeLookingPlayersWithoutRally(response).slice(0, 12);
        fallback.classList.toggle('hidden',rallies.length > 0 || lookingPlayers.length > 0);
        const rallyHtml = rallies.length ? `<section aria-label="Pickup games"><h4 class="live-play-section-title">Pickup games <span>${rallies.length}</span></h4>${rallies.map(arrivalRallyCardHtml).join('')}</section>` : '';
        const playerHtml = lookingPlayers.length ? `<section aria-label="Players waiting at a court"><h4 class="live-play-section-title">Players looking to play <span>${lookingPlayers.length}</span></h4>${lookingPlayers.map((player)=>{
          const firstName = String(player.display_name || 'Player').split(/\s+/)[0];
          return `<article class="live-play-card"><div class="live-play-person">${avatarHtml(player,'sm','span')}<div><h4>${esc(player.display_name || 'Player')}</h4><p>${esc(player.courtName)}</p><small>Here now · looking for casual play${player.distanceMiles != null ? ` · ${esc(player.distanceMiles)} mi` : ''}</small></div></div>
            <div class="live-play-card-actions">${player.isFriend ? `<button type="button" class="btn btn-secondary" data-play-soon-coming="${player.id}">Tell ${esc(firstName)} I can come</button>` : ''}<button type="button" class="btn btn-primary" data-play-soon-player-court="${player.courtId}">Court details</button></div></article>`;
        }).join('')}</section>` : '';
        results.innerHTML = rallyHtml || playerHtml ? `${rallyHtml}${playerHtml}` : `<section class="live-play-empty"><span aria-hidden="true">${uiIcon('users')}</span><h4>No nearby play right now</h4><p>Let players know you’re free this hour.</p><button type="button" class="btn btn-secondary" data-retry-live-play>Check again</button></section>`;
        results.querySelectorAll('[data-play-soon-rally]').forEach(button=>button.addEventListener('click',()=>{
          const rally = rallies.find(item=>item.gameId === Number(button.dataset.rallyGameId));
          openReadyRally(rally || rallySummaryFromDataset(button),button);
        }));
        results.querySelectorAll('[data-live-court], [data-play-soon-player-court]').forEach(button=>button.addEventListener('click',()=>{
          openChildModal(modal,()=>openCourtDetail(Number(button.dataset.liveCourt || button.dataset.playSoonPlayerCourt)));
        }));
        results.querySelectorAll('[data-play-soon-coming]').forEach(button=>button.addEventListener('click',async()=>{
          const reset=beginButtonAction(button,'Sending…'); if (!reset) return;
          try {
            await api(`/players/${button.dataset.playSoonComing}/coming`,{method:'POST'});
            if (!active()) return;
            button.innerHTML = `${uiIcon('check')} Sent`;button.removeAttribute('aria-busy');
            toast('They know you can be there soon',{tone:'success',icon:'pickleball'});
          } catch(error) { if (active()) {reset();toast(error.message);} }
        }));
      } catch(error) {
        if (!active()) return;
        results.innerHTML = `<section class="live-play-empty" role="alert"><h4>Couldn’t load nearby play</h4><p>${esc(error.message)}</p><button type="button" class="btn btn-primary" data-retry-live-play>Try again</button></section>`;
      } finally {
        if (active()) {
          results.setAttribute('aria-busy','false'); refresh.disabled=false;
          results.querySelector('[data-retry-live-play]')?.addEventListener('click',()=>load(true));
        }
      }
    };
    refresh.addEventListener('click',()=>load(true));
    await load();
    return modal;
  }

  async function openPlayNowCourtPicker({ court = null, rally = null, intent = 'play-now' } = {}) {
    const pulseIntent = intent === 'play-pulse';
    const preset = playNowCourt(court || (rally && {
      id: rally.courtId,
      name: rally.courtName,
      city: rally.courtCity,
    }), rally ? `${rally.readyCount || 1} at the court` : 'Selected court');
    let selected = preset;
    const modal = openModal(`
      ${modalHead(pulseIntent ? 'Free this hour' : 'At the court')}
      <form id="play-now-form" novalidate>
        <p class="play-now-intro">${pulseIntent
          ? 'Choose a court you could reach this hour. Nearby players can respond; this does not check you in.'
          : 'Choose the court you’re at. We’ll check you in, then join or gather its casual group.'}</p>
        <div class="play-now-selection ${preset ? '' : 'hidden'}" id="play-now-selection">
          <span aria-hidden="true">${uiIcon('map-pin')}</span>
          <span class="row-main" role="status"><b id="play-now-selected-name">${preset ? esc(preset.name) : ''}</b><small>${pulseIntent ? 'Court selected · only the court is shared' : 'I am at this court now'}</small></span>
          <button type="button" class="btn btn-secondary btn-sm ${preset ? '' : 'hidden'}" id="play-now-change-court" aria-controls="play-now-court-picker" aria-expanded="${preset ? 'false' : 'true'}">Change court</button>
        </div>
        <div class="play-now-court-picker ${preset ? 'hidden' : ''}" id="play-now-court-picker" aria-hidden="${preset ? 'true' : 'false'}">
          <div class="form-field">
            <label for="play-now-search">Court</label>
            <input type="search" id="play-now-search" placeholder="Search courts…" autocomplete="off" />
          </div>
          <div class="play-now-courts" id="play-now-courts" role="group" aria-label="Court choices" aria-busy="true">
            <div class="play-now-loading" role="status"><span class="spinner"></span><span>Finding current, saved, home, and nearby courts…</span></div>
          </div>
          <button type="button" class="btn btn-secondary btn-sm hidden" id="play-now-retry-courts">Try court suggestions again</button>
        </div>
        <p class="play-now-privacy"><span aria-hidden="true">${uiIcon('eye')}</span> ${pulseIntent
          ? 'Nearby signed-in players may see this court for the next hour. Your current location stays private.'
          : 'Nearby signed-in players may see that you’re at this court. This status expires automatically.'}</p>
        <p class="form-error hidden" id="play-now-error" role="alert" tabindex="-1"></p>
        <button type="submit" class="btn btn-primary btn-block" id="play-now-confirm" ${preset ? '' : 'disabled'}>${pulseIntent ? 'Share for this hour' : 'Join or gather a group'}</button>
        <button type="button" class="btn-link modal-close btn-block">Cancel</button>
      </form>
    `, { label: pulseIntent ? 'Share that you are free this hour at a court' : 'Choose the court you are at now' });
    const resultsEl = modal.querySelector('#play-now-courts');
    const searchEl = modal.querySelector('#play-now-search');
    const selectionEl = modal.querySelector('#play-now-selection');
    const pickerEl = modal.querySelector('#play-now-court-picker');
    const changeCourtButton = modal.querySelector('#play-now-change-court');
    const confirmButton = modal.querySelector('#play-now-confirm');
    const retryButton = modal.querySelector('#play-now-retry-courts');
    const errorEl = modal.querySelector('#play-now-error');
    const suggestionsById = new Map();
    let suggestionRows = [];
    let searchTimer = null;
    let searchSeq = 0;
    let suggestionLoadSeq = 0;
    let suggestionLoadFailed = false;

    const addSuggestion = (value, tag = '') => {
      const item = playNowCourt(value, tag);
      if (!item || suggestionsById.has(item.id)) return;
      suggestionsById.set(item.id, item);
      suggestionRows.push(item);
    };
    if (preset) addSuggestion(preset, preset.tag);
    if (state.presence && state.presence.checked_in) addSuggestion({
      id: state.presence.court_id,
      name: state.presence.court_name,
    }, 'Current check-in');
    if (state.me && state.me.home_court_id) addSuggestion({
      id: state.me.home_court_id,
      name: state.me.home_court_name || 'Primary court',
    }, 'Home');

    const setPickerOpen = (open, { focusSearch = false } = {}) => {
      pickerEl.classList.toggle('hidden', !open);
      pickerEl.setAttribute('aria-hidden', String(!open));
      changeCourtButton.setAttribute('aria-expanded', String(open));
      changeCourtButton.classList.toggle('hidden', !selected || open);
      if (!open) errorEl.classList.add('hidden');
      else if (suggestionLoadFailed) {
        errorEl.textContent = 'Court suggestions could not load. Search for a court or try again.';
        errorEl.classList.remove('hidden');
      }
      if (open && focusSearch) requestAnimationFrame(() => searchEl.focus({ preventScroll: true }));
    };
    const syncSelection = ({ collapsePicker = false } = {}) => {
      selectionEl.classList.toggle('hidden', !selected);
      modal.querySelector('#play-now-selected-name').textContent = selected ? selected.name : '';
      confirmButton.disabled = !selected;
      errorEl.classList.add('hidden');
      if (collapsePicker && selected) setPickerOpen(false);
      else changeCourtButton.classList.toggle('hidden', !selected || !pickerEl.classList.contains('hidden'));
      resultsEl.querySelectorAll('[data-play-now-court]').forEach((row) => {
        const active = !!selected && Number(row.dataset.playNowCourt) === selected.id;
        row.classList.toggle('selected', active);
        row.setAttribute('aria-pressed', String(active));
        const pin = row.querySelector('.play-now-court-pin');
        if (pin) pin.innerHTML = uiIcon(active ? 'check-circle' : 'map-pin');
      });
    };
    const renderCourtRows = (items = suggestionRows) => {
      resultsEl.setAttribute('aria-busy', 'false');
      resultsEl.innerHTML = items.length ? items.map((item) => `
        <button type="button" class="play-now-court${selected && selected.id === item.id ? ' selected' : ''}"
          aria-pressed="${!!selected && selected.id === item.id}" data-play-now-court="${item.id}">
          <span class="play-now-court-pin" aria-hidden="true">${uiIcon(selected && selected.id === item.id ? 'check-circle' : 'map-pin')}</span>
          <span class="row-main"><span class="row-title">${esc(item.name)}</span><span class="row-sub">${esc(item.city || 'Pickleball court')}</span></span>
          ${item.tag || item.distanceMiles != null ? `<span class="tag">${esc(item.tag || `${item.distanceMiles} mi`)}</span>` : ''}
        </button>`).join('') : '<div class="empty-state" style="padding:14px">No suggested courts yet. Search by court or city.</div>';
      resultsEl.querySelectorAll('[data-play-now-court]').forEach((row) => row.addEventListener('click', () => {
        selected = items.find((item) => item.id === Number(row.dataset.playNowCourt))
          || suggestionsById.get(Number(row.dataset.playNowCourt));
        syncSelection({ collapsePicker: true });
        confirmButton.focus({ preventScroll: true });
      }));
      syncSelection();
    };

    const loadSuggestions = async () => {
      const loadSeq = ++suggestionLoadSeq;
      suggestionLoadFailed = false;
      retryButton.classList.add('hidden');
      errorEl.classList.add('hidden');
      resultsEl.setAttribute('aria-busy', 'true');
      resultsEl.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Finding current, saved, home, and nearby courts…</span></div>';
      const loc = committedAreaLatLng();
      const [saved, nearby] = await Promise.all([
        api('/courts/favorites').catch(() => null),
        loc
          ? api(`/courts?lat=${loc.lat}&lng=${loc.lng}&radius=30&limit=8`).catch(() => null)
          : Promise.resolve({ items: [] }),
      ]);
      if (loadSeq !== suggestionLoadSeq || !document.body.contains(modal)) return;
      (saved && saved.items || []).forEach((item) => addSuggestion(item, 'Saved'));
      (nearby && nearby.items || []).forEach((item) => addSuggestion(
        item, item.distance_miles != null ? `${item.distance_miles} mi` : 'Nearby',
      ));
      if (searchEl.value.trim().length < 2) renderCourtRows();
      if (!saved && !nearby && searchEl.value.trim().length < 2) {
        suggestionLoadFailed = true;
        retryButton.classList.remove('hidden');
        if (!pickerEl.classList.contains('hidden')) {
          errorEl.textContent = 'Court suggestions could not load. Search for a court or try again.';
          errorEl.classList.remove('hidden');
        }
      }
    };

    changeCourtButton.addEventListener('click', () => setPickerOpen(true, { focusSearch: true }));
    retryButton.addEventListener('click', loadSuggestions);
    searchEl.addEventListener('input', () => {
      clearTimeout(searchTimer);
      errorEl.classList.add('hidden');
      const query = searchEl.value.trim();
      if (query.length < 2) {
        searchSeq += 1;
        renderCourtRows();
        return;
      }
      searchTimer = setTimeout(async () => {
        const seq = ++searchSeq;
        resultsEl.setAttribute('aria-busy', 'true');
        resultsEl.innerHTML = '<div class="play-now-loading" role="status"><span class="spinner"></span><span>Searching courts…</span></div>';
        let url = `/courts?q=${encodeURIComponent(query)}&limit=8`;
        if (state.userLoc) url += `&lat=${state.userLoc[0]}&lng=${state.userLoc[1]}`;
        try {
          const response = await api(url);
          if (seq !== searchSeq || !document.body.contains(modal)) return;
          const items = (response.items || []).map((item) => playNowCourt(
            item, item.distance_miles != null ? `${item.distance_miles} mi` : '',
          )).filter(Boolean);
          items.forEach((item) => {
            if (!suggestionsById.has(item.id)) suggestionsById.set(item.id, item);
          });
          renderCourtRows(items);
        } catch (error) {
          if (seq !== searchSeq || !document.body.contains(modal)) return;
          resultsEl.setAttribute('aria-busy', 'false');
          renderError(resultsEl, error.message || 'Court search could not load.', () => {
            searchEl.dispatchEvent(new Event('input', { bubbles: true }));
            requestAnimationFrame(() => searchEl.focus({ preventScroll: true }));
          });
        }
      }, 250);
    });
    modal._cleanupFns.push(() => clearTimeout(searchTimer));
    modal.querySelector('#play-now-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      if (!selected) {
        errorEl.textContent = pulseIntent
          ? 'Choose the court where you could play this hour.'
          : 'Choose the court where you are playing.';
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
        return;
      }
      if (pulseIntent) await declarePlayPulse(selected, modal, confirmButton, errorEl);
      else await checkInAndStartRally(selected, modal, confirmButton, errorEl);
    });
    loadSuggestions();
    return modal;
  }

  function openPlayPulseCourtPicker(options = {}) {
    return openPlayNowCourtPicker({ ...options, intent: 'play-pulse' });
  }

  function arrivalRequestIsAmbiguous(error) {
    const status = Number(error && error.status) || 0;
    return !!(error && error.isNetworkError) || status === 408 || status === 425
      || status === 429 || status >= 500;
  }

  function arrivalRallySummary(arrival) {
    if (!arrival) return null;
    return rallySummaryFromValue({
      game_id: arrival.gameId,
      court_id: arrival.courtId,
      court_name: arrival.courtName,
      court_city: arrival.courtCity,
      court_address: arrival.courtAddress,
      court_latitude: arrival.courtLatitude,
      court_longitude: arrival.courtLongitude,
      ready_count: arrival.readyCount,
      roster_count: arrival.rosterCount,
      on_the_way_count: arrival.onWayCount,
      committed_count: arrival.committedCount,
      physical_spots_left: arrival.physicalSpotsLeft,
      spots_left: arrival.spotsLeft,
      max_players: arrival.maxPlayers,
      arrival_capability: arrival.arrivalCapability,
      arrival_available: arrival.arrivalAvailable,
      my_arrival: arrival,
    });
  }

  function hydrateArrivalDirections(modal, rally) {
    const link = modal && modal.querySelector('[data-arrival-directions]');
    if (!link) return;
    const applyCourt = (court) => {
      const href = courtDirectionsUrl(court);
      if (!href || !document.body.contains(link)) return false;
      link.href = href;
      link.removeAttribute('aria-disabled');
      link.classList.remove('is-disabled');
      return true;
    };
    if (applyCourt(rallyCourtForDirections(rally))) return;
    link.setAttribute('aria-disabled', 'true');
    link.classList.add('is-disabled');
    const callerSession = instantRallySession();
    if (!callerSession) return;
    api(`/courts/${rally.courtId}`).then((court) => {
      if (!instantRallySessionMatches(callerSession) || !document.body.contains(modal)) return;
      applyCourt(court);
    }).catch(() => { /* the court detail remains available if Maps cannot be resolved */ });
  }

  async function reserveRallyArrival(rally, etaMinutes) {
    const callerSession = instantRallySession();
    const gameId = safePositiveId(rally && rally.gameId);
    if (!callerSession || !gameId) {
      const error = new Error('Sign in again before sharing your ETA.');
      error.code = 'invalid_session';
      throw error;
    }
    const knownArrival = activeArrivalForGame(gameId, rally.myArrival, rally);
    if (knownArrival) {
      clearRallyArrivalAttempt(callerSession.userId, gameId);
      return { outcome: 'existing', arrival: knownArrival };
    }
    const attempt = pendingRallyArrivalAttempt(callerSession.userId, gameId, etaMinutes);
    if (!attempt) {
      const error = new Error('Couldn’t save this yet. Free storage on your device and try again.');
      error.code = 'arrival_attempt_unavailable';
      throw error;
    }
    const shared = rallyArrivalInFlight;
    if (shared && shared.token === callerSession.token && shared.userId === callerSession.userId
        && shared.gameId === gameId && shared.attemptId === attempt.id) return shared.promise;
    const body = {
      eta_minutes: attempt.etaMinutes,
      client_attempt_id: attempt.id,
    };
    if (attempt.replacesAttemptId) {
      body.replaces_client_attempt_id = attempt.replacesAttemptId;
    }
    if (rally.arrivalCapability) body.arrival_capability = rally.arrivalCapability;
    const promise = (async () => {
      try {
        const result = await api(`/games/${gameId}/arrival`, {
          method: 'PUT',
          body: JSON.stringify(body),
        });
        if (!instantRallySessionMatches(callerSession)) return { abandoned: true };
        clearRallyArrivalAttempt(callerSession.userId, gameId, attempt.id);
        const freshRally = rallySummaryFromValue(result && result.game) || rally;
        const arrival = normalizeActiveArrival(result && result.arrival, freshRally);
        if (!arrival) {
          const ended = new Error('That ETA expired. Find another game.');
          ended.code = 'arrival_no_longer_active';
          ended.status = 409;
          throw ended;
        }
        invalidateMeRequests();
        state.activeArrival = arrival;
        refreshPlayGamesAfterRallyMutation();
        renderActiveGameBanner();
        refreshLookingBanner();
        refreshMe().catch(() => {});
        return { ...result, arrival };
      } catch (error) {
        if (instantRallySessionMatches(callerSession) && !arrivalRequestIsAmbiguous(error)) {
          clearRallyArrivalAttempt(callerSession.userId, gameId, attempt.id);
        }
        throw error;
      }
    })();
    const record = {
      token: callerSession.token,
      userId: callerSession.userId,
      gameId,
      attemptId: attempt.id,
      promise,
    };
    rallyArrivalInFlight = record;
    try { return await promise; }
    finally { if (rallyArrivalInFlight === record) rallyArrivalInFlight = null; }
  }

  function openRallyArrivalSheet(value, { fromModal = null } = {}) {
    const rally = value && value.courtId ? value : rallySummaryFromValue(value);
    if (!rally || !rally.gameId) {
      toast('That game changed. Find another game.');
      refreshLookingBanner();
      return null;
    }
    const existingArrival = activeArrivalForGame(rally.gameId, rally.myArrival, rally);
    if (existingArrival) return openArrivalDetails(existingArrival);
    if (!rally.arrivalAvailable || !rally.arrivalCapability) {
      toast('This game is about to start. Find another game.');
      refreshLookingBanner();
      return null;
    }
    if (rally.spotsLeft <= 0) {
      toast('That game is full.');
      return null;
    }
    const callerSession = instantRallySession();
    if (!callerSession) return null;
    const pending = readRallyArrivalAttempt(callerSession.userId, rally.gameId);
    const initialEta = pending ? pending.etaMinutes : 10;
    const modal = openModal(`
      ${modalHead(`On my way to ${rally.courtName}`, 'map-pin')}
      <p class="arrival-summary" role="status">${esc(rallyCountsText(rally))}</p>
      <form id="arrival-eta-form" novalidate>
        <fieldset class="arrival-eta-fieldset">
          <legend>When can you arrive?</legend>
          <div class="arrival-eta-options">
            ${[5, 10, 15].map((eta) => `
              <label class="arrival-eta-option">
                <input type="radio" name="arrival-eta" value="${eta}" ${eta === initialEta ? 'checked' : ''}>
                <span>${eta}<small>min</small></span>
              </label>`).join('')}
          </div>
        </fieldset>
        <p class="arrival-status-explainer">This shares your ETA with the players. It does not reserve entry; join when you arrive if space is still open.</p>
        ${pending ? `<p class="arrival-retry-note" role="status">We still need to confirm your ${pending.etaMinutes}-minute arrival.</p>` : ''}
        <p class="form-error hidden" id="arrival-error" role="alert" tabindex="-1"></p>
        <button type="submit" class="btn btn-primary btn-block" id="arrival-confirm">On my way · ${initialEta} min</button>
        <a class="btn btn-secondary btn-block arrival-directions" data-arrival-directions target="_blank" rel="noopener" aria-label="Directions to ${esc(rally.courtName)} (opens Maps)">${uiIcon('external')}<span>Directions</span></a>
        <button type="button" class="btn-link modal-close btn-block">Not now</button>
      </form>
    `, { label: `Choose your ETA for ${rally.courtName}` });
    hydrateArrivalDirections(modal, rally);
    const form = modal.querySelector('#arrival-eta-form');
    const button = modal.querySelector('#arrival-confirm');
    const errorEl = modal.querySelector('#arrival-error');
    const syncEta = () => {
      const eta = Number(form.elements['arrival-eta'].value) || initialEta;
      button.textContent = pending ? `Try again · ${eta} min` : `On my way · ${eta} min`;
    };
    form.addEventListener('change', syncEta);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (button.disabled) return;
      const eta = Number(form.elements['arrival-eta'].value);
      if (![5, 10, 15].includes(eta)) {
        errorEl.textContent = ERROR_TEXT.invalid_eta_minutes;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
        return;
      }
      button.disabled = true;
      button.setAttribute('aria-busy', 'true');
      button.textContent = pending ? 'Checking your ETA…' : 'Sharing your ETA…';
      errorEl.classList.add('hidden');
      try {
        const result = await reserveRallyArrival(rally, eta);
        if (!result || result.abandoned || !document.body.contains(modal)) return;
        toast(result.outcome === 'existing' ? 'Your ETA is already shared' : `You’re on your way to ${rally.courtName}`);
        refreshMe().catch(() => {});
        if (fromModal?.isConnected && typeof fromModal._refreshGameDetail === 'function') {
          fromModal._refreshGameDetail();
          closeModal(modal);
          return;
        }
        // The persistent arrival banner is the saved confirmation. Return to
        // Play instead of making the player dismiss a second status sheet.
        closeModal(modal);
        setPlaySegment('games', { render: false });
        switchTab('play');
      } catch (error) {
        if (!instantRallySessionMatches(callerSession) || !document.body.contains(errorEl)) return;
        if (error.code === 'already_joined') {
          clearArrivalAfterConfirmedMembership(callerSession, rally.gameId);
          transitionModal(modal, () => openGameScreen(rally.gameId));
          refreshMe().catch(() => {});
          return;
        }
        if (['already_at_court', 'active_checkin_elsewhere'].includes(error.code)) {
          // Presence errors are authoritative even if the follow-up /me read
          // is offline. Keep routing the player to an explicit, private
          // court-confirmation path instead of escaping this submit handler.
          await refreshMe().catch(() => false);
          if (!instantRallySessionMatches(callerSession) || !document.body.contains(modal)) return;
          let atTargetCourt = isCheckedInAtCourt(rally.courtId);
          if (error.code === 'already_at_court' && !atTargetCourt) {
            // The rejected ETA request is itself an authoritative same-court
            // presence check. Keep it private while handing off to direct join.
            invalidateMeRequests();
            state.presence = {
              ...(state.presence || {}),
              checked_in: true,
              court_id: rally.courtId,
              court_name: rally.courtName,
              looking_for_game: false,
            };
            renderPresenceBanner();
            atTargetCourt = true;
          }
          if (atTargetCourt) {
            button.disabled = false;
            button.removeAttribute('aria-busy');
            await openReadyRally(rally, button);
            return;
          }
          errorEl.textContent = error.message;
          errorEl.classList.remove('hidden');
          errorEl.focus({ preventScroll: true });
          return;
        }
        if (['active_arrival_elsewhere', 'arrival_already_active'].includes(error.code)) {
          await refreshMe().catch(() => {});
          if (state.activeArrival && document.body.contains(modal)) {
            transitionModal(modal, () => openArrivalDetails(state.activeArrival));
            return;
          }
        }
        if (['rally_no_longer_active', 'rally_full', 'arrival_slot_taken', 'game_not_found'].includes(error.code)) {
          state.playGamesCache = null;
          refreshLookingBanner();
        }
        const ambiguous = arrivalRequestIsAmbiguous(error);
        errorEl.textContent = ambiguous
          ? 'We couldn’t confirm your ETA. Try again.'
          : error.message;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
        const saved = readRallyArrivalAttempt(callerSession.userId, rally.gameId);
        if (saved) {
          form.querySelectorAll('input[name="arrival-eta"]').forEach((input) => {
            input.checked = Number(input.value) === saved.etaMinutes;
          });
        }
      } finally {
        if (document.body.contains(button)) {
          button.disabled = false;
          button.removeAttribute('aria-busy');
          syncEta();
        }
      }
    });
    return modal;
  }

  async function cancelRallyArrival(arrival, modal, button, errorEl) {
    const callerSession = instantRallySession();
    if (!callerSession || !arrival || button.disabled) return;
    const original = button.textContent;
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.textContent = 'Cancelling…';
    errorEl?.classList.add('hidden');
    try {
      await api(`/games/${arrival.gameId}/arrival`, { method: 'DELETE' });
      if (!instantRallySessionMatches(callerSession)) return;
      clearRallyArrivalAttempt(callerSession.userId, arrival.gameId);
      invalidateMeRequests();
      state.activeArrival = null;
      refreshPlayGamesAfterRallyMutation();
      renderActiveGameBanner();
      refreshLookingBanner();
      closeModal(modal);
      toast('You’re no longer marked on the way');
      refreshMe().catch(() => {});
    } catch (error) {
      if (!instantRallySessionMatches(callerSession) || !document.body.contains(button)) return;
      if (errorEl) {
        errorEl.textContent = error.message;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
      } else toast(error.message);
      button.disabled = false;
      button.removeAttribute('aria-busy');
      button.textContent = original;
    }
  }

  function openArrivalDetails(value) {
    const arrival = normalizeActiveArrival(value);
    if (!arrival) {
      state.activeArrival = null;
      renderActiveGameBanner();
      toast('That ETA expired. Find another game.');
      refreshMe().catch(() => {});
      return null;
    }
    const rally = arrivalRallySummary(arrival);
    const modal = openModal(`
      ${modalHead(`On your way to ${arrival.courtName}`, 'map-pin')}
      <div class="arrival-status-card" role="status">
        <span class="arrival-status-icon" aria-hidden="true">${uiIcon('check')}</span>
        <div><b>ETA shared with players at ${esc(arrival.courtName)}</b><span>${esc(arrivalEtaLabel(arrival))}</span></div>
      </div>
      <p class="arrival-status-copy">${esc(arrivalStatusCopy(arrival))}</p>
      <p class="arrival-summary" role="status">${esc(rallyCountsText(rally))}</p>
      <a class="btn btn-secondary btn-block arrival-directions" data-arrival-directions target="_blank" rel="noopener" aria-label="Directions to ${esc(arrival.courtName)} (opens Maps)">${uiIcon('external')}<span>Directions</span></a>
      <button type="button" class="btn btn-primary btn-block" id="arrival-im-here">I’m at the court · check in &amp; join</button>
      <button type="button" class="btn btn-danger btn-block" id="arrival-cancel">Not coming</button>
      <p class="form-error hidden" id="arrival-detail-error" role="alert" tabindex="-1"></p>
      <button type="button" class="btn-link modal-close btn-block">Close</button>
    `, { label: `On my way to ${arrival.courtName}` });
    hydrateArrivalDirections(modal, rally);
    modal.querySelector('#arrival-im-here').addEventListener('click', async (event) => {
      await confirmArrivalAtCourtAndJoin(arrival, {
        button: event.currentTarget,
        errorEl: modal.querySelector('#arrival-detail-error'),
      });
    });
    modal.querySelector('#arrival-cancel').addEventListener('click', async (event) => {
      const button = event.currentTarget;
      if (!await openActionConfirmation({
        eyebrow: 'On my way',
        title: 'Not coming?',
        message: `Players at ${arrival.courtName} will no longer see that you’re on the way.`,
        detail: 'This does not affect game capacity. You can share a new ETA later.',
        confirmLabel: 'Not coming',
        cancelLabel: 'Keep sharing',
        icon: 'map-pin',
        trigger: button,
      })) return;
      if (!modal.isConnected) return;
      cancelRallyArrival(arrival, modal, button, modal.querySelector('#arrival-detail-error'));
    });
    return modal;
  }

  async function confirmArrivalAtCourtAndJoin(value, { button, errorEl = null } = {}) {
    const arrival = normalizeActiveArrival(value);
    const resemblesArrival = !!(value && (value.expires_at || value.expiresAt));
    if (!arrival && resemblesArrival) {
      state.activeArrival = null;
      renderActiveGameBanner();
      toast('That ETA expired. Find another game.');
      refreshMe().catch(() => {});
      return null;
    }
    const rally = arrival ? arrivalRallySummary(arrival)
      : (value && value.courtId ? value : rallySummaryFromValue(value));
    if (!rally) {
      toast('Find another game before confirming this court.');
      return null;
    }
    if (!button || button.disabled) return null;
    const callerSession = instantRallySession();
    if (!callerSession) return null;
    const originalHtml = button.innerHTML;
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.textContent = 'Confirming your location…';
    errorEl?.classList.add('hidden');
    try {
      const presenceLocation = await freshCourtPresenceLocation({
        id: rally.courtId,
        name: rally.courtName,
      });
      if (!instantRallySessionMatches(callerSession)) return null;
      button.textContent = 'Checking you in…';
      const checkedIn = await api(`/courts/${rally.courtId}/checkin`, {
        method: 'POST',
        body: JSON.stringify({
          looking_for_game: false,
          presence_intent: 'arrival_join',
          presence_location: presenceLocation,
        }),
      });
      if (!instantRallySessionMatches(callerSession)) return null;
      applyAuthoritativeCheckIn(
        { id: rally.courtId, name: rally.courtName }, checkedIn, false,
      );
      button.disabled = false;
      button.removeAttribute('aria-busy');
      button.textContent = 'Joining the game…';
      const joined = await openReadyRally(rally, button);
      if (!instantRallySessionMatches(callerSession)) return null;
      refreshMe().catch(() => {});
      fetchCourtsInView();
      return joined;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return null;
      if (errorEl && document.body.contains(errorEl)) {
        errorEl.textContent = error.message;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
      } else {
        toast(error.message, { tone: 'warning' });
      }
      return null;
    } finally {
      if (document.body.contains(button) && !button.dataset.joiningRally) {
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.innerHTML = originalHtml;
      }
    }
  }

  function refreshPlayGamesAfterRallyMutation() {
    state.playGamesCache = null;
    if (state.tab === 'play' && state.playSeg === 'games') renderPlay();
  }

  function clearArrivalAfterConfirmedMembership(callerSession, arrivalGameId) {
    if (!instantRallySessionMatches(callerSession)) return;
    const gameId = safePositiveId(arrivalGameId);
    invalidateMeRequests();
    if (gameId) clearRallyArrivalAttempt(callerSession.userId, gameId);
    if (!state.activeArrival || !gameId || state.activeArrival.gameId === gameId) {
      state.activeArrival = null;
      renderActiveGameBanner();
    }
    refreshPlayGamesAfterRallyMutation();
  }

  async function openReadyRally(rally, button = null) {
    const summary = rally && rally.courtId ? rally : rallySummaryFromValue(rally);
    const courtId = safePositiveId(summary && summary.courtId);
    const sourceModal = button && button.closest('.modal-backdrop');
    if (!courtId) {
      state.chatSeg = 'friends';
      state.peopleMode = 'nearby';
      switchTab('chat');
      return null;
    }
    const showCurrentOptions = () => {
      const open = () => openGameFlow({
        mode: 'find',
        court: {
          id: courtId,
          name: summary.courtName || 'Selected court',
          city: summary.courtCity || '',
        },
        gameType: summary.gameType,
        maxPlayers: summary.maxPlayers,
        community: summary.gameType !== 'ranked',
      });
      if (sourceModal && currentOverlayEntry()?.el === sourceModal) {
        transitionModal(sourceModal, open);
      } else {
        open();
      }
      return null;
    };
    const ownArrival = activeArrivalForGame(summary.gameId, summary.myArrival, summary);
    if (!isCheckedInAtCourt(courtId)) {
      const openConfirmation = () => ownArrival
        ? openArrivalDetails(ownArrival)
        : openRallyArrivalSheet(summary);
      if (sourceModal && currentOverlayEntry()?.el === sourceModal) {
        transitionModal(sourceModal, openConfirmation);
        return null;
      }
      return openConfirmation();
    }
    if (summary.spotsLeft <= 0 && !ownArrival) {
      toast(summary.onWayCount > 0
        ? 'That game is about to start — showing current options at this court.'
        : 'That game is full — showing current options at this court.');
      return showCurrentOptions();
    }
    const gameId = safePositiveId(summary.gameId);
    const callerSession = instantRallySession();
    if (!callerSession) return null;
    if (!gameId) return showCurrentOptions();
    if (button?.dataset.joiningRally === 'true') return null;
    const original = button?.innerHTML;
    if (button) {
      button.dataset.joiningRally = 'true';
      button.disabled = true;
      button.setAttribute('aria-busy', 'true');
      button.textContent = 'Joining…';
    }
    try {
      await api(`/games/${gameId}/join`, { method: 'POST' });
      if (!instantRallySessionMatches(callerSession)) return null;
      clearArrivalAfterConfirmedMembership(callerSession, gameId);
      showJoinedToast(gameId, "You're in the game!", {
        onUndone: () => {
          if (state.tab === 'play' && state.playSeg === 'games') renderPlay();
        },
      });
      refreshMe().catch(() => {});
      openResolvedRallyGame(gameId, sourceModal || null);
      return gameId;
    } catch (error) {
      if (!instantRallySessionMatches(callerSession)) return null;
      const staleCodes = ['game_full', 'game_not_open', 'game_not_found', 'rally_no_longer_active'];
      if (staleCodes.includes(error.code)) {
        toast('That game just changed — showing current options');
        return showCurrentOptions();
      }
      if (error.code === 'already_joined') {
        clearArrivalAfterConfirmedMembership(callerSession, gameId);
        openResolvedRallyGame(gameId, sourceModal || null);
        return gameId;
      }
      // A direct join only owns another game when the server explicitly says
      // this player already has an active rally. Do not open arbitrary IDs
      // embedded in stale/privacy errors.
      const recoveredGame = error.code === 'active_rally_elsewhere'
        ? authoritativeRallyGame(error) : null;
      if (recoveredGame) {
        clearInstantRallyAttempt();
        clearArrivalAfterConfirmedMembership(callerSession, gameId);
        toast('You already have a pickup game in progress — opening it now');
        openResolvedRallyGame(recoveredGame.id, sourceModal || null);
        return recoveredGame.id;
      }
      if (['active_checkin_required', 'active_checkin_court_mismatch'].includes(error.code)) {
        const openConfirmation = () => {
          if (!instantRallySessionMatches(callerSession)) return;
          if (sourceModal) {
            if (!document.body.contains(sourceModal)
                || currentOverlayEntry()?.el !== sourceModal) return;
            transitionModal(sourceModal, () => openGameFlow({
              mode: 'find',
              court: { id: courtId, name: summary.courtName || 'Selected court' },
              gameType: summary.gameType,
              community: summary.gameType !== 'ranked',
            }));
          } else {
            openGameFlow({
              mode: 'find',
              court: { id: courtId, name: summary.courtName || 'Selected court' },
              gameType: summary.gameType,
              community: summary.gameType !== 'ranked',
            });
          }
        };
        refreshMe().finally(openConfirmation);
        return null;
      }
      toast(error.message);
      return null;
    } finally {
      if (button && document.body.contains(button)) {
        delete button.dataset.joiningRally;
        button.disabled = false;
        button.removeAttribute('aria-busy');
        button.innerHTML = original;
      }
    }
  }

  function applyAuthoritativeCheckIn(court, response, lookingForGame) {
    const selected = playNowCourt(court) || {
      id: safePositiveId(court && (court.id ?? court.court_id)),
      name: String(court && (court.name ?? court.court_name) || 'Court'),
    };
    const fallbackPresence = {
      ...(state.presence || {}),
      checked_in: true,
      court_id: selected.id,
      court_name: selected.name,
      looking_for_game: lookingForGame === true,
    };
    // This mutation response is newer than every /me request already in flight.
    invalidateMeRequests();
    state.presence = response && response.presence
      ? response.presence : fallbackPresence;
    rememberInstantRallyPresenceProof(selected.id, response);
    // Check-in atomically ends the remote "free this hour" signal server-side.
    state.activePlayPulse = null;
    state.playGamesCache = null;
    renderPresenceBanner();
    renderActiveGameBanner();
    updatePlayHeader();
    refreshLookingBanner();
    fetchCourtsInView();
  }

  function openCourtClosureReport(court, onSaved) {
    const modal = openModal(`${modalHead(court.closed ? 'Report this court reopened' : 'Report permanent closure')}<form class="business-feature-body" id="court-closure-report"><p class="row-sub">${esc(court.name)} stays as listed until an operator reviews the evidence. Temporary weather or maintenance belongs in Report conditions.</p><div class="form-field"><label for="closure-evidence">What did you confirm?</label><textarea id="closure-evidence" required minlength="12" maxlength="500" rows="4" placeholder="What changed, when, and an official notice or other source"></textarea></div><p class="simple-note">A reviewed closure pauses new play and check-ins. Existing session participants receive an update.</p><p class="form-error hidden" role="alert"></p><button type="submit" class="btn btn-primary btn-block">Submit for review</button></form>`);
    const form = modal.querySelector('form');
    form.addEventListener('submit', async event => {
      event.preventDefault();
      const evidence = form.querySelector('textarea').value.trim();
      const error = form.querySelector('[role="alert"]');
      if (evidence.length < 12) { error.textContent = 'Add a short explanation and your source.'; error.classList.remove('hidden'); form.querySelector('textarea').focus(); return; }
      const button = form.querySelector('[type="submit"]');
      const reset = beginButtonAction(button, 'Submitting…'); if (!reset) return;
      try { await api(`/courts/${court.id}/suggest`, {method:'POST', body:JSON.stringify({closed:!court.closed,evidence})}); closeModal(modal); toast('Report submitted for operator review.'); onSaved?.(); }
      catch (failure) { reset(); error.textContent = failure.message; error.classList.remove('hidden'); }
    });
    return modal;
  }

  function openCheckInSheet(court, onCheckedIn = null, {
    defaultLooking = true,
    presenceIntent = 'manual_checkin',
  } = {}) {
    const modal = openModal(`
      <div class="checkin-sheet">
        <div class="checkin-sheet-icon" aria-hidden="true">${uiIcon('map-pin')}</div>
        <h3 style="margin:6px 0 2px">I’m at ${esc(court.name)}</h3>
        <p class="row-sub checkin-sheet-intro">Share that you’re here. Location confirmation does not save your precise coordinates or reserve a session place.</p>
        <form id="ci-form">
          <fieldset class="checkin-visibility-fieldset">
            <legend class="sr-only">Check-in visibility</legend>
            <label class="checkin-visibility-option">
              <input type="radio" name="checkin-visibility" value="looking" ${defaultLooking ? 'checked' : ''}>
              <span>${uiIcon('users')}<span><b>Check in &amp; look for a game</b><small>${esc(courtPresenceAudience(true))}</small></span></span>
            </label>
            <label class="checkin-visibility-option">
              <input type="radio" name="checkin-visibility" value="quiet" ${defaultLooking ? '' : 'checked'}>
              <span>${uiIcon('shield')}<span><b>Check in quietly</b><small>${esc(courtPresenceAudience(false))}</small></span></span>
            </label>
          </fieldset>
          <button type="submit" class="btn btn-primary btn-block" id="ci-submit">${uiIcon('check-circle')} Check in</button>
        </form>
        <p class="play-now-privacy"><span aria-hidden="true">${uiIcon('clock')}</span> Your check-in expires automatically. Check out whenever you leave.</p>
        <p class="form-error hidden" id="ci-error" role="alert" tabindex="-1"></p>
        ${presenceIntent === 'manual_checkin' ? `<div id="ci-self-report" class="hidden"><p class="simple-note">Indoors or unable to use location? You can share an unconfirmed check-in. Starting an immediate game still needs location confirmation.</p><button type="button" class="btn btn-secondary btn-block" id="ci-self-report-submit">I’m here — share without location confirmation</button></div>` : ''}
        <button type="button" class="btn-link modal-close btn-block" style="margin-top:8px">Cancel</button>
      </div>
    `);
    const errorEl = modal.querySelector('#ci-error');
    const form = modal.querySelector('#ci-form');
    const button = modal.querySelector('#ci-submit');
    const callerSession = instantRallySession();
    const selfReportPanel = modal.querySelector('#ci-self-report');
    const selfReportButton = modal.querySelector('#ci-self-report-submit');
    const submitCheckIn = async (selfReport = false) => {
      if (button.dataset.submitting === 'true') return;
      if (!callerSession || !instantRallySessionMatches(callerSession)) {
        errorEl.textContent = 'Sign in again before checking in.';
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
        return;
      }
      const lookingForGame = form.elements['checkin-visibility'].value === 'looking';
      const original = button.innerHTML;
      button.dataset.submitting = 'true';
      button.disabled = true;
      if (selfReportButton) selfReportButton.disabled = true;
      form.querySelector('fieldset').disabled = true;
      button.setAttribute('aria-busy', 'true');
      button.textContent = 'Checking in…';
      errorEl.classList.add('hidden');
      try {
        button.textContent = 'Confirming your location…';
        const presenceLocation = selfReport ? null : await freshCourtPresenceLocation(court);
        if (!instantRallySessionMatches(callerSession) || !modal.isConnected) return;
        button.textContent = 'Checking in…';
        const response = await api(`/courts/${court.id}/checkin`, {
          method: 'POST',
          body: JSON.stringify({
            looking_for_game: lookingForGame,
            presence_intent: selfReport ? 'self_reported' : presenceIntent,
            ...(selfReport ? {confirm_at_court: true} : {presence_location: presenceLocation}),
          }),
        });
        if (!instantRallySessionMatches(callerSession)) return;
        applyAuthoritativeCheckIn(court, response, lookingForGame);
      } catch (error) {
        if (!instantRallySessionMatches(callerSession) || !modal.isConnected) return;
        errorEl.textContent = error.message;
        errorEl.classList.remove('hidden');
        errorEl.focus({ preventScroll: true });
        if (selfReportPanel && ['invalid_presence_location', 'location_accuracy_too_low', 'court_location_unavailable'].includes(error.code || error.error)) selfReportPanel.classList.remove('hidden');
        delete button.dataset.submitting;
        button.disabled = false;
        if (selfReportButton) selfReportButton.disabled = false;
        button.removeAttribute('aria-busy');
        form.querySelector('fieldset').disabled = false;
        button.innerHTML = original;
        return;
      }
      const followupLoad = beginFollowupAfterClosingModal(modal);
      toast(lookingForGame
        ? `You’re looking for a game at ${court.name}`
        : `Checked in quietly at ${court.name}`);
      refreshMe().catch(() => { /* the check-in response remains authoritative */ });
      if (!selfReport && followupLoad && routedOverlayLoadIsCurrent(followupLoad)) {
        maybeAskHours(court);
      }
      onCheckedIn?.();
      if (!selfReport) maybeOfferAutoCheckInAfterManualCheckIn(court);
    };
    form.addEventListener('submit', event => { event.preventDefault(); submitCheckIn(false); });
    selfReportButton?.addEventListener('click', () => submitCheckIn(true));
    return modal;
  }

  // ---------- Games ----------
  function gameCancellationDataAttributes(game) {
    const court = game.court || {};
    const playerCount = Array.isArray(game.players) ? game.players.length : Number(game.player_count) || 0;
    return [
      `data-cancel-court="${esc(court.name || game.court_name || '')}"`,
      `data-cancel-when="${esc(game.scheduled_at || '')}"`,
      `data-cancel-type="${game.game_type === 'ranked' ? 'ranked' : 'casual'}"`,
      `data-cancel-max="${Number(game.max_players) || 4}"`,
      `data-cancel-players="${playerCount}"`,
      `data-cancel-instant="${game.is_instant ? 'true' : 'false'}"`,
    ].join(' ');
  }

  function gameCancellationFromDataset(element) {
    return {
      id: safePositiveId(element?.dataset.gameDismiss || element?.dataset.gameCancel),
      court: { name: element?.dataset.cancelCourt || '' },
      scheduled_at: element?.dataset.cancelWhen || null,
      game_type: element?.dataset.cancelType === 'ranked' ? 'ranked' : 'casual',
      max_players: Number(element?.dataset.cancelMax) || 4,
      player_count: Number(element?.dataset.cancelPlayers) || 0,
      is_instant: element?.dataset.cancelInstant === 'true',
    };
  }

  function gameCancellationVariant(variant, game) {
    const playNoun = game.game_type === 'ranked' ? 'match' : 'play session';
    if (variant === 'stale') return {
      eyebrow: `Close out this ${playNoun}`,
      heading: 'Mark it as not played?',
      intro: `Use this when the ${playNoun} never actually happened.`,
      impact: 'No score or rating will be recorded, and it will be cleared from everyone’s feed. This can’t be undone.',
      action: 'Mark as not played',
      keep: `Keep ${playNoun}`,
      success: `${playNoun === 'match' ? 'Match' : 'Play session'} cleared`,
      successCopy: 'It’s closed with no score or rating change.',
      icon: 'trash',
    };
    if (variant === 'instant' || game.is_instant) return {
      eyebrow: 'Live play session',
      heading: 'End this play session for everyone?',
      intro: 'This pickup game is active now, so ending it takes effect immediately.',
      impact: 'The live play session will close, “On my way” statuses will end, and everyone in it will be notified. This can’t be undone.',
      action: 'End session for everyone',
      keep: 'Keep session going',
      success: 'Play session ended',
      successCopy: 'The game is closed and its “On my way” statuses ended.',
      icon: 'x',
    };
    if (variant === 'challenge') return {
      eyebrow: 'Ranked challenge',
      heading: 'Decline this challenge?',
      intro: 'You won’t be added to the matchup.',
      impact: 'The challenger will be notified and this matchup will be cancelled. No rating changes will be recorded.',
      action: 'Decline challenge',
      keep: 'Keep challenge',
      success: 'Challenge declined',
      successCopy: 'The challenger has been notified.',
      icon: 'x',
    };
    return {
      eyebrow: 'Cancel for everyone',
      heading: `Cancel this ${playNoun}?`,
      intro: `Take a second to make sure this is the ${playNoun} you mean.`,
      impact: `Everyone in the ${playNoun} and on the waitlist will be notified, and it will be removed from upcoming play. This can’t be undone.`,
      action: `Yes, cancel ${playNoun}`,
      keep: `Keep ${playNoun}`,
      success: `${playNoun === 'match' ? 'Match' : 'Play session'} cancelled`,
      successCopy: `Players have been notified and the ${playNoun} is no longer upcoming.`,
      icon: 'trash',
    };
  }

  function gameHasDatedSeries(game) {
    return Number(game?.recurrence_series_id) > 0 || game?.recurrence === 'weekly';
  }

  function recurrenceScopeChoicesHtml(game, prefix, action = 'Edit') {
    if (!gameHasDatedSeries(game)) return '';
    return `<fieldset class="recurrence-scope-picker"><legend>${esc(action)} which dates?</legend>
      <label><input type="radio" name="${prefix}-scope" value="this_date" checked /><span><b>This date only</b><small>${esc(fmtDateTime(game.scheduled_at))}</small></span></label>
      <label><input type="radio" name="${prefix}-scope" value="following_dates" /><span><b>This and future dates</b><small>Earlier sessions stay unchanged</small></span></label>
    </fieldset>`;
  }

  function gameOccurrencesHtml(game, rows) {
    const dates = (Array.isArray(rows) ? rows : []).filter((row) => safePositiveId(row.id));
    if (!dates.length) return '<p class="row-sub">No other dates are available.</p>';
    const statusLabel = (row) => row.status === 'cancelled' ? 'Cancelled'
      : row.status === 'completed' ? 'Played'
        : row.status === 'expired' ? 'Past · attendance not recorded'
          : row.status === 'awaiting_confirmation' ? 'Result pending'
            : row.is_skipped ? 'Skipped' : row.is_joined ? 'Going' : `${Math.max(0, Number(row.max_players) - Number(row.player_count))} spots`;
    const upcoming = dates.filter((row) => row.status === 'upcoming' && Date.parse(row.scheduled_at) > Date.now());
    const next = upcoming.find((row) => Number(row.id) !== Number(game.id));
    const isPast = !['upcoming', 'awaiting_confirmation'].includes(game.status);
    return `<div class="series-date-heading"><span>${uiIcon('calendar')} <b>Session dates</b></span><small>${upcoming.length} upcoming</small></div>
      <label class="series-date-select"><span class="sr-only">Choose a session date</span><select id="gs-occurrence-select" aria-label="Choose a session date" data-native-select>
        ${dates.map((row) => `<option value="${row.id}" ${Number(row.id) === Number(game.id) ? 'selected' : ''}>${esc(fmtDateTime(row.scheduled_at))} · ${esc(statusLabel(row))}</option>`).join('')}
      </select></label>
      ${isPast && next ? `<a class="btn btn-primary btn-block series-next-date" href="#game/${next.id}" data-series-date="${next.id}">${uiIcon('arrow-right')} Next session · ${esc(fmtDateTime(next.scheduled_at))}</a>` : ''}
      <small class="series-date-footnote">Each date has its own players and result.</small>`;
  }

  function openGameCancellationConfirmation({
    game = {}, gameId = null, variant = 'scheduled', endpoint = null,
    trigger = null, onCancelled = null,
  } = {}) {
    const resolvedGameId = safePositiveId(gameId ?? game.id);
    if (!resolvedGameId || trigger?.dataset.cancelSheetOpen === 'true') return null;
    const config = gameCancellationVariant(variant, game);
    const recurring = gameHasDatedSeries(game) && variant !== 'challenge';
    const playNoun = game.game_type === 'ranked' ? 'match' : 'play session';
    const courtName = game.court?.name || game.court_name || 'Court not listed';
    const format = Number(game.max_players) === 2 ? 'Singles'
      : Number(game.max_players) === 4 ? 'Doubles' : `${Number(game.max_players) || 4} players`;
    const type = game.game_type === 'ranked' ? 'Ranked' : 'Casual';
    const when = (variant === 'instant' || game.is_instant) ? 'Live now'
      : game.time_vote ? 'Time TBD' : game.scheduled_at ? fmtDateTime(game.scheduled_at) : 'Time not listed';
    const playerCount = Array.isArray(game.players) ? game.players.length : Number(game.player_count) || 0;
    const roster = playerCount ? `${playerCount} player${playerCount === 1 ? '' : 's'} joined` : '';
    const sheet = openModal(`
      <div class="game-cancel-confirmation${recurring ? ' is-series' : ''}">
        ${modalHead(variant === 'challenge' ? 'Decline challenge' : `Cancel ${playNoun}`)}
        <div class="game-cancel-hero">
          <span class="game-cancel-icon" aria-hidden="true">${uiIcon(config.icon)}</span>
          <div><span class="game-cancel-eyebrow">${esc(config.eyebrow)}</span><h2>${esc(config.heading)}</h2><p>${esc(config.intro)}</p></div>
        </div>
        <div class="game-cancel-summary" aria-label="${playNoun === 'match' ? 'Match' : 'Play session'} being cancelled">
          <div class="game-cancel-summary-court"><span aria-hidden="true">${uiIcon('map-pin')}</span><div><b>${esc(recurring && game.title ? game.title : courtName)}</b><span>${esc(recurring && game.title ? courtName + ' · ' + when : when)}</span></div></div>
          <div class="game-cancel-summary-tags"><span>${esc(type)}</span><span>${esc(format)}</span>${roster ? `<span>${esc(roster)}</span>` : ''}</div>
        </div>
        ${recurring ? recurrenceScopeChoicesHtml(game, 'gc', 'Cancel') + '<section id="gc-dates" class="edit-date-scope hidden" aria-label="Dates to cancel" tabindex="-1"></section>' : ''}
        <div class="game-cancel-impact"><span class="game-cancel-impact-icon" aria-hidden="true">${uiIcon('alert-triangle')}</span><div><b>What happens next</b><p>${esc(config.impact)}</p></div></div>
        <div class="game-cancel-error hidden" role="alert" tabindex="-1"></div>
        <div class="game-cancel-actions">
          <button type="button" class="btn btn-secondary" data-game-cancel-keep>${esc(config.keep)}</button>
          <button type="button" class="btn game-cancel-danger" data-game-cancel-confirm>${esc(config.action)}</button>
        </div>
      </div>
    `, { label: config.heading });
    sheet.classList.add('game-cancel-backdrop');
    if (trigger) sheet._returnFocus = trigger;
    sheet._returnFocusFallback = () => document.querySelector('#bottom-nav .nav-btn[aria-current="page"]');
    if (trigger) trigger.dataset.cancelSheetOpen = 'true';
    sheet._cleanupFns?.push(() => {
      if (trigger) delete trigger.dataset.cancelSheetOpen;
    });
    let committing = false;
    sheet._dismissBlocked = () => committing;
    const keep = sheet.querySelector('[data-game-cancel-keep]');
    const confirmButton = sheet.querySelector('[data-game-cancel-confirm]');
    const error = sheet.querySelector('.game-cancel-error');
    const closeButton = sheet.querySelector('.modal-close');
    const selectedScope = () => sheet.querySelector('input[name="gc-scope"]:checked')?.value || 'this_date';
    let cancelDates = null, dateSequence = 0;
    const viewerId = state.me?.id;
    sheet._cleanupFns.push(() => { dateSequence += 1; });
    const loadCancelDates = async ({ focus = false } = {}) => {
      const panel = sheet.querySelector('#gc-dates');
      const sequence = ++dateSequence;
      cancelDates = null;
      panel.classList.remove('hidden'); panel.setAttribute('aria-busy', 'true');
      panel.textContent = 'Loading dates…'; confirmButton.disabled = true;
      if (focus) { panel.scrollIntoView({block:'center'}); panel.focus({preventScroll:true}); }
      const current = () => sheet.isConnected && sequence === dateSequence && selectedScope() === 'following_dates' && state.me?.id === viewerId;
      try {
        const data = await api(`/games/${resolvedGameId}/edit-dates`);
        if (!current()) return;
        if (!data.token || !Array.isArray(data.dates) || !data.dates.some(row => row.id === resolvedGameId)) throw new Error('Missing dates');
        cancelDates = data;
        panel.removeAttribute('aria-busy');
        panel.innerHTML = `<div class="edit-date-scope-head"><b>${data.dates.length} scheduled date${data.dates.length === 1 ? '' : 's'}</b><span>Will cancel</span></div>
          <ul>${data.dates.map((row,i) => `<li${i >= 3 ? ' class="hidden" data-extra-cancel-date' : ''}><span>${esc(fmtDateTime(row.scheduled_at))}</span>${row.is_selected ? '<small>This date</small>' : ''}</li>`).join('')}</ul>
          ${data.dates.length > 3 ? `<button type="button" class="btn-link" data-expand-cancel-dates aria-expanded="false">Show all ${data.dates.length} dates</button>` : ''}`;
        panel.querySelector('[data-expand-cancel-dates]')?.addEventListener('click', event => {
          const expanded = event.currentTarget.getAttribute('aria-expanded') !== 'true';
          event.currentTarget.setAttribute('aria-expanded', String(expanded));
          event.currentTarget.textContent = expanded ? 'Show fewer dates' : `Show all ${data.dates.length} dates`;
          panel.querySelectorAll('[data-extra-cancel-date]').forEach(row => row.classList.toggle('hidden', !expanded));
        });
        config.action = `Cancel ${data.dates.length} date${data.dates.length === 1 ? '' : 's'}`;
        confirmButton.textContent = config.action; confirmButton.disabled = false;
      } catch (requestError) {
        if (!current()) return;
        panel.removeAttribute('aria-busy');
        if (requestError.code === 'future_host_changed') panel.textContent = requestError.message;
        else {
          panel.innerHTML = '<p>Couldn’t load the dates.</p><button type="button" class="btn btn-secondary btn-sm" data-retry-cancel-dates>Try again</button>';
          panel.querySelector('[data-retry-cancel-dates]').addEventListener('click', () => loadCancelDates({focus:true}));
        }
      }
    };
    const syncScope = () => {
      if (!recurring) return;
      dateSequence += 1; cancelDates = null;
      error.textContent = ''; error.classList.add('hidden');
      const following = selectedScope() === 'following_dates';
      sheet.querySelector('#gc-dates').classList.toggle('hidden', !following);
      config.heading = following ? 'Cancel this and future dates?' : 'Cancel only this date?';
      config.action = following ? 'Cancel these dates' : 'Cancel this date';
      config.success = following ? 'Upcoming dates cancelled' : 'This date cancelled';
      config.successCopy = following ? 'The reviewed dates are cancelled. Earlier sessions stay unchanged.' : 'Your other session dates are unchanged.';
      sheet.querySelector('.game-cancel-hero h2').textContent = config.heading;
      sheet.querySelector('.game-cancel-impact b').textContent = 'Players will be notified';
      sheet.querySelector('.game-cancel-impact p').textContent = following
        ? 'Repeating stops. Earlier dates and results stay in history.'
        : 'Other dates and results stay unchanged.';
      confirmButton.textContent = config.action; confirmButton.disabled = false;
      if (following) loadCancelDates();
    };
    sheet.querySelectorAll('input[name="gc-scope"]').forEach(input => input.addEventListener('change', syncScope));
    syncScope();
    keep.addEventListener('click', () => closeModal(sheet));
    confirmButton.addEventListener('click', async () => {
      if (committing || (recurring && selectedScope() === 'following_dates' && !cancelDates)) return;
      const scope = selectedScope();
      const dateToken = cancelDates?.token;
      committing = true;
      keep.disabled = true;
      confirmButton.disabled = true;
      closeButton.disabled = true;
      sheet.querySelectorAll('input[name="gc-scope"]').forEach(input => { input.disabled = true; });
      confirmButton.setAttribute('aria-busy', 'true');
      sheet.querySelector('.game-cancel-confirmation').setAttribute('aria-busy', 'true');
      confirmButton.textContent = variant === 'challenge' ? 'Declining…' : 'Cancelling…';
      error.classList.add('hidden');
      error.textContent = '';
      try {
        const fresh = await api(endpoint || `/games/${resolvedGameId}/cancel`, {
          method: 'POST',
          ...(recurring ? { body: JSON.stringify({ edit_scope: scope, ...(scope === 'following_dates' ? {expected_edit_dates:dateToken} : {}) }) } : {}),
        });
        committing = false;
        if (!document.body.contains(sheet)) return;
        try { onCancelled?.(fresh); } catch { /* refresh callbacks never hide a successful cancel */ }
        const content = sheet.querySelector('.game-cancel-confirmation');
        content.removeAttribute('aria-busy');
        content.innerHTML = `
          ${modalHead(config.success)}
          <div class="game-cancel-success" role="status" aria-live="polite">
            <span class="game-cancel-success-icon" aria-hidden="true">${uiIcon('check-circle')}</span>
            <h2>${esc(config.success)}</h2>
            <p>${esc(config.successCopy)}</p>
            <button type="button" class="btn btn-primary btn-block" data-game-cancel-done>Done</button>
          </div>`;
        setDialogLabel(sheet.querySelector('.modal'), config.success);
        const done = content.querySelector('[data-game-cancel-done]');
        done.addEventListener('click', () => closeModal(sheet));
        requestAnimationFrame(() => done.focus({ preventScroll: true }));
      } catch (requestError) {
        committing = false;
        keep.disabled = false;
        confirmButton.disabled = false;
        closeButton.disabled = false;
        sheet.querySelectorAll('input[name="gc-scope"]').forEach(input => { input.disabled = false; });
        confirmButton.removeAttribute('aria-busy');
        sheet.querySelector('.game-cancel-confirmation').removeAttribute('aria-busy');
        confirmButton.textContent = config.action;
        error.textContent = requestError.message || `Could not cancel this ${playNoun}. Try again.`;
        error.classList.remove('hidden');
        error.focus?.({ preventScroll: true });
        if (recurring && scope === 'following_dates' && ['edit_dates_changed', 'future_host_changed'].includes(requestError.code)) loadCancelDates({focus:true});
      }
    });
    return sheet;
  }

  // Why a joinable game suits this player: their level, their usual slot.
  function loadPlayPreferences() {
    const id = state.me?.id;
    if (!id || state.playPrefsFor === id) return;
    state.playPrefsFor = id;
    state.playLevelFilter = '';
    state.playRadius = 25;
    state.playWhen = 'any';
    state.playFilters = null;
    try {
      const saved = JSON.parse(localStorage.getItem(`thirdshot-play-preferences:${id}`) || '{}');
      if ([10, 25, 50, 100].includes(saved.radius)) state.playRadius = saved.radius;
      if (normalizedGameLevel(saved.level) != null) state.playLevelFilter = String(saved.level);
    } catch { /* Preferences must never block discovery. */ }
  }

  function savePlayPreferences() {
    if (!state.me?.id) return;
    try { localStorage.setItem(`thirdshot-play-preferences:${state.me.id}`, JSON.stringify({
      radius: state.playRadius, level: state.playLevelFilter,
    })); } catch { /* Storage can be unavailable in private browsing. */ }
  }

  function playDiscoveryWindow(when, now = new Date()) {
    const endsAfter = new Date(now);
    let startsBefore = null;
    if (when === 'now') startsBefore = new Date(now.getTime() + 60 * 60000);
    if (when === 'today') { startsBefore = new Date(now); startsBefore.setHours(24, 0, 0, 0); }
    if (when === 'week') { startsBefore = new Date(now); startsBefore.setDate(startsBefore.getDate() + 7); }
    return { endsAfter, startsBefore };
  }

  function playDiscoveryQuery() {
    const filters = state.playFilters || {};
    const window = filters.date ? playCustomDiscoveryWindow(filters) : playDiscoveryWindow(state.playWhen);
    const params = new URLSearchParams({ ends_after: window.endsAfter.toISOString() });
    if (window.startsAfter) params.set('starts_after', window.startsAfter.toISOString());
    if (window.startsBefore) params.set('starts_before', window.startsBefore.toISOString());
    if (filters.courtId) params.set('court_id', String(filters.courtId));
    if (filters.openSpots) params.set('open_spots', '1');
    return `&${params}`;
  }

  function playCustomDiscoveryWindow(filters, now = new Date()) {
    const startClock = filters.startTime || '00:00';
    const startsAfter = new Date(`${filters.date}T${startClock}`);
    const startsBefore = filters.endTime ? new Date(`${filters.date}T${filters.endTime}`)
      : new Date(`${filters.date}T00:00`);
    if (!filters.endTime) startsBefore.setDate(startsBefore.getDate() + 1);
    const clockMatches = (date, clock) => date.getHours() === Number(clock.slice(0, 2))
      && date.getMinutes() === Number(clock.slice(3, 5));
    const dateMatches = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` === filters.date;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(filters.date) || !Number.isFinite(startsAfter.getTime())
        || !Number.isFinite(startsBefore.getTime()) || !dateMatches(startsAfter)
        || !/^\d{2}:\d{2}$/.test(startClock) || !clockMatches(startsAfter, startClock)
        || (filters.endTime && (!/^\d{2}:\d{2}$/.test(filters.endTime)
          || !dateMatches(startsBefore) || !clockMatches(startsBefore, filters.endTime)))) {
      throw new Error('Choose a valid date and time. This time may not exist when the clocks change.');
    }
    if (startsBefore <= startsAfter) throw new Error('The latest start must be after the earliest start.');
    // Keep the requested interval valid if the page stays open past that day.
    // The server also checks current time, so expired games cannot reappear.
    const endsAfter = new Date(Math.min(now.getTime(), startsAfter.getTime()));
    return { endsAfter, startsAfter, startsBefore };
  }

  function openPlayDiscoveryFilters(onApply) {
    const filters = state.playFilters || {};
    const ownerId = state.me?.id;
    const today = scheduleDateTimeValue(new Date()).slice(0, 10);
    const activeLevel = normalizedGameLevel(state.playLevelFilter);
    const modal = openModal(`${modalHead('Game filters')}
      <form id="pd-form" class="play-filter-form">
        <div class="play-filter-time-row">
          <label>Distance<select id="pd-radius" data-select-title="Distance">${[10,25,50,100].map(radius => `<option value="${radius}" ${state.playRadius === radius ? 'selected' : ''}>Within ${radius} mi</option>`).join('')}</select></label>
          <label>Player level<select id="pd-level" data-select-title="Player level"><option value="">Any level</option>${SELF_RATING_CHOICES.map(([value,,description]) => `<option value="${value}" ${value === activeLevel ? 'selected' : ''}>${value.toFixed(1)} · ${value <= 2.5 ? 'Beginner' : description}</option>`).join('')}</select></label>
        </div>
        <label for="pd-date">Date</label><input type="date" id="pd-date" min="${today}" value="${esc(filters.date || '')}">
        <div class="play-filter-time-row"><label>Earliest start<input type="time" id="pd-start" value="${esc(filters.startTime || '')}"></label><label>Starts before<input type="time" id="pd-end" value="${esc(filters.endTime || '')}"></label></div>
        <p class="play-filter-hint">Your local time. Choose a date to set times.</p>
        <label for="pd-court-search">Court <small>Optional</small></label>
        <input id="pd-court-search" placeholder="Any court, or search by name" value="${esc(filters.courtName || '')}" autocomplete="off">
        <input type="hidden" id="pd-court-id" value="${filters.courtId || ''}"><div id="pd-court-results"></div>
        <p class="play-filter-hint">A selected court replaces the distance filter.</p>
        <label class="play-filter-spots"><input type="checkbox" id="pd-spots" ${filters.openSpots ? 'checked' : ''}><span>Open spots only</span></label>
        <button type="submit" class="btn btn-primary btn-block" id="pd-apply">Show games</button>
        <button type="button" class="btn-link btn-block" id="pd-clear">Clear filters</button>
      </form>`, { label: 'Find a game filters' });
    clubCourtPicker(modal, 'pd');
    const formUX = bindModalFormUX(modal, '#pd-apply');
    const updateTimes = () => {
      for (const id of ['#pd-start', '#pd-end']) modal.querySelector(id).disabled = !modal.querySelector('#pd-date').value;
    };
    modal.querySelector('#pd-date').addEventListener('change', updateTimes);
    updateTimes();
    const apply = (next) => {
      if (state.me?.id !== ownerId) return;
      closeModal(modal);
      onApply(next);
    };
    modal.querySelector('#pd-clear').addEventListener('click', () => apply({playFilters:null,playWhen:'any',playLevelFilter:''}));
    modal.querySelector('#pd-form').addEventListener('submit', (event) => {
      event.preventDefault();
      const date = modal.querySelector('#pd-date').value;
      const courtId = Number(modal.querySelector('#pd-court-id').value) || null;
      const courtName = modal.querySelector('#pd-court-search').value.trim();
      if (courtName && !courtId) return formUX.showError('Choose a court from the search results, or clear the court name.', modal.querySelector('#pd-court-search'));
      const next = {date, startTime:date ? modal.querySelector('#pd-start').value : '',
        endTime:date ? modal.querySelector('#pd-end').value : '',courtId,courtName,
        openSpots:modal.querySelector('#pd-spots').checked};
      try { if (date) playCustomDiscoveryWindow(next); }
      catch (error) { formUX.showError(error.message, modal.querySelector('#pd-date')); return; }
      const radius = Number(modal.querySelector('#pd-radius').value);
      const level = normalizedGameLevel(modal.querySelector('#pd-level').value);
      apply({playFilters:next, playRadius:[10,25,50,100].includes(radius) ? radius : 25,
        playLevelFilter:level == null ? '' : String(level),
        playWhen:date ? 'custom' : state.playWhen === 'custom' ? 'any' : state.playWhen});
    });
    return modal;
  }

  function playDiscoveryFilterLabel({ includeOpenSpots = true } = {}) {
    const filters = state.playFilters || {};
    const clock = (value) => new Date(`${filters.date || '2000-01-01'}T${value}`)
      .toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
    const time = filters.startTime && filters.endTime ? `${clock(filters.startTime)}–${clock(filters.endTime)}`
      : filters.startTime ? `From ${clock(filters.startTime)}`
        : filters.endTime ? `Before ${clock(filters.endTime)}` : '';
    return [filters.date ? new Date(`${filters.date}T12:00`).toLocaleDateString([], {month:'short',day:'numeric'}) : '',
      time,filters.courtName,includeOpenSpots && filters.openSpots ? 'Open spots' : ''].filter(Boolean).join(' · ');
  }

  function gameActivityLabel(game) {
    const size = Number(game.max_players);
    const format = size === 2 ? 'singles' : size === 4 ? 'doubles' : '';
    if (game.game_type === 'ranked') return `Ranked ${format || 'match'}`;
    if (game.play_style) return `Casual · ${sessionPlayStyleLabel(game)}`;
    if (format) return game.is_instant || game.completion_kind !== 'session' && game.status !== 'upcoming' ? `Casual ${format}` : 'Casual session';
    return game.visibility === 'open' ? 'Pickup session' : 'Group session';
  }

  function gameResultScoreboardHtml(game, { compact = false } = {}) {
    const final = game.status === 'completed';
    const series = Array.isArray(game.score_games) && game.score_games.length > 1;
    const winner = !final || Number(game.score_team1) === Number(game.score_team2)
      ? null : Number(game.score_team1) > Number(game.score_team2) ? 1 : 2;
    const teamHtml = (number) => {
      const players = (game.players || []).filter((player) => Number(player.team) === number);
      const score = game[`score_team${number}`];
      return `<div class="match-score-side${winner === number ? ' is-winner' : ''}">
        <div class="match-score-people">
          ${!compact && winner === number ? `<span class="match-winner-label">${uiIcon('trophy')} ${players.length > 1 ? 'Winners' : 'Winner'}</span>` : ''}
          ${compact ? `<span class="match-score-names">${esc(players.map((player) => player.display_name).join(' & ') || `Team ${number}`)}</span>`
            : players.map((player) => `<button type="button" class="match-score-player" data-view-user="${player.user_id}" aria-label="View ${esc(player.display_name)}'s profile">
              ${avatarHtml(player, 'sm', 'span')}<span>${esc(player.display_name)}${player.user_id === state.me?.id ? '<small>You</small>' : ''}</span>
            </button>`).join('')}
        </div>
        <strong class="match-score-number" aria-label="${score == null ? 'No score' : `${score} ${series ? 'games won' : 'points'}`}">${score == null ? '–' : esc(score)}</strong>
      </div>`;
    };
    return `<section class="match-scoreboard${compact ? ' is-compact' : ''}" aria-label="${esc(gameActivityLabel(game))} ${final ? 'result' : 'reported score'}">
      ${series ? '<div class="match-score-caption">Games won</div>' : ''}
      ${teamHtml(1)}${teamHtml(2)}
      ${series && !compact ? `<div class="match-score-games">${game.score_games.map((row, index) => `<span>Game ${index + 1} <b>${esc(row.score_team1)}–${esc(row.score_team2)}</b></span>`).join('')}</div>` : ''}
    </section>`;
  }

  function playGameDecision(game, now = Date.now()) {
    if (game.status !== 'upcoming' || game.is_instant) return null;
    const offerDeadline = Date.parse(game.waitlist_offer?.expires_at || '');
    if (!game.is_joined && offerDeadline > now) return {
      kind: 'offer', label: 'Spot offered', action: 'Review spot offer', deadline: offerDeadline,
    };
    const hostDeadline = Date.parse(game.host_handoff?.expires_at || '');
    if (game.is_joined && game.host_handoff?.can_respond && hostDeadline > now) return {
      kind: 'host', label: 'Host request', action: 'Review host request', deadline: hostDeadline,
    };
    const vote = game.time_vote;
    if (vote?.can_vote && !vote.my_votes.length) return {
      kind: 'vote', label: 'Pick times', action: 'Pick times', deadline: Date.parse(vote.locks_at),
    };
    return null;
  }

  function gameRosterStatus(game) {
    if (game.status !== 'upcoming' || game.is_instant) return null;
    const joined = (game.players || []).length;
    const capacity = Math.max(joined, Number(game.max_players) || joined);
    const raw = game.rsvp_counts?.confirmed ?? game.attendance_confirmed_count;
    const confirmed = Math.min(joined, Math.max(0, raw != null && Number.isFinite(Number(raw))
      ? Number(raw) : (game.players || []).filter((player) => player.attending === true).length));
    if (game.attendance_confirmation_due && game.is_joined && !game.is_creator) {
      return { tone: 'attention', label: game.commitment_confirmation_due ? 'Review changes' : 'Confirm your spot', detail: game.commitment_confirmation_due ? 'The plan changed. Your place is held.' : 'Let the group know you’re still coming.' };
    }
    const held = Math.max(0, Number(game.reserved_offer_count) || 0);
    const supplied = game.spots_left == null ? NaN : Number(game.spots_left);
    const open = Math.max(0, Number.isFinite(supplied) ? supplied : capacity - joined - held);
    const needsReply = Math.max(0, Number(game.rsvp_counts?.needs_confirmation) || 0);
    const reserved = Math.max(0, Number(game.rsvp_counts?.reserved) || 0);
    const maybe = Math.max(0, Number(game.rsvp_counts?.maybe) || 0);
    const withMaybe = (detail) => (maybe ? `${maybe} maybe · ${detail}` : detail);
    if (needsReply || reserved) return { tone: 'forming', label: `${confirmed} confirmed`,
      detail: [needsReply ? `${needsReply} to confirm` : '', reserved ? `${reserved} reserved` : '',
        withMaybe(open ? `${open} spots left` : 'Full')].filter(Boolean).join(' · ') };
    if (open) return { tone: 'forming', label: `${joined} joined`,
      detail: withMaybe(`${open} spot${open === 1 ? '' : 's'} left${held ? ` · ${held} held` : ''}`) };
    if (held) return { tone: 'forming', label: `${joined} joined`,
      detail: withMaybe(`${held} spot${held === 1 ? '' : 's'} held`) };
    if (game.attendance_confirmation_due && confirmed < joined) return { tone: 'forming', label: 'Full',
      detail: `${joined - confirmed} still need${joined - confirmed === 1 ? 's' : ''} to confirm` };
    return joined ? { tone: 'ready', label: `${joined} joined`, detail: withMaybe('Full') } : null;
  }

  function gameRosterStatusHtml(game) {
    const status = gameRosterStatus(game);
    return status ? `<span class="game-roster-status is-${status.tone}"><b>${esc(status.label)}</b><span>${esc(status.detail)}</span></span>` : '';
  }

  function playAgainRowHtml(game) {
    return `<button type="button" class="play-again-row" data-play-again-game="${game.id}">
      <span class="play-again-icon" aria-hidden="true">${uiIcon('refresh')}</span>
      <span class="row-main"><b>Play with this group again</b><small>${esc(game.court?.name || 'Your last court')} · ${game.players.length} players</small></span>${uiIcon('chevron-right', 'chev')}
    </button>`;
  }

  function gameMatchReasons(game) {
    if (!state.me || game.is_joined || game.status !== 'upcoming' || game.spots_left <= 0) return [];
    const reasons = [];
    const [levelMin, levelMax] = gameLevelRange(game);
    const myLevel = normalizedGameLevel(state.me.skill_rating);
    if ((game.level_match === true && (levelMin != null || levelMax != null)) || (
      myLevel != null && levelMin != null && levelMax != null
      && myLevel >= levelMin && myLevel <= levelMax
    )) reasons.push('skill');
    const slot = slotForNow(new Date(game.scheduled_at));
    if (slot && (state.me.availability || []).includes(slot)) reasons.push('time');
    return reasons;
  }

  function gameCardHtml(game, { compact = false } = {}) {
    const court = game.court || {};
    if (game.status === 'completed' && game.completion_kind !== 'session'
        && game.score_team1 != null && game.score_team2 != null) {
      return `<article class="card game-card game-result-card">
        <button type="button" class="game-card-main" data-open-game="${game.id}" aria-label="Open ${esc(gameActivityLabel(game))} result, ${gameScoreText(game)} at ${esc(court.name || 'court')}">
          <span class="game-card-context"><b>${esc(gameActivityLabel(game))}</b><span>${game.game_type === 'ranked' ? 'Confirmed' : 'Final'}</span></span>
          ${gameResultScoreboardHtml(game, { compact: true })}
          <span class="game-card-result-place">${esc(court.name || 'Court')} · ${esc(fmtDateTime(game.completed_at || game.scheduled_at))}</span>
        </button>
      </article>`;
    }
    const assembly = instantRallyAssembly(game);
    const isRankedMatch = game.game_type === 'ranked';
    const playNoun = isRankedMatch ? 'match' : 'session';
    const typeTag = `<span class="game-activity-label${isRankedMatch ? ' is-ranked' : ''}">${uiIcon(game.is_instant ? 'zap' : isRankedMatch ? 'trophy' : 'pickleball')} ${esc(gameActivityLabel(game))}</span>`;
    const visTag = game.visibility === 'private'
      ? `<span class="tag" style="margin:0 0 0 6px">${uiIcon('lock')} Invite</span>`
      : game.visibility === 'friends'
        ? `<span class="tag" style="margin:0 0 0 6px">${uiIcon('users')} Friends</span>`
        : '';
    const inviteTag = game.my_invite_status === 'pending' && game.invited_by
      ? `<span class="tag live" style="margin:0 0 0 6px">${uiIcon('send')} Invited by ${esc((game.invited_by.display_name || 'Host').split(' ')[0])}</span>`
      : '';
    const recurTag = game.recurrence === 'weekly'
      ? `<span class="tag" style="margin:0 0 0 6px">${uiIcon('refresh')} Weekly</span>`
      : '';
    const chatTag = game.is_joined && game.chat_unread
      ? `<span class="tag live" style="margin:0 0 0 6px">${uiIcon('message')} ${game.chat_unread > 9 ? '9+' : game.chat_unread} new</span>`
      : '';
    const levelRangeLabel = gameLevelRangeLabel(game);
    const avatars = game.players.slice(0, 5).map((p) => avatarHtml(p, 'sm')).join('');

    let action = '';
    let banner = '';
    let cardStyle = '';

    if (game.status === 'upcoming' && assembly) {
      cardStyle = 'border:2px solid var(--green-600)';
      const openUntil = game.assembly_expires_at
        ? ` · Open until ${fmtTimeShort(game.assembly_expires_at)}` : '';
      banner = `<span class="status-banner rally-banner">${assembly.banner}${esc(openUntil)}</span>`;
      if (!game.is_joined) {
        const rally = rallySummaryFromValue(game);
        const rallyAction = rallyActionState(rally);
        action = rallyAction.enabled
          ? `<button class="btn btn-primary btn-sm" data-game-join="${game.id}" data-instant-rally="true" ${rallyDatasetAttributes(rally)}>${esc(rallyAction.label)}</button>`
          : `<span class="tag warn" style="margin:0">${esc(rallyAction.label)}</span>`;
      }
    } else if (instantRallyScorePending(game)) {
      banner = `<span class="status-banner">${uiIcon('check-circle')} Played? Finish with no score or add one.</span>`;
      if (game.is_creator) {
        action = `<button class="btn btn-secondary btn-sm" data-game-dismiss="${game.id}" ${gameCancellationDataAttributes(game)}>Mark as not played</button>`;
      }
    } else if (instantSessionWrapPending(game)) {
      banner = `<span class="status-banner">${uiIcon('check-circle')} Finished playing? Tap to wrap up the session.</span>`;
      if (game.is_creator) {
        action = `<button class="btn btn-secondary btn-sm" data-game-dismiss="${game.id}" ${gameCancellationDataAttributes(game)}>Mark as not played</button>`;
      }
    } else if (instantRallyClosed(game)) {
      banner = `<span class="status-banner">${uiIcon('clock')} This pickup group ended without enough players.</span>`;
    } else if (game.status === 'upcoming') {
      const startMs = new Date(game.scheduled_at).getTime();
      const inProgress = startMs <= Date.now();
      // Hours past its start a game isn't "live" anymore — nag for the score
      // (2+ players) or admit it never happened.
      const stale = Date.now() - startMs > 4 * 3600e3;
      if (game.is_joined) {
        if (inProgress && stale) {
          banner = game.players.length >= 2
            ? (Number(game.max_players) > 4
              ? `<span class="status-banner">${uiIcon('check-circle')} Finished playing? Tap to wrap up the session.</span>`
              : `<span class="status-banner">${uiIcon('check-circle')} Played? Finish with no score or add one.</span>`)
            : `<span class="status-banner">${uiIcon('clock')} This ${playNoun} never filled up.</span>`;
          if (game.is_creator) {
            action = `<button class="btn btn-secondary btn-sm" data-game-dismiss="${game.id}" ${gameCancellationDataAttributes(game)}>Mark as not played</button>`;
          }
        } else if (inProgress) {
          cardStyle = 'border:2px solid var(--green-600)';
          banner = `<span class="status-banner live-banner">${uiIcon('activity')} ${game.players.length >= 2
            ? (Number(game.max_players) > 4
              ? 'Session time! Wrap it up here when play ends.'
              : `${isRankedMatch ? 'Match time! Enter the score when it ends.' : 'Pickup game time! Finish with no score or add one.'}`)
            : `Live — waiting for ${isRankedMatch ? 'an opponent' : 'players'} to join.`}</span>`;
        } else {
          action = `<button type="button" class="btn btn-primary btn-sm" data-open-game="${game.id}">Open ${playNoun}</button>${game.time_vote ? '' : `
            <button type="button" class="btn btn-secondary btn-sm" data-game-quick-calendar="${game.id}" aria-label="Add this ${playNoun} to calendar">${uiIcon('calendar')} Calendar</button>`}`;
        }
      } else if (game.spots_left > 0) {
        action = `<button class="btn btn-primary btn-sm" data-game-join="${game.id}" data-play-noun="${playNoun}">${game.recurrence === 'weekly' ? 'Join this date' : `Join ${playNoun}`}</button>`;
      } else if (game.waitlist_position) {
        action = `<button class="btn btn-secondary btn-sm" data-game-waitlist-manage="${game.id}">Waitlisted #${game.waitlist_position}</button>`;
      } else {
        action = `<span class="tag warn" style="margin:0">Full</span>
          <button class="btn btn-secondary btn-sm" data-game-waitlist="${game.id}">${uiIcon('clock')} Waitlist</button>`;
      }
    } else if (game.status === 'awaiting_confirmation') {
      const scoreText = gameScoreText(game, { includeGames: true });
      if (game.awaiting_your_confirmation) {
        cardStyle = 'border:2px solid var(--amber-500)';
        banner = `<span class="status-banner confirm-banner">${uiIcon('edit')} <span>${esc(game.score_submitted_by_name || 'Opponent')} reported <b>${scoreText}</b> — is that right?<small>${esc(scoreAutoConfirmCopy(game))}</small></span></span>`;
        action = `<button class="btn btn-primary btn-sm" data-game-confirm="${game.id}" data-score-version="${Number(game.score_version || 0)}">${uiIcon('check-circle')} Confirm</button>
                  <button type="button" class="btn btn-danger btn-sm" data-game-dispute="${game.id}" data-score-version="${Number(game.score_version || 0)}" aria-label="Dispute this score">${uiIcon('x')}</button>`;
      } else {
        banner = `<span class="status-banner">${uiIcon('clock')} ${scoreText} reported — ${esc(scoreAutoConfirmCopy(game))}</span>`;
      }
    } else if (game.status === 'completed') {
      if (game.completion_kind === 'session') {
        action = `<span class="tag live" style="margin:0">${uiIcon('check-circle')} Session complete</span>`;
      } else {
        if (game.confirmed_automatically) {
          banner = `<span class="status-banner">${uiIcon('clock')} Confirmed automatically after the review window</span>`;
        }
        const delta = game.your_rating_delta;
        const deltaHtml = delta != null
          ? ` <span class="${delta >= 0 ? 'delta-up' : 'delta-down'}">${delta >= 0 ? '+' : ''}${delta}</span>` : '';
        if (game.you_won === true) {
          action = `<span class="tag live" style="margin:0">${uiIcon('trophy')} Won ${gameScoreText(game)}</span>${deltaHtml}`;
        } else if (game.you_won === false) {
          action = `<span class="tag warn" style="margin:0">Lost ${gameScoreText(game)}</span>${deltaHtml}`;
        } else {
          action = `<span class="tag" style="margin:0">${gameScoreText(game)}</span>`;
        }
      }
    }

    if (game.status === 'upcoming' && !game.is_instant && game.is_joined
        && !game.is_creator && game.attendance_confirmation_due) {
      action = game.commitment_confirmation_due
        ? `<button type="button" class="btn btn-primary btn-sm" data-open-game="${game.id}">Review changes</button>`
        : `<button type="button" class="btn btn-primary btn-sm" data-game-attend="${game.id}">I’m coming</button><button type="button" class="btn btn-secondary btn-sm" data-open-game="${game.id}">Review game</button>`;
    }

    const decision = playGameDecision(game);
    if (decision) {
      banner = `<span class="status-banner confirm-banner game-decision-banner">${uiIcon('clock')}<span>${decision.kind === 'offer' ? 'A spot is held for you' : decision.kind === 'vote' ? 'When works for you?' : 'You’ve been asked to host'}<small>Reply by ${esc(fmtDateTime(new Date(decision.deadline).toISOString()))}</small></span></span>`;
      action = `<button type="button" class="btn btn-primary btn-sm" data-open-game="${game.id}">${esc(decision.action)}</button>`;
    }

    const scheduledLabel = game.time_vote ? 'Time TBD · voting'
      : `${fmtDateTime(game.scheduled_at)}${game.ends_at ? ` – ${fmtTimeShort(game.ends_at)}` : ''}`;
    const defaultGameTitle = game.is_instant
      ? `${fmtDateTime(game.scheduled_at)}${assembly ? ' · Live' : ''}`
      : scheduledLabel;
    const customTitle = String(game.title || '').trim();
    const gameTitle = esc(customTitle || defaultGameTitle);
    const costLabel = game.cost_cents == null ? ''
      : Number(game.cost_cents) === 0 ? 'Free'
        : `$${(Number(game.cost_cents) / 100).toFixed(2)} per player`;
    const courtSummary = `${court.name || 'Game'}${!compact && court.city ? ` · ${court.city}` : ''}`;
    const rosterStatus = gameRosterStatusHtml(game);
    const queuedCount = Math.max(0, (Number(game.waitlist_count) || 0) - (Number(game.reserved_offer_count) || 0));
    const playerNames = game.players.slice(0, 3).map((player) => player.user_id === state.me?.id ? 'You' : (player.display_name || 'Player').split(' ')[0]);
    const peopleLabel = playerNames.join(', ') + (game.players.length > 3 ? ` +${game.players.length - 3}` : '');
    const joinedState = game.is_joined && game.status === 'upcoming'
      ? `<span class="game-joined-chip">${uiIcon('check')} ${game.is_creator ? 'Hosting' : game.attendance_confirmation_due ? 'Place held' : 'You’re in'}</span>` : '';
    return `
      <article class="card game-card" style="${cardStyle}">
        <button type="button" class="game-card-main" data-open-game="${game.id}" aria-label="Open ${esc(customTitle || defaultGameTitle)} at ${esc(courtSummary)}">
          ${planDateTileHtml(game.time_vote ? '' : game.scheduled_at)}
          <span class="game-card-body">
          <span class="game-card-context">${typeTag}${joinedState || inviteTag || chatTag}</span>
          <span class="row-title game-card-title">${gameTitle}</span>
          ${customTitle && !game.is_instant ? `<span class="game-card-when">${uiIcon('calendar')} ${esc(scheduledLabel)}</span>` : ''}
          <span class="game-card-place">${uiIcon('map-pin')} <span>${esc(court.name || 'Court')}${game.court_number ? ` · ${esc(game.court_number)}` : ''}</span></span>
          ${visTag || recurTag || levelRangeLabel !== 'Any level' || costLabel ? `<span class="game-card-tags">${visTag}${recurTag}${levelRangeLabel !== 'Any level' ? `<span class="game-card-level">Level ${esc(levelRangeLabel)}</span>` : ''}${costLabel ? `<span class="game-card-level">${esc(costLabel)}</span>` : ''}</span>` : ''}
          </span>
          ${banner}
        </button>
        <div class="row game-card-footer">
          <div class="game-card-people"><div class="avatar-stack">${avatars}</div><span>${esc(peopleLabel || 'Be the first to join')}</span></div>
          <div class="game-card-roster">${rosterStatus || (assembly ? esc(rallyCountsText(assembly)) : `${game.players.length}/${game.max_players} players`)}${queuedCount ? `<span class="game-card-waiting">${queuedCount} waiting</span>` : ''}</div>
          <div class="game-card-actions">${action}</div>
        </div>
      </article>`;
  }

  function showJoinedToast(gameId, message, { onUndone = null, icon = 'pickleball', recurring = false } = {}) {
    toast(message, {
      tone: 'success', icon, duration: 3500,
      action: {
        label: 'Undo',
        onClick: () => {
          api(`/games/${gameId}/${recurring ? 'skip-occurrence' : 'leave'}`, { method: 'POST' }).then((fresh) => {
            state.playGamesCache = null;
            toast('Join undone');
            refreshMe().catch(() => {});
            try { onUndone?.(fresh); } catch (error) { reportClientError(error.message, error.stack); }
          }).catch((error) => {
            if (!error.isStaleSession) toast(error.message, { tone: 'warning' });
          });
        },
      },
    });
  }

  function bindGameButtons(rootEl, refresh) {
    // Each card has one primary detail target; mutation actions are siblings,
    // so joining or confirming can never accidentally open the detail screen.
    rootEl.querySelectorAll('[data-open-game]').forEach((card) => makePressable(card, () => {
      const ownerId = state.me?.id;
      const sourceTab = state.tab;
      const gameId = Number(card.dataset.openGame);
      return openDrillInFrom(rootEl, () => openGameScreen(gameId, {
        returnFocus:card,
        returnFocusFallback:() => state.me?.id === ownerId && state.tab === sourceTab
          ? [...document.querySelectorAll(`[data-open-game="${gameId}"]`)]
            .find(node => node.checkVisibility() && !node.closest('[inert]')) : null,
      }));
    }));
    rootEl.querySelectorAll('[data-game-attend]').forEach((button) => button.addEventListener('click', async () => {
      const reset = beginButtonAction(button, 'Confirming…');
      if (!reset) return;
      const card = button.closest('.game-card');
      clearInlineActionError(card);
      try {
        await api(`/games/${button.dataset.gameAttend}/attend`, { method: 'POST' });
        state.playGamesCache = null;
        reset();
        button.textContent = 'Confirmed';
        button.disabled = true;
        toast('Your spot is confirmed');
        refresh();
      } catch (error) {
        reset();
        if (error.code === 'game_commitment_changed') openGameScreen(Number(button.dataset.gameAttend));
        else showInlineActionError(card, error.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-join]').forEach((b) => b.addEventListener('click', async (e) => {
      e.stopPropagation();
      const playNoun = b.dataset.playNoun === 'match' ? 'match'
        : b.dataset.playNoun === 'session' ? 'session' : 'game';
      if (b.dataset.instantRally === 'true') {
        await openReadyRally(rallySummaryFromDataset(b), b);
        return;
      }
      if (b.disabled) return;
      if (b.dataset.openJoinedGame === 'true') {
        openDrillInFrom(rootEl, () => openGameScreen(Number(b.dataset.gameJoin)));
        return;
      }
      const original = b.textContent;
      const card = b.closest('.game-card, article');
      clearInlineActionError(card);
      b.disabled = true;
      b.setAttribute('aria-busy', 'true');
      b.textContent = 'Joining…';
      try {
        const gameId = Number(b.dataset.gameJoin);
        const fresh = await api(`/games/${gameId}`);
        if (fresh.status !== 'upcoming' || Number(fresh.spots_left) <= 0) {
          const unavailable = new Error(
            fresh.status !== 'upcoming'
              ? 'This game is no longer open to join.'
              : 'That spot was just taken. Open the game to see the latest roster or waitlist.',
          );
          unavailable.code = fresh.status !== 'upcoming' ? 'game_not_open' : 'game_full';
          throw unavailable;
        }
        const joined = await api(`/games/${gameId}/join`, { method: 'POST' });
        state.playGamesCache = null;
        const template = document.createElement('template');
        template.innerHTML = gameCardHtml(joined);
        const updatedCard = template.content.firstElementChild;
        card.replaceWith(updatedCard);
        bindGameButtons(updatedCard, refresh);
        updatedCard.querySelector('[data-open-game]')?.focus({ preventScroll: true });
        showJoinedToast(Number(b.dataset.gameJoin), `Joined ${playNoun}`, {
          onUndone: refresh,
          recurring: joined.recurrence === 'weekly',
        });
        refreshMe();
      } catch (err) {
        b.disabled = false;
        b.removeAttribute('aria-busy');
        b.textContent = original;
        state.playGamesCache = null;
        showInlineActionError(card, err.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-waitlist]').forEach((b) => b.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (b.disabled) return;
      if (b.dataset.undoWaitlist === 'true') {
        clearTimeout(b._confirmationTimer);
        b.disabled = true;
        b.textContent = 'Leaving…';
        try {
          await api(`/games/${b.dataset.gameWaitlist}/waitlist/leave`, { method: 'POST' });
          b.innerHTML = `${uiIcon('check')} Left waitlist`;
          toast('Left the waitlist');
          setTimeout(refresh, 450);
        } catch (err) {
          b.disabled = false;
          b.textContent = b.dataset.confirmationLabel || 'Waitlisted · Leave';
          toast(err.message);
        }
        return;
      }
      const original = b.textContent;
      b.disabled = true;
      b.setAttribute('aria-busy', 'true');
      b.textContent = 'Joining waitlist…';
      try {
        const updated = await api(`/games/${b.dataset.gameWaitlist}/waitlist`, { method: 'POST' });
        b.removeAttribute('aria-busy');
        const position = Number(updated.waitlist_position) || null;
        b.dataset.undoWaitlist = 'true';
        b.dataset.confirmationLabel = position ? `Waitlisted #${position} · Leave` : 'Waitlisted · Leave';
        b.disabled = false;
        b.textContent = b.dataset.confirmationLabel;
        b.setAttribute('aria-label', `${b.dataset.confirmationLabel}. Leave the waitlist`);
        toast("Waitlisted — we'll let you know if a spot opens", { tone: 'success', icon: 'clock' });
        maybeOfferPhoneNotifications('Get a ping if a spot opens?');
        b._confirmationTimer = setTimeout(refresh, 4000);
      } catch (err) {
        b.disabled = false;
        b.removeAttribute('aria-busy');
        b.textContent = original;
        toast(err.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-waitlist-manage]').forEach((b) => b.addEventListener('click', (e) => {
      e.stopPropagation();
      openDrillInFrom(rootEl, () => openGameScreen(Number(b.dataset.gameWaitlistManage)));
    }));
    rootEl.querySelectorAll('[data-game-quick-share]').forEach((button) => button.addEventListener('click', async (event) => {
      event.stopPropagation();
      const card = button.closest('.game-card, article');
      clearInlineActionError(card);
      const resetAction = beginButtonAction(button, 'Opening…');
      if (!resetAction) return;
      try {
        const game = await api(`/games/${button.dataset.gameQuickShare}`);
        resetAction();
        await shareGame(game);
      } catch (error) {
        resetAction();
        showInlineActionError(card, error.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-quick-calendar]').forEach((button) => button.addEventListener('click', async (event) => {
      event.stopPropagation();
      const card = button.closest('.game-card, article');
      clearInlineActionError(card);
      const resetAction = beginButtonAction(button, 'Opening…');
      if (!resetAction) return;
      try {
        const game = await api(`/games/${button.dataset.gameQuickCalendar}`);
        resetAction();
        openGameCalendarMenu(game);
      } catch (error) {
        resetAction();
        showInlineActionError(card, error.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-confirm]').forEach((b) => b.addEventListener('click', async (e) => {
      e.stopPropagation();
      const actionRoot = b.closest('.game-card') || rootEl;
      const resetAction = beginButtonAction(
        b,
        'Confirming…',
        [...actionRoot.querySelectorAll('[data-game-confirm], [data-game-dispute]')],
      );
      if (!resetAction) return;
      const modalLoad = beginRoutedOverlayLoad(null);
      try {
        const game = await api(`/games/${b.dataset.gameConfirm}/confirm`, { method: 'POST', body: JSON.stringify({ expected_score_version: Number(b.dataset.scoreVersion || 0) }) });
        if (routedOverlayLoadIsCurrent(modalLoad)) showCelebration(game);
        refreshMe();
        refresh();
      } catch (err) {
        resetAction();
        if (routedOverlayLoadIsCurrent(modalLoad)) toast(err.message);
      }
    }));
    rootEl.querySelectorAll('[data-game-dismiss]').forEach((b) => b.addEventListener('click', (e) => {
      e.stopPropagation();
      openGameCancellationConfirmation({
        game: gameCancellationFromDataset(b),
        gameId: Number(b.dataset.gameDismiss),
        variant: 'stale',
        trigger: b,
        onCancelled: () => {
          refreshMe();
          refresh();
        },
      });
    }));
    rootEl.querySelectorAll('[data-game-dispute]').forEach((b) => b.addEventListener('click', async (e) => {
      e.stopPropagation();
      const disputeReason = await requestScoreDisputeReason({ trigger: b });
      if (!disputeReason) return;
      const actionRoot = b.closest('.game-card') || rootEl;
      const resetAction = beginButtonAction(
        b,
        'Opening score…',
        [...actionRoot.querySelectorAll('[data-game-confirm], [data-game-dispute]')],
      );
      if (!resetAction) return;
      try {
        const updated = await api(`/games/${b.dataset.gameDispute}/dispute`, {
          method: 'POST', body: JSON.stringify({ details: disputeReason, expected_score_version: Number(b.dataset.scoreVersion || 0) }),
        });
        state.playGamesCache = null;
        if (updated.score_dispute_outcome === 'unresolved') {
          toast('Score disputed — review the correction options');
          openGameScreen(Number(b.dataset.gameDispute));
        } else {
          openScoreModal(updated, () => {
            refreshMe();
            refresh();
          }, { mode: 'counter', prefill: updated.score_correction_prefill });
        }
        refreshMe();
        refresh();
      } catch (err) {
        resetAction();
        toast(err.message);
      }
    }));
  }

  // Share text that fits the game's state: brag about results, invite to
  // upcoming games.
  function gameShareText(game) {
    const courtName = game.court ? game.court.name : '';
    if (game.status === 'completed' && game.completion_kind === 'session') {
      return `Wrapped up a ${game.players.length}-player pickleball session${courtName ? ` at ${courtName}` : ''} on Third Shot 🏓`;
    }
    if (game.status === 'completed' && game.score_team1 != null) {
      const score = gameScoreText(game, { includeGames: true });
      if (game.you_won === true) return `Just won ${score}${courtName ? ` at ${courtName}` : ''} 🏆 Come play on Third Shot!`;
      if (game.you_won === false) return `Battled to ${score}${courtName ? ` at ${courtName}` : ''} — rematch soon 🏓`;
      return `Final: ${score}${courtName ? ` at ${courtName}` : ''} on Third Shot 🏓`;
    }
    if (instantRallyScorePending(game)) {
      return `We played a pickup game${courtName ? ` at ${courtName}` : ''} — score coming soon on Third Shot`;
    }
    if (instantRallyClosed(game)) {
      return `That pickup game${courtName ? ` at ${courtName}` : ''} has ended — start a new one on Third Shot`;
    }
    if (game.is_instant) {
      return `Join our pickup game${courtName ? ` at ${courtName}` : ''} — we're finding players now`;
    }
    return `Join my pickleball game${courtName ? ` at ${courtName}` : ''} — ${gameWhenText(game)}`;
  }

  function canManageGameInviteLink(game) {
    return !!(game?.is_creator && game.visibility === 'private'
      && game.status === 'upcoming' && !game.is_instant
      && !game.crew_id && !game.club_id && !game.is_direct_challenge);
  }

  function gameInvitationPreviewHtml(plan) {
    const count = Math.max(0, Number(plan.joined_count) || 0);
    const places = Math.max(0, Number(plan.spots_left) || 0);
    const cost = plan.cost_cents == null ? 'Cost not listed'
      : Number(plan.cost_cents) === 0 ? 'Free' : `$${(Number(plan.cost_cents) / 100).toFixed(2)} per player`;
    const format = plan.game_type === 'ranked'
      ? `Ranked ${Number(plan.max_players) === 2 ? 'singles' : 'doubles'}` : 'Casual session';
    return `<div class="game-invitation-preview">
      <span class="auth-preview-kicker">Private invitation · ${esc(format)}</span>
      <h3>${esc(plan.title || gameActivityLabel(plan))}</h3>
      <p class="game-invitation-host">Hosted by ${esc(plan.host_name || 'the session host')}</p>
      <dl class="auth-preview-facts">
        <div><dt>When</dt><dd>${esc(fmtDateTime(plan.scheduled_at))}<small>Your local time${plan.duration_minutes ? ` · ${Number(plan.duration_minutes)} minutes` : ''}</small></dd></div>
        <div><dt>Where</dt><dd>${esc(plan.court?.name || 'Court not listed')}<small>${esc([plan.court?.address, plan.court?.city].filter(Boolean).join(', '))}</small></dd></div>
        <div><dt>Cost</dt><dd>${esc(cost)}</dd></div>
        <div><dt>Court access</dt><dd>${esc(sessionCourtAccessLabel(plan))}${plan.court_number ? `<small>${esc(plan.court_number)}</small>` : ''}</dd></div>
        ${sessionPlayStyleLabel(plan) ? `<div><dt>Play style</dt><dd>${esc(sessionPlayStyleLabel(plan))}</dd></div>` : ''}
      </dl>
      <p class="game-invitation-places">${count} going · ${places ? `${places} ${places === 1 ? 'place' : 'places'} available` : 'Full · ask to join the waitlist'}</p>
    </div>`;
  }

  function invitationErrorMessage(error) {
    return [404, 410].includes(Number(error?.status))
      ? 'This invitation is no longer available. Ask the host for a current link.'
      : error?.message || 'The invitation could not load. Check your connection and try again.';
  }

  async function renderSignedOutGameInvitation(container, route, stillCurrent) {
    container.classList.add('is-public-detail');
    container.innerHTML = '<p role="status">Opening your private invitation…</p>';
    container.setAttribute('aria-busy', 'true');
    try {
      const plan = await api(`/games/${route.id}/invite-link/preview`, {
        method: 'POST', body: JSON.stringify({ token: route.inviteToken }),
      });
      if (!stillCurrent() || !container.isConnected) return;
      container.innerHTML = `${gameInvitationPreviewHtml(plan)}
        <button type="button" class="btn btn-primary btn-block" data-invitation-signin>Continue to invitation</button>
        <p class="auth-preview-footnote">Log in or create an account to see the players. Joining is your choice.</p>`;
      container.querySelector('[data-invitation-signin]').addEventListener('click', showAuthEntryForm);
    } catch (error) {
      if (!stillCurrent() || !container.isConnected) return;
      container.innerHTML = `<p class="form-error" role="alert">${esc(invitationErrorMessage(error))}</p>
        <button type="button" class="btn btn-secondary btn-block" data-invitation-retry>Try again</button>`;
      container.querySelector('[data-invitation-retry]').addEventListener('click', () => {
        if (stillCurrent()) renderSignedOutGameInvitation(container, route, stillCurrent);
      });
    } finally {
      if (stillCurrent()) container.removeAttribute('aria-busy');
    }
  }

  async function openGameInvitation(route) {
    const owner = captureAuthenticatedSessionOwner();
    const shell = openDetailLoadShell({ route, title: 'Private invitation',
      copy: 'Loading the session…', label: 'Private invitation' });
    if (!shell) return;
    const { modal, box, load } = shell;
    const isCurrent = () => modal.isConnected && authenticatedSessionOwnerIsCurrent(owner)
      && routedOverlayLoadIsCurrent(load);
    try {
      const plan = await api(`/games/${route.id}/invite-link/preview`, {
        method: 'POST', body: JSON.stringify({ token: route.inviteToken }),
      });
      if (!isCurrent()) return;
      box.removeAttribute('aria-busy');
      box.innerHTML = `${modalHead('Private invitation')}${gameInvitationPreviewHtml(plan)}
        <button type="button" class="btn btn-primary btn-block" data-invitation-open>Open invitation</button>
        <p class="game-invitation-note">See the players, then choose Join on the session to confirm your place.</p>
        <p role="alert" class="form-error" data-invitation-error></p>`;
      setDialogLabel(box, 'Private invitation');
      const button = modal.querySelector('[data-invitation-open]');
      button.addEventListener('click', async () => {
        const finish = beginButtonAction(button, 'Opening…');
        if (!finish) return;
        try {
          await api(`/games/${route.id}/invite-link/redeem`, {
            method: 'POST', body: JSON.stringify({ token: route.inviteToken }),
          });
          if (!isCurrent()) return;
          transitionModal(modal, () => openGameScreen(route.id));
        } catch (error) {
          if (isCurrent()) modal.querySelector('[data-invitation-error]').textContent = invitationErrorMessage(error);
        } finally { if (modal.isConnected) finish(); }
      });
    } catch (error) {
      if (!isCurrent()) return;
      renderDetailLoadError(shell, invitationErrorMessage(error),
        () => retryDetailLoad(shell, () => openGameInvitation(route)), 'Invitation unavailable');
    }
    return modal;
  }

  function openGameInviteLinkSheet(game) {
    const owner = captureAuthenticatedSessionOwner();
    const sheet = openModal(`${modalHead('Private invite link')}
      <p class="game-invitation-note">Anyone with this link can open this private session after signing in. Joining is a separate choice.</p>
      <div data-invite-link-content aria-busy="true"><p role="status">Loading invitation…</p></div>
      <p class="game-invitation-note">Existing invitations and RSVPs stay when you replace or disable the link.</p>
      <p class="game-invitation-status" role="status" aria-live="polite" data-invite-link-status></p>`,
    { label: 'Private invite link' });
    let link = null;
    let busy = false;
    let request = 0;
    const isCurrent = () => sheet.isConnected && authenticatedSessionOwnerIsCurrent(owner);
    const content = sheet.querySelector('[data-invite-link-content]');
    const status = sheet.querySelector('[data-invite-link-status]');
    const render = () => {
      if (!isCurrent()) return;
      content.removeAttribute('aria-busy');
      content.innerHTML = !link ? '<button type="button" class="btn btn-secondary btn-block" data-invite-link-retry>Try again</button>'
        : link.enabled ? `<div class="form-field"><label for="private-invite-url">${esc(game.title || 'Session')} invitation</label>
            <input id="private-invite-url" type="url" readonly value="${esc(link.url)}" /></div>
          <p class="game-invitation-note">Expires ${esc(fmtDateTime(link.expires_at))}. This link is for this date.</p>
          <div class="game-invitation-actions"><button type="button" class="btn btn-primary" data-invite-link-copy>Copy link</button><button type="button" class="btn btn-secondary" data-invite-link-share>Share</button></div>
          <div class="game-invitation-actions is-secondary"><button type="button" class="btn-link" data-invite-link-replace>Replace link</button><button type="button" class="btn-link" data-invite-link-disable>Disable link</button></div>`
        : '<p>Link sharing is off.</p><button type="button" class="btn btn-primary btn-block" data-invite-link-create>Create invite link</button>';
      content.querySelector('[data-invite-link-retry]')?.addEventListener('click', () => load());
      content.querySelector('[data-invite-link-create]')?.addEventListener('click', () => change('POST'));
      for (const [action, method] of [['replace', 'POST'], ['disable', 'DELETE']]) {
        content.querySelector(`[data-invite-link-${action}]`)?.addEventListener('click', async (event) => {
          if (busy) return;
          const version = link.version;
          const confirmed = await openActionConfirmation({
            title: action === 'replace' ? 'Replace this invitation link?' : 'Disable this invitation link?',
            message: 'The old link will stop working. Existing invitations and RSVPs stay.',
            confirmLabel: action === 'replace' ? 'Replace link' : 'Disable link',
            cancelLabel: 'Keep link', trigger: event.currentTarget,
          });
          if (confirmed && isCurrent()) change(method, version);
        });
      }
      const copy = async () => {
        if (busy || !link?.enabled) return;
        try {
          await navigator.clipboard.writeText(link.url);
          if (isCurrent()) status.textContent = 'Invitation link copied.';
        } catch {
          if (!isCurrent()) return;
          const input = content.querySelector('#private-invite-url');
          input?.focus(); input?.select();
          status.textContent = 'Select and copy the link above.';
        }
      };
      content.querySelector('[data-invite-link-copy]')?.addEventListener('click', copy);
      content.querySelector('[data-invite-link-share]')?.addEventListener('click', async () => {
        if (busy || !link?.enabled) return;
        if (!navigator.share) { await copy(); return; }
        try {
          await navigator.share({ title: game.title || 'Private pickleball session',
            text: `Join me ${game.time_vote ? '' : `${fmtDateTime(game.scheduled_at)} `}at ${game.court?.name || 'the court'}.`, url: link.url });
          if (isCurrent()) status.textContent = 'Invitation shared.';
        } catch (error) {
          if (isCurrent() && error?.name !== 'AbortError') status.textContent = 'Sharing did not open. You can copy the link instead.';
        }
      });
    };
    const load = async (message = '') => {
      const seq = ++request;
      busy = true;
      content.setAttribute('aria-busy', 'true');
      content.querySelectorAll('button').forEach((button) => { button.disabled = true; });
      try {
        const fresh = await api(`/games/${game.id}/invite-link`);
        if (!isCurrent() || seq !== request) return;
        link = fresh;
        status.textContent = message;
      } catch (error) {
        if (!isCurrent() || seq !== request) return;
        link = null;
        status.textContent = invitationErrorMessage(error);
      } finally {
        if (isCurrent() && seq === request) { busy = false; render(); }
      }
    };
    const change = async (method, version = link?.version) => {
      if (busy || !isCurrent()) return;
      busy = true;
      content.querySelectorAll('button').forEach((button) => { button.disabled = true; });
      try {
        const fresh = await api(`/games/${game.id}/invite-link`, {
          method, body: JSON.stringify({ expected_version: version }),
        });
        if (!isCurrent()) return;
        link = fresh;
        status.textContent = method === 'DELETE' ? 'Link disabled. Existing RSVPs stay.' : 'Your new invitation link is ready.';
      } catch (error) {
        if (!isCurrent()) return;
        await load(error.code === 'invite_link_changed'
          ? 'This link changed on another device. The current version is shown.'
          : error.message || 'The link could not be changed. Review its current status before trying again.');
        return;
      } finally {
        if (isCurrent()) { busy = false; render(); }
      }
    };
    load();
    return sheet;
  }

  async function shareGame(game, { notify = true } = {}) {
    if (canManageGameInviteLink(game)) {
      openGameInviteLinkSheet(game);
      return 'managed';
    }
    const url = `${location.origin}/g/${game.id}`; // short link → OG preview in chat apps
    const text = gameShareText(game);
    try {
      if (navigator.share) {
        await navigator.share({ title: 'Third Shot', text, url });
        return 'shared';
      }
      await navigator.clipboard.writeText(`${text} ${url}`);
      if (notify) toast('Copied to share', { tone: 'success', icon: 'copy' });
      return 'copied';
    } catch (error) {
      if (error && error.name === 'AbortError') return 'cancelled';
      if (notify) toast('Couldn’t open sharing — try again');
      return 'failed';
    }
  }

  function rosterBoostSummaryHtml(game) {
    const players = Array.isArray(game.players) ? game.players : [];
    const spotsLeft = Math.max(0, Number(game.spots_left) || 0);
    const full = spotsLeft === 0;
    const roster = players.slice(0, 6).map((player) => `
      <span class="roster-boost-person" title="${esc(player.display_name)}">
        ${avatarHtml(player, 'sm')}<span>${esc((player.display_name || 'Player').split(' ')[0])}</span>
      </span>`).join('');
    return `
      <div class="roster-boost-summary${full ? ' is-full' : ''}">
        <div class="roster-boost-count"><b>${full ? 'Roster full' : spotsLeft === 1
          ? '1 spot left. The first person to join gets it.'
          : `${spotsLeft} spots left. The next ${spotsLeft} players to join get them.`}</b>
          <span>${players.length}/${game.max_players} players · ${esc(gameWhenText(game))}</span>
        </div>
        <div class="roster-boost-people">${roster}</div>
      </div>`;
  }

  function gameOpenCallCanBeCreated(game) {
    if (!game || !game.is_creator || game.status !== 'upcoming'
        || game.visibility !== 'open' || game.is_instant
        || game.recurrence !== 'none' || !game.court
        || Number(game.spots_left) <= 0) return false;
    const startsAt = new Date(game.scheduled_at).getTime();
    return Number.isFinite(startsAt) && startsAt >= Date.now() - 15 * 60 * 1000;
  }

  function rosterBoostLauncherHtml(game, { primary = false } = {}) {
    const spotsLeft = Math.max(0, Number(game?.spots_left) || 0);
    const maybe = Math.max(0, Number(game?.rsvp_counts?.maybe) || 0);
    return `<section class="roster-boost-launch${primary ? ' is-primary' : ''}" id="gs-fill-roster" aria-labelledby="gs-invite-title">
      <div class="roster-boost-launch-copy">
        <b id="gs-invite-title">Invite</b>
        <span>${maybe ? `${maybe} maybe · ` : ''}${spotsLeft} open spot${spotsLeft === 1 ? '' : 's'}${maybe ? '' : ' · choose how to reach players'}</span>
      </div>
      <div class="roster-boost-launch-actions" role="group" aria-label="Invite players">
        <button type="button" data-roster-boost-channel="friends"><span aria-hidden="true">${uiIcon('users')}</span><b>Friends</b></button>
        ${game.visibility === 'open' ? `<button type="button" data-roster-boost-channel="court"><span aria-hidden="true">${uiIcon('message')}</span><b>Court chat</b></button>` : ''}
        <button type="button" data-roster-boost-channel="share"><span aria-hidden="true">${uiIcon('send')}</span><b>Share link</b></button>
      </div>
    </section>`;
  }

  function openRosterBoostSheet(initialGame, { onGameUpdated, initialChannel = 'friends' } = {}) {
    if (initialChannel === 'share' && canManageGameInviteLink(initialGame)) {
      return openGameInviteLinkSheet(initialGame);
    }
    const accountId = Number(state.me && state.me.id);
    let game = initialGame;
    const playNoun = game.game_type === 'ranked' ? 'match' : 'play session';
    let openCall = game.open_call || null;
    let friends = [];
    let friendsReady = false;
    let friendsError = false;
    let busy = false;
    let activeChannel = ['friends', 'court', 'share'].includes(initialChannel)
      && (initialChannel !== 'court' || game.visibility === 'open') ? initialChannel : 'friends';
    const selected = new Set();
    const sentInviteIds = new Set();

    const sheet = openModal(`
      ${modalHead('Invite')}
      <div class="roster-boost">
        <div id="rb-summary"></div>
        ${game.is_instant ? `<p class="arrival-retry-note">${esc(rallyCountsText(rallySummaryFromValue(game)))}. “On my way” shares an ETA but does not reserve an opening.</p>` : ''}
        <p class="roster-boost-trust">Choose one way to reach players. Each action reports its result below.</p>
        <div class="roster-boost-tabs" role="tablist" aria-label="Invite options">
          <button type="button" role="tab" id="rb-tab-friends" aria-controls="rb-friends-channel" data-rb-channel="friends">${uiIcon('users')}<span>Friends</span></button>
          ${game.visibility === 'open' ? `<button type="button" role="tab" id="rb-tab-court" aria-controls="rb-court-channel" data-rb-channel="court">${uiIcon('message')}<span>Court chat</span></button>` : ''}
          <button type="button" role="tab" id="rb-tab-share" aria-controls="rb-share-channel" data-rb-channel="share">${uiIcon('send')}<span>Share link</span></button>
        </div>
        <section class="roster-boost-channel" id="rb-friends-channel" role="tabpanel" aria-labelledby="rb-tab-friends">
          <div class="roster-boost-channel-head">
            <span class="roster-boost-channel-icon" aria-hidden="true">${uiIcon('users')}</span>
            <div><b id="rb-friends-title">Invite friends</b><span>Pick several and send once.</span></div>
          </div>
          <div class="invite-chips" id="rb-friends" aria-live="polite"></div>
          <button type="button" class="btn btn-primary btn-block" id="rb-invite-send" disabled>Loading friends…</button>
        </section>
        <section class="roster-boost-channel" id="rb-court-channel" role="tabpanel" aria-labelledby="rb-tab-court">
          <div class="roster-boost-channel-head">
            <span class="roster-boost-channel-icon" aria-hidden="true">${uiIcon('message')}</span>
            <div><b>Post in ${esc(game.court?.name || 'Court')} chat</b><span>Share one live opening with players following this court.</span></div>
          </div>
          <button type="button" class="btn btn-secondary btn-block" id="rb-post-court">Post an opening in Court chat</button>
          <button type="button" class="roster-boost-withdraw hidden" id="rb-withdraw-court">Remove from Court chat</button>
          <p class="roster-boost-channel-note" id="rb-court-note"></p>
        </section>
        <section class="roster-boost-channel" id="rb-share-channel" role="tabpanel" aria-labelledby="rb-tab-share">
          <div class="roster-boost-channel-head">
            <span class="roster-boost-channel-icon" aria-hidden="true">${uiIcon('send')}</span>
            <div><b>Share link</b><span>Text the ${playNoun} link to any group.</span></div>
          </div>
          <div class="form-field"><label for="rb-share-url">Session invitation link</label><input id="rb-share-url" type="url" readonly value="${esc(`${location.origin}/g/${game.id}`)}" /></div>
          <button type="button" class="btn btn-primary btn-block" id="rb-copy-link">Copy link</button>
          <button type="button" class="btn btn-secondary btn-block" id="rb-share">Share ${playNoun} link</button>
          <p class="roster-boost-channel-note" id="rb-share-note"></p>
        </section>
        <div class="roster-boost-status" id="rb-status" role="status" aria-live="polite" aria-atomic="true"></div>
      </div>
    `, { label: CTA_LABELS.invitePlayers });

    const summaryEl = sheet.querySelector('#rb-summary');
    const friendsSection = sheet.querySelector('#rb-friends-channel');
    const friendsEl = sheet.querySelector('#rb-friends');
    const sendButton = sheet.querySelector('#rb-invite-send');
    const courtSection = sheet.querySelector('#rb-court-channel');
    const postButton = sheet.querySelector('#rb-post-court');
    const withdrawButton = sheet.querySelector('#rb-withdraw-court');
    const shareButton = sheet.querySelector('#rb-share');
    const copyLinkButton = sheet.querySelector('#rb-copy-link');
    const linkInput = sheet.querySelector('#rb-share-url');
    const shareSection = sheet.querySelector('#rb-share-channel');
    const shareNote = sheet.querySelector('#rb-share-note');
    const courtNote = sheet.querySelector('#rb-court-note');
    const statusEl = sheet.querySelector('#rb-status');
    const channelButtons = [...sheet.querySelectorAll('[data-rb-channel]')];
    const channelPanels = {
      friends: friendsSection, court: courtSection, share: shareSection,
    };

    const selectChannel = (channel, { focus = false } = {}) => {
      if (!channelPanels[channel]) return;
      if (channel === 'share' && canManageGameInviteLink(game)) {
        openChildModal(sheet, () => openGameInviteLinkSheet(game));
        return;
      }
      activeChannel = channel;
      channelButtons.forEach((button) => {
        const selected = button.dataset.rbChannel === channel;
        button.setAttribute('aria-selected', String(selected));
        button.tabIndex = selected ? 0 : -1;
      });
      Object.entries(channelPanels).forEach(([name, panel]) => {
        panel.classList.toggle('hidden', name !== channel);
      });
      if (focus) channelButtons.find((button) => button.dataset.rbChannel === channel)?.focus();
    };

    const announce = (message, tone = '') => {
      statusEl.textContent = message || '';
      statusEl.className = `roster-boost-status${tone ? ` is-${tone}` : ''}`;
    };
    copyLinkButton.addEventListener('click', async () => {
      const reset = beginButtonAction(copyLinkButton, 'Copying…');
      if (!reset) return;
      try {
        await navigator.clipboard.writeText(linkInput.value);
        announce('Session link copied.', 'success');
      } catch {
        linkInput.focus();
        linkInput.select();
        announce('Select and copy the session link above.');
      } finally { reset(); }
    });
    const currentPlayerIds = () => new Set(
      (game.players || []).map((player) => Number(player.user_id)),
    );
    const invitableFriends = () => {
      const inGame = currentPlayerIds();
      return friends.filter((friend) => !inGame.has(Number(friend.id)));
    };
    const syncSendButton = () => {
      const full = Number(game.spots_left) <= 0 || game.status !== 'upcoming';
      sendButton.disabled = busy || full || selected.size === 0;
      if (busy) return;
      if (full) sendButton.textContent = 'Roster is full';
      else if (selected.size) sendButton.textContent = `Send ${selected.size} invite${selected.size === 1 ? '' : 's'}`;
      else sendButton.textContent = 'Select players to invite';
    };
    const renderFriends = () => {
      if (!friendsReady) {
        friendsEl.innerHTML = friendsError
          ? '<button type="button" class="btn btn-secondary btn-block" id="rb-friends-retry">Retry loading friends</button>'
          : '<div class="roster-boost-loading">Loading friends…</div>';
        sendButton.textContent = friendsError ? 'Friends unavailable' : 'Loading friends…';
        sendButton.disabled = true;
        return;
      }
      const candidates = invitableFriends();
      const candidateIds = new Set(candidates.map((friend) => Number(friend.id)));
      [...selected].forEach((userId) => { if (!candidateIds.has(userId)) selected.delete(userId); });
      friendsEl.innerHTML = candidates.length ? candidates.map((friend) => {
        const userId = Number(friend.id);
        const active = selected.has(userId);
        const sent = sentInviteIds.has(userId);
        return `<button type="button" class="invite-chip${active ? ' active' : ''}${sent ? ' is-sent' : ''}"
          data-rb-friend="${userId}" aria-pressed="${active}" ${sent ? 'disabled' : ''}>
          ${avatarHtml(friend, 'sm')} ${esc((friend.display_name || 'Player').split(' ')[0])}${sent ? ` ${uiIcon('check-circle')}` : ''}
        </button>`;
      }).join('') : `<p class="roster-boost-empty">${friendsError ? 'Friends are unavailable right now.' : 'No friends are available to invite.'}</p>`;
      syncSendButton();
    };
    const renderCourtAction = () => {
      const relevant = !!(game && game.is_creator && game.visibility === 'open'
        && !game.is_instant && game.recurrence === 'none' && game.court);
      courtNote.textContent = relevant ? '' : game.visibility !== 'open'
        ? 'Court chat openings are available for public games.'
        : game.is_instant ? 'Live pickup games already appear at the court.'
          : game.recurrence !== 'none' ? 'Recurring series use their direct invite link.'
            : 'Court chat is unavailable for this game.';
      if (!relevant) {
        postButton.disabled = true;
        postButton.textContent = 'Court chat unavailable';
        withdrawButton.classList.add('hidden');
        return;
      }
      const stateName = String(openCall && openCall.state || '');
      const liveCall = ['open', 'full'].includes(stateName);
      withdrawButton.classList.toggle('hidden', !liveCall || !openCall.can_withdraw);
      if (liveCall) {
        postButton.disabled = true;
        postButton.innerHTML = `${uiIcon('check-circle')}<span>${stateName === 'full'
          ? 'Opening posted in Court chat · roster full'
          : 'Opening posted in Court chat'}</span>`;
      } else if (openCall && ['closed', 'withdrawn'].includes(stateName)) {
        postButton.disabled = true;
        postButton.textContent = stateName === 'withdrawn' ? 'Removed from Court chat' : 'Opening closed';
      } else if (Number(game.spots_left) <= 0) {
        postButton.disabled = true;
        postButton.textContent = 'Roster is full';
      } else {
        postButton.disabled = busy || !gameOpenCallCanBeCreated(game);
        postButton.textContent = gameOpenCallCanBeCreated(game)
          ? `Share ${game.spots_left} open spot${game.spots_left === 1 ? '' : 's'} in Court chat`
          : 'This opening can no longer be shared';
      }
    };
    const renderAll = () => {
      summaryEl.innerHTML = rosterBoostSummaryHtml(game);
      renderFriends();
      renderCourtAction();
      const full = Number(game.spots_left) <= 0 || game.status !== 'upcoming';
      shareButton.classList.remove('btn-primary');
      shareButton.classList.add('btn-secondary');
      shareButton.disabled = busy || full;
      shareNote.textContent = full ? 'The roster is full, so recruiting links are paused.' : '';
      selectChannel(activeChannel);
      if (full && !statusEl.textContent) {
        announce('Roster full — game on!', 'success');
      }
    };
    const acceptFreshGame = (fresh, nextOpenCall = undefined) => {
      if (!fresh || Number(fresh.id) !== Number(game.id)) return false;
      const changed = gameFingerprint(fresh) !== gameFingerprint(game);
      game = fresh;
      if (nextOpenCall !== undefined) openCall = nextOpenCall;
      else if (fresh.open_call) openCall = fresh.open_call;
      else if (openCall && ['open', 'full'].includes(openCall.state)) {
        openCall = { ...openCall, state: 'closed', active: false, can_withdraw: false };
      }
      if (changed && typeof onGameUpdated === 'function') onGameUpdated(fresh);
      renderAll();
      return changed;
    };
    const loadFriends = async () => {
      friendsReady = false;
      friendsError = false;
      renderAll();
      try {
        const response = await api('/friends');
        if (!document.body.contains(sheet) || Number(state.me && state.me.id) !== accountId) return;
        friends = response.friends || [];
        friendsReady = true;
      } catch {
        if (!document.body.contains(sheet)) return;
        friendsError = true;
      }
      renderAll();
    };
    const refreshGame = async () => {
      const fresh = await api(`/games/${game.id}`);
      if (!document.body.contains(sheet) || Number(state.me && state.me.id) !== accountId) return false;
      return acceptFreshGame(fresh);
    };

    friendsEl.addEventListener('click', (event) => {
      const retry = event.target.closest('#rb-friends-retry');
      if (retry) { loadFriends(); return; }
      const chip = event.target.closest('[data-rb-friend]');
      if (!chip || chip.disabled || busy) return;
      const userId = Number(chip.dataset.rbFriend);
      if (selected.has(userId)) selected.delete(userId); else selected.add(userId);
      renderFriends();
    });
    sendButton.addEventListener('click', async () => {
      if (!selected.size || busy || Number(game.spots_left) <= 0) return;
      busy = true;
      syncSendButton();
      const requested = [...selected];
      announce(`Sending ${requested.length} invite${requested.length === 1 ? '' : 's'}…`);
      try {
        const response = await api(`/games/${game.id}/invite`, {
          method: 'POST', body: JSON.stringify({ user_ids: requested }),
        });
        (response.invited_user_ids || []).forEach((userId) => sentInviteIds.add(Number(userId)));
        const delivered = Number(response.invited) || 0;
        requested.forEach((userId) => selected.delete(userId));
        const inviteResult = delivered
          ? `${delivered} invite${delivered === 1 ? '' : 's'} sent`
          : 'Invites already sent';
        announce(inviteResult, 'success');
      } catch (error) {
        announce(error.message, 'error');
      } finally {
        busy = false;
        renderAll();
      }
    });
    postButton.addEventListener('click', async () => {
      if (postButton.disabled || busy) return;
      const attempt = pendingGameOpenCallAttempt(accountId, game.id);
      if (!attempt) {
        announce('Couldn’t save this yet. Free storage on your device and try again.', 'error');
        return;
      }
      busy = true;
      renderAll();
      announce('Sharing one opening in Court chat…');
      try {
        const response = await api(`/games/${game.id}/open-call`, {
          method: 'POST',
          body: JSON.stringify({ client_attempt_id: attempt.id }),
        });
        openCall = response.open_call;
        const postResult = response.open_call.state === 'withdrawn'
          ? 'Already removed from Court chat'
          : 'Opening posted in Court chat';
        if (response.game) acceptFreshGame(response.game, response.open_call);
        announce(postResult, 'success');
      } catch (error) {
        announce(error.isNetworkError
          ? 'We couldn’t confirm the opening. Tap Share again.'
          : error.message, 'error');
      } finally {
        busy = false;
        renderAll();
      }
    });
    withdrawButton.addEventListener('click', async () => {
      if (busy) return;
      busy = true;
      renderAll();
      announce('Removing the opening from Court chat…');
      try {
        const response = await api(`/games/${game.id}/open-call`, { method: 'DELETE' });
        openCall = response.open_call;
        if (response.game) acceptFreshGame(response.game, response.open_call);
        announce('Removed from Court chat', 'success');
      } catch (error) {
        announce(error.message, 'error');
      } finally {
        busy = false;
        renderAll();
      }
    });
    shareButton.addEventListener('click', async () => {
      if (busy) return;
      busy = true;
      renderAll();
      const outcome = await shareGame(game, { notify: false });
      busy = false;
      if (outcome === 'shared' || outcome === 'copied') {
        announce(outcome === 'copied' ? 'Game link copied' : 'Game link shared', 'success');
      } else if (outcome === 'failed') announce('Couldn’t open sharing — try again.', 'error');
      else announce('');
      renderAll();
    });

    channelButtons.forEach((button, index) => {
      button.addEventListener('click', () => selectChannel(button.dataset.rbChannel));
      button.addEventListener('keydown', (event) => {
        if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
        event.preventDefault();
        const offset = event.key === 'ArrowRight' ? 1 : -1;
        const next = channelButtons[(index + offset + channelButtons.length) % channelButtons.length];
        selectChannel(next.dataset.rbChannel, { focus: true });
      });
    });
    renderAll();
    loadFriends();
    refreshGame().catch(() => { /* the initial snapshot keeps every action usable */ });
    const pollTimer = setInterval(async () => {
      if (!document.body.contains(sheet)) { clearInterval(pollTimer); return; }
      if (document.hidden || state.connectionState === 'offline'
          || currentOverlayEntry()?.el !== sheet || busy) return;
      try { await refreshGame(); } catch { /* retry on the next live interval */ }
    }, LIVE_DETAIL_POLL_INTERVAL_MS);
    sheet._cleanupFns?.push(() => clearInterval(pollTimer));
    return sheet;
  }

  function crewSummaryFrom(value) {
    if (!value || typeof value !== 'object') return null;
    const candidate = value.crew && typeof value.crew === 'object' ? value.crew
      : value.saved_crew && typeof value.saved_crew === 'object' ? value.saved_crew : value;
    const id = Number(candidate.id ?? candidate.crew_id);
    if (!Number.isSafeInteger(id) || id <= 0) return null;
    const rawVersion = candidate.roster_version ?? candidate.crew_version;
    const version = rawVersion == null || rawVersion === '' ? null : Number(rawVersion);
    return {
      ...candidate,
      id,
      name: String(candidate.name || candidate.crew_name || 'Your play group').slice(0, 80),
      roster_version: Number.isSafeInteger(version) && version >= 0 ? version : null,
      member_count: Math.max(1, Number(candidate.member_count) || 1),
      pending_count: Math.max(0, Number(candidate.pending_count) || 0),
      default_court_id: Number(candidate.default_court_id) || null,
      default_court_name: String(candidate.default_court_name || '').slice(0, 120),
    };
  }

  function pendingCrewInvitationEntries(crews = null) {
    const sources = [];
    if (Array.isArray(crews?.invitations)) sources.push(...crews.invitations);
    if (Array.isArray(state.pendingCrewInvites?.items)) sources.push(...state.pendingCrewInvites.items);
    const byCrew = new Map();
    sources.forEach((invitation) => {
      const crew = crewSummaryFrom(invitation);
      if (crew && !byCrew.has(crew.id)) byCrew.set(crew.id, { invitation, crew });
    });
    return [...byCrew.values()];
  }

  function syncPendingCrewInvitesFromMine(crews) {
    if (!Array.isArray(crews?.invitations)) return;
    state.pendingCrewInvites = {
      count: crews.invitations.length,
      items: [...crews.invitations],
    };
  }

  function retirePendingCrewInvite(crewId) {
    const items = (state.pendingCrewInvites?.items || []).filter(
      (item) => Number(crewSummaryFrom(item)?.id) !== Number(crewId),
    );
    state.pendingCrewInvites = { count: items.length, items };
    renderBadges();
  }

  function completedGameCrewSummary(game, response = null) {
    return crewSummaryFrom(response)
      || crewSummaryFrom(game && game.crew)
      || crewSummaryFrom(game && game.saved_crew)
      || (game && game.crew_id ? crewSummaryFrom({
        id: game.crew_id,
        name: game.crew_name,
        roster_version: game.crew_roster_version,
      }) : null);
  }

  function completedCrewPlannerOptions(game, crew, crewContext = null) {
    const invitees = (crew || []).map(sanitizePlannerInvitee).filter(Boolean);
    const savedCrew = crewSummaryFrom(crewContext);
    const attachCrew = !!savedCrew && (!crewContext || crewContext.attachCrew !== false);
    const suggestion = window.CrewPlanner && window.CrewPlanner.bestSlot
      ? window.CrewPlanner.bestSlot([state.me, ...invitees], {
          hostId: state.me && state.me.id,
          fallbackScheduledAt: game.scheduled_at,
          minLeadMinutes: 50,
        })
      : null;
    let availabilityLabel = `${invitees.length} player${invitees.length === 1 ? '' : 's'} selected`;
    if (suggestion && window.CrewPlanner) {
      const slot = window.CrewPlanner.slotLabel(suggestion.slot);
      availabilityLabel = suggestion.usedFallback
        ? `Same rhythm: ${slot}`
        : `${slot} · ${suggestion.coverage} of ${suggestion.total} usually play then`;
    }
    const sourceLabel = savedCrew
      ? `${savedCrew.name} · ${invitees.length} player${invitees.length === 1 ? '' : 's'}`
      : `Same players · ${invitees.length} selected`;
    return {
      court: game.court ? { ...game.court } : null,
      gameType: game.game_type,
      maxPlayers: game.max_players,
      durationMinutes: game.duration_minutes ?? 0,
      courtNumber: game.court_number || '',
      preferredLevel: game.preferred_level || 'any',
      levelMin: game.level_min,
      levelMax: game.level_max,
      visibility: 'private',
      invitees,
      inviteUserIds: invitees.map((person) => person.id),
      scheduledAt: suggestion && suggestion.scheduledAt,
      sourceGameId: Number(game.id) || null,
      saveGroupName: `${game.court?.name || 'Pickleball'} play group`.slice(0, 80),
      crewId: attachCrew ? savedCrew.id : null,
      crewVersion: attachCrew ? savedCrew.roster_version : null,
      crewName: savedCrew && savedCrew.name,
      sourceLabel,
      availabilityLabel,
      requireAllInvitees: true,
    };
  }

  async function openPostGamePlanner(game, fromModal, button, crewRequest = null) {
    const resetAction = button ? beginButtonAction(button, 'Opening planner…') : () => {};
    if (!resetAction) return;
    try {
      // This read only prepares the form. No game, group, or invitation exists
      // until the player reviews the planner and taps its Schedule action.
      const response = await (crewRequest || api(`/games/${game.id}/crew`));
      const teammates = response.items || [];
      if (!teammates.length) {
        resetAction();
        toast('No eligible teammates are available from this game');
        return;
      }
      const savedGroup = completedGameCrewSummary(game, response);
      const groupReady = savedGroup
        && savedGroup.joined !== false && !savedGroup.invitation_pending;
      let plannerGroup = null;
      if (groupReady) {
        try {
          const detail = await api(`/crews/${savedGroup.id}`);
          const acceptedIds = new Set((detail.members || []).map((person) => Number(person.id)));
          if ([state.me?.id, ...teammates.map((person) => person.id)]
              .every((id) => acceptedIds.has(Number(id)))) plannerGroup = detail;
        } catch { /* The original game's eligible players can still plan independently. */ }
      }
      const options = completedCrewPlannerOptions(
        game,
        teammates,
        plannerGroup || { attachCrew: false },
      );
      // Group creation has its own player review on the completed game.
      // Scheduling another date does not also create a second invitation flow.
      options.offerSaveGroup = false;
      options.saveGroupDefault = false;
      if (!fromModal && (!button?.isConnected || state.tab !== 'play'
          || state.playLane !== 'plans' || currentOverlayEntry())) { resetAction(); return; }
      const opened = fromModal
        ? openChildModal(fromModal, () => openNewGameModal(options))
        : openNewGameModal(options);
      const planner = opened ? currentOverlayEntry()?.el : null;
      if (planner && planner !== fromModal) {
        planner._cleanupFns?.push(() => {
          if (button?.isConnected) resetAction();
        });
      } else resetAction();
    } catch (error) {
      resetAction();
      toast(error.message);
    }
  }

