    const presetTitle = String(restoredDraft?.title ?? plannerOptions.title ?? '').slice(0, 120);
    const presetDescription = String(restoredDraft?.description ?? plannerOptions.description ?? '').slice(0, 1000);
    const requestedDuration = restoredDraft
      ? restoredDraft.durationMinutes : Number(plannerOptions.durationMinutes ?? 90);
