      const summary = crewSummaryFrom(detail);
      const previouslySelected = new Set(inviteIds);
      const freshInvitees = detail.members
        .map(sanitizePlannerInvitee).filter(Boolean)
        .filter((person) => !state.me || person.id !== state.me.id);
