  function openBusinessCatalogUpload(business, connection, onComplete) {
    const approvedBase = connection?.config?.booking_base_url || business.booking_url || business.website_url || '';
    const exampleBookingUrl = approvedBase ? `${String(approvedBase).replace(/\/$/, '')}/open-play` : '';
    const example = JSON.stringify({
      schema_version: 1,
      source_version: 'schedule-2026-09-01',
      generated_at: new Date().toISOString(),
      authoritative: true,
      occurrences: [{
        external_id: 'open-play-2026-09-03', title: 'Open play', kind: 'open_play',
        event_date: '2026-09-03', start_time: '18:00', end_time: '20:00',
        timezone: 'America/Los_Angeles', capacity: 24, spots_remaining: 8,
        status: 'scheduled', booking_url: exampleBookingUrl,
      }],
      conversions: [],
    }, null, 2);
    const modal = openModal(`
      ${modalHead('Upload structured catalog')}
      <div class="business-feature-intro"><b>Third Shot JSON contract</b><p>This generic feed imports dated schedule, capacity, and approved booking links. A booking link must stay beneath the reviewed base URL on your business profile.</p></div>
      <form id="business-catalog-form" novalidate>
        <div class="form-field business-catalog-upload">
          <span class="business-file-label" id="business-catalog-file-label">Import from a file</span>
          <div class="business-file-picker" id="business-catalog-file-picker" data-state="idle" data-idle-icon="plus">
            <input class="business-file-native" type="file" id="business-catalog-file" data-no-draft accept="application/json,.json" tabindex="-1" aria-hidden="true" />
            <button type="button" class="business-file-button" id="business-catalog-file-button" data-file-button aria-labelledby="business-catalog-file-label business-catalog-file-action" aria-describedby="business-catalog-file-feedback business-catalog-file-help">
              <span class="business-file-button-icon" aria-hidden="true">${uiIcon('plus')}</span>
              <span class="business-file-button-copy"><b id="business-catalog-file-action">Choose JSON file</b><small>Browse this device</small></span>
              <span class="business-file-button-cta" aria-hidden="true">Choose</span>
            </button>
            <div class="business-file-feedback" id="business-catalog-file-feedback" data-file-feedback role="status" aria-live="polite" aria-atomic="true">
              <span class="business-file-state-icon" data-file-state-icon aria-hidden="true">${uiIcon('plus')}</span>
              <span class="business-file-feedback-copy"><b data-file-name>No file selected</b><small data-file-meta>JSON · up to 1 MB</small></span>
              <span class="business-file-state" data-file-state>Optional</span>
            </div>
          </div>
          <small class="field-help" id="business-catalog-file-help">Choose a .json file, or paste the same catalog into the editor below.</small>
        </div>
        <div class="form-field"><label for="business-catalog-json">Catalog JSON</label><textarea id="business-catalog-json" rows="13" spellcheck="false" placeholder="${esc(example)}"></textarea></div>
        <button type="submit" class="btn btn-primary btn-block" id="business-catalog-submit">Validate &amp; sync catalog</button>
        <p class="business-form-note">Do not include API keys, passwords, payment data, or player identity. Keep one external_id per occurrence.</p>
      </form>`, { label: 'Upload Third Shot structured business catalog' });
    const formUX = bindModalFormUX(modal, '#business-catalog-submit');
    const input = modal.querySelector('#business-catalog-json');
    const fileInput = modal.querySelector('#business-catalog-file');
    const fileButton = modal.querySelector('#business-catalog-file-button');
    const filePicker = modal.querySelector('#business-catalog-file-picker');
    fileButton.addEventListener('click', () => fileInput.click());
    fileInput.addEventListener('change', async (event) => {
      const file = event.target.files[0];
      if (!file) return;
      formUX.clearError();
      const meta = businessFileDescription(file, 'JSON');
      const looksLikeJson = /\.json$/i.test(file.name) || ['application/json', 'text/json'].includes(String(file.type || '').toLowerCase());
      if (!looksLikeJson) {
        setBusinessFilePickerState(filePicker, { state: 'error', name: file.name, meta, badge: 'Choose JSON' });
        formUX.showError('Choose a JSON file ending in .json.', fileButton);
        event.target.value = '';
        return;
      }
      if (!file.size) {
        setBusinessFilePickerState(filePicker, { state: 'error', name: file.name, meta, badge: 'Empty file' });
        formUX.showError('That JSON file is empty.', fileButton);
        event.target.value = '';
        return;
      }
      if (file.size > 1024 * 1024) {
        setBusinessFilePickerState(filePicker, { state: 'error', name: file.name, meta, badge: 'Too large' });
        formUX.showError('Keep the JSON file under 1 MB.', fileButton);
        event.target.value = '';
        return;
      }
      fileButton.disabled = true;
      setBusinessFilePickerState(filePicker, { state: 'loading', name: file.name, meta, badge: 'Reading…' });
      try {
        input.value = await file.text();
        input.dispatchEvent(new Event('input', { bubbles: true }));
        setBusinessFilePickerState(filePicker, { state: 'success', name: file.name, meta: `${meta} · loaded into editor`, badge: 'Ready' });
        fileButton.querySelector('#business-catalog-file-action').textContent = 'Replace JSON file';
      } catch {
        setBusinessFilePickerState(filePicker, { state: 'error', name: file.name, meta, badge: 'Couldn’t read' });
        formUX.showError('That file could not be read. Choose another JSON file.', fileButton);
        event.target.value = '';
      } finally { fileButton.disabled = false; }
    });
    let lastPayload = '';
    let idempotencyKey = '';
    modal.querySelector('#business-catalog-form').addEventListener('submit', async (event) => {
      event.preventDefault(); formUX.clearError();
      let catalog;
      try { catalog = JSON.parse(input.value); } catch { formUX.showError('Paste a valid JSON object.', input); return; }
      if (!catalog || Array.isArray(catalog) || typeof catalog !== 'object') { formUX.showError('The catalog must be one JSON object.', input); return; }
      if (catalog.schema_version !== 1) { formUX.showError('Use schema_version 1.', input); return; }
      if (!Array.isArray(catalog.occurrences)) { formUX.showError('Add an occurrences array, even when it is empty.', input); return; }
      if (catalog.conversions != null && !Array.isArray(catalog.conversions)) { formUX.showError('Conversions must be an array.', input); return; }
      const serialized = JSON.stringify(catalog);
      if (serialized !== lastPayload) { lastPayload = serialized; idempotencyKey = businessClientEventId().replace(/^web-/, '').slice(0, 64); }
      const finish = formUX.startSubmitting('Syncing catalog…'); if (!finish) return;
      try {
        const result = await api(`/businesses/${business.id}/connections/${connection.id}/catalog`, {
          method: 'PUT', headers: { 'Idempotency-Key': idempotencyKey }, body: serialized,
        });
        closeModal(modal);
        toast(result.duplicate
          ? 'That catalog was already accepted'
          : result.connection?.health_status === 'healthy'
            ? 'Catalog synced and ready'
            : 'Catalog synced — check links before it goes live');
        onComplete?.(result.connection || connection);
      } catch (error) { finish(); formUX.showError(error.message); }
    });
    return modal;
  }

  function openBusinessAddConnection(business, existing, onComplete) {
    const modal = openModal(`${modalHead('Add structured feed')}<div class="business-feature-body" aria-live="polite">${skeletonHtml(2)}</div>`, { label: 'Add a structured business feed' });
    const body = modal.querySelector('.business-feature-body');
    (async () => {
      try {
        const data = await api('/business-integrations/providers');
        const providers = (Array.isArray(data.items) ? data.items : []).filter((item) => item.availability === 'active');
        if (!providers.length) { body.innerHTML = `<div class="business-feature-state is-neutral"><span aria-hidden="true">${uiIcon('link')}</span><div><b>No executable feed adapters are available</b><p>Add normal booking links now or request integration help.</p></div></div>`; return; }
        body.innerHTML = `
          <div class="business-feature-intro"><b>Only active adapters can be connected.</b><p>Today, Third Shot supports its generic structured JSON catalog. Provider names marked unavailable elsewhere are not vendor partnerships.</p></div>
          <form id="business-add-connection-form" novalidate>
            <div class="form-field"><label for="business-provider-key">Feed contract</label><select id="business-provider-key" data-select-title="Feed contract">${providers.map((item) => `<option value="${esc(item.key)}">${esc(item.name)}</option>`).join('')}</select></div>
            <div class="card business-provider-note" data-provider-note></div>
            <div class="form-field"><label for="business-connection-name">Display name</label><input type="text" id="business-connection-name" maxlength="120" value="${esc(business.name || 'Business catalog')}" /></div>
            <div class="form-field"><label for="business-connection-label">Catalog label</label><input type="text" id="business-connection-label" maxlength="120" value="${esc(business.name || 'Business schedule')}" /></div>
            <div class="form-field"><label for="business-connection-source">Public source URL (optional)</label><input type="url" id="business-connection-source" placeholder="https://your-site.example/schedule.json" inputmode="url" /></div>
            <div class="form-field"><label for="business-connection-booking">Booking base URL (optional)</label><input type="url" id="business-connection-booking" value="${esc(business.booking_url || '')}" placeholder="https://booking.example/your-club" inputmode="url" /></div>
            <button type="submit" class="btn btn-primary btn-block" id="business-add-connection-submit">Create structured feed</button>
            <p class="business-form-note">This form never accepts credentials. A source URL is checked as a public link; paste the catalog after the connection is created.</p>
          </form>`;
        const select = body.querySelector('#business-provider-key');
        const note = body.querySelector('[data-provider-note]');
        const showNote = () => { const provider = providers.find((item) => item.key === select.value); note.innerHTML = `<b>${esc(provider?.name || 'Feed')}</b><p>${esc(provider?.note || 'Executable Third Shot adapter')}</p><small>${esc((provider?.capabilities || []).join(' · '))}</small>`; };
        select.addEventListener('change', showNote); showNote();
        const formUX = bindModalFormUX(modal, '#business-add-connection-submit');
        body.querySelector('#business-add-connection-form').addEventListener('submit', async (event) => {
          event.preventDefault(); formUX.clearError();
          const providerKey = select.value;
          if (providerKey !== 'link_catalog') { formUX.showError('This setup currently supports only Third Shot’s generic link_catalog JSON contract.', select); return; }
          if (existing.some((item) => item.provider_key === providerKey)) { formUX.showError('This feed contract already has a connection, including disconnected history.', select); return; }
          const displayName = body.querySelector('#business-connection-name');
          const label = body.querySelector('#business-connection-label');
          if (!displayName.value.trim()) { formUX.showError('Add a display name.', displayName); return; }
          if (!label.value.trim()) { formUX.showError('Add a catalog label.', label); return; }
          const sourceInput = body.querySelector('#business-connection-source');
          const bookingInput = body.querySelector('#business-connection-booking');
          const sourceUrl = sourceInput.value.trim() ? businessActionHref(sourceInput.value.trim()) : '';
          const bookingUrl = bookingInput.value.trim() ? businessActionHref(bookingInput.value.trim()) : '';
          if (sourceInput.value.trim() && !sourceUrl) { formUX.showError('Use a secure https:// source URL.', sourceInput); return; }
          if (bookingInput.value.trim() && !bookingUrl) { formUX.showError('Use a secure https:// booking URL.', bookingInput); return; }
          const approvedLinks = [business.website_url, business.booking_url, business.membership_url].map((value) => businessActionHref(value)).filter(Boolean);
          if (bookingUrl && !approvedLinks.includes(bookingUrl)) { formUX.showError('First save this exact booking base URL on the business profile so it can be reviewed.', bookingInput); return; }
          const finish = formUX.startSubmitting('Creating feed…'); if (!finish) return;
          try {
            const result = await api(`/businesses/${business.id}/connections`, { method: 'POST', body: JSON.stringify({
              provider_key: 'link_catalog', display_name: displayName.value.trim(),
              config: { label: label.value.trim(), source_url: sourceUrl, booking_base_url: bookingUrl },
            }) });
            closeModal(modal); toast('Structured feed created'); onComplete?.(result.connection);
          } catch (error) { finish(); formUX.showError(error.message); }
        });
      } catch (error) { body.innerHTML = `${businessUnavailableHtml('Integration providers', error)}<button type="button" class="btn btn-secondary btn-block" data-retry>Try again</button>`; body.querySelector('[data-retry]')?.addEventListener('click', () => { closeModal(modal); openBusinessAddConnection(business, existing, onComplete); }); }
    })();
    return modal;
  }

  function openBusinessConnections(business, onSaved) {
    const modal = openModal(`${modalHead('Booking & schedule tools')}<div class="business-feature-body" aria-live="polite">${skeletonHtml(2)}</div>`, { label: 'Business data connections' });
    const body = modal.querySelector('.business-feature-body');
    const role = String(business.manager_role || (business.is_owner ? 'owner' : '')).toLowerCase();
    const canConfigure = ['owner', 'admin'].includes(role);
    const canSync = ['owner', 'admin', 'editor'].includes(role);
    const load = async ({ fallbackConnections = null } = {}) => {
      body.innerHTML = skeletonHtml(2);
      let data;
      let usingCommittedFallback = false;
      try { data = await api(`/businesses/${business.id}/connections`); }
      catch (error) {
        if (Array.isArray(fallbackConnections)) {
          data = { items: fallbackConnections };
          usingCommittedFallback = true;
        } else {
          body.innerHTML = `${businessUnavailableHtml('Live connections', error)}<button class="btn btn-secondary btn-block" data-request>Request integration help</button>${![404, 501].includes(error.status) ? '<button class="btn btn-secondary btn-block" data-retry>Try again</button>' : ''}`;
          body.querySelector('[data-tools-booking]').addEventListener('click', () => openChildModal(modal, () => openBusinessBookingSetup(business, onSaved)));
      body.querySelector('[data-tools-schedule]')?.addEventListener('click', () => openChildModal(modal, () => openBusinessScheduleEditor(business, onSaved, {startImport:true})));
      body.querySelector('[data-request]').addEventListener('click', () => openChildModal(modal, () => openBusinessIntegrationRequest(business)));
          body.querySelector('[data-retry]')?.addEventListener('click', () => load());
          return;
        }
      }
      const connections = Array.isArray(data.items) ? data.items : [];
      body.innerHTML = `<div class="business-feature-intro"><b>How should players book and find your sessions?</b><p>Booking happens on your provider’s site. Add dates here or import them from a supported source.</p></div><div class="venue-connection-tasks"><button type="button" class="btn btn-secondary" data-tools-booking>Add booking link</button>${canSync ? '<button type="button" class="btn btn-secondary" data-tools-schedule>Import schedule spreadsheet</button>' : ''}<button type="button" class="btn btn-secondary" data-request>Get setup help</button></div>
        ${usingCommittedFallback ? '<p class="competition-sync-note" role="status">Saved. Live connection details will refresh when the connection returns.</p>' : ''}
        <div class="business-connections-list">${connections.length ? connections.map((item) => {
          const status = String(item.status || 'draft').toLowerCase();
          const health = String(item.health_status || 'unknown').toLowerCase();
          const disconnected = status === 'disconnected';
          const problem = ['error', 'degraded'].includes(status) || ['degraded', 'unreachable', 'unsafe'].includes(health);
          const connected = status === 'connected' && health === 'healthy' && item.publication_ready === true && !problem;
          const needsCheck = !disconnected && status === 'connected' && health === 'unknown';
          const held = !disconnected && status === 'connected' && health === 'healthy' && item.publication_ready === false;
          const label = disconnected ? 'Disconnected' : problem ? 'Attention' : connected ? 'Live' : needsCheck ? 'Needs link check' : held ? 'Held from public' : 'Draft';
          const statusIcon = problem ? 'alert-triangle' : connected ? 'check-circle' : disconnected ? 'x' : 'refresh';
          const lastSync = item.last_sync_succeeded_at;
          return `<article class="card business-connection-row ${problem ? 'is-error' : connected ? 'is-ready' : disconnected ? 'is-neutral' : 'is-pending'}"><div class="business-connection-head"><span aria-hidden="true">${uiIcon(statusIcon)}</span><div class="row-main"><b>${esc(item.display_name || item.provider_key || 'Data connection')}</b><small>${connected ? 'Players can see this imported schedule' : disconnected ? 'Imported sessions are hidden' : needsCheck ? 'Check the links before players can use this schedule' : held ? 'Complete venue review and publish to show these sessions' : problem ? 'Updates need attention; check the source and links' : 'Add schedule data, then check its links'}</small></div><span class="business-status ${problem ? 'is-rejected' : connected ? 'is-verified' : 'is-pending'}">${uiIcon(businessStateIconName(health))}<span>${esc(label)}</span></span></div>
            <details class="simple-disclosure"><summary>Advanced connection details</summary><p>${esc(item.provider_key)} · ${esc(health)} · ${esc((item.capabilities || []).join(' · '))}</p></details>${lastSync ? `<small>Last successful sync ${esc(fmtDateTime(lastSync))}</small>` : '<small>No successful sync yet</small>'}${needsCheck ? '<div class="business-form-note">Run Check links to validate configured destinations before imported data is public.</div>' : ''}${held ? '<div class="business-form-note">The feed is healthy, but business verification, content approval, or publication is still holding imported data from players.</div>' : ''}${item.last_error_message ? `<div class="business-connection-error" role="alert">${esc(item.last_error_message)}</div>` : ''}
            ${disconnected ? `<p class="business-form-note">Disconnected connections keep their audit history and do not publish imported data.</p>${canConfigure && item.provider_key === 'link_catalog' ? `<div class="business-connection-actions"><button type="button" class="btn btn-primary btn-sm" data-connection-reconnect="${item.id}">Reconnect schedule source</button></div>` : ''}` : `<div class="business-connection-actions">${canSync ? `<button type="button" class="btn btn-secondary btn-sm" data-connection-check="${item.id}">Check links</button>${item.provider_key === 'link_catalog' ? `<button type="button" class="btn btn-primary btn-sm" data-connection-catalog="${item.id}">Update imported schedule</button>` : ''}` : ''}${canConfigure ? `<button type="button" class="btn btn-secondary btn-sm" data-connection-disconnect="${item.id}">Disconnect</button>` : ''}</div>`}</article>`;
        }).join('') : `<div class="business-manager-empty"><span aria-hidden="true">${uiIcon('link')}</span><b>No live data connections</b><p>Secure outbound links may still work, but Third Shot is not importing schedules, capacity, bookings, or memberships.</p></div>`}</div>
        ${canConfigure ? '<button type="button" class="btn btn-primary btn-block" data-add-connection>Set up advanced schedule import</button>' : '<p class="business-form-note">Only an owner or admin can create or disconnect feeds. Editors can sync an existing catalog; viewers have read-only access.</p>'}
`;
      body.querySelector('[data-tools-booking]').addEventListener('click', () => openChildModal(modal, () => openBusinessBookingSetup(business, onSaved)));
      body.querySelector('[data-tools-schedule]')?.addEventListener('click', () => openChildModal(modal, () => openBusinessScheduleEditor(business, onSaved, {startImport:true})));
      body.querySelector('[data-request]').addEventListener('click', () => openChildModal(modal, () => openBusinessIntegrationRequest(business)));
      body.querySelector('[data-add-connection]')?.addEventListener('click', () => openChildModal(modal, () => openBusinessAddConnection(business, connections, async (connection) => {
        const nextConnections = [...connections, connection];
        await load();
        onSaved?.({ ...business, connections: nextConnections });
        openChildModal(modal, () => openBusinessCatalogUpload(business, connection, async () => { await load(); }));
      })));
      body.querySelectorAll('[data-connection-catalog]').forEach((button) => button.addEventListener('click', () => {
        const connection = connections.find((item) => Number(item.id) === Number(button.dataset.connectionCatalog));
        if (connection) openChildModal(modal, () => openBusinessCatalogUpload(business, connection, load));
      }));
      body.querySelectorAll('[data-connection-check]').forEach((button) => button.addEventListener('click', async () => {
        const row = button.closest('.business-connection-row') || body;
        clearInlineActionError(row);
        const resetAction = beginButtonAction(button, 'Checking links…', [...row.querySelectorAll('button')]);
        if (!resetAction) return;
        try {
          const result = await api(`/businesses/${business.id}/connections/${button.dataset.connectionCheck}/recheck`, { method: 'POST' });
          const updatedConnections = connections.map((item) => (
            Number(item.id) === Number(button.dataset.connectionCheck) && result.connection
              ? result.connection : item
          ));
          toast('Connection links checked');
          await load({ fallbackConnections: updatedConnections });
        } catch (error) {
          resetAction();
          showInlineActionError(row, error.message);
        }
      }));
      body.querySelectorAll('[data-connection-reconnect]').forEach((button) => button.addEventListener('click', async () => {
        const row = button.closest('.business-connection-row') || body;
        clearInlineActionError(row);
        const resetAction = beginButtonAction(button, 'Reconnecting…', [...row.querySelectorAll('button')]);
        if (!resetAction) return;
        try {
          const result = await api(`/businesses/${business.id}/connections/${button.dataset.connectionReconnect}/reconnect`, { method: 'POST', body: '{}' });
          const updatedConnections = connections.map((item) => (
            Number(item.id) === Number(button.dataset.connectionReconnect) && result.connection
              ? result.connection : item
          ));
          toast('Structured feed reconnected');
          await load({ fallbackConnections: updatedConnections });
        } catch (error) {
          resetAction();
          showInlineActionError(row, error.message);
        }
      }));
      body.querySelectorAll('[data-connection-disconnect]').forEach((button) => button.addEventListener('click', () => openBusinessConfirmAction({
        title: 'Disconnect this feed?',
        message: 'Imported data stops refreshing and queued syncs are cancelled. Normal outbound profile links are unchanged.',
        confirmLabel: 'Disconnect feed',
        onConfirm: async (sheet) => {
          const result = await api(`/businesses/${business.id}/connections/${button.dataset.connectionDisconnect}`, { method: 'DELETE' });
          const updatedConnections = connections.map((item) => (
            Number(item.id) === Number(button.dataset.connectionDisconnect) && result.connection
              ? result.connection : item
          ));
          closeModal(sheet);
          toast('Connection disconnected');
          await load({ fallbackConnections: updatedConnections });
          onSaved?.({ ...business, connections: updatedConnections });
        },
      })));
    };
    load(); return modal;
  }

