  function openBusinessRevisionHistory(business, onSaved) {
    const modal = openModal(`${modalHead('Change history')}<div class="business-feature-body" aria-live="polite">${skeletonHtml(3)}</div>`, { label: 'Business change history' });
    const body = modal.querySelector('.business-feature-body');
    const canRestore = ['owner', 'admin', 'editor'].includes(String(business.manager_role || (business.is_owner ? 'owner' : 'viewer')).toLowerCase());
    const load = async () => {
      body.innerHTML = skeletonHtml(3);
      try {
        const data = await api(`/businesses/${business.id}/revisions`); const items = Array.isArray(data.items) ? data.items : [];
        const currentId = safePositiveId(data.current_revision_id) || safePositiveId(items[0]?.id);
        body.innerHTML = `<div class="business-feature-intro"><b>Saved edits create an audit entry.</b><p>Review exactly what changed. Restoring saves a new draft and keeps history. Your approved player listing stays live while sensitive edits are reviewed.</p></div>${items.length ? `<div class="business-revision-list">${items.map((item) => {
          const current = Number(item.id) === Number(currentId);
          const review = String(item.review_status || 'approved').toLowerCase();
          return `<div class="card business-revision-row"><span aria-hidden="true">${uiIcon(current ? 'check-circle' : 'refresh')}</span><div class="row-main"><b>${esc(item.change_summary || item.summary || (item.fields || []).join(', ') || 'Business profile updated')}</b><small>${esc(item.actor_name || 'Business manager')} · ${esc(fmtDateTime(item.created_at))}</small><small>${item.sensitive ? 'Sensitive change · ' : ''}${esc(review.replace(/_/g, ' '))}</small>${item.review_note ? `<p class="business-revision-note">${esc(item.review_note)}</p>` : ''}<details><summary>View changes</summary>${businessRevisionDiffHtml(item)}</details></div>${current ? `<span class="business-status is-verified">${uiIcon('check-circle')}<span>Current</span></span>` : canRestore ? `<button type="button" class="btn btn-secondary btn-sm" data-revision-restore="${item.id}">${uiIcon('refresh')} Restore</button>` : `<span class="business-status">${uiIcon('eye')}<span>Read only</span></span>`}</div>`;
        }).join('')}</div>` : `<div class="business-manager-empty"><span aria-hidden="true">${uiIcon('clock')}</span><b>No saved revisions yet</b><p>Future profile changes will appear here when revision tracking is enabled.</p></div>`}`;
        body.querySelectorAll('[data-revision-restore]').forEach((button) => button.addEventListener('click', () => {
          const revision = items.find((item) => Number(item.id) === Number(button.dataset.revisionRestore));
          const sheet = openChildModal(modal, () => openModal(`${modalHead('Preview restored version')}<p class="business-form-note">These changes will be saved as a new draft. Your approved listing stays live while sensitive edits are reviewed.</p>${businessRevisionDiffHtml({ before_snapshot: data.current_snapshot, after_snapshot: revision?.after_snapshot || revision?.snapshot })}<button class="btn btn-primary btn-block" data-confirm-restore>Restore this draft</button>`, { label: 'Preview restored venue version' }));
          const formUX = bindModalFormUX(sheet, '[data-confirm-restore]');
          sheet.querySelector('[data-confirm-restore]').addEventListener('click', async () => {
            const finish = formUX.startSubmitting('Restoring…'); if (!finish) return;
            try {
              const result = await api(`/businesses/${business.id}/revisions/${revision.id}/restore`, { method: 'POST', headers: window.VenueWorkspace.contentHeaders(data) });
              closeModal(sheet); closeModal(modal); toast(window.VenueWorkspace.savedStatus(result.business)); onSaved?.(result.business);
            } catch (error) { finish(); formUX.showError(error.message); }
          });
        }));
      } catch (error) { body.innerHTML = `${businessUnavailableHtml('Change history', error)}${![404, 501].includes(error.status) ? '<button class="btn btn-secondary btn-block" data-retry>Try again</button>' : ''}`; body.querySelector('[data-retry]')?.addEventListener('click', load); }
    }; load(); return modal;
  }

  function openBusinessSecurity(business) {
    return openAccountSecurity({ businessContext: true });
  }

  function openAccountSecurity({ businessContext = false } = {}) {
    const title = businessContext ? 'Business security' : 'Account security';
    const modal = openModal(`${modalHead(title)}<div class="business-feature-body" aria-live="polite"></div>`, { label: title });
    const body = modal.querySelector('.business-feature-body');
    const render = () => {
      const mfa = state.me?.mfa && typeof state.me.mfa === 'object' ? state.me.mfa : {};
      const enabled = mfa.enabled === true;
      body.innerHTML = `
        <div class="business-feature-intro"><b>Security follows your Third Shot account.</b><p>${businessContext ? 'These controls protect every business location your account can manage; they do not change another teammate’s account.' : 'Use an authenticator app to add a second sign-in step.'}</p></div>
        <div class="business-trust-summary ${enabled ? 'is-ready' : 'is-pending'}"><span aria-hidden="true">${uiIcon(enabled ? 'check-circle' : 'shield')}</span><div><b>${enabled ? 'Multi-factor authentication is on' : 'Add an authenticator'}</b><p>${enabled ? `A second factor is required when you sign in.${Number(mfa.recovery_codes_remaining) >= 0 ? ` ${Number(mfa.recovery_codes_remaining)} recovery code${Number(mfa.recovery_codes_remaining) === 1 ? '' : 's'} remain.` : ''}` : 'You’ll use your password and a six-digit code. Save the recovery codes in case you lose access to your authenticator.'}</p></div></div>
        <div class="business-security-actions">${enabled ? '<button type="button" class="btn btn-secondary btn-block" data-mfa-disable>Disable MFA</button>' : '<button type="button" class="btn btn-primary btn-block" data-mfa-start>Set up MFA</button>'}</div>
        <div class="section-label">Active sessions</div>
        <div class="business-feature-state is-neutral"><span aria-hidden="true">${uiIcon('lock')}</span><div><b>Sign out other sessions</b><p>Account settings can sign out all other sessions while keeping this device signed in. Individual devices are not listed.</p><button type="button" class="btn btn-secondary btn-sm" data-open-account-security>Open account settings</button></div></div>`;
      body.querySelector('[data-mfa-start]')?.addEventListener('click', async (event) => {
        const sheet = openChildModal(modal, () => openModal(`${modalHead('Set up MFA')}<p class="row-sub business-editor-intro">Confirm your password before Third Shot creates a one-time authenticator setup key.</p><div class="form-field"><label for="business-mfa-password">Current account password</label><input type="password" id="business-mfa-password" autocomplete="current-password" /></div><button type="button" class="btn btn-primary btn-block" id="business-mfa-setup">Create setup key</button>`, { label: 'Set up account multi-factor authentication' }));
        const formUX = bindModalFormUX(sheet, '#business-mfa-setup');
        sheet.querySelector('#business-mfa-setup').addEventListener('click', async () => {
          const password = sheet.querySelector('#business-mfa-password').value;
          if (!password) { formUX.showError('Enter your current password.', sheet.querySelector('#business-mfa-password')); return; }
          const finish = formUX.startSubmitting('Creating setup key…'); if (!finish) return;
          try {
            const setup = await api('/auth/mfa/setup', { method: 'POST', body: JSON.stringify({ current_password: password }) });
            sheet.innerHTML = `${modalHead('Confirm MFA')}<p class="row-sub business-editor-intro">Add this account in your authenticator app, then enter its current six-digit code.</p><div class="business-mfa-secret"><span>Manual setup key</span><code>${esc(setup.secret || '')}</code></div>${setup.otpauth_uri ? `<div class="form-field"><label for="business-mfa-uri">Authenticator setup URI</label><input type="text" id="business-mfa-uri" readonly value="${esc(setup.otpauth_uri)}" aria-describedby="business-mfa-uri-help" /><small class="field-help" id="business-mfa-uri-help">This URI contains your private setup key. Only paste it into your authenticator app.</small></div><button type="button" class="btn btn-secondary btn-block business-private-copy" id="business-mfa-copy-uri">${uiIcon('copy')} Copy setup URI</button><p class="business-copy-status" id="business-mfa-uri-status" role="status" aria-live="polite" aria-atomic="true"></p>` : ''}<div class="form-field"><label for="business-mfa-code">Authentication code</label><input type="text" id="business-mfa-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div><button type="button" class="btn btn-primary btn-block" id="business-mfa-confirm">Turn on MFA</button><p class="business-form-note">Keep the setup key private. Third Shot will show recovery codes once after confirmation.</p>`;
            const setupUriInput = sheet.querySelector('#business-mfa-uri');
            const setupUriCopy = sheet.querySelector('#business-mfa-copy-uri');
            if (setupUriInput && setupUriCopy) {
              setupUriInput.addEventListener('focus', () => setupUriInput.select());
              setupUriInput.addEventListener('click', () => setupUriInput.select());
              setupUriCopy.addEventListener('click', async () => {
                clearInlineActionError(sheet);
                const copyFinish = beginButtonAction(setupUriCopy, 'Copying…');
                if (!copyFinish) return;
                try {
                  await navigator.clipboard.writeText(setupUriInput.value);
                  copyFinish();
                  setupUriCopy.innerHTML = `${uiIcon('check')} Copied`;
                  sheet.querySelector('#business-mfa-uri-status').textContent = 'Authenticator setup URI copied.';
                } catch (error) {
                  copyFinish();
                  setupUriInput.focus();
                  setupUriInput.select();
                  showInlineActionError(sheet, 'Copy was blocked. The setup URI is selected so you can copy it manually.');
                }
              });
            }
            const confirmUX = bindModalFormUX(sheet, '#business-mfa-confirm');
            sheet.querySelector('#business-mfa-confirm').addEventListener('click', async () => {
              const code = sheet.querySelector('#business-mfa-code').value.trim();
              if (!/^\d{6}$/.test(code)) { confirmUX.showError('Enter the current six-digit code.', sheet.querySelector('#business-mfa-code')); return; }
              const confirmFinish = confirmUX.startSubmitting('Confirming…'); if (!confirmFinish) return;
              try {
                const result = await api('/auth/mfa/enable', { method: 'POST', body: JSON.stringify({ code }) });
                persistReplacementToken(result);
                state.me.mfa = { enabled: true, recovery_codes_remaining: Array.isArray(result.recovery_codes) ? result.recovery_codes.length : 0 };
                closeModal(sheet);
                const codes = Array.isArray(result.recovery_codes) ? result.recovery_codes : [];
                const recovery = openChildModal(modal, () => openModal(`${modalHead('Save recovery codes')}<div class="business-trust-summary is-ready"><span aria-hidden="true">${uiIcon('check-circle')}</span><div><b>MFA is on</b><p>Save these one-time codes somewhere private. They will not be shown again.</p></div></div><label class="business-recovery-label" for="business-recovery-codes">One-time recovery codes</label><textarea id="business-recovery-codes" class="business-recovery-codes" readonly rows="${Math.max(4, codes.length)}" aria-describedby="business-recovery-help">${esc(codes.join('\n'))}</textarea><small class="field-help" id="business-recovery-help">Each code can be used once if you lose access to your authenticator.</small><button type="button" class="btn btn-primary btn-block business-private-copy" id="business-copy-recovery">${uiIcon('copy')} Copy recovery codes</button><p class="business-copy-status" id="business-recovery-copy-status" role="status" aria-live="polite" aria-atomic="true"></p><p class="form-error inline-action-error" data-inline-action-error role="alert" tabindex="-1" hidden></p>`, { label: 'Save account MFA recovery codes' }));
                const recoveryCodes = recovery.querySelector('#business-recovery-codes');
                const recoveryCopy = recovery.querySelector('#business-copy-recovery');
                recoveryCodes.addEventListener('focus', () => recoveryCodes.select());
                recoveryCodes.addEventListener('click', () => recoveryCodes.select());
                recoveryCopy.addEventListener('click', async () => {
                  clearInlineActionError(recovery);
                  const copyFinish = beginButtonAction(recoveryCopy, 'Copying…');
                  if (!copyFinish) return;
                  try {
                    await navigator.clipboard.writeText(codes.join('\n'));
                    copyFinish();
                    recoveryCopy.innerHTML = `${uiIcon('check')} Copied`;
                    recovery.querySelector('#business-recovery-copy-status').textContent = 'Recovery codes copied. Store them somewhere private.';
                  } catch (error) {
                    copyFinish();
                    recoveryCodes.focus();
                    recoveryCodes.select();
                    showInlineActionError(recovery, 'Copy was blocked. The recovery codes are selected so you can copy them manually.');
                  }
                });
                render();
              } catch (error) { confirmFinish(); confirmUX.showError(error.message); }
            });
          } catch (error) { finish(); formUX.showError(error.message); }
        });
      });
      body.querySelector('[data-mfa-disable]')?.addEventListener('click', () => {
        const sheet = openChildModal(modal, () => openModal(`${modalHead('Disable MFA')}<div class="business-confirm-card"><span aria-hidden="true">${uiIcon('alert-triangle')}</span><p>This removes the second-factor requirement from your whole Third Shot account.</p></div><form id="business-mfa-disable-form" novalidate><div class="form-field"><label for="business-mfa-disable-password">Current password</label><input type="password" id="business-mfa-disable-password" autocomplete="current-password" /></div><div class="form-field"><label for="business-mfa-disable-code">Current six-digit code</label><input type="text" id="business-mfa-disable-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div><button type="submit" class="btn btn-danger btn-block" id="business-mfa-disable-submit">Disable MFA</button></form>`, { label: 'Disable account multi-factor authentication' }));
        const formUX = bindModalFormUX(sheet, '#business-mfa-disable-submit');
        sheet.querySelector('#business-mfa-disable-form').addEventListener('submit', async (event) => { event.preventDefault(); formUX.clearError(); const password = sheet.querySelector('#business-mfa-disable-password'); const code = sheet.querySelector('#business-mfa-disable-code'); if (!password.value) { formUX.showError('Enter your current password.', password); return; } if (!/^\d{6}$/.test(code.value.trim())) { formUX.showError('Enter the current six-digit code.', code); return; } const finish = formUX.startSubmitting('Disabling MFA…'); if (!finish) return; try { const result = await api('/auth/mfa/disable', { method: 'POST', body: JSON.stringify({ current_password: password.value, code: code.value.trim() }) }); persistReplacementToken(result); state.me.mfa = { enabled: false, recovery_codes_remaining: 0 }; closeModal(sheet); toast('Multi-factor authentication disabled'); render(); } catch (error) { finish(); formUX.showError(error.message); } });
      });
      body.querySelector('[data-open-account-security]')?.addEventListener('click', () => openChildModal(modal, openAccountSettings));
    };
    render();
    if (!state.me?.mfa) refreshMe().then((changed) => { if (changed && body.isConnected) render(); });
    return modal;
  }

  function openBusinessOwnershipControls(business, onSaved) {
    const canTransfer = business.permissions?.can_transfer === true || business.is_owner === true || String(business.manager_role || '').toLowerCase() === 'owner';
    const mfaEnabled = state.me?.mfa?.enabled === true;
    const modal = openModal(`
      ${modalHead('Ownership & visibility')}
      <div class="business-feature-intro"><b>Sensitive actions require owner permission.</b><p>Unpublishing hides the player listing. Only an authorized Third Shot operator can suspend live connection activity. Releasing this claim removes your organization’s control of this location.</p></div>
      <section class="card business-danger-section"><div><b>${business.suspended ? 'Venue operations are suspended' : 'Safety suspension status'}</b><p>${business.suspended ? 'Players cannot use official actions until an authorized operator resumes the venue.' : 'Only authorized Third Shot operators can suspend venue operations. Owners can unpublish the listing from the Business Hub.'}</p></div><span class="business-status ${business.suspended ? 'is-rejected' : 'is-verified'}">${uiIcon(business.suspended ? 'alert-triangle' : 'check-circle')}<span>${business.suspended ? 'Suspended' : 'Active'}</span></span></section>
      <section class="card business-danger-section"><div><b>Transfer organization ownership</b><p>Move the whole business organization and every attached location to an accepted admin. Existing staff should not share credentials.</p></div><button type="button" class="btn btn-secondary" data-business-transfer ${canTransfer ? '' : 'disabled'}>Transfer</button></section>
      <section class="card business-danger-section is-danger"><div><b>Release this venue claim</b><p>This listing is unpublished and organization access to this location ends. Other attached locations, public court data, and historical audit entries remain.</p></div><button type="button" class="btn btn-danger" data-business-release ${canTransfer ? '' : 'disabled'}>Release claim</button></section>
      ${canTransfer ? '' : '<p class="business-form-note">Only the primary owner can transfer or release this venue.</p>'}
    `, { label: 'Business ownership and visibility controls' });
    modal.querySelector('[data-business-transfer]')?.addEventListener('click', async (event) => {
      const transferButton = event.currentTarget;
      transferButton.disabled = true;
      try {
        const team = await api(`/businesses/${business.id}/team`);
        const admins = (Array.isArray(team.members) ? team.members : []).filter((member) => member.role === 'admin');
        if (!admins.length) {
          openChildModal(modal, () => openModal(`${modalHead('Add an admin first')}<div class="business-feature-state is-neutral"><span aria-hidden="true">${uiIcon('users')}</span><div><b>No eligible owner is ready</b><p>Invite the person in Team access, assign Admin, and wait for them to accept before transferring ownership.</p></div></div>`, { label: 'No eligible business owner transfer target', returnFocus: transferButton }));
          transferButton.disabled = false;
          return;
        }
        const sheet = openChildModal(modal, () => openModal(`${modalHead('Transfer organization')}<div class="business-confirm-card"><span aria-hidden="true">${uiIcon('alert-triangle')}</span><p>Ownership of <b>${esc(team.organization?.name || business.name || 'this organization')}</b> and all ${(team.locations || []).length || 'attached'} location${(team.locations || []).length === 1 ? '' : 's'} moves immediately to an accepted organization admin. Every location is unpublished for the new owner to review, and you become an admin.</p></div><form id="business-transfer-form" novalidate><div class="form-field"><label for="business-transfer-member">New organization owner</label><select id="business-transfer-member" data-select-title="New organization owner">${admins.map((member) => `<option value="${member.id}">${esc(member.display_name || member.email)} · ${esc(member.email || '')}</option>`).join('')}</select></div><div class="form-field"><label for="business-transfer-password">Current account password</label><input type="password" id="business-transfer-password" autocomplete="current-password" /></div>${mfaEnabled ? '<div class="form-field"><label for="business-transfer-mfa">Current six-digit MFA code</label><input type="text" id="business-transfer-mfa" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div>' : ''}<button type="submit" class="btn btn-danger btn-block" id="business-transfer-send">Transfer all locations now</button></form>`, { label: 'Transfer business organization ownership', returnFocus: transferButton }));
        transferButton.disabled = false;
        const formUX = bindModalFormUX(sheet, '#business-transfer-send');
        sheet.querySelector('#business-transfer-form').addEventListener('submit', async (submitEvent) => { submitEvent.preventDefault(); const password = sheet.querySelector('#business-transfer-password'); if (!password.value) { formUX.showError('Enter your current password.', password); return; } const mfa = sheet.querySelector('#business-transfer-mfa'); if (mfaEnabled && !/^\d{6}$/.test(mfa.value.trim())) { formUX.showError('Enter the current six-digit MFA code.', mfa); return; } const finish = formUX.startSubmitting('Transferring organization…'); if (!finish) return; try { await api(`/businesses/${business.id}/transfer`, { method: 'POST', body: JSON.stringify({ member_id: Number(sheet.querySelector('#business-transfer-member').value), current_password: password.value, ...(mfaEnabled ? { mfa_code: mfa.value.trim() } : {}) }) }); toast('Organization and attached locations transferred'); dismissAllModals(() => openBusinessHub()); } catch (error) { finish(); formUX.showError(error.message); } });
      } catch (error) { transferButton.disabled = false; toast(error.message); }
    });
    modal.querySelector('[data-business-release]')?.addEventListener('click', () => openBusinessConfirmAction({ title: 'Release this venue claim?', message: 'This official listing will be unpublished and organization access to this location will end. Other attached locations are unchanged, and another representative may claim this venue.', confirmLabel: 'Release venue claim', requireText: business.name, stepUp: true, onConfirm: async (sheet, auth) => { await api(`/businesses/${business.id}/claim`, { method: 'DELETE', body: JSON.stringify({ confirmation: business.name, ...auth }) }); toast('Venue claim released'); dismissAllModals(() => openBusinessHub()); } }));
    return modal;
  }

  function currentUserIsBusinessOperator() {
    return state.me?.can_review_businesses === true
      && ['reviewer', 'admin'].includes(String(state.me?.operator_role || '').toLowerCase());
  }

  function businessRevisionDiffHtml(item) {
    return window.VenueWorkspace.revisionDiff(item);
  }

  function openCourtCorrectionQueue() {
    const modal = openModal(`${modalHead('Court closure reviews')}<div class="form-field"><label for="court-review-status">Show</label><select id="court-review-status"><option value="pending">Needs review</option><option value="reviewed">Reviewed decisions</option></select></div><div class="business-feature-body" aria-live="polite"></div>`, {page:true});
    const body = modal.querySelector('.business-feature-body');
    let generation = 0;
    const load = async () => {
      const request = ++generation; body.innerHTML = skeletonHtml(2);
      try {
        const data = await api(`/operator/courts/corrections?status=${modal.querySelector('#court-review-status').value}`);
        if (request !== generation || !modal.isConnected) return;
        body.innerHTML = `<p class="simple-note">Review evidence before changing court access. Reports never close a court automatically.</p>${data.items.length ? data.items.map(item => `<article class="card row"><span class="row-main"><b>${esc(item.court_name)}</b><small>${item.proposed_closed ? 'Closure' : 'Reopening'} · ${esc(fmtDateTime(item.submitted_at))}</small><small>${item.status === 'pending' ? `${item.impact.upcoming_sessions} upcoming sessions · ${item.impact.players} players` : `${esc(item.status)} · ${esc(fmtDateTime(item.reviewed_at))}`}</small></span><button class="btn btn-secondary" type="button" data-court-review="${item.id}">${item.status === 'pending' ? 'Review' : 'Inspect decision'}</button></article>`).join('') : '<p>No court status reports need review.</p>'}`;
        body.querySelectorAll('[data-court-review]').forEach(button => button.addEventListener('click', () => openChildModal(modal, () => openCourtCorrectionReview(Number(button.dataset.courtReview), load))));
      } catch (error) { if (request !== generation || !modal.isConnected) return; body.innerHTML = `<p role="alert">${esc(error.message)}</p><button class="btn btn-secondary" data-retry>Try again</button>`; body.querySelector('[data-retry]').addEventListener('click', load); }
    };
    modal.querySelector('#court-review-status').addEventListener('change', load);
    load(); return modal;
  }

  function openCourtCorrectionReview(id, onSaved) {
    const modal = openModal(`${modalHead('Review court status')}<div class="business-feature-body">${skeletonHtml(2)}</div>`);
    const body = modal.querySelector('.business-feature-body');
    const load = async () => {
      try {
        const item = await api(`/operator/courts/corrections/${id}`); if (!modal.isConnected) return;
        body.innerHTML = `<h3>${esc(item.court_name)}</h3><p class="simple-note">Current: ${item.current_closed ? 'Closed to new play' : 'Open to new play'} → Proposed: ${item.proposed_closed ? 'Closed' : 'Reopened'}</p><div class="card"><b>Submitted evidence</b><p>${esc(item.evidence || 'No written evidence. Investigate before approving.')}</p></div><div class="card"><b>What changes</b><p>${esc(item.impact.effect)}</p><p>${item.impact.upcoming_sessions} upcoming sessions · ${item.impact.players} players</p>${item.impact.sessions.map(game => `<p>${esc(game.title)} · ${esc(fmtDateTime(game.scheduled_at))}</p>`).join('')}</div><details><summary>Previous decisions (${item.history.length})</summary>${item.history.map(row => `<p><b>${esc(row.status)} · ${esc(fmtDateTime(row.reviewed_at))}</b><br>${esc(row.review_note)}</p>`).join('') || '<p>No reviewed decisions yet.</p>'}</details>${item.status !== 'pending' ? '<p>This report has already been reviewed.</p>' : `<form id="court-review-form"><div class="form-field"><label for="court-review-decision">Decision</label><select id="court-review-decision"><option value="">Choose after reviewing</option><option value="approve">Approve ${item.proposed_closed ? 'closure' : 'reopening'}</option><option value="reject">Keep current court status</option></select></div><div class="form-field"><label for="court-review-note">Reason and evidence checked</label><textarea id="court-review-note" minlength="12" maxlength="500" required rows="3"></textarea></div><div class="form-field"><label for="court-review-mfa">Current authenticator code</label><input id="court-review-mfa" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required maxlength="6" /></div><p class="form-error hidden" role="alert"></p><button class="btn btn-primary btn-block" type="submit">Save reviewed decision</button></form>`}`;
        body.querySelector('form')?.addEventListener('submit', async event => {
          event.preventDefault(); const form = event.currentTarget; const error = form.querySelector('[role="alert"]');
          const decision = form.querySelector('select').value; const note = form.querySelector('textarea').value.trim();
          if (!decision || note.length < 12) { error.textContent = 'Choose a decision and explain the evidence checked.'; error.classList.remove('hidden'); return; }
          const reset = beginButtonAction(form.querySelector('[type="submit"]'), 'Saving decision…'); if (!reset) return;
          try { await api(`/operator/courts/corrections/${id}/review`, {method:'POST',body:JSON.stringify({decision,review_note:note,mfa_code:form.querySelector('input').value,expected_closed:item.current_closed})}); closeModal(modal); onSaved?.(); toast('Court status decision saved.'); }
          catch (failure) { reset(); error.textContent = failure.message; error.classList.remove('hidden'); }
        });
      } catch (error) { if (!modal.isConnected) return; body.innerHTML = `<p role="alert">${esc(error.message)}</p><button class="btn btn-secondary" data-retry>Try again</button>`; body.querySelector('[data-retry]').addEventListener('click', load); }
    };
    load(); return modal;
  }

  function openBusinessOperatorHub() {
    if (!currentUserIsBusinessOperator()) { toast('Operator access is required'); return null; }
    const modal = openModal(`${modalHead('Business operator queue')}<form id="venue-operator-filters" class="venue-operator-filters"><div class="form-field"><label for="venue-queue-search">Find venue or claimant</label><input type="search" id="venue-queue-search" maxlength="120" placeholder="Venue name or claimant email" /></div><div class="form-grid"><div class="form-field"><label for="venue-queue-type">Review type</label><select id="venue-queue-type"><option value="all">All types</option><option value="claims">Claims</option><option value="revisions">Sensitive content</option><option value="integration_requests">Setup requests</option><option value="reports">Player reports</option><option value="actions_requiring_second_admin">Second-admin approvals</option><option value="connection_alerts">Connection alerts</option><option value="profile_link_alerts">Link alerts</option></select></div><div class="form-field"><label for="venue-queue-assignment">Assigned to</label><select id="venue-queue-assignment"><option value="any">Anyone</option><option value="mine">Me</option><option value="unassigned">Unassigned</option></select></div><div class="form-field"><label for="venue-queue-sort">Order</label><select id="venue-queue-sort"><option value="due">Due first</option><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></div></div><label class="business-authorized-check"><input type="checkbox" id="venue-queue-overdue" /><span>Overdue only</span></label><div class="venue-connection-tasks"><button type="submit" class="btn btn-primary">Apply filters</button><button type="button" class="btn btn-secondary" id="venue-queue-reset">Reset filters</button></div></form><div class="business-feature-body" aria-live="polite">${skeletonHtml(3)}</div>`, { page: true, label: 'Business operator queue' });
    modal.querySelector('#venue-operator-filters').insertAdjacentHTML('beforebegin', '<button type="button" class="btn btn-secondary btn-block" data-open-court-reviews>Court closure & reopening reviews</button>');
    modal.querySelector('[data-open-court-reviews]').addEventListener('click', () => openChildModal(modal, openCourtCorrectionQueue));
    const body = modal.querySelector('.business-feature-body');
    let requestGeneration = 0;
    const load = async () => {
      const generation = ++requestGeneration;
      body.innerHTML = skeletonHtml(3);
      try {
        const query = new URLSearchParams({q:modal.querySelector('#venue-queue-search').value.trim(),assignment:modal.querySelector('#venue-queue-assignment').value,sort:modal.querySelector('#venue-queue-sort').value,overdue:modal.querySelector('#venue-queue-overdue').checked ? '1' : '0'});
        const data = await api(`/operator/business/queue?${query}`);
        if (generation !== requestGeneration || !body.isConnected) return;
        const mfaReady = state.me?.mfa?.enabled === true;
        const queueData = data;
        const allGroups = [
          ['claims', 'Claims'], ['revisions', 'Sensitive content'],
          ['integration_requests', 'Integration requests'], ['reports', 'Player & profile-link reports'],
          ['actions_requiring_second_admin', 'Second-admin approvals'], ['connection_alerts', 'Connection health'],
          ['profile_link_alerts', 'Profile link health'],
        ];
        const selectedType = modal.querySelector('#venue-queue-type').value;
        const groups = allGroups.filter(([key]) => selectedType === 'all' ? (data[key] || []).length : key === selectedType);
        const assignableKinds = new Set(['claims', 'integration_requests', 'reports']);
        const itemSummary = (kind, item) => {
          if (kind === 'claims') return `${item.claimant_email || 'Claimant'} · ${(item.evidence || []).length} evidence item${(item.evidence || []).length === 1 ? '' : 's'}`;
          if (kind === 'revisions') return item.change_summary || 'Sensitive listing change';
          if (kind === 'integration_requests') return [item.provider, ...(item.capabilities || [])].filter(Boolean).join(' · ') || item.details || 'Integration request';
          if (kind === 'reports') return `${item.category || 'Report'} · ${item.details || ''}`;
          if (kind === 'actions_requiring_second_admin') return `${String(item.action_type || 'action').replace(/_/g, ' ')} · proposed by ${item.proposed_by || `user ${item.proposed_by_id || 'unknown'}`}`;
          return item.last_error_message || item.error_message || item.status || item.health_status || 'Connection needs review';
        };
        body.innerHTML = `<div class="business-operator-warning"><b>Privileged workspace</b><p>Operator actions are server-authorized and audited. Verification confirms listing control, not the truth of every service or link. Player reports and automated link-health alerts remain separate so each follows its correct review flow.</p></div>${mfaReady ? '' : `<div class="business-feature-state is-error"><span aria-hidden="true">${uiIcon('lock')}</span><div><b>Set up MFA before changing queue state</b><p>You can inspect the queue and run link checks, but assignment and review decisions require a fresh six-digit code.</p><button type="button" class="btn btn-primary btn-sm" data-operator-setup-mfa>Set up MFA</button></div></div>`}${!groups.length ? '<div class="business-operator-empty">No review items match these filters.</div>' : ''}<p class="simple-note">Up to 200 results per review type. Narrow the search for older items.</p>${groups.map(([key, label]) => { const items = Array.isArray(queueData[key]) ? queueData[key] : []; return `<section class="business-operator-section"><div class="section-label">${esc(label)} · ${items.length}</div>${items.length ? items.map((item, index) => { const deadline = item.due_at || item.response_due_at || item.expires_at; const assignment = item.assigned_operator_identifier || (item.assigned_operator_id ? `Operator ${item.assigned_operator_id}` : 'Unassigned'); const sla = String(item.sla_state || (item.overdue ? 'overdue' : '')).replace(/_/g, ' '); return `<article class="card business-operator-row"><div class="row-main"><b>${esc(item.business_name || item.court_name || item.display_name || item.provider || item.action_type || 'Business request')}</b><small>${esc(itemSummary(key, item))}</small>${assignableKinds.has(key) ? `<small>${esc(assignment)}${sla ? ` · SLA ${esc(sla)}` : ''}</small>` : ''}${deadline ? `<small class="${item.overdue ? 'business-operator-overdue' : ''}">${item.overdue ? 'Overdue · ' : ''}${item.expires_at ? 'Expires' : 'Due'} ${esc(fmtDateTime(deadline))}</small>` : item.created_at ? `<small>Submitted ${esc(fmtDateTime(item.created_at))}</small>` : ''}</div><div class="business-operator-actions">${assignableKinds.has(key) && !item.assigned_operator_id ? `<button type="button" class="btn btn-secondary btn-sm" data-operator-assign-kind="${key}" data-operator-assign-index="${index}" ${mfaReady ? '' : 'disabled'}>Assign to me</button>` : ''}<button type="button" class="btn btn-secondary btn-sm" data-operator-kind="${key}" data-operator-index="${index}" ${!mfaReady && !['connection_alerts', 'profile_link_alerts'].includes(key) ? 'disabled' : ''}>${key === 'actions_requiring_second_admin' ? 'Inspect' : 'Review'}</button></div></article>`; }).join('') : `<div class="business-operator-empty">No ${esc(label.toLowerCase())} need attention.</div>`}</section>`; }).join('')}`;
        body.querySelector('[data-operator-setup-mfa]')?.addEventListener('click', () => {
          openChildModal(modal, () => openBusinessSecurity({}));
        });
        body.querySelectorAll('[data-operator-assign-kind]').forEach((button) => button.addEventListener('click', () => {
          const items = Array.isArray(queueData[button.dataset.operatorAssignKind]) ? queueData[button.dataset.operatorAssignKind] : [];
          const item = items[Number(button.dataset.operatorAssignIndex)];
          if (item) openChildModal(modal, () => openBusinessOperatorAssignment(button.dataset.operatorAssignKind, item, load));
        }));
        body.querySelectorAll('[data-operator-kind]').forEach((button) => button.addEventListener('click', () => {
          const items = Array.isArray(queueData[button.dataset.operatorKind]) ? queueData[button.dataset.operatorKind] : [];
          const item = items[Number(button.dataset.operatorIndex)];
          if (item) openChildModal(modal, () => openBusinessOperatorReview(button.dataset.operatorKind, item, load));
        }));
      } catch (error) { if (generation !== requestGeneration || !body.isConnected) return; body.innerHTML = `${businessUnavailableHtml('Operator queue', error)}<button class="btn btn-secondary btn-block" data-retry>Try again</button>`; body.querySelector('[data-retry]').addEventListener('click', load); }
    };
    modal.querySelector('#venue-operator-filters').addEventListener('submit', event => { event.preventDefault(); load(); });
    modal.querySelectorAll('#venue-operator-filters select, #venue-queue-overdue').forEach(input => input.addEventListener('change', load));
    modal.querySelector('#venue-queue-reset').addEventListener('click', () => { modal.querySelector('#venue-operator-filters').reset(); modal.querySelectorAll('#venue-operator-filters select').forEach(syncAppSelect); load(); });
    load(); return modal;
  }

  function openBusinessOperatorAssignment(kind, item, onDone) {
    const segment = { claims: 'claims', integration_requests: 'integration-requests', reports: 'reports' }[kind];
    const id = safePositiveId(item?.id);
    if (!segment || !id) return null;
    if (state.me?.mfa?.enabled !== true) { toast('Set up MFA before assigning operator work'); return null; }
    const modal = openModal(`${modalHead('Assign queue item')}<div class="business-feature-intro"><b>Assign this item to your operator account?</b><p>This changes queue ownership but does not approve, reject, or resolve the request.</p></div><form id="operator-business-assign" novalidate><div class="form-field"><label for="operator-business-assign-mfa">Current six-digit MFA code</label><input type="text" id="operator-business-assign-mfa" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div><button type="submit" class="btn btn-primary btn-block" id="operator-business-assign-submit">Assign to me</button></form>`, { label: 'Assign business operator queue item' });
    const formUX = bindModalFormUX(modal, '#operator-business-assign-submit');
    modal.querySelector('#operator-business-assign').addEventListener('submit', async (event) => {
      event.preventDefault(); formUX.clearError();
      const mfa = modal.querySelector('#operator-business-assign-mfa');
      if (!/^\d{6}$/.test(mfa.value.trim())) { formUX.showError('Enter the current six-digit MFA code.', mfa); return; }
      const finish = formUX.startSubmitting('Assigning…'); if (!finish) return;
      try {
        await api(`/operator/business/${segment}/${id}/assign`, {
          method: 'POST', body: JSON.stringify({ operator_user_id: Number(state.me.id), mfa_code: mfa.value.trim() }),
        });
        closeModal(modal); toast('Queue item assigned to you'); onDone?.();
      } catch (error) { finish(); formUX.showError(error.message); }
    });
    return modal;
  }

  function openBusinessOperatorEvidenceReview(evidence, onDone) {
    const evidenceId = safePositiveId(evidence?.id);
    if (!evidenceId) return null;
    const modal = openModal(`${modalHead('Review evidence')}<div class="business-operator-detail"><b>${esc(String(evidence.type || 'evidence').replace(/_/g, ' '))}</b><p>${esc(evidence.value || '')}</p><small>${evidence.domain_match === true ? 'Matches an approved official domain' : evidence.domain_match === false ? 'Does not match an approved official domain' : 'No domain comparison available'} · status ${esc(evidence.status || 'submitted')}</small>${evidence.note ? `<p>Claimant note: ${esc(evidence.note)}</p>` : ''}</div><form id="operator-evidence-action" novalidate><div class="form-field"><label for="operator-evidence-decision">Evidence decision</label><select id="operator-evidence-decision" data-select-title="Evidence decision"><option value="" selected disabled>Choose a decision</option><option value="accept">Accept as control evidence</option><option value="reject">Reject evidence</option></select></div><div class="form-field"><label for="operator-evidence-note">Immutable review note</label><textarea id="operator-evidence-note" rows="4" maxlength="1000"></textarea></div><div class="form-field"><label for="operator-evidence-mfa">Current six-digit MFA code</label><input type="text" id="operator-evidence-mfa" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div><button type="submit" class="btn btn-primary btn-block" id="operator-evidence-submit">Save evidence decision</button></form>`, { label: 'Review business verification evidence' });
    const formUX = bindModalFormUX(modal, '#operator-evidence-submit');
    modal.querySelector('#operator-evidence-action').addEventListener('submit', async (event) => {
      event.preventDefault(); formUX.clearError();
      const decision = modal.querySelector('#operator-evidence-decision');
      const note = modal.querySelector('#operator-evidence-note');
      const mfa = modal.querySelector('#operator-evidence-mfa');
      if (!decision.value) { formUX.showError('Choose whether to accept or reject this evidence.', decision); return; }
      if (note.value.trim().length < 3) { formUX.showError('Add a clear evidence review note.', note); return; }
      if (!/^\d{6}$/.test(mfa.value.trim())) { formUX.showError('Enter the current six-digit MFA code.', mfa); return; }
      const finish = formUX.startSubmitting('Saving evidence review…'); if (!finish) return;
      try {
        await api(`/operator/business/evidence/${evidenceId}/review`, { method: 'POST', body: JSON.stringify({
          decision: modal.querySelector('#operator-evidence-decision').value,
          review_note: note.value.trim(), mfa_code: mfa.value.trim(),
        }) });
        closeModal(modal); toast('Evidence review saved'); onDone?.();
      } catch (error) { finish(); formUX.showError(error.message); }
    });
    return modal;
  }

  function openBusinessOperatorReview(kind, item, onDone) {
    if (!['connection_alerts', 'profile_link_alerts'].includes(kind) && state.me?.mfa?.enabled !== true) {
      const modal = openModal(`${modalHead('MFA required')}<div class="business-feature-state is-error"><span aria-hidden="true">${uiIcon('lock')}</span><div><b>Protect operator actions with MFA</b><p>Set up account MFA, then reopen this queue item.</p><button type="button" class="btn btn-primary btn-sm" data-operator-setup-mfa>Set up MFA</button></div></div>`, { label: 'Operator MFA required' });
      modal.querySelector('[data-operator-setup-mfa]').addEventListener('click', () => {
        openChildModal(modal, () => openBusinessSecurity({}));
      });
      return modal;
    }
    const id = safePositiveId(item.id);
    if (!id) return null;
    if (['connection_alerts', 'profile_link_alerts'].includes(kind)) {
      const connectionId = safePositiveId(item.connection_id || item.id);
      const businessId = safePositiveId(item.business_id);
      const profileAlert = kind === 'profile_link_alerts';
      if ((profileAlert && !businessId) || (!profileAlert && !connectionId)) return null;
      const endpoint = profileAlert ? `/operator/businesses/${businessId}/link-health/recheck` : `/operator/business/connections/${connectionId}/recheck`;
      const modal = openModal(`${modalHead(profileAlert ? 'Profile link health check' : 'Connection health check')}<div class="business-feature-intro"><b>${esc(item.display_name || item.provider_key || (profileAlert ? 'Business profile link' : 'Business connection'))}</b><p>${esc(item.last_error_message || item.error_message || item.status || 'Run a fresh link health check.')}</p></div><form id="operator-connection-recheck-form" novalidate><button type="submit" class="btn btn-primary btn-block" id="operator-connection-recheck">Run health check</button><p class="business-form-note">This checks the current configured public links. It does not acknowledge, hide, or resolve the alert by itself.</p></form>`, { label: profileAlert ? 'Operator business profile link health check' : 'Operator business connection health check' });
      const formUX = bindModalFormUX(modal, '#operator-connection-recheck');
      bindModalDiscardConfirmation(modal, { isDirty: formUX.isDirty });
      modal.querySelector('#operator-connection-recheck-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const finish = formUX.startSubmitting('Checking links…');
        if (!finish) return;
        try {
          await api(endpoint, { method: 'POST', body: '{}' });
          closeModal(modal);
          toast(profileAlert ? 'Profile links checked' : 'Connection health checked');
          onDone?.();
        } catch (error) {
          finish();
          formUX.showError(error.message);
        }
      });
      return modal;
    }
    const mfaField = '<div class="form-field"><label for="operator-business-mfa">Current six-digit MFA code</label><input type="text" id="operator-business-mfa" inputmode="numeric" autocomplete="one-time-code" maxlength="6" /></div>';
    let title = 'Review business item';
    let fields = '';
    let claimEvidence = [];
    if (kind === 'claims') {
      title = 'Review business claim';
      const evidence = Array.isArray(item.evidence) ? item.evidence : [];
      claimEvidence = evidence;
      const history = Array.isArray(item.review_history) ? item.review_history : [];
      const proposed = item.business_profile?.proposed_location;
      const approvedEvidence = evidence.some((entry) => ['verified', 'accepted'].includes(String(entry.status || '').toLowerCase()));
      fields = `<div class="business-operator-detail"><b>${esc(item.business_name || item.court_name || 'Venue claim')}</b><p>${esc(item.claimant_name || item.claimant_email || 'Claimant')} · role ${esc(item.role || 'not provided')}</p><small>Claimant user ${esc(item.claimant_user_id || 'unknown')} · current owner ${esc(item.current_owner_user_id || 'none')}</small>${item.ownership_transfer ? '<div class="business-connection-error">Approval transfers control and requires a different administrator to confirm it.</div>' : ''}</div>
        ${proposed ? `<div class="card"><b>New venue location · private</b><p>${esc([proposed.name, proposed.address, proposed.city, proposed.state].join(', '))}</p><p>${esc(proposed.num_courts)} ${proposed.indoor ? 'indoor' : 'outdoor'} courts</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${proposed.latitude},${proposed.longitude}`)}" target="_blank" rel="noopener">Check proposed map location ${uiIcon('link')}</a><label class="business-authorized-check"><input type="checkbox" id="operator-location-reviewed" /><span>I checked this venue’s name, address and map location. Approval adds the court to public discovery.</span></label></div>` : ''}
        <div class="section-label">Submitted evidence</div>
        ${evidence.length ? evidence.map((entry) => `<div class="card business-evidence-row"><span aria-hidden="true">${uiIcon(businessStateIconName(entry.status))}</span><div class="row-main"><b>${esc(String(entry.type || 'evidence').replace(/_/g, ' '))}</b><small>${esc(entry.value || '')} · ${esc(entry.status || 'submitted')}</small><small>${entry.domain_match === true ? 'Matches approved official domain' : entry.domain_match === false ? 'Does not match approved official domain' : 'Domain match not applicable'}</small>${entry.note ? `<p>Claimant note: ${esc(entry.note)}</p>` : ''}${entry.review_note ? `<p>Immutable reviewer note: ${esc(entry.review_note)}</p>` : ''}</div>${entry.status === 'submitted' ? `<button type="button" class="btn btn-secondary btn-sm" data-operator-evidence-index="${evidence.indexOf(entry)}">Review</button>` : ''}</div>`).join('') : '<div class="business-operator-empty">No evidence submitted.</div>'}
        ${history.length ? `<details class="business-operator-history"><summary>Immutable review history · ${history.length}</summary>${history.map((entry) => `<p><b>${esc(entry.decision || 'review')}</b> · ${esc(entry.verification_method || 'method not recorded')} · ${esc(entry.review_note || '')}${entry.reviewer_identifier ? ` · ${esc(entry.reviewer_identifier)}` : ''}</p>`).join('')}</details>` : '<div class="business-operator-empty">No earlier claim decisions.</div>'}
        ${approvedEvidence ? '' : `<div class="business-feature-state is-pending"><span aria-hidden="true">${uiIcon('clock')}</span><div><b>Review evidence before approval</b><p>At least one evidence item must be accepted or verified. You can still reject the claim with clear feedback.</p></div></div>`}
        <div class="form-field"><label for="operator-business-decision">Claim decision</label><select id="operator-business-decision" data-select-title="Claim decision"><option value="" selected disabled>Choose a decision</option>${approvedEvidence ? '<option value="approve">Approve listing control</option>' : ''}<option value="reject">Request changes</option></select></div><div class="form-field"><label for="operator-verification-method">Verification method relied on</label><select id="operator-verification-method" data-select-title="Verification method">${['business_email', 'business_phone', 'website_domain', 'documents', 'in_person', 'other'].map((value) => `<option value="${value}">${esc(value.replace(/_/g, ' '))}</option>`).join('')}</select></div><div class="form-field"><label for="operator-business-note">Private audit note</label><textarea id="operator-business-note" rows="4" maxlength="1000"></textarea></div><div class="form-field"><label for="operator-claimant-feedback">Feedback sent to claimant</label><textarea id="operator-claimant-feedback" rows="4" maxlength="1000"></textarea></div>`;
    } else if (kind === 'integration_requests') {
      title = 'Review integration request';
      fields = `<div class="business-operator-detail"><b>${esc(item.business_name || item.provider || 'Integration request')}</b><p>${esc(item.details || '')}</p><small>${esc(item.contact_email || '')}</small></div><div class="form-field"><label for="operator-business-decision">Status</label><select id="operator-business-decision" data-select-title="Request status"><option value="" selected disabled>Choose a status</option><option value="contacted">Contacted</option><option value="completed">Completed</option><option value="declined">Declined</option></select></div><div class="form-field"><label for="operator-business-note">Business-facing status message</label><textarea id="operator-business-note" rows="5" maxlength="1000"></textarea></div>`;
    } else if (kind === 'reports') {
      title = 'Review player report';
      fields = `<div class="business-operator-detail"><b>${esc(String(item.category || 'Report').replace(/_/g, ' '))}</b><p>${esc(item.details || '')}</p></div><div class="form-field"><label for="operator-business-decision">Status</label><select id="operator-business-decision" data-select-title="Report status"><option value="" selected disabled>Choose a status</option><option value="reviewing">Reviewing</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select></div><div class="form-field"><label for="operator-business-note">Reporter-facing status message</label><textarea id="operator-business-note" rows="5" maxlength="1000"></textarea></div>`;
    } else if (kind === 'revisions') {
      title = 'Review sensitive content';
      fields = `<div class="business-operator-detail"><b>${esc(item.change_summary || item.action || 'Sensitive listing change')}</b><p>${item.sensitive ? 'Sensitive content review required.' : 'Listing revision.'}</p></div>${businessRevisionDiffHtml(item)}<div class="form-field"><label for="operator-business-decision">Decision</label><select id="operator-business-decision" data-select-title="Revision decision"><option value="" selected disabled>Choose a decision</option><option value="approve">Approve change</option><option value="reject">Reject &amp; restore accepted content</option></select></div><div class="form-field"><label for="operator-business-note">Review note</label><textarea id="operator-business-note" rows="5" maxlength="1000"></textarea></div>`;
    } else if (kind === 'actions_requiring_second_admin') {
      title = 'Second-admin approval';
      const payload = item.payload && typeof item.payload === 'object' ? item.payload : {};
      fields = `<div class="business-confirm-card"><span aria-hidden="true">${uiIcon('alert-triangle')}</span><p>This ${esc(String(item.action_type || 'action').replace(/_/g, ' '))} was proposed by ${esc(item.proposed_by || `user ${item.proposed_by_id || 'unknown'}`)}. A different administrator must independently verify it.</p></div><div class="card business-operator-detail"><b>Proposal context</b><p>${esc(payload.reason || payload.review_note || 'No additional reason was included.')}</p>${item.business_id ? `<small>Business ${esc(item.business_id)}</small>` : ''}${item.claim_id ? `<small>Claim ${esc(item.claim_id)}</small>` : ''}${item.expires_at ? `<small>Expires ${esc(fmtDateTime(item.expires_at))}</small>` : ''}</div>`;
    } else return null;
    const submitLabel = kind === 'actions_requiring_second_admin' ? 'Confirm as second administrator' : 'Save audited decision';
    const modal = openModal(`${modalHead(title)}<form id="operator-business-action" novalidate>${fields}${mfaField}<button type="submit" class="btn ${kind === 'actions_requiring_second_admin' ? 'btn-danger' : 'btn-primary'} btn-block" id="operator-business-submit" ${kind === 'actions_requiring_second_admin' && state.me?.operator_role !== 'admin' ? 'disabled' : ''}>${submitLabel}</button>${kind === 'actions_requiring_second_admin' && state.me?.operator_role !== 'admin' ? '<p class="business-form-note">Administrator role required to confirm this proposal.</p>' : ''}</form>`, { label: title });
    modal.querySelectorAll('[data-operator-evidence-index]').forEach((button) => button.addEventListener('click', () => {
      const evidence = claimEvidence[Number(button.dataset.operatorEvidenceIndex)];
      if (evidence) openChildModal(modal, () => openBusinessOperatorEvidenceReview(evidence, () => { closeModal(modal); onDone?.(); }));
    }));
    const formUX = bindModalFormUX(modal, '#operator-business-submit');
    modal.querySelector('#operator-business-action').addEventListener('submit', async (event) => {
      event.preventDefault(); formUX.clearError();
      const mfa = modal.querySelector('#operator-business-mfa');
      if (!/^\d{6}$/.test(mfa.value.trim())) { formUX.showError('Enter the current six-digit MFA code.', mfa); return; }
      const decision = modal.querySelector('#operator-business-decision');
      if (decision && !decision.value) { formUX.showError('Choose a decision before saving.', decision); return; }
      const note = modal.querySelector('#operator-business-note')?.value.trim() || '';
      if (kind !== 'actions_requiring_second_admin' && note.length < 3) { formUX.showError('Add a clear status or audit note.', modal.querySelector('#operator-business-note')); return; }
      const finish = formUX.startSubmitting('Saving decision…'); if (!finish) return;
      try {
        let result;
        if (kind === 'claims') {
          const feedback = modal.querySelector('#operator-claimant-feedback').value.trim();
          if (feedback.length < 3) { finish(); formUX.showError('Add claimant-facing feedback.', modal.querySelector('#operator-claimant-feedback')); return; }
          result = await api(`/operator/business/claims/${id}/review`, { method: 'POST', body: JSON.stringify({
            decision: modal.querySelector('#operator-business-decision').value,
            verification_method: modal.querySelector('#operator-verification-method').value,
            review_note: note, claimant_feedback: feedback, mfa_code: mfa.value.trim(),
            location_reviewed: modal.querySelector('#operator-location-reviewed')?.checked === true,
          }) });
        } else if (kind === 'integration_requests') {
          result = await api(`/operator/business/integration-requests/${id}`, { method: 'PATCH', body: JSON.stringify({ status: modal.querySelector('#operator-business-decision').value, status_message: note, mfa_code: mfa.value.trim() }) });
        } else if (kind === 'reports') {
          result = await api(`/operator/business/reports/${id}`, { method: 'PATCH', body: JSON.stringify({ status: modal.querySelector('#operator-business-decision').value, status_message: note, mfa_code: mfa.value.trim() }) });
        } else if (kind === 'revisions') {
          result = await api(`/operator/business/revisions/${id}/review`, { method: 'POST', body: JSON.stringify({ decision: modal.querySelector('#operator-business-decision').value, review_note: note, mfa_code: mfa.value.trim() }) });
        } else {
          result = await api(`/operator/business/actions/${id}/confirm`, { method: 'POST', body: JSON.stringify({ mfa_code: mfa.value.trim() }) });
        }
        closeModal(modal);
        toast(result?.requires_second_admin ? 'Proposal sent for second-admin approval' : 'Operator decision saved');
        onDone?.();
      } catch (error) { finish(); formUX.showError(error.message); }
    });
    return modal;
  }

  async function openBusinessHub({ court = null, businessId = null } = {}) {
    const modal = openModal(`
      ${modalHead('Manage your venue')}
      <div id="business-hub-body" aria-live="polite">${skeletonHtml(3)}</div>
    `, { page: true, label: 'Business Hub' });
    const body = modal.querySelector('#business-hub-body');
    let businesses = [];
    let claims = [];
    const context = { businesses, claims, renderHome: null, showLocations: null, onClaimed: null, onMissing: null, refresh: null };

    const onMissing = async () => {
      closeModal(modal);
      switchTab('courts');
      try { await ensureMapReady(); } catch { /* the inline map retry stays available */ }
      setCourtSheetSnap('half');
      toast('Move the map to your venue, then tap “Missing a court? Add it.”');
    };

    const renderHome = ({ forceList = false } = {}) => {
      context.businesses = businesses;
      context.claims = claims;
      const contextualBusiness = court && businesses.find((item) => Number(item.court_id) === Number(court.id));
      const requestedBusiness = businesses.find((item) => Number(item.id) === Number(businessId));
      if (!forceList && (requestedBusiness || contextualBusiness || (businesses.length === 1 && !court))) {
        renderBusinessHubDashboard(modal, body, requestedBusiness || contextualBusiness || businesses[0], context);
        return;
      }
      if (!businesses.length && !claims.length) {
        body.innerHTML = businessHubEmptyHtml(court);
        body.querySelector('#business-claim-start').addEventListener('click', () => openChildModal(
          modal, () => openBusinessClaimSheet({ court, onSaved: onClaimed, onMissing }),
        ));
        return;
      }
      const representedCourts = new Set(businesses.map((item) => Number(item.court_id)));
      const visibleClaims = claims.filter((claim) => !representedCourts.has(Number(claim.court_id)));
      const claimHtml = (claim) => {
        const claimStatus = String(claim.status || 'pending').toLowerCase();
        const copy = claimStatus === 'verified'
          ? ['Claim approved', 'is-verified', 'check-circle']
          : claimStatus === 'rejected'
            ? ['Claim needs attention', 'is-rejected', 'alert-triangle']
            : ['Claim submitted — only you can see this draft.', 'is-pending', 'clock'];
        const badge = claimStatus === 'verified' ? 'Verified'
          : claimStatus === 'rejected' ? 'Needs attention' : 'Submitted for review';
        return `<div class="card business-pending-claim">
          <span aria-hidden="true">${uiIcon(copy[2])}</span><span class="row-main"><b>${esc(claim.court_name || claim.business_name || 'Venue claim')}</b><small>${esc(copy[0])}</small>${claimStatus === 'rejected' && claim.feedback ? `<small>${esc(claim.feedback)}</small>` : ''}</span>${claimStatus === 'rejected' ? `<button type="button" class="btn btn-secondary btn-sm" data-business-claim-resubmit="${claim.id}">${uiIcon('refresh')} Review &amp; resubmit</button>` : `<span class="business-status ${copy[1]}">${uiIcon(copy[2])}<span>${badge}</span></span>`}
        </div>`;
      };
      body.innerHTML = `
        <div class="business-hub-intro compact">
          <p class="tab-kicker">Third Shot for businesses</p>
          <h2>Your locations</h2>
          <p>Manage the information that helps players decide, book, and show up.</p>
        </div>
        ${businesses.length ? `<div class="business-location-list">${businesses.map(businessHubLocationCard).join('')}</div>` : ''}
        ${visibleClaims.length ? `<div class="section-label">Claims</div><div class="business-claim-list">${visibleClaims.map(claimHtml).join('')}</div>` : ''}
        <button type="button" class="btn btn-primary btn-block" id="business-add-location" style="margin-top:16px">${uiIcon('plus')} Claim another location</button>`;
      body.querySelectorAll('[data-business-open]').forEach((button) => button.addEventListener('click', () => {
        const business = businesses.find((item) => Number(item.id) === Number(button.dataset.businessOpen));
        if (business) { context.savedMessage = ''; renderBusinessHubDashboard(modal, body, business, context); }
      }));
      body.querySelectorAll('[data-business-claim-resubmit]').forEach((button) => button.addEventListener('click', () => {
        const claim = visibleClaims.find((item) => Number(item.id) === Number(button.dataset.businessClaimResubmit));
        if (!claim) return;
        openChildModal(modal, () => openBusinessClaimSheet({
          court: { id: claim.court_id, name: claim.court_name || claim.business_name || 'Venue' },
          onSaved: onClaimed,
          onMissing,
        }));
      }));
      body.querySelector('#business-add-location').addEventListener('click', () => openChildModal(
        modal, () => openBusinessClaimSheet({ court, onSaved: onClaimed, onMissing }),
      ));
    };

    const onClaimed = (business, claim) => {
      if (business && business.is_owner !== false) {
        const normalized = normalizeBusinessProfile(business);
        businesses = businesses.filter((item) => Number(item.id) !== Number(normalized.id));
        businesses.unshift(normalized);
        businessId = normalized.id;
      }
      if (claim) {
        claims = claims.filter((item) => Number(item.id) !== Number(claim.id));
        claims.unshift(claim);
      }
      context.businesses = businesses;
      context.claims = claims;
      renderHome();
    };
    context.renderHome = renderHome;
    context.showLocations = () => {
      businessId = null;
      court = null;
      renderHome({ forceList: true });
    };
    context.onClaimed = onClaimed;
    context.onMissing = onMissing;

    const refresh = async () => {
      const data = await api('/businesses/mine');
      businesses = businessMineItems(data);
      claims = Array.isArray(data?.claims) ? data.claims : [];
      context.businesses = businesses;
      context.claims = claims;
      renderHome();
    };
    context.refresh = refresh;

    try {
      const data = await api('/businesses/mine');
      if (!body.isConnected) return modal;
      businesses = businessMineItems(data);
      claims = Array.isArray(data?.claims) ? data.claims : [];
      context.businesses = businesses;
      context.claims = claims;
      renderHome();
    } catch (error) {
      if (!body.isConnected) return modal;
      body.innerHTML = `<div class="empty-state"><span class="big" aria-hidden="true">${uiIcon('building')}</span><b>Business Hub couldn’t load</b><p>${esc(error.message)}</p><button type="button" class="btn btn-secondary" id="business-hub-retry">Try again</button></div>`;
      body.querySelector('#business-hub-retry').addEventListener('click', () => transitionModal(modal, () => openBusinessHub({ court, businessId })));
    }
    return modal;
  }

  function openBusinessClaimSheet({ court = null, onSaved = null, onMissing = null } = {}) {
    const modal = openModal(`
      ${modalHead('Manage a venue')}
      <ol class="simple-step-trail" aria-label="Venue setup"><li id="claim-trail-venue">1. Choose venue</li><li id="claim-trail-role">2. Confirm your role</li></ol>
      <form id="business-claim-form" novalidate>
        <section id="claim-step-venue" aria-labelledby="claim-venue-title">
        <div class="simple-page-intro"><h3 id="claim-venue-title">Which venue do you manage?</h3><p>Find its court listing so players have one place to find you.</p></div>
        <div class="form-field">
          <label for="bh-court-search">Club or court</label>
          <input type="search" id="bh-court-search" placeholder="Search by venue name or city" autocomplete="off" value="${esc(court?.name || '')}" ${court ? 'readonly' : ''} />
          <input type="hidden" id="bh-court-id" value="${court?.id || ''}" />
          <div id="bh-court-results" class="business-court-results"></div>
          ${!court ? `<div class="business-missing-venue"><span>Can’t find your venue?</span><button type="button" class="btn-link" id="business-add-missing-venue">Add a missing venue</button></div>` : ''}
        </div>
        <button type="button" class="btn btn-primary btn-block" id="claim-next">Continue</button>
        </section>
        <section id="claim-step-location" hidden><button type="button" class="simple-back" id="claim-location-back">${uiIcon('arrow-left')} Search existing venues</button><div class="simple-page-intro"><h3>Add your missing venue</h3><p>This location stays private while we review it. Submit your venue and management role together.</p></div>${window.VenueWorkspace.locationFields()}<button type="button" class="btn btn-primary btn-block" id="claim-location-next">Continue to your role</button></section>
        <section id="claim-step-role" aria-labelledby="claim-role-title" hidden>
        <button type="button" class="simple-back" id="claim-back">${uiIcon('arrow-left')} ${court ? 'Review venue' : 'Change venue'}</button>
        <div class="simple-page-intro"><h3 id="claim-role-title">Confirm you manage this venue</h3><p id="claim-selected-name">${esc(court?.name || '')}</p></div>
        <div class="form-field">
          <label for="business-claim-role">Your role</label>
          <select id="business-claim-role" data-select-title="Your role" data-select-prefix="Role">
            <option value="owner" data-icon-name="key" data-description="I own this facility or business">Owner</option>
            <option value="manager" data-icon-name="building" data-description="I manage this venue or its programs">Manager</option>
            <option value="staff" data-icon-name="users" data-description="I am authorized to publish venue information">Authorized staff</option>
          </select>
        </div>
        <div class="form-field"><label for="business-claim-contact">Work email</label><input type="email" id="business-claim-contact" maxlength="255" value="${esc(state.me?.email || '')}" autocomplete="email" /><small class="field-help">Used privately to review your request. It will not appear on the court listing.</small></div>
        <details class="simple-disclosure" id="claim-supporting-details"><summary>Add supporting information <span>Optional</span></summary>
        <div class="form-field"><label for="business-claim-evidence-url">Official website or staff page (optional)</label><input type="url" id="business-claim-evidence-url" placeholder="https://official-site.example/team" inputmode="url" /><small class="field-help">An official page can help us confirm your role.</small></div>
        <div class="form-field"><label for="business-claim-evidence-notes">How can the venue confirm your role?</label><textarea id="business-claim-evidence-notes" rows="3" maxlength="800" placeholder="Your title and the best public or business contact to verify it."></textarea><small class="field-help">Tell us who to contact or where your role is listed.</small></div>
        </details>
        <label class="business-authorized-check"><input type="checkbox" id="business-claim-authorized" data-no-draft /> <span>I confirm I’m authorized to represent this business.</span></label>
        <button type="submit" class="btn btn-primary btn-block" id="business-claim-submit">Create my venue workspace</button>
        <p class="business-form-note">Your listing stays private until your management role is approved. You can add details and booking links while we review it.</p>
        </section>
      </form>
    `, { label: 'Manage a venue' });
    if (!court) clubCourtPicker(modal, 'bh');
    const formUX = bindModalFormUX(modal, '#business-claim-submit', { draftKey: 'business-claim' });
    let missingLocation = false;
    const readLocation = window.VenueWorkspace.bindLocation(modal, {request: api, showError: formUX.showError, icon:uiIcon});
    let claimStep = court ? 'role' : 'venue';
    const showClaimStep = (step, focus = false) => {
      claimStep = step;
      modal.querySelector('#claim-step-venue').hidden = step !== 'venue';
      modal.querySelector('#claim-step-location').hidden = step !== 'location';
      modal.querySelector('#claim-step-role').hidden = step !== 'role';
      modal.querySelector('#claim-selected-name').textContent = missingLocation ? modal.querySelector('#venue-location-name').value : modal.querySelector('#bh-court-search').value;
      ['venue', 'role'].forEach((name) => modal.querySelector(`#claim-trail-${name}`).setAttribute('aria-current', name === step ? 'step' : 'false'));
      if (focus) {
        const target = modal.querySelector(step === 'location' ? '#venue-location-name' : step === 'venue' ? '#bh-court-search' : '#business-claim-role');
        (target._appSelectButton || target).focus();
      }
    };
    const continueClaim = () => {
      formUX.clearError();
      const search = modal.querySelector('#bh-court-search');
      const selected = Number(search.dataset.selectedCourtId || modal.querySelector('#bh-court-id').value);
      if (!Number.isSafeInteger(selected) || selected <= 0) { formUX.showError('Select your venue from the search results.', search); return false; }
      showClaimStep('role', true); return true;
    };
    modal.querySelector('#business-add-missing-venue')?.addEventListener('click', () => { missingLocation = true; showClaimStep('location', true); });
    modal.querySelector('#claim-location-back').addEventListener('click', () => { missingLocation = false; showClaimStep('venue', true); });
    const continueLocation = () => { formUX.clearError(); if (readLocation()) showClaimStep('role', true); };
    modal.querySelector('#claim-location-next').addEventListener('click', continueLocation);
    modal.querySelector('#claim-next').addEventListener('click', continueClaim);
    modal.querySelector('#claim-back').addEventListener('click', () => showClaimStep(missingLocation ? 'location' : 'venue', true));
    showClaimStep(claimStep);
    modal.querySelector('#business-claim-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      if (claimStep === 'location') { continueLocation(); return; }
      if (claimStep === 'venue') { continueClaim(); return; }
      formUX.clearError();
      const searchInput = modal.querySelector('#bh-court-search');
      const courtId = Number(searchInput.dataset.selectedCourtId || modal.querySelector('#bh-court-id').value);
      const location = missingLocation ? readLocation() : null;
      if (missingLocation && !location) { showClaimStep('location'); return; }
      if (!missingLocation && (!Number.isSafeInteger(courtId) || courtId <= 0)) {
        showClaimStep('venue');
        formUX.showError('Choose your club or court from the search results.', modal.querySelector('#bh-court-search'));
        return;
      }
      if (!modal.querySelector('#business-claim-authorized').checked) {
        formUX.showError('Confirm that you are authorized to represent this business.', modal.querySelector('#business-claim-authorized'));
        return;
      }
      const contactInput = modal.querySelector('#business-claim-contact');
      if (!contactInput.value.trim() || !contactInput.validity.valid) {
        formUX.showError('Enter a valid private work email for verification.', contactInput);
        return;
      }
      const evidenceRaw = modal.querySelector('#business-claim-evidence-url').value.trim();
      const evidenceUrl = evidenceRaw ? businessActionHref(evidenceRaw) : '';
      if (evidenceRaw && !evidenceUrl) {
        modal.querySelector('#claim-supporting-details').open = true;
        formUX.showError('Use a secure https:// official evidence link.', modal.querySelector('#business-claim-evidence-url'));
        return;
      }
      const finish = formUX.startSubmitting('Submitting for review…');
      if (!finish) return;
      try {
        const result = await api(missingLocation ? '/businesses/claims/new-location' : '/businesses/claims', {
          method: 'POST',
          body: JSON.stringify({
            ...(missingLocation ? {location} : {court_id: courtId}),
            role: modal.querySelector('#business-claim-role').value,
            authorized_attestation: true,
            verification_contact_email: contactInput.value.trim(),
            evidence_url: evidenceUrl,
            evidence_notes: modal.querySelector('#business-claim-evidence-notes').value.trim(),
          }),
        });
        formUX.clearDraft({ disable: true });
        closeModal(modal);
        toast('Submitted for review');
        onSaved?.(result.business, result.claim);
      } catch (error) {
        finish();
        if (error.code === 'venue_location_already_listed') {
          showClaimStep('location');
          const results = modal.querySelector('#venue-location-results');
          results.innerHTML = `<p>${esc(error.data?.message || 'This location is already listed.')}</p>${(error.data?.items || []).map(item => `<button type="button" class="court-search-row" data-existing-venue="${item.id}"><span class="row-main"><b>${esc(item.name)}</b><small>${esc([item.address, item.city, item.state].filter(Boolean).join(', '))}</small></span><span>Use this venue</span></button>`).join('')}`;
          results.querySelectorAll('[data-existing-venue]').forEach(button => button.addEventListener('click', () => { const item = error.data.items.find(item => String(item.id) === button.dataset.existingVenue); missingLocation = false; searchInput.dataset.selectedCourtId = item.id; searchInput.value = item.name; modal.querySelector('#bh-court-id').value = item.id; showClaimStep('role', true); }));
        }
        formUX.showError(error.data?.message || error.message);
      }
    });
    return modal;
  }

  function optionalBusinessUrl(modal, selector, label, formUX, original = undefined) {
    const input = modal.querySelector(selector);
    const raw = input.value.trim();
    if (!raw) return '';
    const href = businessActionHref(raw);
    if (!href) {
      const disclosure = input.closest('details');
      if (disclosure) disclosure.open = true;
      formUX.showError(`Enter a valid ${label} link that starts with https://`, input);
      return null;
    }
    return original !== undefined && raw === String(original || '').trim() ? original || '' : href;
  }

