  function openBusinessDetailsEditor(rawBusiness, onSaved, { focusField = null } = {}) {
    const business = normalizeBusinessProfile(rawBusiness);
    const initialDetails = { ...business, amenities: [...business.amenities] };
    const hasManagedLogo = business.has_logo_upload || /^\/api\/businesses\/\d+\/logo$/.test(business.logo_url || '');
    const modal = openModal(window.VenueWorkspace.detailsForm(business, { head: modalHead('Edit venue details'), icon: uiIcon, hasManagedLogo }), { page: true, label: 'Edit venue details' });
    modal.querySelector('.modal').classList.add('venue-details-modal');
    const formUX = bindModalFormUX(modal, '#business-details-save', { draftKey: `business-details-${business.id}` });
    const syncPreview = window.VenueWorkspace.bindDetailsEditor(modal, business, { formUX, icon: uiIcon, baseline: initialDetails, verified: businessVerificationState(business) === 'verified', publicNow: businessWorkspaceState(business).publicNow });
    bindModalDiscardConfirmation(modal, { isDirty: formUX.isDirty, onDiscard: () => formUX.clearDraft({ disable: true }), title: 'Discard unsaved venue details?', message: 'Your text edits have not been saved. Logo uploads or removals already completed are kept.' });
    if (focusField) requestAnimationFrame(() => { const input = modal.querySelector(focusField); syncPreview.reveal(input); input?.scrollIntoView({ block: 'center' }); input?.focus({ preventScroll: true }); });
    const adoptLogoState = (updated) => { initialDetails.logo_url = updated.logo_url || ''; Object.assign(business, normalizeBusinessProfile(updated)); modal.querySelector('#business-logo-saved').textContent = 'Logo saved. ' + window.VenueWorkspace.savedStatus(updated); modal.querySelector('#business-logo-history').hidden = false; syncPreview(); onSaved?.(business); };
    modal.querySelector('#business-logo-history').addEventListener('click', () => openChildModal(modal, () => openBusinessRevisionHistory(business, updated => { adoptLogoState(updated); modal.querySelector('#business-logo-url').value = updated.logo_url || ''; syncPreview(); })));
    modal.querySelector('#business-edit-hours')?.addEventListener('click', () => openChildModal(modal, () => openBusinessHoursEditor(business, updated => { Object.assign(business, normalizeBusinessProfile(updated)); for (const key of ['structured_hours','hours_dawn_to_dusk','effective_hours','timezone','hours']) initialDetails[key]=updated[key]; modal.querySelector('#business-hours').value=updated.hours || ''; modal.querySelector('#business-timezone').value=updated.timezone || '';onSaved?.(updated);syncPreview(); })));
    modal.querySelector('#business-edit-visiting')?.addEventListener('click', () => openChildModal(modal, () => openBusinessVisitEditor(business, updated => { Object.assign(business, normalizeBusinessProfile(updated)); for (const key of ['visitor_info','effective_visiting']) initialDetails[key] = updated[key]; onSaved?.(updated); syncPreview(); })));
    let pendingLogoFile = null;
    modal.querySelector('#business-logo-retry').addEventListener('click', () => { if (pendingLogoFile) uploadLogo(pendingLogoFile); });
    const logoFileInput = modal.querySelector('#business-logo-file');
    const logoFileButton = modal.querySelector('#business-logo-file-button');
    const logoFilePicker = modal.querySelector('#business-logo-file-picker');
    const logoRemoveButton = modal.querySelector('#business-logo-remove');
    const detailsSaveButton = modal.querySelector('#business-details-save');
    logoFileButton.addEventListener('click', () => logoFileInput.click());
    logoFileInput.addEventListener('change', event => uploadLogo(event.currentTarget.files?.[0]));
    const uploadLogo = async (file) => {
      const fileInput = logoFileInput;
      if (!file) return;
      pendingLogoFile = file;
      modal.querySelector('#business-logo-retry').hidden = true;
      formUX.clearError();
      const meta = businessFileDescription(file, 'Image');
      const fileType = String(file.type || '').toLowerCase();
      const looksLikeImage = ['image/jpeg', 'image/png', 'image/webp'].includes(fileType)
        || /\.(?:jpe?g|png|webp)$/i.test(file.name);
      if (!looksLikeImage) {
        setBusinessFilePickerState(logoFilePicker, { state: 'error', name: file.name, meta, badge: 'Choose an image' });
        formUX.showError('Choose a PNG, JPEG, or WebP logo.', logoFileButton);
        fileInput.value = '';
        return;
      }
      if (!file.size) {
        setBusinessFilePickerState(logoFilePicker, { state: 'error', name: file.name, meta, badge: 'Empty file' });
        formUX.showError('That logo file is empty.', logoFileButton);
        fileInput.value = '';
        return;
      }
      if (file.size > 12 * 1024 * 1024) {
        setBusinessFilePickerState(logoFilePicker, { state: 'error', name: file.name, meta, badge: 'Too large' });
        formUX.showError('Choose a logo smaller than 12 MB.', logoFileButton);
        fileInput.value = '';
        return;
      }
      setBusinessFilePickerState(logoFilePicker, { state: 'loading', name: file.name, meta: `${meta} · optimizing`, badge: 'Uploading…' });
      fileInput.disabled = true;
      logoFileButton.disabled = true;
      detailsSaveButton.disabled = true;
      let uploadError = '';
      try {
        const image = await imageFileToDataUrl(file, 768);
        const result = await window.VenueWorkspace.saveLogo(business, {data: image, request: api, resolveConflicts: conflicts => openBusinessConflictReview(modal, conflicts)});
        pendingLogoFile = null;
        if (result.business) adoptLogoState(result.business);
        const url = result.logo_url || '';
        if (url) modal.querySelector('#business-logo-url').value = url;
        setBusinessFilePickerState(logoFilePicker, { state: 'success', name: file.name, meta: `${meta} · uploaded securely`, badge: 'Uploaded' });
        logoFileButton.querySelector('#business-logo-file-action').textContent = 'Replace uploaded logo';
        logoRemoveButton.hidden = false;
        syncPreview(); toast(window.VenueWorkspace.savedStatus(result.business || business));
        if (!result.business) adoptLogoState(await api(`/businesses/${business.id}`));
      } catch (error) {
        uploadError = error.status === 404
          ? 'Managed logo uploads are not enabled yet. Use a secure image link for now.'
          : error.message === 'image_too_large'
            ? 'That logo could not be compressed below 512 KB. Try a smaller image.'
            : error.message === 'bad_image'
              ? 'That image could not be opened. Choose another PNG, JPEG, or WebP.'
              : error.message || 'Logo upload failed. Try again.';
        setBusinessFilePickerState(logoFilePicker, { state: 'error', name: file.name, meta, badge: 'Not saved' });
        modal.querySelector('#business-logo-retry').hidden = false;
      } finally {
        fileInput.disabled = false;
        logoFileButton.disabled = false;
        detailsSaveButton.disabled = false;
        fileInput.value = '';
      }
      if (uploadError) formUX.showError(uploadError, logoFileButton);
    };
    logoRemoveButton.addEventListener('click', () => openBusinessConfirmAction({
      title: 'Remove uploaded logo?', message: 'Logo removal saves a draft for review. The approved logo stays live until you publish the new version.', confirmLabel: 'Remove logo',
      onConfirm: async (sheet) => { const removed = await window.VenueWorkspace.saveLogo(business, {request: api, resolveConflicts: conflicts => openBusinessConflictReview(sheet, conflicts)}); adoptLogoState(removed.business); modal.querySelector('#business-logo-url').value = ''; logoRemoveButton.hidden = true; syncPreview(); setBusinessFilePickerState(logoFilePicker, { state: 'idle', name: 'Uploaded logo removed', meta: 'Choose an image to add a new logo', badge: 'Optional', icon: 'camera' }); logoFileButton.querySelector('#business-logo-file-action').textContent = 'Choose logo image'; closeModal(sheet); toast(window.VenueWorkspace.savedStatus(removed.business)); },
    }));
    modal.querySelector('#business-details-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      const name = modal.querySelector('#business-name').value.trim();
      if (name.length < 2) {
        formUX.showError('Enter the business name players will recognize.', modal.querySelector('#business-name'));
        return;
      }
      const emailInput = modal.querySelector('#business-email');
      if (emailInput.value.trim() && !emailInput.validity.valid) {
        formUX.showError('Enter a valid public email address.', emailInput);
        return;
      }
      const rawLogoUrl = modal.querySelector('#business-logo-url').value.trim();
      const managedLogo = /^\/api\/businesses\/\d+\/logo$/.test(rawLogoUrl);
      const urls = {
        website_url: optionalBusinessUrl(modal, '#business-website-url', 'website', formUX, initialDetails.website_url),
        ...(managedLogo ? {} : { logo_url: optionalBusinessUrl(modal, '#business-logo-url', 'logo image', formUX, initialDetails.logo_url) }),
      };
      if (Object.values(urls).some((value) => value === null)) return;
      const finish = formUX.startSubmitting('Saving details…');
      if (!finish) return;
      try {
        const updated = await window.VenueWorkspace.saveEdits(initialDetails, {
          changes: window.VenueWorkspace.changedDetails(initialDetails, {
            name,
            description: modal.querySelector('#business-description').value.trim(),
            announcement: modal.querySelector('#business-announcement').value.trim(),
            phone: modal.querySelector('#business-phone').value.trim(),
            email: emailInput.value.trim(),
            hours: modal.querySelector('#business-hours').value.trim(),
            timezone: modal.querySelector('#business-timezone').value,
            amenities: modal.querySelector('#business-amenities').value.split(',').map((item) => item.trim()).filter(Boolean),
            ...urls,
          }), request: api, resolveConflicts: conflicts => openBusinessConflictReview(modal, conflicts),
        });
        formUX.clearDraft({ disable: true });
        closeModal(modal);
        onSaved?.(updated);
        toast('Venue details saved');
      } catch (error) {
        finish();
        formUX.showError(error.message);
      }
    });
    return modal;
  }

  function openBusinessIntegrationRequest(business) {
    const role = String(business.manager_role || (business.is_owner ? 'owner' : '')).toLowerCase();
    if (!['owner', 'admin'].includes(role)) {
      toast('Owner or admin access is required for integration requests.');
      return null;
    }
    if (businessVerificationState(business) !== 'verified') {
      toast('Your venue must be verified before requesting an integration.');
      return null;
    }
    const followUpEmail = String(business.email || state.me?.email || '').trim();
    const modal = openModal(`
      ${modalHead('Request a custom integration')}
      <form id="business-integration-form" novalidate>
        <div class="business-integration-hero"><span aria-hidden="true">${uiIcon('link')}</span><h3>Ask about connecting your existing tools</h3><p>This creates a request for the Third Shot team to review with you. It does not install a connector or start a sync.</p></div>
        <div id="business-integration-history" aria-live="polite"></div>
        <div class="form-field">
          <label for="business-integration-provider">What system or provider do you use?</label>
          <input type="text" id="business-integration-provider" maxlength="120" placeholder="Booking platform, website, custom system…" />
        </div>
        <fieldset class="business-integration-needs">
          <legend>What should players be able to do?</legend>
          ${[
            ['bookings', 'Book courts'], ['lessons', 'Book lessons and clinics'],
            ['schedule', 'See a live schedule'], ['memberships', 'Buy or manage memberships'],
            ['events', 'Register for leagues and events'], ['other', 'Something else'],
          ].map(([value, label]) => `<label><input type="checkbox" name="integration-need" value="${value}" /> <span>${label}</span></label>`).join('')}
        </fieldset>
        <div class="form-field">
          <label for="business-integration-notes">Anything we should know?</label>
          <textarea id="business-integration-notes" rows="4" maxlength="1000" placeholder="Links, workflow details, who we should contact, or what would make this useful…"></textarea>
        </div>
        <div class="form-field">
          <label for="business-integration-email">Best email for follow-up</label>
          <input type="email" id="business-integration-email" maxlength="255" required value="${esc(followUpEmail)}" autocomplete="email" />
          <small class="field-help">We will use this address to discuss feasibility and next steps.</small>
        </div>
        <div class="business-preview-note"><span aria-hidden="true">${uiIcon('lock')}</span><p><b>Never paste passwords, API keys, access tokens, or private credentials here.</b><br />If a connection is feasible, the team will arrange a secure authorization process separately.</p></div>
        <button type="submit" class="btn btn-primary btn-block" id="business-integration-send">Send integration request</button>
        <p class="business-form-note">A request marked handled does not mean a live API connection exists unless the team confirms that separately.</p>
      </form>
    `, { label: 'Request a custom business integration' });
    const history = modal.querySelector('#business-integration-history');
    const renderHistory = (items) => {
      if (!Array.isArray(items) || !items.length) { history.innerHTML = ''; return; }
      const statusLabels = {
        submitted: ['Submitted', 'is-pending'], contacted: ['In touch', 'is-pending'],
        completed: ['Request handled', 'is-verified'], declined: ['Closed', 'is-rejected'],
      };
      history.innerHTML = `<div class="section-label">Previous requests</div><div class="business-request-history">${items.slice(0, 3).map((item) => {
        const [label, tone] = statusLabels[item.status] || [item.status || 'Submitted', ''];
        const submitted = item.created_at ? new Date(item.created_at).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' }) : '';
        return `<div class="business-request-row"><span aria-hidden="true">${uiIcon('link')}</span><span class="row-main"><b>#${item.id} · ${esc(item.provider || 'Custom integration')}</b><small>${esc([(item.capabilities || []).join(' · ') || 'Integration request', submitted, item.status_message || ''].filter(Boolean).join(' · '))}</small></span><span class="business-status ${tone}">${uiIcon(businessStateIconName(item.status))}<span>${esc(label)}</span></span></div>`;
      }).join('')}</div>`;
    };
    renderHistory(business.integration_requests);
    api(`/businesses/${business.id}/integration-requests`).then((data) => {
      if (history.isConnected) renderHistory(data.items || []);
    }).catch(() => {
      if (history.isConnected && !history.innerHTML) {
        history.innerHTML = '<p class="business-form-note">Previous requests could not be loaded. You can still send a new request.</p>';
      }
    });
    const formUX = bindModalFormUX(modal, '#business-integration-send', { draftKey: `business-integration-${business.id}` });
    modal.querySelector('#business-integration-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      formUX.clearError();
      const provider = modal.querySelector('#business-integration-provider').value.trim();
      const needs = [...modal.querySelectorAll('[name="integration-need"]:checked')].map((input) => input.value);
      const notes = modal.querySelector('#business-integration-notes').value.trim();
      const emailInput = modal.querySelector('#business-integration-email');
      if (!provider && !needs.length && notes.length < 3) {
        formUX.showError('Tell us which tool you use or what you want players to do.', modal.querySelector('#business-integration-provider'));
        return;
      }
      if (!emailInput.value.trim() || !emailInput.validity.valid) {
        formUX.showError('Enter the email we should use to follow up.', emailInput);
        return;
      }
      const finish = formUX.startSubmitting('Sending request…');
      if (!finish) return;
      try {
        const result = await api(`/businesses/${business.id}/integration-requests`, {
          method: 'POST',
          body: JSON.stringify({
            provider,
            capabilities: needs,
            details: notes,
            contact_email: emailInput.value.trim(),
          }),
        });
        formUX.clearDraft({ disable: true });
        closeModal(modal);
        toast(`Request #${result.request.id} sent — we’ll follow up by email`);
      } catch (error) {
        finish();
        formUX.showError(error.message);
      }
    });
    return modal;
  }

