  function openAccountDeletionConfirmation(impact, trigger) {
    return new Promise((resolve) => {
      let settled = false;
      const rows = accountDeletionImpactCopy(impact);
      const sheet = openModal(`
        <div class="action-confirmation is-danger account-deletion-confirmation">
          ${modalHead('Confirm deletion')}
          <div class="action-confirm-hero">
            <span class="action-confirm-icon" aria-hidden="true">${uiIcon('trash')}</span>
            <div>
              <span class="action-confirm-eyebrow">Permanent account deletion</span>
              <h2 id="account-deletion-confirm-title">Delete your account forever?</h2>
              <p>Review each consequence before using the password you already entered to confirm.</p>
            </div>
          </div>
          <dl class="account-deletion-impact-list">
            ${rows.map((row) => `<div><dt>${esc(row.label)}</dt><dd>${esc(row.copy)}</dd></div>`).join('')}
          </dl>
          <div class="action-confirm-actions">
            <button type="button" class="btn btn-secondary" data-account-delete-cancel>Keep my account</button>
            <button type="button" class="btn action-confirm-danger" data-account-delete-accept>Delete my account</button>
          </div>
        </div>
      `, { label: 'Confirm permanent account deletion' });
      sheet.classList.add('action-confirm-backdrop');
      sheet.querySelector('.modal')?.setAttribute('aria-labelledby', 'account-deletion-confirm-title');
      if (trigger) sheet._returnFocus = trigger;
      const settle = (accepted) => {
        if (settled) return;
        settled = true;
        closeModal(sheet);
        resolve(accepted);
      };
      sheet._cleanupFns?.push(() => {
        if (!settled) { settled = true; resolve(false); }
      });
      sheet.querySelector('[data-account-delete-cancel]')?.addEventListener('click', () => settle(false));
      sheet.querySelector('[data-account-delete-accept]')?.addEventListener('click', () => settle(true));
      requestAnimationFrame(() => sheet.querySelector('[data-account-delete-cancel]')?.focus({ preventScroll: true }));
    });
  }

  function showAccountDeletionSuccess(modal, impact, discardGuard) {
    discardGuard?.authorizeClose();
    // The server has already revoked this identity. Clear its local credential
    // immediately so a late polling response cannot turn the acknowledgement
    // screen into a generic "session expired" logout before it is read.
    invalidateMeRequests();
    authSessionEpoch += 1;
    authTokenRevision += 1;
    state.token = null;
    localStorage.removeItem('pp_token');
    localStorage.removeItem('pp_me_snapshot_v1');
    clearInterval(state.presenceHeartbeatTimer);
    clearInterval(state.playLiveRefreshTimer);
    state.presenceHeartbeatTimer = null;
    state.playLiveRefreshTimer = null;
    stopThreadPolling();
    stopLocationWatch();
    const box = modal.querySelector('.modal');
    if (!box) return logout({ reason: 'Your account was deleted.' });
    box.innerHTML = `
      <div class="account-deletion-success" role="status" aria-live="polite">
        <span class="account-deletion-success-icon" aria-hidden="true">${uiIcon('check-circle')}</span>
        <span class="action-confirm-eyebrow">Deletion complete</span>
        <h2 id="account-deletion-success-title">Your account has been deleted</h2>
        <p>Your personal profile and access are gone. Records retained for other players now identify you only as “Deleted player.”</p>
        ${(impact?.tournaments?.length || impact?.leagues?.length)
          ? '<p>Affected tournament and league entrants have been notified.</p>' : ''}
        <button type="button" class="btn btn-primary btn-block" data-account-delete-finish>Return to sign in</button>
      </div>`;
    setDialogLabel(box, 'Account deletion complete');
    box.setAttribute('aria-labelledby', 'account-deletion-success-title');
    modal._dismissBlocked = () => true;
    modal._onDismissBlocked = () => {
      modal.querySelector('[data-account-delete-finish]')?.focus({ preventScroll: true });
    };
    const finish = modal.querySelector('[data-account-delete-finish]');
    finish?.addEventListener('click', () => logout({ reason: 'Your account was deleted.' }));
    requestAnimationFrame(() => finish?.focus({ preventScroll: true }));
  }

  function openPlayerDataDownload() {
    const accountId = Number(state.me?.id);
    let downloadUrl = null;
    const modal = openModal(`${modalHead('Download player data')}
      <p class="row-sub">Your profile, saved courts, dated sessions, league and tournament results, group memberships, and messages and photos you sent.</p>
      <p class="field-help">Prepare a JSON file, then save it to this device. Other players’ messages, sign-in secrets and organization records are excluded.</p>
      <form id="player-export-form" novalidate><div class="form-field"><label for="player-export-password">Current password</label><input id="player-export-password" type="password" autocomplete="current-password" /></div>
      ${state.me?.mfa?.enabled ? '<div class="form-field"><label for="player-export-mfa">Authenticator code</label><input id="player-export-mfa" type="text" autocomplete="one-time-code" inputmode="numeric" maxlength="6" /></div>' : ''}
      <button type="submit" class="btn btn-primary btn-block" id="player-export-download">Prepare JSON file</button></form>
      <div id="player-export-ready" hidden aria-live="polite"></div>
    `, { label: 'Download your player data' });
    const formUX = bindModalFormUX(modal, '#player-export-download');
    modal.querySelector('#player-export-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const password = modal.querySelector('#player-export-password');
      const code = modal.querySelector('#player-export-mfa');
      if (!password.value) { formUX.showError('Enter your current password.', password); return; }
      if (code && !/^\d{6}$/.test(code.value.trim())) { formUX.showError('Enter your current six-digit code.', code); return; }
      const finish = formUX.startSubmitting('Preparing download…');
      if (!finish) return;
      try {
        const data = await api('/me/export', { method: 'POST', body: JSON.stringify({ current_password: password.value, mfa_code: code?.value.trim() || '' }) });
        if (!modal.isConnected || Number(state.me?.id) !== accountId) return;
        if (!data || data.format !== 'third-shot-player-data-v1' || Number(data.profile?.id) !== accountId
            || !Array.isArray(data.sent_messages) || !Array.isArray(data.sessions)
            || !Array.isArray(data.league_matches) || !Array.isArray(data.tournament_matches)) {
          throw new Error('The complete file could not be prepared. Try again.');
        }
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        downloadUrl = URL.createObjectURL(blob);
        const filename = `third-shot-player-data-${new Date().toISOString().slice(0, 10)}.json`;
        password.value = ''; if (code) code.value = '';
        finish();
        modal.querySelector('#player-export-form').hidden = true;
        const ready = modal.querySelector('#player-export-ready');
        ready.hidden = false;
        ready.innerHTML = `<p class="row-title">Your file is ready</p><p class="field-help">${esc(filename)} · ${Math.max(1, Math.ceil(blob.size / 1024))} KB</p><a class="btn btn-primary btn-block" href="${downloadUrl}" download="${filename}" id="player-export-save">Save JSON file</a><p class="field-help">Contains personal information. Keep the saved file private.</p><button type="button" class="btn btn-secondary btn-block" id="player-export-done">Done</button>`;
        ready.querySelector('#player-export-done').addEventListener('click', () => closeModal(modal));
        ready.querySelector('#player-export-save').focus({ preventScroll: true });
      } catch (error) {
        finish();
        formUX.showError(error.code === 'invalid_credentials' ? 'That is not your current password.' : error.message,
          error.code === 'invalid_mfa_code' ? code : password);
      }
    });
    modal._cleanupFns?.push(() => { if (downloadUrl) URL.revokeObjectURL(downloadUrl); });
    return modal;
  }

  function appRunsStandalone() {
    return state.appInstalled === true || navigator.standalone === true
      || window.matchMedia('(display-mode: standalone)').matches;
  }

  function sessionPlayStyleLabel(game) {
    switch (game.play_style) {
      case 'rotating_doubles': return 'Rotating doubles';
      case 'singles': return 'Singles';
      case 'mixed': return 'Mixed play';
      default: return '';
    }
  }

  function sessionCourtAccessLabel(game) {
    if (game.court_access === 'public_drop_in') return 'Public drop-in · host reported';
    if (game.court_access === 'booking_needed') return 'Court booking still needed';
    const count = Number(game.court_count);
    if (Number.isInteger(count) && count > 0) return `Host says ${count} court${count === 1 ? ' is' : 's are'} reserved`;
    return game.court_access === 'host_reserved' ? 'Host says the court is reserved' : 'Court booking not listed';
  }

  function sessionRsvpStatus(player) {
    if (['confirmed', 'needs_confirmation', 'reserved'].includes(player.rsvp_status)) return player.rsvp_status;
    return player.attending === true ? 'confirmed'
      : player.attendance_confirmation_requested_at ? 'needs_confirmation' : 'reserved';
  }

  function sessionRosterGroupsHtml(game, renderPlayer, viewerId = null) {
    if (game.players.length > 8) {
      const priority = (person) => person.user_id === game.creator_id ? 0 : person.user_id === viewerId ? 1 : 2;
      const people = [...game.players].sort((a, b) => priority(a) - priority(b));
      const counts = [['confirmed', 'Confirmed'], ['needs_confirmation', 'To confirm'], ['reserved', 'Reserved']]
        .map(([key, label]) => `<span data-rsvp-state="${key}"><b>${people.filter((person) => sessionRsvpStatus(person) === key).length}</b>${label}</span>`).join('');
      const row = (person) => renderPlayer(person, true);
      return `<div class="session-roster-counts" aria-label="Player confirmations">${counts}</div>${people.slice(0, 4).map(row).join('')}
        <details class="session-roster-more" id="session-roster-more-all"><summary>View ${people.length - 4} more players</summary>${people.slice(4).map(row).join('')}</details>`;
    }
    return [['confirmed', 'Confirmed'], ['needs_confirmation', 'Needs confirmation'], ['reserved', 'Place reserved']]
      .map(([key, label]) => {
        const people = game.players.filter((player) => sessionRsvpStatus(player) === key);
        if (!people.length) return '';
        return `<div class="session-roster-group" data-rsvp-state="${key}"><h5>${label} <span>${people.length}</span></h5>${people.map(renderPlayer).join('')}</div>`;
      }).join('');
  }

  // Invitees who answered "Maybe": no spot held, so no RSVP state or Remove.
  function sessionMaybeGroupHtml(game) {
    const people = game.status === 'upcoming' && Array.isArray(game.maybe_people) ? game.maybe_people : [];
    return people.length ? `<div class="session-roster-group" data-rsvp-state="maybe"><h5>Maybe <span>${people.length}</span></h5>${people.map((person) => `<div class="game-player-row"><button type="button" class="player-profile-link" data-view-user="${Number(person.user_id)}" aria-label="View ${esc(person.display_name)}'s profile">${avatarHtml(person, 'sm', 'span')}<span class="row-main"><span class="row-title">${esc(person.display_name)}</span></span></button></div>`).join('')}</div>` : '';
  }

  function sessionConfirmationHtml(game) {
    if (!game.attendance_confirmation_due || !game.is_joined || game.is_creator
        || game.is_instant || game.status !== 'upcoming'
        || !(Date.parse(game.scheduled_at) > Date.now())) return '';
    const changed = game.commitment_confirmation_due;
    return `<section class="attendance-confirmation" aria-labelledby="attendance-confirmation-title">
      <div><b id="attendance-confirmation-title" tabindex="-1">${changed ? 'The plan changed' : 'Still coming?'}</b>
        <span>${changed ? 'Check the current time, court and cost.' : 'Confirm your place for this date.'}</span></div>
      <div class="attendance-confirmation-actions"><button class="btn btn-primary" id="gs-attend">${changed ? 'Confirm this plan' : 'Yes, I’m coming'}</button><button class="btn btn-secondary" id="gs-not-coming">Can’t make it</button></div>
    </section>`;
  }

  // Rain during an upcoming outdoor plan. The host's buttons open the same
  // edit and cancel sheets as Manage (data-rain-proxy names that control).
  function gameRainAlertHtml(game, rain) {
    if (!(rain?.chance >= 50) || game.court?.indoor || game.is_instant || !game.is_joined
        || game.status !== 'upcoming' || !(Date.parse(game.scheduled_at) > Date.now())) return '';
    return `<section class="attendance-confirmation rain-alert" aria-label="Rain forecast">
      <div><b>${uiIcon('water')} Rain likely around ${esc(rain.label)} · ${Number(rain.chance)}% chance</b>
        ${game.is_creator ? '' : '<span>Your host can move or cancel it.</span>'}</div>
      ${game.is_creator ? '<div class="attendance-confirmation-actions"><button type="button" class="btn btn-primary" data-rain-proxy="gs-edit">Move it</button><button type="button" class="btn btn-secondary" data-rain-proxy="gs-cancel">Cancel game</button></div>' : ''}
    </section>`;
  }

  function sessionVisitFactsHtml(game) {
    const cost = game.cost_cents == null ? 'Cost not listed'
      : Number(game.cost_cents) === 0 ? 'Free session'
        : `$${(Number(game.cost_cents) / 100).toFixed(2)} per player`;
    const access = sessionCourtAccessLabel(game);
    return `<div class="session-visit-facts" role="group" aria-label="Session cost and court access">
      <span><b>${esc(cost)}</b></span><span>${esc(access)}</span>
    </div>`;
  }

  function sessionReturnToolsHtml(game) {
    if (!game.is_joined || game.status !== 'upcoming' || game.is_instant || game.time_vote
        || !(new Date(game.scheduled_at).getTime() > Date.now())) return '';
    return `<div class="session-return-tools" role="group" aria-label="Keep this plan handy">
      <button type="button" class="btn btn-secondary" id="gs-calendar">${uiIcon('calendar')} Add to calendar</button>
      ${appRunsStandalone() ? '' : `<button type="button" class="btn btn-secondary" id="gs-install" aria-label="Add Third Shot to your Home Screen">${uiIcon('home')} Home Screen</button>`}
    </div>`;
  }
  // "When works?" replaces the time in the plan card until one time locks.
  function sessionTimeVoteHtml(game) {
    const vote = game.time_vote, mine = new Set(vote.my_votes);
    const leader = vote.options.find((option) => option.id === vote.leader_id);
    return `<div class="session-time-vote" role="group" aria-labelledby="gs-time-vote-title">
      <b id="gs-time-vote-title">When works?</b>
      <div class="schedule-suggestions">${vote.options.map((option) => `<button type="button" data-time-vote="${esc(option.id)}" class="${mine.has(option.id) ? 'active' : ''}" aria-pressed="${mine.has(option.id)}" ${vote.can_vote ? '' : 'disabled'}><b>${esc(fmtVoteTime(option.starts_at))}</b><small>${Number(option.count) || 0} can</small></button>`).join('')}</div>
      ${vote.can_vote ? '<p class="simple-note">Tap every time that works for you.</p>' : ''}
      ${vote.can_lock && leader ? `<button type="button" class="btn btn-primary btn-block" id="gs-time-lock" data-option-id="${esc(leader.id)}">Lock ${esc(fmtVoteTime(leader.starts_at))}</button>
      <p class="simple-note">Locks automatically ${esc(fmtVoteTime(vote.locks_at))}</p>` : ''}
    </div>`;
  }

  function openInstallApp() {
    const modal = openModal(`${modalHead('Keep Third Shot handy', 'home')}
      <p class="row-sub">Open your plans and chats from your Home Screen.</p>
      <p class="field-help" id="install-status" role="status">${appRunsStandalone() ? 'Third Shot is already running as an app.' : 'Adding the app is optional.'}</p>
      ${state.installPrompt && !appRunsStandalone() ? '<button type="button" class="btn btn-primary btn-block" id="install-native">Install Third Shot</button>' : ''}
      <details class="simple-disclosure" open><summary>iPhone or iPad · Safari</summary><p class="row-sub">Open Third Shot in Safari. Tap Share, then Add to Home Screen. If shown, leave Open as Web App on, then tap Add.</p></details>
      <details class="simple-disclosure"><summary>Android · Chrome</summary><p class="row-sub">Open Third Shot in Chrome. Open the browser menu, choose Add to Home screen or Install app, then follow the browser’s steps.</p></details>
      <details class="simple-disclosure"><summary>Computer or another browser</summary><p class="row-sub">Look for Install in the address bar or browser menu. If it is unavailable, bookmark Third Shot to return later.</p></details>
    `, { label: 'Add Third Shot to your Home Screen' });
    modal.querySelector('#install-native')?.addEventListener('click', async (event) => {
      const prompt = state.installPrompt;
      if (!prompt) return;
      state.installPrompt = null;
      const button = event.currentTarget;
      button.disabled = true;
      const status = modal.querySelector('#install-status');
      try {
        await prompt.prompt();
        const choice = await prompt.userChoice;
        if (modal.isConnected) status.textContent = choice.outcome === 'accepted'
          ? 'Install requested. Follow your browser to finish.'
          : 'No changes made. You can keep using Third Shot in this browser.';
      } catch {
        if (modal.isConnected) status.textContent = 'The install prompt could not open. Use the steps below or bookmark Third Shot.';
      } finally {
        if (modal.isConnected) {
          button.remove();
          status.setAttribute('tabindex', '-1');
          status.focus();
        }
      }
    });
    return modal;
  }

