  async function renderProfile({ reuseDashboard = false } = {}) {
    const generation = ++profileRenderGeneration;
    const el = $('#profile-content');
    const me = state.me;
    if (!me) return;
    const previousScrollTop = Math.max(0, Number(el.scrollTop) || 0);
    const hasUsableProfile = el.dataset.profileReady === String(me.id)
      && el.childElementCount > 0;
    el.dataset.profileRender = String(generation);
    const renderIsCurrent = () => generation === profileRenderGeneration
      && el.dataset.profileRender === String(generation)
      && state.tab === 'profile'
      && state.me && state.me.id === me.id;
    const dashboardRequest = profileDashboardRequest(me.id, {
      reuse: reuseDashboard,
    });
    let prefetchedDashboard = null;
    if (hasUsableProfile) {
      el.setAttribute('aria-busy', 'true');
      el.classList.add('view-refreshing');
      el.querySelector('.view-refresh-note')?.remove();
      try {
        prefetchedDashboard = await dashboardRequest;
      } catch (error) {
        if (!renderIsCurrent()) return;
        retainViewAfterError(
          el,
          `${error.message || 'Your profile could not refresh.'} Showing your last update.`,
          () => renderProfile(),
        );
        requestAnimationFrame(() => { if (el.isConnected) el.scrollTop = previousScrollTop; });
        return;
      }
      if (!renderIsCurrent()) return;
    }
    const total = me.ranked_wins + me.ranked_losses;
    const winPct = total ? Math.round((me.ranked_wins / total) * 100) : 0;
    const availabilityLines = availabilitySummary(me.availability);
    const headlineStats = total ? `
      <div class="stat-card"><div class="stat-value">${me.ranked_wins}–${me.ranked_losses}</div><div class="stat-label">Ranked wins–losses</div></div>
      <div class="stat-card"><div class="stat-value">${winPct}%</div><div class="stat-label">Ranked win rate</div></div>
      <div class="stat-card"><div class="stat-value">${me.current_streak >= 2 ? uiIcon('trophy', 'profile-stat-icon') : ''}${me.current_streak}</div><div class="stat-label">Current ranked win streak · best ${me.best_streak}</div></div>` : `
      <section class="profile-ranked-starter" aria-labelledby="profile-ranked-starter-title">
        <span class="profile-ranked-starter-icon" aria-hidden="true">${uiIcon('pickleball')}</span>
        <span class="row-main"><b id="profile-ranked-starter-title">Your play history</b><small>Completed sessions and matches appear here after you play.</small></span>
      </section>`;

    el.innerHTML = `
      <div class="profile-dashboard-head">
        <div class="profile-hero">
          <button type="button" class="profile-avatar-edit" id="profile-avatar-edit" aria-label="Change profile photo">${avatarHtml(me)}</button>
          <div class="profile-name">${esc(me.display_name)}</div>
          <div class="profile-sub">${playerSkillIdentityHtml(me)}${me.home_court_name ? ` · ${uiIcon('home', 'community-inline-icon')} ${esc(me.home_court_name)}` : ''}</div>
          ${me.bio ? `<p class="profile-sub profile-bio">${esc(me.bio)}</p>` : ''}
        </div>
        <dl class="profile-hero-stats" id="pf-hero-stats" hidden></dl>
        <button type="button" class="profile-availability-summary" id="profile-availability-edit" aria-label="Edit when you usually play">
          <span aria-hidden="true">${uiIcon('clock')}</span>
          <span class="row-main"><b>Usually plays</b>${playerAwayLabel(me) ? `<small>${esc(playerAwayLabel(me))}</small>` : ''}<small>${availabilityLines.length ? availabilityLines.join(' · ') : 'Add your usual days and times'}</small></span>
          ${uiIcon('chevron-right', 'chev')}
        </button>
      </div>
      <div class="profile-load-error hidden" id="pf-dashboard-error" role="alert">
        <span class="nav-row-leading" aria-hidden="true">${uiIcon('refresh')}</span>
        <span class="row-main"><b>Your latest play dashboard did not load</b><span>Your profile and settings still work. Check the connection and try the play sections again.</span></span>
        <button type="button" class="btn btn-secondary btn-sm" id="pf-dashboard-retry">Try again</button>
      </div>
      <div id="pf-upcoming" aria-busy="true" style="min-height:108px">
        <div class="section-label">Up next</div>${skeletonHtml(1)}
      </div>
      <div id="pf-upcoming-more"></div>
      <div id="pf-courts" aria-busy="true" style="min-height:108px">
        <div class="section-label">Saved courts</div>${skeletonHtml(1)}
      </div>
      <div class="profile-dashboard-actions profile-dashboard-primary-actions">
        <button type="button" class="btn btn-secondary" id="pf-invite">${uiIcon('send')} Invite friends</button>
        <button type="button" class="btn btn-secondary" id="pf-feedback">${uiIcon('message')} Send feedback</button>
      </div>
      <section class="profile-compete" aria-labelledby="pf-compete-title">
        <div class="section-label" id="pf-compete-title">Compete</div>
        <div class="profile-compete-list">
          <button type="button" class="profile-compete-row" id="pf-compete-rankings">
            <span class="profile-compete-icon" aria-hidden="true">${uiIcon('chart')}</span>
            <span class="row-main"><b>Rankings</b><small>${total ? `${me.ranked_wins}–${me.ranked_losses} ranked · see where you stand` : 'Top players near you and among friends'}</small></span>
            ${uiIcon('chevron-right', 'chev')}
          </button>
          <button type="button" class="profile-compete-row" id="pf-compete-events">
            <span class="profile-compete-icon" aria-hidden="true">${uiIcon('trophy')}</span>
            <span class="row-main"><b>Tournaments &amp; leagues</b><small>Join an event or run your own</small></span>
            <span id="competition-action-badge" class="segment-badge${Number(state.competitionActionCount) ? '' : ' hidden'}" aria-hidden="true">${Number(state.competitionActionCount) > 99 ? '99+' : Number(state.competitionActionCount) || 0}</span>
            ${uiIcon('chevron-right', 'chev')}
          </button>
          <button type="button" class="profile-compete-row" id="pf-compete-ranked">
            <span class="profile-compete-icon" aria-hidden="true">${uiIcon('zap')}</span>
            <span class="row-main"><b>Start a ranked match</b><small>Play a friend and the result counts toward your rating</small></span>
            ${uiIcon('chevron-right', 'chev')}
          </button>
        </div>
      </section>
      <details class="profile-dashboard-more simple-disclosure" aria-label="Play stats and history">
        <summary>Your progress &amp; history</summary>
      <div class="stat-grid" id="profile-headline-stats" ${total ? '' : 'aria-busy="true"'}>
        ${headlineStats}
      </div>
      <div id="pf-new-player-progress" aria-live="polite"></div>
      <div id="pf-history" aria-busy="true" style="min-height:166px">
        <div class="section-label">Recent play</div>${skeletonHtml(2)}
      </div>

        <div id="pf-play-stats" aria-busy="true" style="min-height:146px">
          <div class="section-label">Your play stats</div>${skeletonHtml(1)}
        </div>
        <div id="pf-history-more">
        </div>
      </details>
      <button type="button" class="profile-business-entry" id="pf-business-hub">
        <span class="profile-business-icon" aria-hidden="true">${uiIcon('building')}</span>
        <span class="row-main"><b>Manage a venue</b><small>Your listing, bookings and events</small></span>
        ${uiIcon('chevron-right', 'chev')}
      </button>

    `;

    el.querySelector('#profile-avatar-edit')?.addEventListener('click', () => openEditProfile({ section: 'photo' }));
    el.querySelector('#profile-availability-edit')?.addEventListener('click', () => openEditProfile({ section: 'availability' }));
    el.querySelector('#pf-first-ranked')?.addEventListener('click', openRankedMatchFlow);
    // One dashboard response keeps Profile to a single mobile round trip while
    // preserving the endpoint-parity section shapes consumed below.
    const profileDataPromise = (prefetchedDashboard
      ? Promise.resolve(prefetchedDashboard) : dashboardRequest).then((dashboard) => [
      { status: 'fulfilled', value: dashboard.games },
      { status: 'fulfilled', value: dashboard.stats },
      { status: 'fulfilled', value: dashboard.favorites },
      { status: 'fulfilled', value: dashboard.history },
    ], (reason) => [
      { status: 'rejected', reason },
      { status: 'rejected', reason },
      { status: 'rejected', reason },
      { status: 'rejected', reason },
    ]);

    el.querySelector('#pf-feedback')?.addEventListener('click', () => {
      const sheet = openModal(`
        ${modalHead('Send feedback')}
        <p class="row-sub" style="margin-bottom:10px">Found a bug? Missing a feature? It goes straight to the person building Third Shot.</p>
        <form id="feedback-form" novalidate>
          <div class="form-field">
            <label for="fb-text">What should we know?</label>
            <textarea id="fb-text" maxlength="2000" rows="5" placeholder="Tell us what happened or what would make the app better."></textarea>
            <small class="field-help">Please do not include passwords or other private information.</small>
          </div>
          <button type="submit" class="btn btn-primary btn-block" id="fb-send" style="margin-top:12px">Send feedback</button>
        </form>
      `, { label: 'Send feedback' });
      const formUX = bindModalFormUX(sheet, '#fb-send');
      bindModalDiscardConfirmation(sheet, {
        isDirty: formUX.isDirty,
        title: 'Discard this feedback?',
        message: 'Your feedback has not been sent yet.',
      });
      sheet.querySelector('#feedback-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const field = sheet.querySelector('#fb-text');
        const message = field.value.trim();
        if (message.length < 3) {
          formUX.showError('Share at least a few words so we can act on it.', field);
          return;
        }
        const resetSubmitting = formUX.startSubmitting('Sending feedback…');
        if (!resetSubmitting) return;
        try {
          await api('/feedback', { method: 'POST', body: JSON.stringify({ message }) });
          closeModal(sheet);
          toast('Thanks — feedback sent');
        } catch (err) {
          resetSubmitting();
          formUX.showError(err.message);
        }
      });
    });
    el.querySelector('#pf-invite').addEventListener('click', shareInviteLink);
    el.querySelector('#pf-business-hub').addEventListener('click', () => openBusinessHub());
    el.querySelector('#pf-compete-rankings').addEventListener('click', () => {
      setPlaySegment('scores', { render: false });
      switchTab('play', { scrollToTop: true });
    });
    el.querySelector('#pf-compete-events').addEventListener('click', () => {
      setPlaySegment('brackets', { render: false });
      switchTab('play', { scrollToTop: true });
    });
    el.querySelector('#pf-compete-ranked').addEventListener('click', openRankedMatchFlow);
    el.querySelector('#pf-dashboard-retry').addEventListener('click', (event) => {
      event.currentTarget.disabled = true;
      event.currentTarget.textContent = 'Trying…';
      renderProfile();
    });
    const [mineResult, statsResult, favoritesResult, historyResult] = await profileDataPromise;
    if (!renderIsCurrent()) return;

    // Remove all reserved loading space in one paint, then hydrate the same
    // fixed section nodes. A newer Profile render (or another active tab) owns
    // the DOM as soon as the generation/current-view guard above stops matching.
    const statsEl = el.querySelector('#pf-play-stats');
    const upcomingEl = el.querySelector('#pf-upcoming');
    const upcomingMoreEl = el.querySelector('#pf-upcoming-more');
    const courtsEl = el.querySelector('#pf-courts');
    const historyEl = el.querySelector('#pf-history');
    const historyMoreEl = el.querySelector('#pf-history-more');
    [statsEl, upcomingEl, courtsEl, historyEl].forEach((section) => {
      section.innerHTML = '';
      section.removeAttribute('aria-busy');
      section.style.removeProperty('min-height');
    });
    const dashboardFailed = [mineResult, statsResult, favoritesResult, historyResult]
      .every((result) => result.status === 'rejected');
    const heroCounts = {};
    const showProfileSectionUnavailable = (section, title, copy) => {
      section.innerHTML = `<div class="section-label">${esc(title)}</div><div class="profile-section-unavailable">
        <span class="profile-section-unavailable-icon" aria-hidden="true">${uiIcon('refresh')}</span>
        <span class="row-main"><b>${esc(copy)}</b><small>The rest of your profile is still available.</small></span>
        <button type="button" class="btn btn-secondary btn-sm" data-profile-section-retry>Retry</button>
      </div>`;
      section.querySelector('[data-profile-section-retry]')?.addEventListener('click', (event) => {
        event.currentTarget.disabled = true;
        event.currentTarget.textContent = 'Trying…';
        renderProfile();
      });
    };
    if (dashboardFailed) {
      el.querySelector('#pf-dashboard-error').classList.remove('hidden');
      upcomingEl.innerHTML = '<div class="section-label">Up next</div><div class="profile-section-unavailable">Upcoming play is unavailable right now.</div>';
      courtsEl.innerHTML = '<div class="section-label">Saved courts</div><div class="profile-section-unavailable">Saved courts are unavailable right now.</div>';
      historyEl.innerHTML = '<div class="section-label">Recent play</div><div class="profile-section-unavailable">Recent play is unavailable right now.</div>';
      statsEl.innerHTML = '<div class="section-label">Your play stats</div><div class="profile-section-unavailable">Play stats are unavailable right now.</div>';
    }

    // My upcoming games (parity with public profiles), tappable into the game screen.
    try {
      const mine = mineResult.status === 'fulfilled' ? mineResult.value : null;
      if (!mine) throw mineResult.reason;
      const nowMs = Date.now();
      const scorePending = (mine.items || []).filter((game) =>
        game.status === 'upcoming' && game.can_enter_score
          && (game.is_instant
            ? instantRallyScorePending(game)
            : new Date(game.scheduled_at).getTime() <= nowMs));
      const wrapPending = (mine.items || []).filter((game) =>
        game.status === 'upcoming' && game.can_complete_session
          && (game.is_instant
            ? instantSessionWrapPending(game)
            : new Date(game.scheduled_at).getTime() <= nowMs));
      const up = (mine.items || []).filter((game) =>
        game.status === 'upcoming' && !scorePending.includes(game) && !wrapPending.includes(game)
          && !instantRallyClosed(game)
          && (instantRallyAssembly(game) || new Date(game.scheduled_at).getTime() > nowMs));
      const ordered = [...scorePending, ...wrapPending, ...up];
      heroCounts.plans = ordered.length;
      const nextGame = ordered[0] || null;
      if (nextGame) {
        const nextLabel = scorePending.includes(nextGame) ? 'Add a score'
          : wrapPending.includes(nextGame) ? 'Finish session' : 'Up next';
        upcomingEl.innerHTML = `<div class="section-label">${nextLabel}</div>${gameCardHtml(nextGame)}`;
        const remaining = ordered.slice(1);
        upcomingMoreEl.innerHTML = remaining.length
          ? `<details class="simple-disclosure"><summary>See all ${ordered.length} plans</summary>${remaining.map((game) => gameCardHtml(game, { compact: true })).join('')}</details>`
          : '';
        bindGameButtons(upcomingEl, renderProfile);
        bindGameButtons(upcomingMoreEl, renderProfile);
      } else {
        upcomingEl.innerHTML = '<div class="section-label">Up next</div><div class="empty-state" style="padding:14px">Nothing planned yet.<br><button type="button" class="btn btn-primary btn-sm" id="pf-find-game" style="margin-top:9px">Find a game</button> <button type="button" class="btn btn-secondary btn-sm" id="pf-plan-game" style="margin-top:9px">Plan a session</button></div>';
        upcomingEl.querySelector('#pf-find-game').addEventListener('click', () => {
          setPlaySegment('nearby', { render: false });
          switchTab('play');
        });
        upcomingEl.querySelector('#pf-plan-game').addEventListener('click', () => openNewGameModal({
          gameType: 'casual',
          maxPlayers: 6,
          lockGameType: true,
          sessionMode: true,
          onCreated: () => {
            profileDashboardCache = { userId: null, promise: null, data: null, readyAt: 0 };
            if (state.tab === 'profile') renderProfile();
          },
        }));
      }
    } catch {
      upcomingMoreEl.replaceChildren();
      if (!dashboardFailed) showProfileSectionUnavailable(
        upcomingEl, 'Up next', 'Upcoming play is unavailable right now.',
      );
    }

    // Personal play stats — quietly skipped for brand-new players.
    try {
      const stats = statsResult.status === 'fulfilled' ? statsResult.value : null;
      if (!stats) throw statsResult.reason;
      heroCounts.plays = stats.games_total;
      heroCounts.streak = stats.week_streak;
      if (!total) {
        const headline = el.querySelector('#profile-headline-stats');
        if (headline) {
          headline.removeAttribute('aria-busy');
          const progressCopy = Number(stats.games_total || 0)
            ? `${stats.games_total} completed play${stats.games_total === 1 ? '' : 's'} · ${stats.week_streak || 0} week${stats.week_streak === 1 ? '' : 's'} in a row`
            : 'Completed sessions and matches appear here after you play.';
          headline.querySelector('.profile-ranked-starter small').textContent = progressCopy;
        }
      }
      if (stats.games_total > 0) {
        statsEl.innerHTML = `
          <div class="stat-grid" style="margin-top:10px">
            <div class="stat-card"><div class="stat-value">${stats.games_this_month}</div><div class="stat-label">Plays this month</div></div>
            <div class="stat-card"><div class="stat-value">${stats.week_streak >= 2 ? uiIcon('calendar', 'profile-stat-icon') : ''}${stats.week_streak}</div><div class="stat-label">Weeks in a row</div></div>
            ${stats.top_court ? `<button type="button" class="stat-card stat-card-action" data-pfcourt-top="${stats.top_court.id}" aria-label="Open ${esc(stats.top_court.name)} court">` : '<div class="stat-card">'}
              <div class="stat-value" style="font-size:13px;line-height:1.25;padding-top:4px">${stats.top_court ? esc(stats.top_court.name) : '—'}</div>
              <div class="stat-label">Top court${stats.top_court ? ` · ${stats.top_court.games}` : ''}</div>
            ${stats.top_court ? '</button>' : '</div>'}
          </div>`;
        const relationshipLinks = [];
        if (stats.best_partner) {
          relationshipLinks.push(`
            <button type="button" class="profile-relationship-link" data-view-user="${stats.best_partner.user_id}" aria-label="View ${esc(stats.best_partner.display_name)}'s profile, your best partner">
              <span class="nav-row-leading">${uiIcon('users')}</span>
              <span class="row-main"><span class="row-title">Best partner · ${esc(stats.best_partner.display_name)}</span><span class="row-sub">${stats.best_partner.wins} win${stats.best_partner.wins === 1 ? '' : 's'} together</span></span>
              ${uiIcon('chevron-right', 'chev')}
            </button>`);
        }
        if (stats.top_rival) {
          relationshipLinks.push(`
            <button type="button" class="profile-relationship-link" data-view-user="${stats.top_rival.user_id}" aria-label="View ${esc(stats.top_rival.display_name)}'s profile, your most faced player">
              <span class="nav-row-leading">${uiIcon('target')}</span>
              <span class="row-main"><span class="row-title">Most faced · ${esc(stats.top_rival.display_name)}</span><span class="row-sub">Your record is ${stats.top_rival.your_wins}–${stats.top_rival.games - stats.top_rival.your_wins}</span></span>
              ${uiIcon('chevron-right', 'chev')}
            </button>`);
        }
        if (relationshipLinks.length) {
          statsEl.insertAdjacentHTML('beforeend',
            `<div class="profile-relationship-links">${relationshipLinks.join('')}</div>`);
        }
        statsEl.insertAdjacentHTML('beforeend', formStripHtml(stats.form));
        if ((stats.badges || []).length || (stats.badge_progress || []).length) {
          const earned = (stats.badges || []).map((b) =>
            `<span class="tag" style="margin:0" title="${esc(b.label)}">${b.emoji} ${esc(b.label)}${b.id === 'mvp' && stats.mvp_awards > 1 ? ` ×${stats.mvp_awards}` : ''}</span>`);
          // Locked badges show dimmed with progress toward the next milestone.
          const locked = (stats.badge_progress || []).map((b) =>
            `<span class="tag" style="margin:0;opacity:.5;filter:grayscale(1)" title="${esc(b.label)} (${b.current}/${b.target})">${b.emoji} ${esc(b.label)} ${b.current}/${b.target}</span>`);
          statsEl.insertAdjacentHTML('beforeend', `
            <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-top:10px">
              ${[...earned, ...locked].join('')}
            </div>`);
        }
        statsEl.insertAdjacentHTML('beforeend',
          tournamentTitlesHtml(stats.tournament_titles, stats.league_titles));
        statsEl.querySelectorAll('[data-open-tournament]').forEach((row) => {
          row.addEventListener('click', () => openTournamentScreen(Number(row.dataset.openTournament)));
        });
        statsEl.querySelectorAll('[data-open-league]').forEach((row) => {
          row.addEventListener('click', () => openLeagueScreen(Number(row.dataset.openLeague)));
        });
        if (stats.insights) {
          const ins = stats.insights;
          const lines = [];
          if (ins.best_part) {
            const pct = Math.round((ins.best_part.wins / ins.best_part.games) * 100);
            lines.push(`${uiIcon('sun', 'community-inline-icon')} You win ${pct}% of your ${esc(ins.best_part.label.replace(/s$/, ''))} games (${ins.best_part.wins}/${ins.best_part.games})`);
          }
          if (ins.busiest_day) lines.push(`${uiIcon('calendar', 'community-inline-icon')} You play most on ${esc(ins.busiest_day)}s`);
          if (ins.avg_margin != null) {
            lines.push(`${uiIcon('chart', 'community-inline-icon')} Average margin: ${ins.avg_margin > 0 ? '+' : ''}${ins.avg_margin} points`);
          }
          if (lines.length) {
            statsEl.insertAdjacentHTML('beforeend', `
              <div class="card profile-insights" style="margin-top:12px;padding:12px 14px">
                <div class="profile-insights-title">${uiIcon('chart')} Your patterns</div>
                ${lines.map((l) => `<div class="row-sub profile-insight-row">${l}</div>`).join('')}
              </div>`);
          }
        }
        // Brag line built from real numbers, carrying the invite deep link.
        statsEl.insertAdjacentHTML('beforeend',
          `<button class="btn btn-secondary btn-sm btn-block" id="pf-share-season" style="margin-top:12px">${uiIcon('send')} Share my season</button>`);
        el.querySelector('#pf-share-season').addEventListener('click', async () => {
          const bits = [];
          if (me.ranked_wins + me.ranked_losses > 0) bits.push(`${me.ranked_wins}–${me.ranked_losses} ranked`);
          if (stats.games_this_month) bits.push(`${stats.games_this_month} game${stats.games_this_month === 1 ? '' : 's'} this month`);
          if (stats.week_streak >= 2) bits.push(`${stats.week_streak}-week play streak`);
          if (stats.top_court) bits.push(`home turf: ${stats.top_court.name}`);
          const text = `My season on Third Shot: ${bits.join(' · ')}. Come play with me!`;
          const url = `${location.origin}/u/${me.id}`; // short link → OG preview in chat apps
          try {
            if (navigator.share) await navigator.share({ title: 'Third Shot', text, url });
            else { await navigator.clipboard.writeText(`${text} ${url}`); toast('Season copied to share'); }
          } catch { /* user cancelled */ }
        });
        el.querySelector('[data-pfcourt-top]')?.addEventListener('click', (e) => openCourtDetail(Number(e.currentTarget.dataset.pfcourtTop)));
        bindUserButtons(statsEl);
      } else {
        statsEl.innerHTML = '<div class="section-label">Your play stats</div>' + emptyStateHtml({
          icon: 'activity', title: 'Your play story starts here',
          body: 'Log a completed game to start seeing patterns, streaks, and favorite partners.',
          primary: { goto: 'log-game', label: 'Log a game', icon: 'plus' },
          className: 'profile-stats-empty',
        });
      }
    } catch {
      el.querySelector('#profile-headline-stats')?.removeAttribute('aria-busy');
      if (!dashboardFailed) showProfileSectionUnavailable(
        statsEl, 'Your play stats', 'Play stats are unavailable right now.',
      );
    }

    // Saved courts lead with their next real dated opportunity; expand the rest on demand.
    try {
      const favs = favoritesResult.status === 'fulfilled' ? favoritesResult.value : null;
      if (!favs) throw favoritesResult.reason;
      const rows = [];
      const seen = new Set();
      if (me.home_court_id) {
        rows.push({ id: me.home_court_id, name: me.home_court_name || 'Primary court', city: '', is_home: true });
        seen.add(me.home_court_id);
      }
      (favs.items || []).forEach((c) => { if (!seen.has(c.id)) { rows.push({ ...c, is_home: false }); seen.add(c.id); } });
      heroCounts.courts = rows.length;
      const savedCourtRowHtml = (c) => `
        <article class="card profile-saved-court"><button type="button" class="row nav-row-button" data-pfcourt="${c.id}" aria-label="Open ${esc(c.name)} court">
          <span class="nav-row-leading">${uiIcon(c.is_home ? 'home' : 'star')}</span>
          <span class="row-main">
            <span class="row-title">${esc(c.name)}</span>
            <span class="row-sub">${esc(c.city || '')}${c.is_home ? ' · Primary court' : ''}${c.rating_avg ? ` · Rated ${c.rating_avg}` : ''}</span>
          </span>
          ${uiIcon('chevron-right', 'chev')}
        </button><div class="court-next-opportunity" data-saved-next="${c.id}"></div></article>`;
      const featuredCourts = rows.slice(0, 3);
      const moreCourts = rows.slice(3);
      courtsEl.innerHTML = '<div class="section-label">Saved courts</div>' + (rows.length
        ? `${featuredCourts.map(savedCourtRowHtml).join('')}${moreCourts.length ? `
            <details class="profile-saved-courts-more">
              <summary>See all ${rows.length} saved courts</summary>
              ${moreCourts.map(savedCourtRowHtml).join('')}
            </details>` : ''}`
        : `<div class="empty-state" style="padding:16px">No saved courts yet — use Save on a court to keep it here.<br><button class="btn btn-secondary btn-sm" data-goto="courts-list" style="margin-top:10px">${uiIcon('map')} Browse courts</button></div>`);
      courtsEl.querySelectorAll('[data-pfcourt]').forEach((row) =>
        makePressable(row, () => openCourtDetail(Number(row.dataset.pfcourt))));
      featuredCourts.forEach(court => loadCourtNextOpportunity(courtsEl.querySelector(`[data-saved-next="${court.id}"]`),court));
      courtsEl.querySelector('.profile-saved-courts-more')?.addEventListener('toggle',event=>{
        if(event.currentTarget.open) moreCourts.forEach(court=>loadCourtNextOpportunity(courtsEl.querySelector(`[data-saved-next="${court.id}"]`),court));
      });
    } catch {
      if (!dashboardFailed) showProfileSectionUnavailable(
        courtsEl, 'Saved courts', 'Saved courts are unavailable right now.',
      );
    }

    try {
      const history = historyResult.status === 'fulfilled' ? historyResult.value : null;
      if (!history) throw historyResult.reason;
      if (history.items.length) {
        historyEl.replaceChildren();
        let historyItems = [...history.items];
        let historyNextCursor = history.next_cursor || null;
        let historyHasMore = history.has_more === true && !!historyNextCursor;
        const filters = [
          ['all', 'All', () => true],
          ['wins', `${uiIcon('trophy')} Wins`, (g) => g.you_won === true],
          ['losses', 'Losses', (g) => g.you_won === false],
          ['ranked', 'Ranked', (g) => g.game_type === 'ranked'],
          ['casual', 'Casual', (g) => g.game_type === 'casual'],
        ];
        let active = 'all';
        let historyRequest = 0;
        let historyLoading = false;
        let historyError = '';
        const loadHistoryFilter = async (filter) => {
          active = filter;
          const request = ++historyRequest;
          historyLoading = true;
          historyError = '';
          render({ restoreFilterFocus: true });
          try {
            const page = await api(`/games/history?limit=30&filter=${encodeURIComponent(filter)}`);
            if (request !== historyRequest || !renderIsCurrent()) return;
            historyItems = [...(page.items || [])];
            historyNextCursor = page.next_cursor || null;
            historyHasMore = page.has_more === true && !!historyNextCursor;
          } catch (error) {
            if (request !== historyRequest || !renderIsCurrent()) return;
            historyError = error.message || 'Could not load this history.';
          }
          if (request !== historyRequest || !renderIsCurrent()) return;
          historyLoading = false;
          render({ restoreFilterFocus: true });
        };
        const render = ({ restoreFilterFocus = false } = {}) => {
          const rows = historyItems;
          historyMoreEl.innerHTML = `
            <div class="section-label">Play history</div>
            <div class="quick-times" role="group" aria-label="Filter play history" style="margin:0 0 10px">
            ${filters.map(([k, label]) => `<button type="button" data-hf="${k}" class="${k === active ? 'active' : ''}" aria-pressed="${k === active}">${label}</button>`).join('')}
            </div>
            ${historyLoading ? '<p role="status">Loading play history…</p>' : historyError
              ? `<div role="alert">${esc(historyError)} <button type="button" class="btn-link" id="profile-history-retry">Try again</button></div>`
              : rows.length ? rows.map(resultRowHtml).join('')
              : emptyStateHtml({
                  icon: 'sliders', title: 'No play matches this filter',
                  body: 'Show the full history and choose another result.',
                  primary: { id: 'profile-history-clear-filter', label: 'Show all play', icon: 'refresh' },
                })}
            ${historyHasMore && !historyLoading && !historyError ? '<button type="button" class="btn btn-secondary btn-block" id="profile-history-load-more">Load more play</button>' : ''}`;
          historyMoreEl.querySelectorAll('[data-hf]').forEach((b) => b.addEventListener('click', () => {
            loadHistoryFilter(b.dataset.hf);
          }));
          historyMoreEl.querySelector('#profile-history-retry')?.addEventListener('click', () => loadHistoryFilter(active));
          historyMoreEl.querySelector('#profile-history-clear-filter')?.addEventListener('click', () => {
            loadHistoryFilter('all');
          });
          historyMoreEl.querySelector('#profile-history-load-more')?.addEventListener('click', async (event) => {
            const button = event.currentTarget;
            const resetAction = beginButtonAction(button, 'Loading…');
            if (!resetAction || !historyNextCursor) return;
            const request = ++historyRequest;
            try {
              const nextPage = await api(`/games/history?limit=30&filter=${encodeURIComponent(active)}&cursor=${encodeURIComponent(historyNextCursor)}`);
              if (request !== historyRequest || !renderIsCurrent()) return;
              const knownIds = new Set(historyItems.map((game) => game.id));
              (nextPage.items || []).forEach((game) => {
                if (!knownIds.has(game.id)) historyItems.push(game);
              });
              historyNextCursor = nextPage.next_cursor || null;
              historyHasMore = nextPage.has_more === true && !!historyNextCursor;
              render();
              requestAnimationFrame(() => {
                const target = historyMoreEl.querySelector('#profile-history-load-more')
                  || historyMoreEl.querySelector('[data-hf]');
                target?.focus({ preventScroll: true });
              });
            } catch (error) {
              if (request !== historyRequest || !renderIsCurrent()) return;
              resetAction();
              showInlineActionError(historyMoreEl, error.message);
            }
          });
          bindGameButtons(historyMoreEl, renderProfile);
          if (restoreFilterFocus) {
            const activeFilter = historyMoreEl.querySelector(`[data-hf="${active}"]`);
            requestAnimationFrame(() => activeFilter?.isConnected && activeFilter.focus({ preventScroll: true }));
          }
        };
        render();
      } else historyEl.innerHTML = '<div class="section-label">Recent play</div>' + emptyStateHtml({
        icon: 'pickleball', title: 'No completed play yet',
        body: 'Log a game you played to start your history.',
        primary: { goto: 'log-game', label: 'Log a game', icon: 'plus' },
      });
    } catch {
      historyMoreEl.replaceChildren();
      if (!dashboardFailed) showProfileSectionUnavailable(
        historyEl, 'Recent play', 'Recent play is unavailable right now.',
      );
    }
    const heroStats = [['plays', 'Plays'], ['plans', 'Upcoming'], ['courts', 'Courts'], ['streak', 'Week streak']]
      .filter(([key]) => heroCounts[key] != null);
    const heroStatsEl = el.querySelector('#pf-hero-stats');
    heroStatsEl.innerHTML = heroStats.map(([key, label]) => `<div><dt>${label}</dt><dd>${Number(heroCounts[key]) || 0}</dd></div>`).join('');
    heroStatsEl.hidden = !heroStats.length;
    el.dataset.profileReady = String(me.id);
    markViewReady('profile');
    el.setAttribute('aria-busy', 'false');
    el.classList.remove('view-refreshing');
    el.querySelector('.view-refresh-note')?.remove();
    requestAnimationFrame(() => {
      if (renderIsCurrent()) el.scrollTop = previousScrollTop;
    });
  }

  function profileChangesForSection(body, section) {
    const allowed = {
      about: ['display_name', 'bio'],
      level: ['skill_rating', 'dupr_rating', 'dupr_id'],
      photo: ['avatar_color', 'avatar_data', 'avatar_url'],
      availability: ['availability', 'away_until'], court: ['home_court_id'],
    }[section];
    return Object.fromEntries(Object.entries(body).filter(([key]) => !allowed || allowed.includes(key)));
  }

